  }

  /**
   * Display a listing of the resource for registrasi page.
   *
   * @return \Illuminate\Http\Response
   */
  public function indexRegistrasi()
  {
    // Redirect ALAB/PLAB/ANLS dengan lab klinik ke halaman verifikasi lists
    $user = Auth::user();
    if ($user && in_array($user->getlevel->level, ['ALAB', 'PLAB', 'ANLS'])) {
      $isKlinik = false;

      if (!empty($user->id_petugas)) {
        $petugasLogin = Petugas::find($user->id_petugas);
        if ($petugasLogin) {
          $labIds = is_array($petugasLogin->lab_id)
            ? $petugasLogin->lab_id
            : json_decode($petugasLogin->lab_id, true);

          if (empty($labIds)) {
            // Tanpa lab → dianggap klinik
            $isKlinik = true;
          } else {
            $klinikLab = \Smt\Masterweb\Models\Laboratorium::where('kode_laboratorium', 'KLI')->first();
            if ($klinikLab && in_array($klinikLab->id_laboratorium, (array) $labIds)) {
              $isKlinik = true;
            }
          }
        }
      }

      if ($isKlinik) {
        return redirect()->route('elits-permohonan-uji-klinik.verifikasi-lists');
      }
    }

    return view('masterweb::module.admin.laboratorium.permohonan-uji-klinik-2.pagination-registrasi');
  }

  /**
   * Get data for registrasi page with doctor_type filter for doctors.
   * For DKTR users, only show records where doctor_type is 'lab' (waiting for diagnosis).
   *
   * @return \Illuminate\Http\Response
   */
  public function data_permohonan_uji_klinik_registrasi(Request $request)
  {
    if (Auth::user()->getlevel->level == 'DKTR') {
      // For doctors, only show records where doctor_type is 'lab' (need diagnosis)
      $query = PermohonanUjiKlinik2::where('doctor_type', 'lab');

      if ($request->is_filter == '1') {
        $query->where('is_prolanis_gula', 1);

        if ($request->filter_prolanis_gula && $request->filter_prolanis_gula != 'all') {
          $query->where('id_permohonan_uji_klinik_prolanis', $request->filter_prolanis_gula);
        }
      } elseif ($request->is_filter == '2') {
        $query->where('is_prolanis_urine', 1);

        if ($request->filter_prolanis_urine && $request->filter_prolanis_urine != 'all') {
          $query->where('id_permohonan_uji_klinik_prolanis', $request->filter_prolanis_urine);
        }
      } elseif ($request->is_filter == '3') {
        $query->where('is_haji', 1);

        if ($request->filter_haji && $request->filter_haji != 'all') {
          $query->where('id_permohonan_uji_klinik_haji', $request->filter_haji);
        }
      } elseif ($request->is_filter == '0') {
        $query->where('is_prolanis_gula', 0)->where('is_prolanis_urine', 0)->where('is_haji', 0)->where('tipe_pemeriksaan_prolanis', '');
      } else {
        $query->whereIn('is_prolanis_gula', [0, 1, 2, 3]);
      }
    } else {
      // For non-doctors, show all records (same as original)
      $query = PermohonanUjiKlinik2::query();

      if ($request->is_filter == '1') {
        $query->where('is_prolanis_gula', 1);

        if ($request->filter_prolanis_gula && $request->filter_prolanis_gula != 'all') {
          $query->where('id_permohonan_uji_klinik_prolanis', $request->filter_prolanis_gula)->orWhereNotNull('tipe_pemeriksaan_prolanis');
        }
      } elseif ($request->is_filter == '2') {
        $query->where('is_prolanis_urine', 1);

        if ($request->filter_prolanis_urine && $request->filter_prolanis_urine != 'all') {
          $query->where('id_permohonan_uji_klinik_prolanis', $request->filter_prolanis_urine);
        }
      } elseif ($request->is_filter == '4') {
        $query->where('id_permohonan_uji_klinik_prolanis', '!=', null)->orWhereNotNull('tipe_pemeriksaan_prolanis');

        if ($request->filter_prolanis && $request->filter_prolanis != 'all') {
          $query->where('id_permohonan_uji_klinik_prolanis', $request->filter_prolanis);
        }
      } elseif ($request->is_filter == '3') {
        $query->where('is_haji', 1);

        if ($request->filter_haji && $request->filter_haji != 'all') {
          $query->where('id_permohonan_uji_klinik_haji', $request->filter_haji);
        }
      } elseif ($request->is_filter == '0') {
        $query->where('is_prolanis_gula', 0)->where('is_prolanis_urine', 0)->where('is_haji', 0)->whereNull('tipe_pemeriksaan_prolanis');
        $query->whereIn('is_prolanis_gula', [0, 1, 2, 3]);
      }
    }

    $query = $this->applyDateRegisterFilterOnKlinikQuery(
      $query,
      $request->input('date_start'),
      $request->input('date_end')
    );

    // Filter status pembayaran: lunas | belum_lunas | all/empty
    $filterPembayaran = strtolower(trim((string) $request->input('filter_pembayaran', '')));
    if ($filterPembayaran === 'lunas') {
      $query->where('tb_permohonan_uji_klinik_2.status_pembayaran', 1);
    } elseif ($filterPembayaran === 'belum_lunas' || $filterPembayaran === 'belum') {
      $query->where(function ($q) {
        $q->where('tb_permohonan_uji_klinik_2.status_pembayaran', 0)
          ->orWhereNull('tb_permohonan_uji_klinik_2.status_pembayaran');
      });
    }

    $query = $query->join('ms_pasien', 'tb_permohonan_uji_klinik_2.pasien_permohonan_uji_klinik', '=', 'ms_pasien.id_pasien');
    $query = $query->select(
      'tb_permohonan_uji_klinik_2.id_permohonan_uji_klinik',
      'tb_permohonan_uji_klinik_2.nomor_lab_manual',
      'tb_permohonan_uji_klinik_2.nomer_lab',
      'tb_permohonan_uji_klinik_2.nomor_spesimen_manual',
      'tb_permohonan_uji_klinik_2.is_nomor_lab_manual',
      'tb_permohonan_uji_klinik_2.is_nomor_spesimen_manual',
      'tb_permohonan_uji_klinik_2.noregister_permohonan_uji_klinik',
      'tb_permohonan_uji_klinik_2.status_permohonan_uji_klinik',
      'tb_permohonan_uji_klinik_2.status_pembayaran',
      'tb_permohonan_uji_klinik_2.tipe_pemeriksaan_prolanis',
      'tb_permohonan_uji_klinik_2.id_permohonan_uji_klinik_prolanis',
      'tb_permohonan_uji_klinik_2.is_prolanis_gula',
      'tb_permohonan_uji_klinik_2.is_prolanis_urine',
      'tb_permohonan_uji_klinik_2.id_permohonan_uji_klinik_haji',
      'tb_permohonan_uji_klinik_2.is_haji',
      'tb_permohonan_uji_klinik_2.done_register',
      'tb_permohonan_uji_klinik_2.doctor_type',
      'ms_pasien.nama_pasien as nama_pasien',
      'ms_pasien.no_rekammedis_pasien as no_rekammedis',
      'tb_permohonan_uji_klinik_2.nourut_permohonan_uji_klinik',
      'tb_permohonan_uji_klinik_2.tglregister_permohonan_uji_klinik'
    );

    $query = $this->applyRegistrasiKlinikOrderBy($query, $request);

    $limit_val = (int) $request->input('length', 10);
    if ($limit_val < 1) {
      $limit_val = 10;
    }
    if ($limit_val > 50) {
      $limit_val = 50;
    }
    $start = (int) $request->input('start', 0);
    $search = $request->input('search', '');
    if (is_array($search)) {
      $search = isset($search['value']) ? (string) $search['value'] : '';
    }

    $countQuery = clone $query;
    $totalDataRecord = $this->loadDataSearch($countQuery, $search)->count();
    $totalFilteredRecord = $totalDataRecord;

    $dataQuery = $this->loadDataSearch(clone $query, $search);
    if ($limit_val > 0) {
      $dataQuery = $dataQuery->offset($start)->limit($limit_val);
    }
    $datas = $dataQuery->get();

    $klinikNumberSettings = \Smt\Masterweb\Models\KlinikNumberSettings::getSettings();
    $registrasiMeta = $this->prefetchKlinikRegistrasiMeta(
      $datas->pluck('id_permohonan_uji_klinik')->all()
    );
    $namaHajiMap = $this->prefetchNamaHajiMap($datas);

    $canDeleteMassal = Auth::user()->getlevel->level != 'DKTR' && getAction('delete');

    $datatable = Datatables::of($datas)
      ->addColumn('action', function ($data) use ($request, $registrasiMeta) {
        // Check if user is DKTR (Dokter)
        if (Auth::user()->getlevel->level == 'DKTR') {
          // For doctors, only show Diagnosis button
          return '<a class="btn btn-sm btn-info" href="' . route('elits-permohonan-uji-klinik-2.diagnosis', $data->id_permohonan_uji_klinik) . '" title="Input Diagnosis">
                    <i class="fa fa-stethoscope"></i> Diagnosis
                  </a>';
        } else {
          // For non-doctors, show all actions
          $parameterButton = '';
          $verifikasiButton = '';
          $editButton = '';
          $deleteButton = '';
          $pid = $data->id_permohonan_uji_klinik;
          $hasParameter = isset($registrasiMeta['has_parameter'][$pid]);
          $userLevel = auth()->user()->getlevel->level ?? null;

          if (getSpesialAction($request->segment(1), 'parameter-klinik', '') || $userLevel === 'RGSTR') {
            $parameterLabel = $hasParameter ? 'Edit Parameter' : 'Masukkan Parameter';
            $parameterButton = '<a class="dropdown-item" href="' . route('elits-permohonan-uji-klinik-2.permohonan-uji-klinik-parameter', $pid) . '" title="' . e($parameterLabel) . '">' . e($parameterLabel) . '</a> ';
          }

          if (getAction('read') && $this->canAccessKlinikVerifikasi()) {
            $verifikasiButton = '<a class="dropdown-item" href="' . route('elits-permohonan-uji-klinik-2.verification', $pid) . '" title="Verifikasi">Verifikasi</a> ';
          }

          if (getAction('read')) {
            $editButton = '<a href="' . route('elits-permohonan-uji-klinik-2.edit', $pid) . '" class="dropdown-item" title="Edit">Edit</a> ';
          }

          if (getAction('delete')) {
            $deleteButton = '<a class="dropdown-item btn-hapus" href="#hapus" data-id="' . $pid . '" data-nama="' . $data->noregister_permohonan_uji_klinik . '" title="Hapus">Hapus</a> ';
          }

          $jenisFlags = isset($registrasiMeta['jenis'][$pid]) ? $registrasiMeta['jenis'][$pid] : [];

          $printFormulirKlinik = '<a class="dropdown-item" href="' . route('elits-permohonan-uji-klinik-2.print-permohonan-uji-klinik-formulir', $pid) . '" target="__blank">
            <i class="fa fa-file-signature mr-2"></i>Print Informed Consent
          </a>';

          $printLembarPersetujuan = '<a class="dropdown-item" href="' . route('elits-permohonan-uji-klinik-2.print-lembar-persetujuan', $pid) . '" target="__blank">
            <i class="fa fa-file-alt mr-2"></i>Print Lembar Persetujuan
          </a>';

          $printkartuMedis = '';

          if ($hasParameter) {
            $printNota = '<a class="dropdown-item" href="' . route('elits-persuratan.invoice.klinik', $pid) . '" target="__blank">
              <i class="fa fa-file-invoice mr-2"></i>Print Invoice
            </a>';
            if ((int) $data->status_pembayaran === 1) {
              $printNota .= '<a class="dropdown-item" href="' . route('elits-persuratan.nota.klinik', $pid) . '" target="__blank">
                <i class="fa fa-file-alt mr-2"></i>Print Nota
              </a>';
            }
          } else {
            $printNota = '';
          }

          $printHasilKlinik = '<a class="dropdown-item pointer" data-href="' . route('elits-permohonan-uji-klinik-2.print-permohonan-uji-klinik-hasil', $pid) . '" target="__blank" data-toggle="modal" data-target="#signOptionModal">
            <i class="fa fa-file-medical mr-2"></i>Print Hasil Klinik
          </a>';

          if (!empty($jenisFlags['2'])) {
            $printHasilRapidAntibody = '<a class="dropdown-item" href="' . route('elits-permohonan-uji-klinik-2.print-permohonan-uji-klinik-hasil-rapid-antibody', $pid) . '" target="__blank">
              <i class="fa fa-vial mr-2"></i>Print Hasil Rapid Antibody
            </a>';
          } else {
            $printHasilRapidAntibody = '';
          }

          if (!empty($jenisFlags['3'])) {
            $printHasilRapidAntigen = '<a class="dropdown-item" href="' . route('elits-permohonan-uji-klinik-2.print-permohonan-uji-klinik-hasil-rapid-antigen', $pid) . '" target="__blank">
              <i class="fa fa-vial mr-2"></i>Print Hasil Rapid Antigen
            </a>';
          } else {
            $printHasilRapidAntigen = '';
          }

          if (!empty($jenisFlags['1'])) {
            $printHasilPcr = '<a class="dropdown-item" href="' . route('elits-permohonan-uji-klinik-2.print-permohonan-uji-klinik-hasil-pcr', $pid) . '" target="__blank">
              <i class="fa fa-dna mr-2"></i>Print Hasil PCR
            </a>';
          } else {
            $printHasilPcr = '';
          }

          if ($data->is_haji == 1) {
            $printAmplopHaji = '<a class="dropdown-item" href="' . route('elits-permohonan-uji-klinik-2.print-amplop', $data->id_permohonan_uji_klinik) . '" target="__blank">
              <i class="fa fa-envelope mr-2"></i>Print Amplop Haji
            </a>';
          } else {
            $printAmplopHaji = '';
          }

          if ($data->id_permohonan_uji_klinik_prolanis != null) {
            if ($data->is_prolanis_gula == 1) {
                $printAmplopProlanisGula = '<a class="dropdown-item" href="' . route('elits-permohonan-uji-klinik-2.print-amplop-prolanis', $data->id_permohonan_uji_klinik) . '" target="__blank">
                  <i class="fa fa-envelope mr-2"></i>Print Amplop Prolanis Gula
                </a>';
            } else {
                $printAmplopProlanisGula = '';
            }

            if ($data->is_prolanis_urine == 1) {
                $printAmplopProlanisUrine = '<a class="dropdown-item" href="' . route('elits-permohonan-uji-klinik-2.print-amplop-prolanis', $data->id_permohonan_uji_klinik) . '" target="__blank">
                  <i class="fa fa-envelope mr-2"></i>Print Amplop Prolanis Urine
                </a>';
            } else {
                $printAmplopProlanisUrine = '';
            }
          } else {
              $printAmplopProlanisGula = '';
              $printAmplopProlanisUrine = '';
          }

          $printLabel = '<a class="dropdown-item" href="' . url('/elits-label-permohonan-uji-klinik-2/print?permohonan_uji_klinik=' . $data->id_permohonan_uji_klinik) . '" target="__blank">
            <i class="fa fa-barcode mr-2"></i>Print Label
          </a>';

          $printMenu = '';
          if ($printFormulirKlinik || $printLembarPersetujuan || $printNota || $printHasilKlinik ||
              $printHasilRapidAntibody || $printHasilRapidAntigen || $printHasilPcr ||
              $printAmplopHaji || $printAmplopProlanisGula || $printAmplopProlanisUrine || $printLabel) {
            $printMenu = '<div class="dropdown-divider"></div>'
              . $printFormulirKlinik
              . $printLembarPersetujuan
              . $printkartuMedis
              . $printNota
              . $printHasilKlinik
              . $printHasilRapidAntibody
              . $printHasilRapidAntigen
              . $printHasilPcr
              . $printAmplopHaji
              . $printAmplopProlanisGula
              . $printAmplopProlanisUrine
              . $printLabel;
          }

          return '<div class="dropdown">'
            . '<button class="btn btn-primary btn-sm dropdown-toggle" type="button" data-toggle="dropdown" data-display="static" aria-expanded="false"><i class="fa fa-cog"></i></button>'
            . '<div class="dropdown-menu dropdown-menu-right">'
            . $parameterButton
            . $verifikasiButton
            . $editButton
            . $deleteButton
            . $printMenu
            . '</div></div>';
        }
      })
      // Override tampilan No Register untuk klinik:
      // jika is_nomor_lab_manual = 1 dan is_nomor_spesimen_manual = 1, tampilkan nomor_lab_manual / nomor_spesimen_manual
      // jika tidak, tampilkan noregister_permohonan_uji_klinik
      ->editColumn('noregister_permohonan_uji_klinik', function ($data) use ($klinikNumberSettings) {
        return $this->formatKlinikDisplayNoregister($data, $klinikNumberSettings);
      })
      ->addColumn('prolanis', function ($data) use ($namaHajiMap) {
        $badges = [];

        if ($data->tipe_pemeriksaan_prolanis == "PROLANIS DM") {
          $badges[] = '<span class="badge badge-info">Prolanis DM</span>';
        } elseif ($data->tipe_pemeriksaan_prolanis == "PROLANIS HT") {
          $badges[] = '<span class="badge badge-info">Prolanis HT</span>';
        } else {
          $badges[] = '<span class="badge badge-primary">Klinik</span>';
        }

        $hajiBadges = $this->formatHajiListBadgesHtml($data, $namaHajiMap, 'simple');
        if ($hajiBadges !== '') {
          $badges[] = $hajiBadges;
        }

        return implode(' ', $badges);
      })
      ->addColumn('status_permohonan', function ($data) {
        if ($data->status_permohonan_uji_klinik == "PARAMETER") {
          $status = '<span class="badge badge-danger">Proses Parameter</span>';
        } elseif ($data->status_permohonan_uji_klinik == "ANALIS") {
          $status = '<span class="badge badge-warning">Proses Analisa</span>';
        } elseif ($data->status_permohonan_uji_klinik == "SELESAI") {
          $status = '<span class="badge badge-success">Selesai</span>';
        } else {
          $status = '';
        }

        return $status;
      })
      ->addColumn('status_registrasi', function ($data) use ($registrasiMeta) {
        // Check doctor_type status
        if ($data->doctor_type == 'lab') {
          // Untuk doctor_type 'lab', cek done_register
          // Pastikan pengecekan yang lebih eksplisit untuk menghindari masalah dengan tipe data
          $doneRegister = $data->done_register;
          
          // Konversi ke boolean untuk memastikan pengecekan yang konsisten
          // Jika done_register adalah 1, '1', true, atau string 'true' -> Sudah Terdiagnosis
          $isDone = false;
          
          // Cek jika done_register adalah true/1/'1'
          if ($doneRegister === true || $doneRegister === 1 || $doneRegister === '1') {
            $isDone = true;
          } elseif (is_string($doneRegister) && strtolower(trim($doneRegister)) === 'true') {
            $isDone = true;
          }
          
          $pid = $data->id_permohonan_uji_klinik;
          $hasPaket = isset($registrasiMeta['has_paket'][$pid]);
          $hasParameter = isset($registrasiMeta['has_parameter'][$pid]);
          $belumPemeriksaan = !$hasPaket && !$hasParameter;
          
          if ($isDone) {
            return '<span class="badge badge-success">Sudah Terdiagnosis</span>';
          } elseif ($belumPemeriksaan) {
            return '<span class="badge badge-warning">Menunggu Diagnosis</span>';
          }

          return '<span class="badge badge-success">Sudah Terdiagnosis</span>';
        }

        return '<span class="badge badge-success">Rujukan Dokter</span>';
      })
      ->addColumn('nama_pasien', function ($data) {
        // Handle if patient name is null (patient deleted or not found)
        if (empty($data->nama_pasien)) {
          return '<span class="text-danger"><i class="fa fa-exclamation-triangle"></i> Pasien Tidak Ditemukan</span>';
        }
        return e($data->nama_pasien);
      })
      ->addIndexColumn();

    if ($canDeleteMassal) {
      $datatable->addColumn('checkbox', function ($data) {
        return '<div class="custom-control custom-checkbox m-0 p-0 text-center">'
          . '<input type="checkbox" class="custom-control-input check-hapus-massal" id="chk_' . e($data->id_permohonan_uji_klinik) . '" value="' . e($data->id_permohonan_uji_klinik) . '" data-nama="' . e($data->noregister_permohonan_uji_klinik) . '">'
          . '<label class="custom-control-label" for="chk_' . e($data->id_permohonan_uji_klinik) . '"></label>'
          . '</div>';
      });
    }

    // Only add status_pembayaran column if user is not DKTR (Dokter)
    if (Auth::user()->getlevel->level != 'DKTR') {
      $isBendahara = (Auth::user()->getlevel->level == 'BNDR');
      $datatable->addColumn("status_pembayaran", function ($data) use ($isBendahara) {
        if ($data->status_pembayaran == 0 || $data->status_pembayaran == null) {
          if ($isBendahara) {
            $status_pembayaran = '<span class="badge badge-danger pointer btn-payment" data-id="' . $data->id_permohonan_uji_klinik . '">Belum Bayar</span>';
          } else {
            $status_pembayaran = '<span class="badge badge-danger">Belum Bayar</span>';
          }
        } elseif ($data->status_pembayaran == 1) {
          $status_pembayaran = '<span class="badge badge-success pointer btn-payment-detail" data-id="' . $data->id_permohonan_uji_klinik . '">Lunas</span>';
        } else {
          $status_pembayaran = '<span class="badge badge-secondary">Unknown</span>';
        }
        return $status_pembayaran;
      });
      $rawCols = ['action', 'status_permohonan', 'status_pembayaran', 'status_registrasi', 'prolanis', 'nama_pasien'];
    } else {
      $rawCols = ['action', 'status_permohonan', 'status_registrasi', 'prolanis', 'nama_pasien'];
    }

    if ($canDeleteMassal) {
      $rawCols[] = 'checkbox';
    }

    $datatable->rawColumns($rawCols);

    $datatable->setTotalRecords($totalDataRecord);
    $datatable->setFilteredRecords($totalFilteredRecord);

    return $datatable->skipPaging()->make(true);
  }

  /**
   * Get statistics for verifikasi lists page
   *
   * @return \Illuminate\Http\JsonResponse
   */
  public function getStatisticsVerifikasi(Request $request)
  {
    $user = auth()->user();
    $userLevel = $user && $user->getlevel ? $user->getlevel->level : null;
    $kodeLab = $user && $user->laboratorium ? $user->laboratorium->kode_laboratorium : null;
    $isDokterLab = $user && $user->getlevel && ($user->getlevel->level == 'dokter-lab' || $user->getlevel->level == 'DKTR');

    // Jika kode laboratorium adalah KIM, KMA, FKA (kimia) atau MBI (mikro), hitung statistik dari tb_samples
    if (in_array($kodeLab, ['KIM', 'KMA', 'FKA', 'MBI'])) {
      return $this->getStatisticsVerifikasiKesmas($request, $kodeLab);
    }

    // Base query - semua permohonan (termasuk yang belum terdiagnosa untuk dihitung di tab "belum_pemeriksaan" dan "all")
    // Untuk tab lain, hanya menghitung data yang sudah ada pemeriksaan
    $baseQuery = PermohonanUjiKlinik2::query();

    // Filter untuk dokter-lab
    if ($isDokterLab) {
      $baseQuery->where(function($q) {
        // Yang sudah id_verification_activity = 4 dan is_done = 1, atau sudah id_verification_activity = 5
        $q->whereExists(function ($subquery) {
        $subquery->select(DB::raw(1))
          ->from('tb_verification_activity_samples')
          ->whereColumn('tb_verification_activity_samples.is_klinik', 'tb_permohonan_uji_klinik_2.id_permohonan_uji_klinik')
          ->where(function ($q) {
            $q->where(function ($q2) {
              $q2->where('id_verification_activity', 4)
                 ->where('is_done', 1);
            })->orWhere('id_verification_activity', 5);
            });
        })
        // ATAU yang belum terdiagnosa (done_register = false) dengan doctor_type = 'lab' - untuk dihitung di tab "belum_pemeriksaan"
        ->orWhere(function($q2) {
          $q2->where('done_register', false)
             ->where('doctor_type', 'lab');
        });
      });
    }

    // Filter untuk analis berdasarkan lab: ANLS = klinik (KLI)
    if ($userLevel == 'ANLS') {
      // Analis Klinik: tampilkan permohonan uji klinik yang memiliki parameter dengan jenis pemeriksaan klinik (0)
      // ATAU yang belum terdiagnosa (done_register = false) 
      // ATAU yang belum ada pemeriksaan yang dipilih (belum ada PermohonanUjiPaketKlinik)
      $baseQuery->where(function($q) {
        // Yang sudah ada parameter dengan jenis pemeriksaan klinik
        $q->whereExists(function ($subquery) {
          $subquery->select(DB::raw(1))
            ->from('tb_permohonan_uji_parameter_klinik')
            ->join('ms_parameter_satuan_klinik', 'ms_parameter_satuan_klinik.id_parameter_satuan_klinik', '=', 'tb_permohonan_uji_parameter_klinik.parameter_satuan_klinik')
            ->whereColumn('tb_permohonan_uji_parameter_klinik.permohonan_uji_klinik', 'tb_permohonan_uji_klinik_2.id_permohonan_uji_klinik')
            ->where('ms_parameter_satuan_klinik.jenis_pemeriksaan_parameter_satuan_klinik', '0')
            ->whereNull('tb_permohonan_uji_parameter_klinik.deleted_at')
            ->whereNull('ms_parameter_satuan_klinik.deleted_at');
        })
        // ATAU yang belum terdiagnosa (done_register = false)
        ->orWhere('done_register', false)
        // ATAU yang belum ada pemeriksaan yang dipilih (belum ada PermohonanUjiPaketKlinik)
        ->orWhereDoesntHave('permohonanujipaketklinik', function($q2) {
          $q2->whereNull('deleted_at');
          });
      });
    }

    // Apply filters
    if ($request->is_filter == '1') {
      $baseQuery->where('is_prolanis_gula', 1);
      if ($request->filter_prolanis_gula && $request->filter_prolanis_gula != 'all') {
        $baseQuery->where('id_permohonan_uji_klinik_prolanis', $request->filter_prolanis_gula);
      }
    } elseif ($request->is_filter == '2') {
      $baseQuery->where('is_prolanis_urine', 1);
      if ($request->filter_prolanis_urine && $request->filter_prolanis_urine != 'all') {
        $baseQuery->where('id_permohonan_uji_klinik_prolanis', $request->filter_prolanis_urine);
      }
    } elseif ($request->is_filter == '4') {
      $baseQuery->where('id_permohonan_uji_klinik_prolanis', '!=', null)->orWhereNotNull('tipe_pemeriksaan_prolanis');
      if ($request->filter_prolanis && $request->filter_prolanis != 'all') {
        $baseQuery->where('id_permohonan_uji_klinik_prolanis', $request->filter_prolanis);
      }
    } elseif ($request->is_filter == '3') {
      $this->applyPemeriksaanHajiFilter($baseQuery, '1', $request->filter_haji);
    } elseif ($request->is_filter == '0') {
      $baseQuery->where('is_prolanis_gula', 0)->where('is_prolanis_urine', 0)->where('is_haji', 0)->whereNull('tipe_pemeriksaan_prolanis');
      $baseQuery->whereIn('is_prolanis_gula', [0, 1, 2, 3]);
    }

    if ($request->is_filter != '3') {
      $this->applyPemeriksaanHajiFilter($baseQuery, $request->filter_pemeriksaan_haji, $request->filter_haji);
    }

    $baseQuery = $this->applyDateRegisterFilterOnKlinikQuery(
      $baseQuery,
      $request->input('date_start'),
      $request->input('date_end')
    );

    $permohonanIds = $baseQuery->pluck('id_permohonan_uji_klinik')->toArray();

    // Hitung statistik per step berdasarkan id_verification_activity dengan urutan 1-6-7-2-3-4-5
    // Logika: Step sebelumnya sudah is_done = 1, step tersebut is_done = 0 atau belum ada
    $stats = [
      'belum_pemeriksaan' => 0, // Step 1 belum selesai atau belum ada
      'pengambilan_sample' => 0, // Step 1 selesai, Step 6 belum selesai atau belum ada
      'penerimaan_sample' => 0, // Step 1, 6 selesai, Step 7 belum selesai atau belum ada
      'pemeriksaan' => 0, // Step 1, 6, 7 selesai, Step 2 belum selesai atau belum ada
      'input_hasil' => 0, // Step 1, 6, 7, 2 selesai, Step 3 belum selesai atau belum ada
      'verifikasi' => 0, // Step 1, 6, 7, 2, 3 selesai, Step 4 belum selesai atau belum ada
      'validasi' => 0, // Step 1, 6, 7, 2, 3, 4 selesai, Step 5 belum selesai atau belum ada
      'selesai' => 0, // Step 1, 6, 7, 2, 3, 4, 5 selesai
    ];

    if (empty($permohonanIds)) {
      return response()->json($stats);
    }

    $hasParameterIds = PermohonanUjiParameterKlinik::whereIn('permohonan_uji_klinik', $permohonanIds)
      ->whereNull('deleted_at')
      ->distinct()
      ->pluck('permohonan_uji_klinik')
      ->flip()
      ->all();

    // Get semua verification activities untuk permohonan ini
    $verificationActivities = DB::table('tb_verification_activity_samples')
      ->whereIn('is_klinik', $permohonanIds)
      ->select('is_klinik', 'id_verification_activity', 'is_done')
      ->get()
      ->groupBy('is_klinik')
      ->map(function ($group) {
        $result = [];
        foreach ($group as $item) {
          $result[$item->id_verification_activity] = $item->is_done;
        }
        return $result;
      });


    // Hitung statistik per step dengan urutan hierarki dari tahap akhir ke awal (5-4-3-2-7-6-1)
    // Setiap permohonan berada tepat di satu posisi aktif
    foreach ($permohonanIds as $id) {
      $activities = $verificationActivities->get($id, []);

      $hasParameter = isset($hasParameterIds[$id]);
      
      if (!$hasParameter) {
        // Data yang belum ada pemeriksaan hanya dihitung di tab "belum_pemeriksaan"
        $stats['belum_pemeriksaan']++;
        continue;
      }
      // Cek status setiap step (1 = sudah done, 0 = belum done, null = belum ada)
      $step1Done = isset($activities[1]) && $activities[1] == 1;
      $step6Done = isset($activities[6]) && $activities[6] == 1;
      $step7Done = isset($activities[7]) && $activities[7] == 1;
      $step2Done = isset($activities[2]) && $activities[2] == 1;
      $step3Done = isset($activities[3]) && $activities[3] == 1;
      $step4Done = isset($activities[4]) && $activities[4] == 1;
      $step5Done = isset($activities[5]) && $activities[5] == 1;

      // 1. Selesai: Step 5 sudah selesai
      if ($step5Done) {
        $stats['selesai']++;
      }
      // 2. Validasi: Step 4 sudah selesai, Step 5 belum selesai
      elseif ($step4Done) {
        $stats['validasi']++;
      }
      // 3. Verifikasi: Step 3 sudah selesai, Step 4 belum selesai
      elseif ($step3Done) {
        $stats['verifikasi']++;
      }
      // 4. Input Hasil: Step 2 sudah selesai, Step 3 belum selesai
      elseif ($step2Done) {
        $stats['input_hasil']++;
      }
      // 5. Pemeriksaan: Step 7 sudah selesai, Step 2 belum selesai
      elseif ($step7Done) {
        $stats['pemeriksaan']++;
      }
      // 6. Penerimaan Sample: Step 6 sudah selesai, Step 7 belum selesai
      elseif ($step6Done) {
        $stats['penerimaan_sample']++;
      }
      // 7. Pengambilan Sample: Step 1 sudah selesai, Step 6 belum selesai, dan belum ada step lanjutan
      elseif ($step1Done) {
        $stats['pengambilan_sample']++;
      }
      // 8. Belum Pemeriksaan: Step 1 belum selesai atau belum ada
      else {
        $stats['belum_pemeriksaan']++;
      }
    }

    return response()->json($stats);
  }

  /**
   * Get statistics for verifikasi lists page (kesmas - from tb_samples)
   *
   * @return \Illuminate\Http\JsonResponse
   */
  private function getStatisticsVerifikasiKesmas(Request $request, $kodeLab)
  {
    // Tentukan kode laboratorium berdasarkan kode lab yang diberikan
    $labCodes = [];
    if (in_array($kodeLab, ['KIM', 'KMA', 'FKA'])) {
      $labCodes = ['KIM', 'KMA', 'FKA'];
    } elseif ($kodeLab == 'MBI') {
      $labCodes = ['MBI'];
    }

    // Query dari tb_samples dengan join ke tb_sample_method dan ms_laboratorium
    // Gunakan struktur yang sama dengan createStatsQuery untuk konsistensi
    $baseQuery = Sample::query()
      ->join('tb_sample_method', function ($join) {
        $join->on('tb_sample_method.sample_id', '=', 'tb_samples.id_samples')
          ->whereNull('tb_sample_method.deleted_at')
          ->whereNull('tb_samples.deleted_at');
      })
      ->join('ms_laboratorium', function ($join) use ($labCodes) {
        $join->on('ms_laboratorium.id_laboratorium', '=', 'tb_sample_method.laboratorium_id')
          ->whereNull('ms_laboratorium.deleted_at')
          ->whereNull('tb_sample_method.deleted_at')
          ->whereIn('ms_laboratorium.kode_laboratorium', $labCodes);
      })
      ->select('tb_samples.id_samples')
      ->groupBy('tb_samples.id_samples');

    // Filter berdasarkan jenis sample jika ada
    if ($request->filter_jenis_sample && $request->filter_jenis_sample != 'all') {
      $baseQuery->where('tb_samples.typesample_samples', $request->filter_jenis_sample);
    }

    $baseQuery = $this->applyDateSendingFilterOnSampleQuery(
      $baseQuery,
      $request->input('date_start'),
      $request->input('date_end')
    );

    $sampleIds = $baseQuery->pluck('tb_samples.id_samples')->toArray();

    // Hitung statistik per step berdasarkan id_verification_activity dengan urutan 1-6-7-2-3-4-5
    // Logika sesuai dengan filter: step sebelumnya sudah is_done = 1, step tersebut is_done = 0 atau belum ada
    $stats = [
      'belum_pemeriksaan' => 0,
      'pengambilan_sample' => 0,
      'penerimaan_sample' => 0, // Step 7 belum selesai atau belum ada
      'pemeriksaan' => 0, // Step 7 sudah selesai, Step 2 belum selesai atau belum ada
      'input_hasil' => 0, // Step 2 sudah selesai, Step 3 belum selesai atau belum ada
      'verifikasi' => 0, // Step 3 sudah selesai, Step 4 belum selesai atau belum ada
      'validasi' => 0, // Step 4 sudah selesai, Step 5 belum selesai atau belum ada
      'selesai' => 0, // Step 5 sudah selesai
    ];

    if (empty($sampleIds)) {
      return response()->json($stats);
    }

    // Helper function untuk membuat base query statistik
    // Menggunakan struktur yang sama persis dengan query data untuk konsistensi
    $createStatsQuery = function() use ($labCodes, $request) {
      $query = Sample::query()
        ->join('tb_sample_method', function ($join) {
          $join->on('tb_sample_method.sample_id', '=', 'tb_samples.id_samples')
            ->whereNull('tb_sample_method.deleted_at')
            ->whereNull('tb_samples.deleted_at');
        })
        ->join('ms_laboratorium', function ($join) use ($labCodes) {
          $join->on('ms_laboratorium.id_laboratorium', '=', 'tb_sample_method.laboratorium_id')
            ->whereNull('ms_laboratorium.deleted_at')
            ->whereNull('tb_sample_method.deleted_at')
            ->whereIn('ms_laboratorium.kode_laboratorium', $labCodes);
        })
        ->leftjoin('tb_permohonan_uji', function ($join) {
          $join->on('tb_permohonan_uji.id_permohonan_uji', '=', 'tb_samples.permohonan_uji_id')
            ->whereNull('tb_permohonan_uji.deleted_at')
            ->whereNull('tb_samples.deleted_at');
        })
        ->leftjoin('ms_customer', function ($join) {
          $join->on('ms_customer.id_customer', '=', 'tb_permohonan_uji.customer_id')
            ->whereNull('ms_customer.deleted_at')
            ->whereNull('tb_permohonan_uji.deleted_at');
        })
        ->leftjoin('ms_packet', function ($join) {
          $join->on('ms_packet.id_packet', '=', 'tb_samples.packet_id')
            ->whereNull('ms_packet.deleted_at');
        })
        ->leftjoin('tb_sample_method as sm_for_param', function ($join) use ($labCodes) {
          $join->on('sm_for_param.sample_id', '=', 'tb_samples.id_samples')
            ->whereNull('sm_for_param.deleted_at');
        })
        ->leftjoin('ms_laboratorium as lab_for_param', function ($join) use ($labCodes) {
          $join->on('lab_for_param.id_laboratorium', '=', 'sm_for_param.laboratorium_id')
            ->whereNull('lab_for_param.deleted_at')
            ->whereIn('lab_for_param.kode_laboratorium', $labCodes);
        })
        ->leftjoin('ms_method', function ($join) {
          $join->on('ms_method.id_method', '=', 'sm_for_param.method_id')
            ->whereNull('ms_method.deleted_at');
        })
        ->select('tb_samples.id_samples')
        ->groupBy('tb_samples.id_samples');
      
      // Filter berdasarkan jenis sample jika ada
      if ($request->filter_jenis_sample && $request->filter_jenis_sample != 'all') {
        $query->where('tb_samples.typesample_samples', $request->filter_jenis_sample);
      }

      $query = $this->applyDateSendingFilterOnSampleQuery(
        $query,
        $request->input('date_start'),
        $request->input('date_end')
      );

      return $query;
    };

    // Selesai: Step 5 (Validasi) sudah selesai
    $selesaiQuery = $createStatsQuery()
      ->whereExists(function ($subquery) {
        $subquery->select(DB::raw(1))
          ->from('tb_verification_activity_samples')
          ->whereColumn('tb_verification_activity_samples.id_sample', 'tb_samples.id_samples')
          ->whereNull('tb_verification_activity_samples.is_klinik')
          ->where('tb_verification_activity_samples.id_verification_activity', 5)
          ->where('tb_verification_activity_samples.is_done', 1);
      });
    $stats['selesai'] = DB::table(DB::raw("({$selesaiQuery->toSql()}) as subquery"))
      ->mergeBindings($selesaiQuery->getQuery())
      ->count();

    // Validasi: Step 4 sudah selesai, Step 5 belum selesai atau belum ada
    $validasiQuery = $createStatsQuery()
      ->whereExists(function ($subquery) {
        $subquery->select(DB::raw(1))
          ->from('tb_verification_activity_samples')
          ->whereColumn('tb_verification_activity_samples.id_sample', 'tb_samples.id_samples')
          ->whereNull('tb_verification_activity_samples.is_klinik')
          ->where('tb_verification_activity_samples.id_verification_activity', 4)
          ->where('tb_verification_activity_samples.is_done', 1);
      })
      ->where(function ($q) {
        $q->whereNotExists(function ($subquery) {
          $subquery->select(DB::raw(1))
            ->from('tb_verification_activity_samples')
            ->whereColumn('tb_verification_activity_samples.id_sample', 'tb_samples.id_samples')
            ->whereNull('tb_verification_activity_samples.is_klinik')
            ->where('tb_verification_activity_samples.id_verification_activity', 5);
        })->orWhereExists(function ($subquery) {
          $subquery->select(DB::raw(1))
            ->from('tb_verification_activity_samples')
            ->whereColumn('tb_verification_activity_samples.id_sample', 'tb_samples.id_samples')
            ->whereNull('tb_verification_activity_samples.is_klinik')
            ->where('tb_verification_activity_samples.id_verification_activity', 5)
            ->where('tb_verification_activity_samples.is_done', 0);
        });
      });
    $stats['validasi'] = DB::table(DB::raw("({$validasiQuery->toSql()}) as subquery"))
      ->mergeBindings($validasiQuery->getQuery())
      ->count();

    // Verifikasi: Step 3 sudah selesai, Step 4 belum selesai atau belum ada
    $verifikasiQuery = $createStatsQuery()
      ->whereExists(function ($subquery) {
        $subquery->select(DB::raw(1))
          ->from('tb_verification_activity_samples')
          ->whereColumn('tb_verification_activity_samples.id_sample', 'tb_samples.id_samples')
          ->whereNull('tb_verification_activity_samples.is_klinik')
          ->where('tb_verification_activity_samples.id_verification_activity', 3)
          ->where('tb_verification_activity_samples.is_done', 1);
      })
      ->where(function ($q) {
        $q->whereNotExists(function ($subquery) {
          $subquery->select(DB::raw(1))
            ->from('tb_verification_activity_samples')
            ->whereColumn('tb_verification_activity_samples.id_sample', 'tb_samples.id_samples')
            ->whereNull('tb_verification_activity_samples.is_klinik')
            ->where('tb_verification_activity_samples.id_verification_activity', 4);
        })->orWhereExists(function ($subquery) {
          $subquery->select(DB::raw(1))
            ->from('tb_verification_activity_samples')
            ->whereColumn('tb_verification_activity_samples.id_sample', 'tb_samples.id_samples')
            ->whereNull('tb_verification_activity_samples.is_klinik')
            ->where('tb_verification_activity_samples.id_verification_activity', 4)
            ->where('tb_verification_activity_samples.is_done', 0);
        });
      });
    $stats['verifikasi'] = DB::table(DB::raw("({$verifikasiQuery->toSql()}) as subquery"))
      ->mergeBindings($verifikasiQuery->getQuery())
      ->count();

    // Input Hasil: Step 2 sudah selesai, Step 3 belum selesai atau belum ada
    $inputHasilQuery = $createStatsQuery()
      ->whereExists(function ($subquery) {
        $subquery->select(DB::raw(1))
          ->from('tb_verification_activity_samples')
          ->whereColumn('tb_verification_activity_samples.id_sample', 'tb_samples.id_samples')
          ->whereNull('tb_verification_activity_samples.is_klinik')
          ->where('tb_verification_activity_samples.id_verification_activity', 2)
          ->where('tb_verification_activity_samples.is_done', 1);
      })
      ->where(function ($q) {
        $q->whereNotExists(function ($subquery) {
          $subquery->select(DB::raw(1))
            ->from('tb_verification_activity_samples')
            ->whereColumn('tb_verification_activity_samples.id_sample', 'tb_samples.id_samples')
            ->whereNull('tb_verification_activity_samples.is_klinik')
            ->where('tb_verification_activity_samples.id_verification_activity', 3);
        })->orWhereExists(function ($subquery) {
          $subquery->select(DB::raw(1))
            ->from('tb_verification_activity_samples')
            ->whereColumn('tb_verification_activity_samples.id_sample', 'tb_samples.id_samples')
            ->whereNull('tb_verification_activity_samples.is_klinik')
            ->where('tb_verification_activity_samples.id_verification_activity', 3)
            ->where('tb_verification_activity_samples.is_done', 0);
        });
      });
    $stats['input_hasil'] = DB::table(DB::raw("({$inputHasilQuery->toSql()}) as subquery"))
      ->mergeBindings($inputHasilQuery->getQuery())
      ->count();

    // Pemeriksaan: Step 7 sudah selesai, Step 2 belum selesai atau belum ada
    $pemeriksaanQuery = $createStatsQuery()
      ->whereExists(function ($subquery) {
        $subquery->select(DB::raw(1))
          ->from('tb_verification_activity_samples')
          ->whereColumn('tb_verification_activity_samples.id_sample', 'tb_samples.id_samples')
          ->whereNull('tb_verification_activity_samples.is_klinik')
          ->where('tb_verification_activity_samples.id_verification_activity', 7)
          ->where('tb_verification_activity_samples.is_done', 1);
      })
      ->where(function ($q) {
        $q->whereNotExists(function ($subquery) {
          $subquery->select(DB::raw(1))
            ->from('tb_verification_activity_samples')
            ->whereColumn('tb_verification_activity_samples.id_sample', 'tb_samples.id_samples')
            ->whereNull('tb_verification_activity_samples.is_klinik')
            ->where('tb_verification_activity_samples.id_verification_activity', 2);
        })->orWhereExists(function ($subquery) {
          $subquery->select(DB::raw(1))
            ->from('tb_verification_activity_samples')
            ->whereColumn('tb_verification_activity_samples.id_sample', 'tb_samples.id_samples')
            ->whereNull('tb_verification_activity_samples.is_klinik')
            ->where('tb_verification_activity_samples.id_verification_activity', 2)
            ->where('tb_verification_activity_samples.is_done', 0);
        });
      });
    $stats['pemeriksaan'] = DB::table(DB::raw("({$pemeriksaanQuery->toSql()}) as subquery"))
      ->mergeBindings($pemeriksaanQuery->getQuery())
      ->count();

    // Penerimaan Sample: Step 7 belum selesai atau belum ada
    $penerimaanSampleQuery = $createStatsQuery()
      ->where(function ($q) {
        $q->whereNotExists(function ($subquery) {
          $subquery->select(DB::raw(1))
            ->from('tb_verification_activity_samples')
            ->whereColumn('tb_verification_activity_samples.id_sample', 'tb_samples.id_samples')
            ->whereNull('tb_verification_activity_samples.is_klinik')
            ->where('tb_verification_activity_samples.id_verification_activity', 7);
        })->orWhereExists(function ($subquery) {
          $subquery->select(DB::raw(1))
            ->from('tb_verification_activity_samples')
            ->whereColumn('tb_verification_activity_samples.id_sample', 'tb_samples.id_samples')
            ->whereNull('tb_verification_activity_samples.is_klinik')
            ->where('tb_verification_activity_samples.id_verification_activity', 7)
            ->where('tb_verification_activity_samples.is_done', 0);
        });
      });
    $stats['penerimaan_sample'] = DB::table(DB::raw("({$penerimaanSampleQuery->toSql()}) as subquery"))
      ->mergeBindings($penerimaanSampleQuery->getQuery())
      ->count();

    return response()->json($stats);
  }

  /**
   * Show the verifikasi lists page
   *
   * @return \Illuminate\Http\Response
   */
  public function indexVerifikasi()
  {
    $user = auth()->user();
    $userLevel = $user && $user->getlevel ? $user->getlevel->level : null;
    $kodeLab = $user && $user->laboratorium ? $user->laboratorium->kode_laboratorium : null;
    $isKesmas = in_array($kodeLab, ['KIM', 'KMA', 'FKA', 'MBI']);
    $isKlinik = ($kodeLab == 'KLI');
    
    // Untuk kesmas, ambil daftar jenis sample
    $sampleTypes = [];
    if ($isKesmas) {
      $sampleTypes = SampleType::orderBy('name_sample_type', 'asc')
        ->whereNull('deleted_at')
        ->get();
    }
    
    // Ambil daftar grup untuk ALAB, PLAB, ANLS dengan mikro atau kimia
    $groups = [];
    if (in_array($userLevel, ['ALAB', 'PLAB', 'ANLS']) && ($isKesmas || $isKlinik)) {
      $groups = $this->getGroupsForUser($userLevel, $kodeLab);
    }
    
    return view('masterweb::module.admin.laboratorium.permohonan-uji-klinik-2.pagination-verifikasi', [
      'userLevel' => $userLevel,
      'kodeLab' => $kodeLab,
      'isKesmas' => $isKesmas,
      'isKlinik' => $isKlinik,
      'sampleTypes' => $sampleTypes,
      'groups' => $groups
    ]);
  }

  /**
   * Get data for verifikasi lists page (done_register = true)
   *
   * @return \Illuminate\Http\Response
   */
  public function data_permohonan_uji_klinik_verifikasi(Request $request)
  {
    $user = auth()->user();
    $userLevel = $user && $user->getlevel ? $user->getlevel->level : null;
    $kodeLab = $user && $user->laboratorium ? $user->laboratorium->kode_laboratorium : null;
    
    // Jika kode laboratorium adalah KIM, KMA, FKA (kimia) atau MBI (mikro), query dari tb_samples
    // Jika kode laboratorium adalah KLI (klinik) atau null/role lain, query dari tb_permohonan_uji_klinik_2
    if (in_array($kodeLab, ['KIM', 'KMA', 'FKA', 'MBI'])) {
      // Tentukan userLevel untuk badge berdasarkan kode lab
      $badgeLevel = in_array($kodeLab, ['KIM', 'KMA', 'FKA']) ? 'ALAB' : 'KLAB';
      return $this->data_samples_verifikasi($request, $badgeLevel, $kodeLab);
    }
    
    // Jika kode laboratorium adalah KLI (klinik) atau null/role lain, query dari tb_permohonan_uji_klinik_2
    // Filter: show records where done_register = true (sudah terdiagnosa) 
    //        OR done_register = false (belum terdiagnosa)
    //        OR belum ada pemeriksaan yang dipilih (belum ada PermohonanUjiPaketKlinik)
    // Ini berarti menampilkan semua data, termasuk yang belum terdiagnosa atau belum dipilih pemeriksaannya
    // Bungkus semua kondisi dalam closure untuk memastikan data yang belum terdiagnosa tetap muncul
    $query = PermohonanUjiKlinik2::orderBy('tb_permohonan_uji_klinik_2.created_at', 'desc');

    // Filter untuk dokter-lab: hanya tampilkan yang sudah id_verification_activity = 4 dan is_done = 1, atau sudah id_verification_activity = 5
    // ATAU yang belum terdiagnosa (done_register = false) untuk menampilkan yang menunggu diagnosis dokter
    // Cek apakah user adalah dokter-lab
    if ($user && $user->getlevel && ($user->getlevel->level == 'dokter-lab' || $user->getlevel->level == 'DKTR')) {
      $query->where(function($q) {
        // Yang sudah id_verification_activity = 4 dan is_done = 1, atau sudah id_verification_activity = 5
        $q->whereExists(function ($subquery) {
          $subquery->select(DB::raw(1))
            ->from('tb_verification_activity_samples')
            ->whereColumn('tb_verification_activity_samples.is_klinik', 'tb_permohonan_uji_klinik_2.id_permohonan_uji_klinik')
            ->where(function ($q) {
              // Kondisi: (id_verification_activity = 4 dan is_done = 1) ATAU (id_verification_activity = 5)
              $q->where(function ($q2) {
                $q2->where('id_verification_activity', 4)
                   ->where('is_done', 1);
              })->orWhere('id_verification_activity', 5);
            });
        })
        // ATAU yang belum terdiagnosa (done_register = false) dengan doctor_type = 'lab' - untuk menampilkan yang menunggu diagnosis dokter
        ->orWhere(function($q2) {
          $q2->where('done_register', false)
             ->where('doctor_type', 'lab');
        });
      });
    }

    // Filter untuk analis berdasarkan lab: ANLS = klinik (KLI)
    if ($userLevel == 'ANLS') {
      // Analis Klinik: tampilkan permohonan uji klinik yang memiliki parameter dengan jenis pemeriksaan klinik (0)
      // ATAU yang belum terdiagnosa (done_register = false) 
      // ATAU yang belum ada pemeriksaan yang dipilih (belum ada PermohonanUjiPaketKlinik)
      $query->where(function($q) {
        // Yang sudah ada parameter dengan jenis pemeriksaan klinik
        $q->whereExists(function ($subquery) {
          $subquery->select(DB::raw(1))
            ->from('tb_permohonan_uji_parameter_klinik')
            ->join('ms_parameter_satuan_klinik', 'ms_parameter_satuan_klinik.id_parameter_satuan_klinik', '=', 'tb_permohonan_uji_parameter_klinik.parameter_satuan_klinik')
            ->whereColumn('tb_permohonan_uji_parameter_klinik.permohonan_uji_klinik', 'tb_permohonan_uji_klinik_2.id_permohonan_uji_klinik')
            ->where('ms_parameter_satuan_klinik.jenis_pemeriksaan_parameter_satuan_klinik', '0')
            ->whereNull('tb_permohonan_uji_parameter_klinik.deleted_at')
            ->whereNull('ms_parameter_satuan_klinik.deleted_at');
        })
        // ATAU yang belum terdiagnosa (done_register = false)
        ->orWhere('done_register', false)
        // ATAU yang belum ada pemeriksaan yang dipilih (belum ada PermohonanUjiPaketKlinik)
        ->orWhereDoesntHave('permohonanujipaketklinik', function($q2) {
          $q2->whereNull('deleted_at');
        });
      });
    }

    // Filter by group for ALAB, PLAB, ANLS with mikro or kimia
    $groupFilter = $request->filter_grup;
    if (in_array($userLevel, ['ALAB', 'PLAB', 'ANLS']) && $groupFilter && $groupFilter != 'all') {
      // Get Petugas names in the selected group (based on lab_id combination)
      $groupLabIds = explode(',', $groupFilter);
      $groupLabIds = array_map('trim', $groupLabIds);
      
      // Get Petugas with matching lab_id combination
      $petugasNamesInGroup = Petugas::whereNotNull('role')->get()->filter(function($petugas) use ($groupLabIds) {
        $labIds = is_array($petugas->lab_id) ? $petugas->lab_id : json_decode($petugas->lab_id, true);
        if (!is_array($labIds)) {
          $labIds = $labIds ? [$labIds] : [];
        }
        sort($labIds);
        return implode(',', $labIds) == implode(',', $groupLabIds);
      })->map(function($petugas) {
        return trim($petugas->nama);
      })->filter()->unique()->values()->toArray();
      
      if (!empty($petugasNamesInGroup)) {
        // Filter verification activity samples by Petugas names in the group
        // This filters records where verification activity samples have nama_petugas from Petugas in the group
        $query->whereExists(function($subquery) use ($petugasNamesInGroup) {
          $subquery->select(DB::raw(1))
            ->from('tb_verification_activity_samples')
            ->whereColumn('tb_verification_activity_samples.is_klinik', 'tb_permohonan_uji_klinik_2.id_permohonan_uji_klinik')
            ->where(function($q) use ($petugasNamesInGroup) {
              foreach ($petugasNamesInGroup as $index => $nama) {
                if ($index === 0) {
                  $q->where('tb_verification_activity_samples.nama_petugas', 'LIKE', '%' . $nama . '%');
                } else {
                  $q->orWhere('tb_verification_activity_samples.nama_petugas', 'LIKE', '%' . $nama . '%');
                }
              }
            });
        });
      } else {
        // If no Petugas in group, return empty result
        $query->whereRaw('1 = 0');
      }
    }

    // Apply other filters
    if ($request->is_filter == '1') {
      $query->where('is_prolanis_gula', 1);

      if ($request->filter_prolanis_gula && $request->filter_prolanis_gula != 'all') {
        $query->where('id_permohonan_uji_klinik_prolanis', $request->filter_prolanis_gula);
      }
    } elseif ($request->is_filter == '2') {
      $query->where('is_prolanis_urine', 1);

      if ($request->filter_prolanis_urine && $request->filter_prolanis_urine != 'all') {
        $query->where('id_permohonan_uji_klinik_prolanis', $request->filter_prolanis_urine);
      }
    } elseif ($request->is_filter == '4') {
      $query->where('id_permohonan_uji_klinik_prolanis', '!=', null)->orWhereNotNull('tipe_pemeriksaan_prolanis');

      if ($request->filter_prolanis && $request->filter_prolanis != 'all') {
        $query->where('id_permohonan_uji_klinik_prolanis', $request->filter_prolanis);
      }
    } elseif ($request->is_filter == '3') {
      $this->applyPemeriksaanHajiFilter($query, '1', $request->filter_haji);
    } elseif ($request->is_filter == '0') {
      $query->where('is_prolanis_gula', 0)->where('is_prolanis_urine', 0)->where('is_haji', 0)->whereNull('tipe_pemeriksaan_prolanis');
      $query->whereIn('is_prolanis_gula', [0, 1, 2, 3]);
    }

    // Filter mandiri: Pemeriksaan Haji (Semua / Ya / Tidak)
    // Tidak dobel-apply jika Tipe Permohonan sudah "Haji" (is_filter=3)
    if ($request->is_filter != '3') {
      $this->applyPemeriksaanHajiFilter($query, $request->filter_pemeriksaan_haji, $request->filter_haji);
    }

    // Apply status filter
    // Logika: Step sebelumnya harus is_done = 1, tapi step yang difilter harus is_done = 0 (belum selesai)
    // Validasi filter berdasarkan level user dan kode lab
    $user = auth()->user();
    $userLevel = $user && $user->getlevel ? $user->getlevel->level : null;
    $kodeLab = $user && $user->laboratorium ? $user->laboratorium->kode_laboratorium : null;
    $isKesmas = in_array($kodeLab, ['KIM', 'KMA', 'FKA', 'MBI']);
    $isKlinik = ($kodeLab == 'KLI');
    
    // Tentukan filter yang diizinkan berdasarkan level dan kode lab
    $allowedFilters = [];
    $petugasFilters = \Smt\Masterweb\Helpers\PetugasStepAccess::usesPetugasSteps($userLevel)
      ? \Smt\Masterweb\Helpers\PetugasStepAccess::getAllowedFilters($user, true, true)
      : [];

    if (!empty($petugasFilters)) {
      // Analis / Tim Teknis: step dari relasi petugas.role (ms_verification_activities)
      $allowedFilters = $petugasFilters;
    } elseif ($userLevel == 'KSKM') {
      // Kasie kesmas: semua pemeriksaan + langkah verifikasi sesuai lab
      $allowedFilters = ['all', 'penerimaan_sample', 'pemeriksaan', 'input_hasil', 'verifikasi', 'validasi', 'selesai'];
    } elseif ($isKesmas) {
      // Kesmas (KIM, KMA, FKA, MBI): semua filter termasuk all dan selesai
      $allowedFilters = ['all', 'penerimaan_sample', 'pemeriksaan', 'input_hasil', 'verifikasi', 'validasi', 'selesai'];
    } elseif (\Smt\Masterweb\Helpers\SampleCollectorAccess::isKlinik($userLevel)) {
      // Pengambil sampel klinik (SOLK): hanya pengambilan_sample
      $allowedFilters = ['pengambilan_sample'];
    } elseif ($userLevel == 'KSKL') {
      // Kasie klinik: pengambilan → penerimaan → pemeriksaan → ...
      $allowedFilters = ['all', 'pengambilan_sample', 'penerimaan_sample', 'pemeriksaan', 'input_hasil', 'verifikasi', 'validasi', 'selesai'];
    } elseif ($isKlinik || $userLevel == 'ANLS') {
      // Klinik (KLI) / ANLS
      $allowedFilters = ['all', 'pengambilan_sample', 'pemeriksaan', 'input_hasil', 'verifikasi', 'validasi', 'selesai'];
    } elseif ($userLevel == 'RGSTR') {
      $allowedFilters = ['all', 'belum_pemeriksaan', 'selesai'];
    } elseif ($userLevel == 'DKTR') {
      $allowedFilters = ['all', 'belum_pemeriksaan', 'validasi', 'selesai'];
    } else {
      $allowedFilters = ['all', 'belum_pemeriksaan', 'pengambilan_sample', 'penerimaan_sample', 'pemeriksaan', 'input_hasil', 'verifikasi', 'validasi', 'selesai'];
    }
    
    if ($request->status_filter && $request->status_filter != '') {
      $statusFilter = $request->status_filter;
      
      // Validasi: jika filter tidak diizinkan untuk level user, set ke 'all'
      if (!in_array($statusFilter, $allowedFilters)) {
        $statusFilter = 'all';
      }
      
      if ($statusFilter == 'belum_pemeriksaan') {
        // Step 1 (id_verification_activity = 1) belum selesai atau belum ada
        // Dan tidak punya data tb_permohonan_uji_parameter_klinik atau null
        // ATAU yang belum terdiagnosa (done_register = false)
        $query->where(function ($q) {
          // Tidak punya data tb_permohonan_uji_parameter_klinik atau null
          $q->whereNotExists(function ($subquery) {
            $subquery->select(DB::raw(1))
              ->from('tb_permohonan_uji_parameter_klinik')
              ->whereColumn('tb_permohonan_uji_parameter_klinik.permohonan_uji_klinik', 'tb_permohonan_uji_klinik_2.id_permohonan_uji_klinik');
          })
          // ATAU yang belum terdiagnosa (done_register = false) - untuk menampilkan yang menunggu diagnosis dokter
          ->orWhere('done_register', false);
        });
      } elseif ($statusFilter == 'pengambilan_sample') {
        // Step 1 selesai, Step 6 (id_verification_activity = 6) belum selesai,
        // dan belum ada step lanjutan (7, 2, 3, 4, 5) yang selesai
        // Hanya tampilkan data yang sudah ada pemeriksaan (sudah ada tb_permohonan_uji_parameter_klinik)
        $query->where(function($mainQ) {
          $mainQ->whereExists(function ($subquery) {
            $subquery->select(DB::raw(1))
              ->from('tb_verification_activity_samples')
              ->whereColumn('tb_verification_activity_samples.is_klinik', 'tb_permohonan_uji_klinik_2.id_permohonan_uji_klinik')
              ->where('id_verification_activity', 1)
              ->where('is_done', 1);
          })->whereNotExists(function ($subquery) {
            $subquery->select(DB::raw(1))
              ->from('tb_verification_activity_samples')
              ->whereColumn('tb_verification_activity_samples.is_klinik', 'tb_permohonan_uji_klinik_2.id_permohonan_uji_klinik')
              ->where('id_verification_activity', 6)
              ->where('is_done', 1);
          })->whereNotExists(function ($subquery) {
            $subquery->select(DB::raw(1))
              ->from('tb_verification_activity_samples')
              ->whereColumn('tb_verification_activity_samples.is_klinik', 'tb_permohonan_uji_klinik_2.id_permohonan_uji_klinik')
              ->whereIn('id_verification_activity', [7, 2, 3, 4, 5])
              ->where('is_done', 1);
          })->where(function($q) {
            $q->whereNull('status_permohonan_uji_klinik')
              ->orWhere('status_permohonan_uji_klinik', '!=', 'SELESAI');
          })->where(function ($q) {
            // Harus sudah ada data tb_permohonan_uji_parameter_klinik (sudah ada pemeriksaan)
            $q->whereExists(function ($subquery) {
              $subquery->select(DB::raw(1))
                ->from('tb_permohonan_uji_parameter_klinik')
                ->whereColumn('tb_permohonan_uji_parameter_klinik.permohonan_uji_klinik', 'tb_permohonan_uji_klinik_2.id_permohonan_uji_klinik')
                ->whereNull('tb_permohonan_uji_parameter_klinik.deleted_at');
            });
          });
        });
      } elseif ($statusFilter == 'penerimaan_sample') {
        // Step 1, 6 selesai, Step 7 (id_verification_activity = 7) belum selesai atau belum ada
        // Hanya tampilkan data yang sudah ada pemeriksaan (sudah ada tb_permohonan_uji_parameter_klinik)
        $query->where(function($mainQ) {
          $mainQ->whereExists(function ($subquery) {
            $subquery->select(DB::raw(1))
              ->from('tb_verification_activity_samples')
              ->whereColumn('tb_verification_activity_samples.is_klinik', 'tb_permohonan_uji_klinik_2.id_permohonan_uji_klinik')
              ->where('id_verification_activity', 1)
              ->where('is_done', 1);
          })->whereExists(function ($subquery) {
            $subquery->select(DB::raw(1))
              ->from('tb_verification_activity_samples')
              ->whereColumn('tb_verification_activity_samples.is_klinik', 'tb_permohonan_uji_klinik_2.id_permohonan_uji_klinik')
              ->where('id_verification_activity', 6)
              ->where('is_done', 1);
          })->where(function ($q) {
            $q->whereNotExists(function ($subquery) {
              $subquery->select(DB::raw(1))
                ->from('tb_verification_activity_samples')
                ->whereColumn('tb_verification_activity_samples.is_klinik', 'tb_permohonan_uji_klinik_2.id_permohonan_uji_klinik')
                ->where('id_verification_activity', 7);
            })->orWhereExists(function ($subquery) {
              $subquery->select(DB::raw(1))
                ->from('tb_verification_activity_samples')
                ->whereColumn('tb_verification_activity_samples.is_klinik', 'tb_permohonan_uji_klinik_2.id_permohonan_uji_klinik')
                ->where('id_verification_activity', 7)
                ->where('is_done', 0);
            });
          })->where(function ($q) {
            // Harus sudah ada data tb_permohonan_uji_parameter_klinik (sudah ada pemeriksaan)
            $q->whereExists(function ($subquery) {
              $subquery->select(DB::raw(1))
                ->from('tb_permohonan_uji_parameter_klinik')
