        $pid = $data->id_permohonan_uji_klinik;
        $hasParameter = isset($verifikasiMeta['has_parameter'][$pid]);
        $steps = $verificationStepsMap[$pid] ?? [];

        return $this->buildKlinikVerifikasiActionHtml($data, $hasParameter, $steps);
      })
