        if ($data->tipe_pemeriksaan_prolanis == "PROLANIS DM") {
          $badges[] = '<span class="badge badge-info">Prolanis DM</span>';
        } elseif ($data->tipe_pemeriksaan_prolanis == "PROLANIS HT") {
          $badges[] = '<span class="badge badge-info">Prolanis HT</span>';
        } else {
          $badges[] = '<span class="badge badge-primary">Klinik</span>';
        }

        $hajiBadges = $this->formatHajiListBadgesHtml($data, $namaHajiMap, 'simple');
        if ($hajiBadges !== '') {
          $badges[] = $hajiBadges;
        }

        return implode(' ', $badges);
      })
      ->addColumn('status_permohonan', function ($data) {
        if ($data->status_permohonan_uji_klinik == "PARAMETER") {
          $status = '<span class="badge badge-danger">Proses Pemeriksaan</span>';
        } elseif ($data->status_permohonan_uji_klinik == "ANALIS") {
          $status = '<span class="badge badge-warning">Proses Pemeriksaan</span>';
        } elseif ($data->status_permohonan_uji_klinik == "SELESAI") {
          $status = '<span class="badge badge-success">Selesai</span>';
        } else {
          $status = '';
        }

        return $status;
      })
      ->addColumn('status_registrasi', function ($data) use ($statusFilterForColumn, $verifikasiMeta) {
        // Check doctor_type status
        if ($data->doctor_type == 'lab') {
          // Untuk doctor_type 'lab', cek done_register
          // Pastikan pengecekan yang lebih eksplisit untuk menghindari masalah dengan tipe data
          $doneRegister = $data->done_register;
          
          // Konversi ke boolean untuk memastikan pengecekan yang konsisten
          // Jika done_register adalah 1, '1', true, atau string 'true' -> Sudah Terdiagnosis
          $isDone = false;
          
          // Cek jika done_register adalah true/1/'1'
          if ($doneRegister === true || $doneRegister === 1 || $doneRegister === '1') {
            $isDone = true;
          } elseif (is_string($doneRegister) && strtolower(trim($doneRegister)) === 'true') {
            $isDone = true;
          }
          
          $pid = $data->id_permohonan_uji_klinik;
          $hasPaket = isset($verifikasiMeta['has_paket'][$pid]);
          $hasParameter = isset($verifikasiMeta['has_parameter'][$pid]);
          $belumPemeriksaan = !$hasPaket && !$hasParameter;

          $isBelumPemeriksaanTab = ($statusFilterForColumn == 'belum_pemeriksaan' || $statusFilterForColumn == 'all' || $statusFilterForColumn == '');

          if ($isDone) {
            return '<span class="badge badge-success">Sudah Terdiagnosis</span>';
          } elseif ($belumPemeriksaan && $isBelumPemeriksaanTab) {
            return '<span class="badge badge-warning">Menunggu Diagnosis</span>';
          }

          return '<span class="badge badge-success">Sudah Terdiagnosis</span>';
        }

        return '<span class="badge badge-success">Rujukan Dokter</span>';
      })
      ->addColumn('nama_pasien', function ($data) {
        if (empty($data->nama_pasien)) {
          return '<span class="text-danger"><i class="fa fa-exclamation-triangle"></i> Pasien Tidak Ditemukan</span>';
        }
        return e($data->nama_pasien);
      })
      ->addIndexColumn();

    $isBendaharaReg = (Auth::user()->getlevel->level == 'BNDR');
    $datatable->addColumn("status_pembayaran", function ($data) use ($isBendaharaReg) {
      if ($data->status_pembayaran == 0 || $data->status_pembayaran == null) {
        if ($isBendaharaReg) {
          $status_pembayaran = '<span class="badge badge-danger pointer btn-payment" data-id="' . $data->id_permohonan_uji_klinik . '">Belum Bayar</span>';
        } else {
          $status_pembayaran = '<span class="badge badge-danger">Belum Bayar</span>';
        }
      } elseif ($data->status_pembayaran == 1) {
        $status_pembayaran = '<span class="badge badge-success pointer btn-payment-detail" data-id="' . $data->id_permohonan_uji_klinik . '">Lunas</span>';
      } else {
        $status_pembayaran = '<span class="badge badge-secondary">Unknown</span>';
      }
      return $status_pembayaran;
    });
    $datatable->rawColumns(['action', 'status_permohonan', 'status_pembayaran', 'status_registrasi', 'prolanis', 'nama_pasien']);

    $datatable->setTotalRecords($totalDataRecord);
    $datatable->setFilteredRecords($totalFilteredRecord);

    return $datatable->skipPaging()->make(true);
    } catch (\Throwable $e) {
      \Log::error('Failed to build klinik verifikasi datatable', [
        'message' => $e->getMessage(),
        'file' => $e->getFile(),
        'line' => $e->getLine(),
      ]);

      return response()->json([
        'draw' => (int) $request->input('draw', 0),
        'recordsTotal' => 0,
        'recordsFiltered' => 0,
        'data' => [],
        'error' => 'Gagal memuat data verifikasi.',
      ], 200);
    }
  }

  /**
   * Get data for verifikasi lists page from tb_samples (for ALAB/KLAB)
   *
   * @return \Illuminate\Http\Response
   */
  private function data_samples_verifikasi(Request $request, $userLevel, $kodeLab = null)
  {
    $labCodes = $this->resolveKesmasVerifikasiLabCodes($userLevel, $kodeLab);

    $query = $this->buildKesmasVerifikasiSampleListQuery($labCodes);

    if ($request->filter_jenis_sample && $request->filter_jenis_sample != 'all') {
      $query->where('tb_samples.typesample_samples', $request->filter_jenis_sample);
    }

    $query = $this->applyDateSendingFilterOnSampleQuery(
      $query,
      $request->input('date_start'),
      $request->input('date_end')
    );

    $this->applyKesmasVerifikasiSampleStatusFilter($query, $request->status_filter ?? '');

    $query = $this->applySampleRowListOrdering($query, 'tb_samples', 'ms_laboratorium.kode_laboratorium');

    $limit_val = (int) $request->input('length', 10);
    if ($limit_val < 1) {
      $limit_val = 10;
    }
    if ($limit_val > 50) {
      $limit_val = 50;
    }
    $start = (int) $request->input('start', 0);
    $search = $request->input('search', '');
    if (is_array($search)) {
      $search = isset($search['value']) ? (string) $search['value'] : '';
    }
    $request['start'] = 0;

    $filteredQuery = $this->loadDataSearchSamples(clone $query, $search);

    $countQuery = clone $filteredQuery;
    $countQuery->getQuery()->orders = null;
    $countQuery->getQuery()->limit = null;
    $countQuery->getQuery()->offset = null;
    $countQuery->getQuery()->groups = null;
    $countQuery->getQuery()->columns = null;
    $countQuery->select(DB::raw('COUNT(DISTINCT tb_samples.id_samples) as aggregate'));
    $totalDataRecord = (int) $countQuery->value('aggregate');
    $totalFilteredRecord = $totalDataRecord;

    $datas = (clone $filteredQuery)
      ->offset($start)
      ->limit($limit_val)
      ->get();

    $sampleIds = $datas->pluck('id_samples')->filter()->unique()->values()->all();
    $parameterNamesMap = $this->prefetchKesmasSampleParameterNames($sampleIds, $labCodes);
    $verificationStepsMap = $this->prefetchKesmasSampleVerificationSteps($sampleIds);

    $datatable = Datatables::of($datas)
      ->addColumn('action', function ($data) {
        if (!getAction('read')) {
          return '';
        }

        return '<a href="' . route('elits-samples.verification-2', [$data->id_samples, $data->id_laboratorium]) . '" class="btn btn-primary btn-sm" title="Verifikasi"><i class="fas fa-pencil-alt"></i></a>';
      })
      ->addColumn('noregister_permohonan_uji_klinik', function ($data) {
        return $data->codesample_samples ?? '-';
      })
      ->addColumn('prolanis', function ($data) use ($userLevel) {
        if ($userLevel == 'ALAB') {
          return '<label class="badge badge-warning badge-pill" style="font-size: 13px; padding: 6px 12px;"><i class="fa fa-flask mr-1"></i>Pemeriksaan Kimia</label>';
        } elseif ($userLevel == 'KLAB') {
          return '<label class="badge badge-info badge-pill" style="font-size: 13px; padding: 6px 12px;"><i class="fa fa-microscope mr-1"></i>Pemeriksaan Mikro</label>';
        }
        return '<label class="badge badge-secondary badge-pill" style="font-size: 13px; padding: 6px 12px;">Kesmas</label>';
      })
      ->addColumn('nama_pasien', function ($data) {
        $customer = e($data->nama_customer ?? '-');
        $titik = trim(strip_tags(html_entity_decode((string) ($data->titik_pengambilan ?? ''), ENT_QUOTES | ENT_HTML5, 'UTF-8')));
        $html = '<div class="kesmas-verifikasi-customer-cell">';
        $html .= '<div class="kesmas-verifikasi-customer-name">' . $customer . '</div>';
        if ($titik !== '') {
          $html .= '<div class="kesmas-verifikasi-titik">(' . e($titik) . ')</div>';
        }
        $html .= '</div>';

        return $html;
      })
      ->addColumn('status_registrasi', function ($data) use ($parameterNamesMap) {
        // Jika ada packet_id, tampilkan nama paket
        if (!empty($data->packet_id) && !empty($data->name_packet)) {
          return '<label class="badge badge-info badge-pill" style="font-size: 13px; padding: 6px 12px;"><i class="fa fa-box mr-1"></i>' . htmlspecialchars($data->name_packet) . '</label>';
        }
        $parameterNames = $parameterNamesMap[$data->id_samples] ?? null;
        // Jika tidak ada paket, tampilkan parameter (jika ada)
        if (!empty($parameterNames)) {
          // Ambil parameter pertama atau beberapa parameter pertama jika terlalu panjang
          $params = explode(', ', $parameterNames);
          $displayParams = count($params) > 3 ? implode(', ', array_slice($params, 0, 3)) . '...' : $parameterNames;
          return '<label class="badge badge-primary badge-pill" style="font-size: 13px; padding: 6px 12px;"><i class="fa fa-list mr-1"></i>' . htmlspecialchars($displayParams) . '</label>';
        }
        // Fallback jika tidak ada paket maupun parameter
        return '<label class="badge badge-secondary badge-pill" style="font-size: 13px; padding: 6px 12px;"><i class="fa fa-question mr-1"></i>Belum Ada Pemeriksaan</label>';
      })
      ->addColumn('status_permohonan', function ($data) use ($verificationStepsMap) {
        $stepMap = $verificationStepsMap[$data->id_samples] ?? [];

        return $this->renderKesmasSampleStatusBadgeHtml($stepMap);
      })
      ->addIndexColumn();

    $datatable->rawColumns(['action', 'prolanis', 'status_registrasi', 'status_permohonan', 'nama_pasien']);

    $datatable->setTotalRecords($totalDataRecord);
    $datatable->setFilteredRecords($totalFilteredRecord);

    return $datatable->skipPaging()->make(true);
  }

  /**
   * Helper function untuk search pada samples
   */
  private function resolveKesmasVerifikasiLabCodes($userLevel, $kodeLab = null)
  {
    if ($kodeLab) {
      if (in_array($kodeLab, ['KIM', 'KMA', 'FKA'], true)) {
        return ['KIM', 'KMA', 'FKA'];
      }
      if ($kodeLab === 'MBI') {
        return ['MBI'];
      }

      return [];
    }

    if ($userLevel === 'ALAB') {
      return ['KIM', 'KMA', 'FKA'];
    }
    if ($userLevel === 'KLAB') {
      return ['MBI'];
    }

    return [];
  }

  /**
   * Query dasar daftar verifikasi Kesmas tanpa join parameter (lebih ringan).
   */
  private function buildKesmasVerifikasiSampleListQuery(array $labCodes)
  {
    if (empty($labCodes)) {
      return Sample::query()->whereRaw('1 = 0');
    }

    return Sample::query()
      ->join('tb_sample_method', function ($join) {
        $join->on('tb_sample_method.sample_id', '=', 'tb_samples.id_samples')
          ->whereNull('tb_sample_method.deleted_at')
          ->whereNull('tb_samples.deleted_at');
      })
      ->join('ms_laboratorium', function ($join) use ($labCodes) {
        $join->on('ms_laboratorium.id_laboratorium', '=', 'tb_sample_method.laboratorium_id')
          ->whereNull('ms_laboratorium.deleted_at')
          ->whereNull('tb_sample_method.deleted_at')
          ->whereIn('ms_laboratorium.kode_laboratorium', $labCodes);
      })
      ->leftJoin('tb_permohonan_uji', function ($join) {
        $join->on('tb_permohonan_uji.id_permohonan_uji', '=', 'tb_samples.permohonan_uji_id')
          ->whereNull('tb_permohonan_uji.deleted_at')
          ->whereNull('tb_samples.deleted_at');
      })
      ->leftJoin('ms_customer', function ($join) {
        $join->on('ms_customer.id_customer', '=', 'tb_permohonan_uji.customer_id')
          ->whereNull('ms_customer.deleted_at')
          ->whereNull('tb_permohonan_uji.deleted_at');
      })
      ->leftJoin('ms_packet', function ($join) {
        $join->on('ms_packet.id_packet', '=', 'tb_samples.packet_id')
          ->whereNull('ms_packet.deleted_at');
      })
      ->select(
        'tb_samples.id_samples',
        'tb_samples.codesample_samples',
        'tb_samples.titik_pengambilan',
        'tb_samples.date_sending',
        'tb_samples.created_at',
        'tb_samples.packet_id',
        'ms_laboratorium.id_laboratorium',
        'ms_laboratorium.nama_laboratorium',
        'ms_laboratorium.kode_laboratorium',
        'tb_permohonan_uji.id_permohonan_uji',
        'ms_customer.name_customer as nama_customer',
        'ms_packet.name_packet'
      )
      ->groupBy(
        'tb_samples.id_samples',
        'tb_samples.codesample_samples',
        'tb_samples.titik_pengambilan',
        'tb_samples.date_sending',
        'tb_samples.created_at',
        'tb_samples.packet_id',
        'ms_laboratorium.id_laboratorium',
        'ms_laboratorium.nama_laboratorium',
        'ms_laboratorium.kode_laboratorium',
        'tb_permohonan_uji.id_permohonan_uji',
        'ms_customer.name_customer',
        'ms_packet.name_packet'
      );
  }

  /**
   * Filter status proses verifikasi Kesmas per sample.
   */
  private function applyKesmasVerifikasiSampleStatusFilter($query, $statusFilter)
  {
    if (!$statusFilter || $statusFilter === '') {
      return $query;
    }

    if ($statusFilter === 'selesai') {
      return $query->whereExists(function ($subquery) {
        $subquery->select(DB::raw(1))
          ->from('tb_verification_activity_samples')
          ->whereColumn('tb_verification_activity_samples.id_sample', 'tb_samples.id_samples')
          ->whereNull('tb_verification_activity_samples.is_klinik')
          ->where('tb_verification_activity_samples.id_verification_activity', 5)
          ->where('tb_verification_activity_samples.is_done', 1);
      });
    }

    if ($statusFilter === 'penerimaan_sample') {
      return $query->where(function ($q) {
        $q->whereNotExists(function ($subquery) {
          $subquery->select(DB::raw(1))
            ->from('tb_verification_activity_samples')
            ->whereColumn('tb_verification_activity_samples.id_sample', 'tb_samples.id_samples')
            ->whereNull('tb_verification_activity_samples.is_klinik')
            ->where('tb_verification_activity_samples.id_verification_activity', 7);
        })->orWhereExists(function ($subquery) {
          $subquery->select(DB::raw(1))
            ->from('tb_verification_activity_samples')
            ->whereColumn('tb_verification_activity_samples.id_sample', 'tb_samples.id_samples')
            ->whereNull('tb_verification_activity_samples.is_klinik')
            ->where('tb_verification_activity_samples.id_verification_activity', 7)
            ->where('tb_verification_activity_samples.is_done', 0);
        });
      });
    }

    if ($statusFilter === 'pemeriksaan') {
      return $query->whereExists(function ($subquery) {
        $subquery->select(DB::raw(1))
          ->from('tb_verification_activity_samples')
          ->whereColumn('tb_verification_activity_samples.id_sample', 'tb_samples.id_samples')
          ->whereNull('tb_verification_activity_samples.is_klinik')
          ->where('tb_verification_activity_samples.id_verification_activity', 7)
          ->where('tb_verification_activity_samples.is_done', 1);
      })->where(function ($q) {
        $q->whereNotExists(function ($subquery) {
          $subquery->select(DB::raw(1))
            ->from('tb_verification_activity_samples')
            ->whereColumn('tb_verification_activity_samples.id_sample', 'tb_samples.id_samples')
            ->whereNull('tb_verification_activity_samples.is_klinik')
            ->where('tb_verification_activity_samples.id_verification_activity', 2);
        })->orWhereExists(function ($subquery) {
          $subquery->select(DB::raw(1))
            ->from('tb_verification_activity_samples')
            ->whereColumn('tb_verification_activity_samples.id_sample', 'tb_samples.id_samples')
            ->whereNull('tb_verification_activity_samples.is_klinik')
            ->where('tb_verification_activity_samples.id_verification_activity', 2)
            ->where('tb_verification_activity_samples.is_done', 0);
        });
      });
    }

    if ($statusFilter === 'input_hasil') {
      return $query->whereExists(function ($subquery) {
        $subquery->select(DB::raw(1))
          ->from('tb_verification_activity_samples')
          ->whereColumn('tb_verification_activity_samples.id_sample', 'tb_samples.id_samples')
          ->whereNull('tb_verification_activity_samples.is_klinik')
          ->where('tb_verification_activity_samples.id_verification_activity', 2)
          ->where('tb_verification_activity_samples.is_done', 1);
      })->where(function ($q) {
        $q->whereNotExists(function ($subquery) {
          $subquery->select(DB::raw(1))
            ->from('tb_verification_activity_samples')
            ->whereColumn('tb_verification_activity_samples.id_sample', 'tb_samples.id_samples')
            ->whereNull('tb_verification_activity_samples.is_klinik')
            ->where('tb_verification_activity_samples.id_verification_activity', 3);
        })->orWhereExists(function ($subquery) {
          $subquery->select(DB::raw(1))
            ->from('tb_verification_activity_samples')
            ->whereColumn('tb_verification_activity_samples.id_sample', 'tb_samples.id_samples')
            ->whereNull('tb_verification_activity_samples.is_klinik')
            ->where('tb_verification_activity_samples.id_verification_activity', 3)
            ->where('tb_verification_activity_samples.is_done', 0);
        });
      });
    }

    if ($statusFilter === 'verifikasi') {
      return $query->whereExists(function ($subquery) {
        $subquery->select(DB::raw(1))
          ->from('tb_verification_activity_samples')
          ->whereColumn('tb_verification_activity_samples.id_sample', 'tb_samples.id_samples')
          ->whereNull('tb_verification_activity_samples.is_klinik')
          ->where('tb_verification_activity_samples.id_verification_activity', 3)
          ->where('tb_verification_activity_samples.is_done', 1);
      })->where(function ($q) {
        $q->whereNotExists(function ($subquery) {
          $subquery->select(DB::raw(1))
            ->from('tb_verification_activity_samples')
            ->whereColumn('tb_verification_activity_samples.id_sample', 'tb_samples.id_samples')
            ->whereNull('tb_verification_activity_samples.is_klinik')
            ->where('tb_verification_activity_samples.id_verification_activity', 4);
        })->orWhereExists(function ($subquery) {
          $subquery->select(DB::raw(1))
