                            <div class="dropdown-menu" aria-labelledby="dropdownMenuLink">
                                ' . $printFormulirKlinik . '
                                ' . $printLembarPersetujuan . '
                                ' . $printkartuMedis . '
                                ' . $printNota . '
                                ' . $printHasilKlinik . '
                                ' . $printHasilRapidAntibody . '
                                ' . $printHasilRapidAntigen . '
