      ->addColumn('nama_pasien', function ($data) {
        return $data->pasien->nama_pasien;
      })
      ->addColumn('no_rekammedis', function ($data) {
        return Carbon::createFromFormat('Y-m-d', $data->pasien->tgllahir_pasien)->format('dmY') . str_pad((int) $data->pasien->no_rekammedis_pasien, 4, '0', STR_PAD_LEFT);
      })

      ->addColumn('prolanis', function ($data) {
        $badges = [];
        
        // Check for Prolanis DM
        if ($data->tipe_pemeriksaan_prolanis == "PROLANIS DM") {
          $badges[] = '<label class="badge badge-primary badge-pill">Prolanis DM</label>';
        }
        // Check for Prolanis HT
        else if ($data->tipe_pemeriksaan_prolanis == "PROLANIS HT") {
          $badges[] = '<label class="badge badge-primary badge-pill">Prolanis HT</label>';
        }
        // Default Pemeriksaan Klinik
        else {
          $badges[] = '<label class="badge badge-primary badge-pill">Pemeriksaan Klinik</label>';
        }
        
        // Check for Haji - if id_permohonan_uji_klinik_haji is not null, add haji badge
        $hajiBadges = $this->formatHajiListBadgesHtml($data, [], 'pill');
        if ($hajiBadges !== '') {
          $badges[] = $hajiBadges;
        }
        
