  private function loadDataSearch($data, $search)
  {
    if ($search === null || $search === '' || is_array($search)) {
      return $data;
    }

    $data = $data->where(function ($query) use ($search) {
      $query->where('noregister_permohonan_uji_klinik', 'like', "%{$search}%")
        ->Orwhere('nama_pasien', 'like', "%{$search}%")
        ->Orwhere('no_rekammedis_pasien', 'like', "%{$search}%")
        ->Orwhere('status_permohonan_uji_klinik', 'like', "%{$search}%");
    });

    return $data;
  }

  /**
   * Prefetch paket/parameter flags untuk DataTables registrasi klinik (hindari N+1 per baris).
   *
   * @param  array<int, string>  $permohonanIds
   * @return array{has_paket: array, has_parameter: array, jenis: array}
   */
  private function prefetchKlinikRegistrasiMeta(array $permohonanIds)
  {
    $empty = ['has_paket' => [], 'has_parameter' => [], 'jenis' => []];
    if (empty($permohonanIds)) {
      return $empty;
    }

    $hasPaket = PermohonanUjiPaketKlinik::whereIn('permohonan_uji_klinik', $permohonanIds)
      ->whereNull('deleted_at')
      ->distinct()
      ->pluck('permohonan_uji_klinik')
      ->flip()
      ->all();

    $hasParameter = [];
    $jenis = [];

    $parameterRows = DB::table('tb_permohonan_uji_parameter_klinik as pup')
      ->join('ms_parameter_satuan_klinik as ps', 'pup.parameter_satuan_klinik', '=', 'ps.id_parameter_satuan_klinik')
      ->whereIn('pup.permohonan_uji_klinik', $permohonanIds)
      ->whereNull('pup.deleted_at')
      ->whereNull('ps.deleted_at')
      ->select('pup.permohonan_uji_klinik', 'ps.jenis_pemeriksaan_parameter_satuan_klinik')
      ->get();

    foreach ($parameterRows as $row) {
      $pid = $row->permohonan_uji_klinik;
      $hasParameter[$pid] = true;
      $jenisKey = (string) $row->jenis_pemeriksaan_parameter_satuan_klinik;
      if (!isset($jenis[$pid])) {
        $jenis[$pid] = [];
      }
      $jenis[$pid][$jenisKey] = true;
    }

    return [
      'has_paket' => $hasPaket,
      'has_parameter' => $hasParameter,
      'jenis' => $jenis,
    ];
  }

  /**
   * Prefetch langkah verifikasi klinik per permohonan (hindari N+1 di daftar verifikasi).
   *
   * @param  array<int, string>  $permohonanIds
   * @return array<string, array<int, int>>
   */
  private function prefetchKlinikVerificationSteps(array $permohonanIds)
  {
    if (empty($permohonanIds)) {
      return [];
    }

    $steps = [];
    $activities = VerificationActivitySample::whereIn('is_klinik', $permohonanIds)->get();

    foreach ($activities as $act) {
      $pid = $act->is_klinik;
      if (!isset($steps[$pid])) {
        $steps[$pid] = [];
      }
      $steps[$pid][$act->id_verification_activity] = (int) $act->is_done;
    }

    return $steps;
  }

  /**
   * Verifikasi klinik hanya untuk analis (dan admin).
   */
  private function canAccessKlinikVerifikasi(): bool
  {
    $level = auth()->user()->getlevel->level ?? null;

    return in_array($level, ['ANLS', 'ALAB', 'PLAB', 'ADMN'], true);
  }

  /**
   * Tombol aksi ringan untuk daftar verifikasi klinik.
   */
  private function buildKlinikVerifikasiActionHtml($data, bool $hasParameter, array $steps): string
  {
    $targetUrl = null;
    $title = 'Detail';
    $isFinished = ($data->status_permohonan_uji_klinik == 'SELESAI');
    $pid = $data->id_permohonan_uji_klinik;

    if (!$hasParameter) {
      $targetUrl = route('elits-permohonan-uji-klinik-2.create-permohonan-uji-klinik-parameter', $pid);
      $title = 'Input Parameter Pemeriksaan';
    } else {
      $stepOrder = Smt::isUrineOnlySample($pid) ? [1, 7, 2, 3, 4, 5] : [1, 6, 7, 2, 3, 4, 5];
      $currentStep = null;
      foreach ($stepOrder as $stepId) {
        if (!isset($steps[$stepId]) || $steps[$stepId] !== 1) {
          $currentStep = $stepId;
          break;
        }
      }

      if ($currentStep === null || $isFinished) {
        $targetUrl = route('elits-permohonan-uji-klinik-2.verification', $pid);
        $title = 'Lihat Hasil (Selesai)';
        $isFinished = true;
      } else {
        switch ($currentStep) {
          case 6:
            $targetUrl = route('elits-permohonan-uji-klinik-2.create-permohonan-uji-sample', [$pid, 1]);
            $title = 'Pengambilan Sampel';
            break;
          case 7:
            $targetUrl = route('elits-permohonan-uji-klinik-2.create-penerima-sampel', $pid);
            $title = 'Penerimaan Sampel';
            break;
          case 2:
            $targetUrl = route('elits-permohonan-uji-klinik-2.verification', $pid);
            $title = 'Pemeriksaan Sampel';
            break;
          case 3:
            $targetUrl = route('elits-permohonan-uji-klinik-2.create-permohonan-uji-analis2', $pid);
            $title = 'Input Hasil Pemeriksaan';
            break;
          case 4:
            $targetUrl = route('elits-permohonan-uji-klinik-2.verification-permohonan-uji-paramater-klinik', $pid);
            $title = 'Verifikasi Hasil';
            break;
          case 5:
            $targetUrl = route('elits-permohonan-uji-klinik-2.disabled-permohonan-uji-analis2', $pid);
            $title = 'Validasi / Hasil Final';
            $isFinished = true;
            break;
          default:
            $targetUrl = route('elits-permohonan-uji-klinik-2.verification', $pid);
            $title = 'Verifikasi';
            break;
        }
      }
    }

    if (!$targetUrl || !getAction('read')) {
      return '';
    }

    $safeTitle = htmlspecialchars($title, ENT_QUOTES, 'UTF-8');
    $btnClass = $isFinished ? 'btn-success' : 'btn-primary';

    return '<a href="' . $targetUrl . '" class="btn ' . $btnClass . ' btn-sm" title="' . $safeTitle . '"><i class="fas fa-pencil-alt"></i></a>';
  }

  /**
   * Urutan daftar registrasi klinik (nomor lab/spesimen selalu DESC — terbesar di atas).
   */
  private function applyRegistrasiKlinikOrderBy($query, Request $request)
  {
    $orderColumn = (int) $request->input('order.0.column', 1);
    $orderDir = strtolower((string) $request->input('order.0.dir', 'desc')) === 'asc' ? 'asc' : 'desc';
    $isDktr = Auth::user()->getlevel->level == 'DKTR';
    $hasCheckbox = !$isDktr && getAction('delete');
    $colOffset = $hasCheckbox ? 1 : 0;
    $noregDir = 'desc';

    // Nama Pasien: index 3 (+1 jika kolom checkbox)
    if ($orderColumn === (3 + $colOffset)) {
      $query->orderBy('ms_pasien.nama_pasien', $orderDir);

      return $this->applyKlinikNoregisterOrderBy($query, $noregDir);
    }

    // Status Pembayaran: index 5 (+1 jika kolom checkbox)
    if (!$isDktr && $orderColumn === (5 + $colOffset)) {
      $query->orderBy('tb_permohonan_uji_klinik_2.status_pembayaran', $orderDir);

      return $this->applyKlinikNoregisterOrderBy($query, $noregDir);
    }

    if ($isDktr) {
      $query->orderBy('tb_permohonan_uji_klinik_2.done_register', 'asc');
    }

    return $this->applyKlinikNoregisterOrderBy($query, $noregDir);
  }

  /**
   * Sort numerik sama dengan tampilan No Register: spesimen (kiri) lalu lab (kanan).
   * Jangan pakai bagian kanan noregister (sering = jumlah pendaftaran), itu yang membuat daftar loncat.
   */
  private function applyKlinikNoregisterOrderBy($query, $orderDir)
  {
    return $query
      ->orderByNomerSpesimen($orderDir)
      ->orderBy('tb_permohonan_uji_klinik_2.tglregister_permohonan_uji_klinik', $orderDir);
  }

  /**
   * Format nomor register klinik (tanpa query tambahan per baris).
   * Format: {number sampel} / {number lab}
   */
  private function formatKlinikDisplayNoregister($row, $settings = null)
  {
    // Samakan dengan model: hormati flag manual + pasangan spesimen/lab
    if ($row instanceof PermohonanUjiKlinik2) {
      return $row->getDisplayNoregister($settings);
    }

    $model = new PermohonanUjiKlinik2();
    foreach ([
      'nourut_permohonan_uji_klinik',
      'noregister_permohonan_uji_klinik',
      'nomor_spesimen_manual',
      'nomor_lab_manual',
      'nomer_lab',
      'is_nomor_spesimen_manual',
      'is_nomor_lab_manual',
    ] as $field) {
      if (isset($row->{$field})) {
        $model->{$field} = $row->{$field};
      }
    }

    return $model->getDisplayNoregister($settings);
  }

  /**
   * True jika permohonan ini diregistrasi dengan nomor lab & spesimen manual.
   */
  private function permohonanUsesManualKlinikNumbers($row): bool
  {
    $labManual = (int) ($row->is_nomor_lab_manual ?? 0) === 1;
    $spesimenManual = (int) ($row->is_nomor_spesimen_manual ?? 0) === 1;

    return $labManual
      && $spesimenManual
      && trim((string) ($row->nomor_lab_manual ?? '')) !== ''
      && trim((string) ($row->nomor_spesimen_manual ?? '')) !== '';
  }

  /**
   * Show the form for creating a new resource.
   *
   * @return \Illuminate\Http\Response
   */
  public function create()
  {

    // $bpjs = new PCare\Kunjungan($this->pcare_conf());
    // dd($bpjs->riwayat("2362")->index());

    $user = Auth()->user();
    $seqYear = GlobalLabSequence::resolveYear(date('Y'));
    // Get current number from global sequence (without incrementing) — sync per tahun
    $count = GlobalLabSequence::getCurrentNumber($seqYear);

    $start_num = StartNum::where('code_lab_start_number', 'KLI')->first();

    if ($count < 1) {
      $set_count = 1 + (int) ($start_num->count_start_number ?? 0);
      if ($seqYear != ($start_num->year_start_number ?? $seqYear)) {
        $set_count = 1;
      }
    } else {
      $set_count = $count + 1;
    }

    $count_pasien = Pasien::nextNoRekamMedis();

    // Get global settings untuk nomor lab dan spesimen
    $numberSettings = KlinikNumberSettings::getSettings();

    $nextLabNumber = $this->resolveNextKlinikLabNumber($seqYear, $numberSettings, (int) $set_count);
    $nextSpesimenNumber = $this->resolveNextKlinikSpesimenNumber($seqYear, $numberSettings, (int) $set_count);

    // Format resmi:
    // No. Spesimen      : 03/{number sampel}/YYYY
    // No. Laboratorium  : 449.5/03/{number lab}/YYYY
    // No. Register      : {number sampel} / {number lab}
    $nomor_spesimen_preview = '03/' . (int) $nextSpesimenNumber . '/' . $seqYear;
    $nomor_lab_preview = '449.5/03/' . (int) $nextLabNumber . '/' . $seqYear;
    $nomor_register_preview = (int) $nextSpesimenNumber . ' / ' . (int) $nextLabNumber;

    $nomor_lab_manual_default = (int) $nextLabNumber;
    $nomor_spesimen_manual_default = (int) $nextSpesimenNumber;
    $lastLabNumber = max(0, (int) $nextLabNumber - 1);

    // Legacy $code (nourut global / count) — tetap dipakai di hidden bila diperlukan JS lama
    $jumlah_terakhir = PermohonanUjiKlinik2::whereNull('deleted_at')
        ->whereYear('created_at', $seqYear)
        ->count() + 1;
    $code = $nomor_register_preview;

    // Get petugas administrasi/pendaftaran from ms_verification_activities register column
    $petugasPenerima = $this->getPetugasAdministrasi();
    $petugasPengambilSampel = $this->getPetugasPengambilKlinik();

    return view('masterweb::module.admin.laboratorium.permohonan-uji-klinik-2.add', compact(
      'code',
      'set_count',
      'count_pasien',
      'petugasPenerima',
      'petugasPengambilSampel',
      'numberSettings',
      'nomor_lab_preview',
      'nomor_spesimen_preview',
      'nomor_register_preview',
      'nomor_lab_manual_default',
      'nomor_spesimen_manual_default',
      'nextLabNumber',
      'nextSpesimenNumber',
      'lastLabNumber',
      'seqYear'
    ));
    //get all menu public
  }

  /**
   * Nomor lab klinik berikutnya (preview create + store).
   * Gabungan kesmas + klinik — tidak memakai GlobalLabSequence spesimen.
   * Selalu mengembalikan slot yang belum terpakai.
   */
  private function resolveNextKlinikLabNumber(int $year, $numberSettings = null, int $fallbackAuto = 1): int
  {
    return NomerLabSequence::resolveUniqueLabNumber(null, $year);
  }

  /**
   * Saat edit nomor lab: simpan nomor_lab_manual + nomer_lab, lalu naikkan
   * global_nomer_lab_sequence agar nomor berikutnya tidak mundur.
   * Jika nomor bentrok dengan permohonan lain → geser ke slot kosong.
   */
  private function applyKlinikLabNumberOnEdit(PermohonanUjiKlinik2 $post, string $nomorLabManual, int $seqYear): void
  {
    $labInt = (int) $nomorLabManual;
    if ($labInt < 1 || $labInt > 999999) {
      return;
    }

    $existingLabUrut = $post->resolveLabUrut();
    if ($existingLabUrut !== '' && (string) $labInt === (string) $existingLabUrut) {
      return;
    }

    $labInt = NomerLabSequence::resolveUniqueLabNumber(
      $labInt,
      $seqYear,
      $post->id_permohonan_uji_klinik ?? null
    );

    $post->nomor_lab_manual = (string) $labInt;
    $post->is_nomor_lab_manual = 1;

    if (Schema::hasColumn('tb_permohonan_uji_klinik_2', 'nomer_lab')) {
      $post->nomer_lab = $labInt;
    }

    NomerLabSequence::raiseLastNumberToAtLeast($labInt, $seqYear);
  }

  /**
   * Nomor spesimen/sampel klinik berikutnya.
   * - Mode manual: max nomor_spesimen_manual (angka wajar) + 1
   * - Mode otomatis: ikut global sequence (sama dengan set_count / No. SAMPLE otomatis)
   */
  private function resolveNextKlinikSpesimenNumber(int $year, $numberSettings = null, int $fallbackAuto = 1): int
  {
    $numberSettings = $numberSettings ?: KlinikNumberSettings::getSettings();
    $isManual = (bool) ($numberSettings->is_nomor_spesimen_manual ?? false);

    if (!$isManual) {
      // Otomatis: pakai counter global bersama (bukan max nomor_spesimen_manual yang bisa junk)
      return max(1, $fallbackAuto);
    }

    $maxSpesimen = (int) (PermohonanUjiKlinik2::query()
      ->whereNull('deleted_at')
      ->where(function ($q) use ($year) {
        $q->whereYear('tglregister_permohonan_uji_klinik', $year)
          ->orWhere(function ($q2) use ($year) {
            $q2->whereNull('tglregister_permohonan_uji_klinik')
              ->whereYear('created_at', $year);
          });
      })
      ->where('is_nomor_spesimen_manual', 1)
      ->whereNotNull('nomor_spesimen_manual')
      ->whereRaw("TRIM(nomor_spesimen_manual) <> ''")
      ->whereRaw("nomor_spesimen_manual REGEXP '^[0-9]{1,6}$'")
      ->selectRaw('MAX(CAST(TRIM(nomor_spesimen_manual) AS UNSIGNED)) as m')
      ->value('m') ?? 0);

    return max($maxSpesimen, 0) + 1;
  }

  /**
   * Get petugas administrasi/pendaftaran from:
   * 1. ms_verification_activities register column
   * 2. ms_petugas yang memiliki role dengan id "1" (Pendaftaran/Registrasi)
   */
  /**
   * Normalisasi nama petugas untuk perbandingan duplikat.
   */
  public static function normalizePetugasNameKey($nama)
  {
    $nama = strtolower(trim((string) $nama));
    $nama = str_replace([',', '.'], '', $nama);

    return preg_replace('/\s+/', ' ', $nama) ?? $nama;
  }

  public static function petugasNamesMatch($a, $b)
  {
    return self::normalizePetugasNameKey($a) === self::normalizePetugasNameKey($b);
  }

  /**
   * Cari nama petugas yang sudah ada di daftar (abaikan perbedaan format penulisan).
   */
  public static function findMatchingPetugasName($needle, array $haystack)
  {
    $needle = trim((string) $needle);
    if ($needle === '') {
      return null;
    }

    foreach ($haystack as $name) {
      if (self::petugasNamesMatch($needle, $name)) {
        return $name;
      }
    }

    return null;
  }

  /**
   * Tanggal & waktu sampling untuk ditampilkan (selaras baris Pengambil Sample di halaman verification).
   * Prioritas: VerificationActivitySample step 6 → time_sampling → tgl/jam permohonan → created_at.
   * Jangan pakai created_at dulu — itu waktu input form, bukan jam pengambilan.
   */
  public static function formatTanggalWaktuSamplingKlinikDisplay(
    $permohonanId,
    $latestSampling = null,
    $permohonan = null
  ): string {
    $va = VerificationActivitySample::where('is_klinik', $permohonanId)
      ->where('id_verification_activity', VerificationActivitySample::ACTIVITY_PENGAMBILAN_SAMPLE)
      ->orderByDesc('start_date')
      ->first();

    if ($va && !empty($va->start_date)) {
      return Carbon::parse($va->start_date)->isoFormat('D MMMM Y, HH:mm');
    }

    if ($latestSampling && !empty($latestSampling->time_sampling)) {
      return Carbon::parse($latestSampling->time_sampling)->isoFormat('D MMMM Y, HH:mm');
    }

    $tgl = $permohonan->tgl_sampling_permohonan_uji_klinik ?? null;
    $jam = $permohonan->jam_sampling_permohonan_uji_klinik ?? null;
    if (!empty($tgl) && !empty($jam)) {
      try {
        return Carbon::parse(trim($tgl) . ' ' . trim($jam))->isoFormat('D MMMM Y, HH:mm');
      } catch (\Throwable $e) {
        // lanjut fallback
      }
    }

    if ($latestSampling && !empty($latestSampling->created_at)) {
      return Carbon::parse($latestSampling->created_at)->isoFormat('D MMMM Y, HH:mm');
    }

    return '-';
  }

  /**
   * Ambil penulisan nama petugas sesuai ms_petugas (termasuk kapitalisasi gelar).
   * Jangan pakai ucwords(strtolower()) — merusak gelar seperti A.Md.Kes → A.md.kes.
   */
  public static function resolvePetugasCanonicalName($nama)
  {
    $nama = trim((string) $nama);
    if ($nama === '' || $nama === '-' || $nama === '...................') {
      return $nama;
    }

    static $resolved = [];
    static $masterNames = null;

    $key = self::normalizePetugasNameKey($nama);
    if ($key === '') {
      return $nama;
    }
    if (array_key_exists($key, $resolved)) {
      return $resolved[$key];
    }

    if ($masterNames === null) {
      $masterNames = Petugas::query()
        ->whereNotNull('nama')
        ->where('nama', '!=', '')
        ->pluck('nama')
        ->map(function ($n) {
          return trim((string) $n);
        })
        ->filter()
        ->values()
        ->all();
    }

    $matched = self::findMatchingPetugasName($nama, $masterNames);
    $resolved[$key] = $matched !== null ? $matched : $nama;

    return $resolved[$key];
  }

  /**
   * Hilangkan nama petugas duplikat (abaikan perbedaan kapital, koma, titik, spasi).
   */
  public static function uniquePetugasNames(array $names)
  {
    $result = [];
    $seen = [];

    foreach ($names as $name) {
      $name = trim((string) $name);
      if ($name === '') {
        continue;
      }

      $key = self::normalizePetugasNameKey($name);
      if (isset($seen[$key])) {
        continue;
      }

      $seen[$key] = true;
      $result[] = $name;
    }

    return $result;
  }

  /**
   * Helper function to check if nama exists in array by comparing without commas
   * @param string $nama Nama yang akan dicek
   * @param array $array Array untuk dibandingkan
   * @return bool True jika nama sudah ada (setelah menghilangkan koma), false jika belum ada
   */
  private function namaExistsInArray($nama, $array)
  {
    return self::findMatchingPetugasName($nama, $array) !== null;
  }

  private function getPetugasAdministrasi()
  {
    $petugasPenerima = [];

    // 1. Get from ms_verification_activities register column
    $verificationActivities = VerificationActivity::all();
    foreach ($verificationActivities as $activity) {
      if (!empty($activity->register) && $activity->register !== '-' && $activity->register !== 'NULL') {
        // Parse names from register column (comma-separated)
        // Names are stored as "Name1, Name2, Name3" format
        $names = explode(', ', $activity->register);
        foreach ($names as $name) {
          $name = trim($name);
          if (!empty($name) && !$this->namaExistsInArray($name, $petugasPenerima)) {
            $petugasPenerima[] = $name;
          }
        }
      }
    }

    // 2. Get from ms_petugas yang memiliki role dengan id "1" (Pendaftaran/Registrasi)
    // Meskipun petugas juga memiliki role lain (misalnya role "6" untuk pengambil sample),
    // tetap dianggap sebagai petugas pendaftaran jika memiliki role "1"
    $petugasWithRole1 = Petugas::whereNotNull('role')->get();
    foreach ($petugasWithRole1 as $petugas) {
      $roles = is_array($petugas->role) ? $petugas->role : json_decode($petugas->role, true);
      if (is_array($roles) && in_array('1', $roles)) {

        // Petugas memiliki role "1" (Pendaftaran/Registrasi)
        $nama = trim($petugas->nama);
        if (!empty($nama) && !$this->namaExistsInArray($nama, $petugasPenerima)) {
          $petugasPenerima[] = $nama;
        }
      }
    }

    // Sort alphabetically
    sort($petugasPenerima);


    return $petugasPenerima;
  }

  /**
   * Get validators for step 5 (Validasi) from:
   * ms_verification_activities klinik column where id = 5
   */
  private function getPetugasValidator()
  {
    $petugasValidator = [];

    // Get from ms_verification_activities klinik column for step 5 (id = 5)
    $verificationActivity = VerificationActivity::find(5);
    if ($verificationActivity && !empty($verificationActivity->klinik) && $verificationActivity->klinik !== '-' && $verificationActivity->klinik !== 'NULL') {
      // Parse names from klinik column (comma-separated)
      // Names are stored as "Name1, Name2, Name3" format
      $names = explode(', ', $verificationActivity->klinik);
      foreach ($names as $name) {
        $name = trim($name);
        if (!empty($name) && !in_array($name, $petugasValidator)) {
          $petugasValidator[] = $name;
        }
      }
    }

    // Sort alphabetically
    sort($petugasValidator);

    return $petugasValidator;
  }

  /**
   * Get petugas penerima sampel klinik (analis) from:
   * 1. ms_verification_activities klinik column where id = 7
   * 2. Fallback: petugas analis lab klinik (role 3)
   */
  private function getPetugasPenerimaKlinik()
  {
    $petugasPenerima = [];

    $verificationActivity = VerificationActivity::find(7);
    if ($verificationActivity && !empty($verificationActivity->klinik) && $verificationActivity->klinik !== '-' && $verificationActivity->klinik !== 'NULL') {
      foreach (preg_split('/,\s*/', $verificationActivity->klinik) as $name) {
        $name = trim($name);
        if ($name !== '' && !$this->namaExistsInArray($name, $petugasPenerima)) {
          $petugasPenerima[] = $name;
        }
      }
    }

    if (empty($petugasPenerima)) {
      foreach ($this->getPetugasAnalisKlinik() as $petugas) {
        $nama = trim($petugas['nama'] ?? '');
        if ($nama !== '' && !$this->namaExistsInArray($nama, $petugasPenerima)) {
          $petugasPenerima[] = $nama;
        }
      }
    }

    sort($petugasPenerima);

    return self::uniquePetugasNames($petugasPenerima);
  }

  /**
   * Get petugas pengambil sampel untuk SOLAB dengan id_petugas NULL:
   * Petugas dengan role 6 (Pengambil Sampel) yang tidak mempunyai lab
   * atau yang berada di lab klinik (kode KLI).
   */
  private function getPetugasPengambilKlinik()
  {
    $klinikLab = \Smt\Masterweb\Models\Laboratorium::where('kode_laboratorium', 'KLI')->first();
    $klinikLabId = $klinikLab ? $klinikLab->id_laboratorium : null;

    $result = [];
    $petugasList = Petugas::whereNotNull('role')->get();

    foreach ($petugasList as $petugas) {
      $roles  = is_array($petugas->role)   ? $petugas->role   : json_decode($petugas->role, true);
      $labIds = is_array($petugas->lab_id) ? $petugas->lab_id : json_decode($petugas->lab_id, true);

      // Hanya petugas dengan role 6 (Pengambil Sampel)
      if (!is_array($roles) || !in_array('6', $roles)) continue;

      $noLab   = empty($labIds);
      $inKlinik = $klinikLabId && is_array($labIds) && in_array($klinikLabId, $labIds);

      if ($noLab || $inKlinik) {
        $nama = trim($petugas->nama ?? '');
        if (!empty($nama) && !in_array($nama, $result)) {
          $result[] = $nama;
        }
      }
    }

    sort($result);
    return $result;
  }

  /**
   * Get groups for user based on user level and lab code
   * Groups are determined from Petugas with matching lab_id
   */
  private function getGroupsForUser($userLevel, $kodeLab)
  {
    $groups = [];
    
    // Determine target lab codes based on user level and lab code
    $targetLabCodes = [];
    if (in_array($kodeLab, ['KIM', 'KMA', 'FKA'])) {
      // Kimia labs
      $targetLabCodes = ['KIM', 'KMA', 'FKA'];
    } elseif ($kodeLab == 'MBI') {
      // Mikro lab
      $targetLabCodes = ['MBI'];
    } elseif ($kodeLab == 'KLI' && in_array($userLevel, ['ALAB', 'PLAB', 'ANLS'])) {
      // Klinik lab for ALAB, PLAB, ANLS
      $targetLabCodes = ['KLI'];
    }
    
    if (empty($targetLabCodes)) {
      return $groups;
    }
    
    // Get lab IDs for target lab codes
    $targetLabIds = Laboratorium::whereIn('kode_laboratorium', $targetLabCodes)
      ->whereNull('deleted_at')
      ->pluck('id_laboratorium')
      ->toArray();
    
    if (empty($targetLabIds)) {
      return $groups;
    }
    
    // Get Petugas with matching lab_id
    $petugasList = Petugas::whereNotNull('role')->get();
    
    // Group Petugas by their lab_id combination
    $groupMap = [];
    
    foreach ($petugasList as $petugas) {
      $labIds = is_array($petugas->lab_id) ? $petugas->lab_id : json_decode($petugas->lab_id, true);
      if (!is_array($labIds)) {
        $labIds = $labIds ? [$labIds] : [];
      }
      
      // Check if petugas has any of the target lab IDs
      $hasTargetLab = false;
      foreach ($targetLabIds as $targetLabId) {
        if (in_array($targetLabId, $labIds)) {
          $hasTargetLab = true;
          break;
        }
      }
      
      if ($hasTargetLab) {
        // Create a group key based on lab_id combination
        sort($labIds);
        $groupKey = implode(',', $labIds);
        
        if (!isset($groupMap[$groupKey])) {
          $groupMap[$groupKey] = [
            'id' => $groupKey,
            'name' => $this->getGroupName($labIds),
            'lab_ids' => $labIds
          ];
        }
      }
    }
    
    // Convert to array and sort by name
    $groups = array_values($groupMap);
    usort($groups, function($a, $b) {
      return strcmp($a['name'], $b['name']);
    });
    
    return $groups;
  }
  
  /**
   * Get group name based on lab IDs
   */
  private function getGroupName($labIds)
  {
    if (empty($labIds)) {
      return 'Tanpa Lab';
    }
    
    $labNames = [];
    foreach ($labIds as $labId) {
      $lab = Laboratorium::find($labId);
      if ($lab) {
        $labNames[] = $lab->nama_laboratorium;
      }
    }
    
    if (empty($labNames)) {
      return 'Grup ' . implode(', ', $labIds);
    }
    
    return implode(', ', $labNames);
  }



  public function getPatients(Request $request){
      // dd($request->all());
    $params = [];
    if ($request->get('identifier') !== null){
      $params['identifier'] = 'https://fhir.kemkes.go.id/id/nik|'.$request->get('identifier');
    }

    if ($request->get('name') !== null){
      $params['name'] = $request->get('name');
    }

    if ($request->get('birthday') !== null){
      $params['birthdate'] = $request->get('birthday')['year']."-". sprintf("%02d",$request->get('birthday')['month'])."-". sprintf("%02d",$request->get('birthday')['day']);

      // dd($request->get('birthday')['year']."-". sprintf("%02d",$request->get('birthday')['month'])."-". sprintf("%02d",$request->get('birthday')['day']));
    }

    // dd($request->all());
    if ($request->get('gender') !== null){
      $params['gender'] = $request->get('gender');
    }

    $response = $this->satuSehatHelper->get('Patient', $params)['body'];

    $entries = $response['entry'] ?? [];
    $result = [];

    foreach ($entries as $entry) {
      $resource = $entry['resource'] ?? [];
      if (!isset($resource['identifier'][1]['value']) ||
        !ctype_digit($resource['identifier'][1]['value'])) {

        $nik = null;
      } else {
        $nik = $resource['identifier'][1]['value'];
      }

      $gender = $resource['gender'] == 'male' ? 'L' : 'P';


      $result[] = [
        'nik' => $nik,
        'gender' => $gender ?? null,
        'id' => $resource['id'] ?? null,
        'address' => $resource['address'][0]['city'] ?? null,
        'birthDate' => DateHelper::formatOnlyDate($resource['birthDate']) ?? null,
        'name' => $resource['name'][0]['text'] ?? null,
        'telepon' => $resource['telecom'][0]['value'] ?? null,
      ];
    }

    return response()->json($result);
  }

  public function getPatientsSilaboy(Request $request)
  {
    $inputs = $request->all();
    $filteredInputs = collect($inputs)->filter(function ($value, $key) {
      if ($key === 'birthday') {
        return false;
      }
      return !empty($value);
    });

    $patients = Pasien::query()
      ->where(function($query) use ($filteredInputs) {
        foreach ($filteredInputs as $key => $value) {
          $query->orWhere($key, 'LIKE', '%' . $value . '%');
        }
      })
      ->get();

    $result = [];
    foreach ($patients as $patient){
      $result[] = [
        'nik' => $patient->nik_pasien ?? null,
        'gender' => $patient->gender_pasien ?? null,
        'id' => $patient->id_pasien_satu_sehat ?? null,
        'address' => $patient->alamat_pasien ?? null,
        'birthDate' => DateHelper::formatOnlyDate($patient->tgllahir_pasien) ?? null,
        'name' => $patient->nama_pasien ?? null,
        'telepon' => $patient->phone_pasien ?? null,
      ];
    }

    return response()->json($result);
  }

  private function getDataPasienSatuSehat($nik, $name, $dob)
  {
    $params = [
      "identifier" => 'https://fhir.kemkes.go.id/id/nik|'.$nik,
      "name" => $name,
      "birthdate" => $dob
    ];

    $response = $this->satuSehatHelper->get('Patient', $params)['body'];


    $entries = $response['entry'] ?? [];
    $result = [];

    foreach ($entries as $entry) {
      $resource = $entry['resource'] ?? [];
      $result[] = [
        'id' => $resource['id'] ?? null,
      ];
    }
    return $result[0]["id"] ?? null;
  }

  public function store(Request $request)
  {
    // Validasi data yang dikirim
    $validator = $this->rules($request->all());


    if ($validator->fails()) {
      return response()->json(['status' => false, 'pesan' => $validator->errors()]);
    }

    DB::beginTransaction();

    try {
      $post = new PermohonanUjiKlinik2();


      $start_num=StartNum::where('code_lab_start_number','KLI')->first();

      # Get current number from global sequence (scoped per tahun register)
      $seqYear = GlobalLabSequence::resolveYear(
        $request->post('tglregister_permohonan_uji_klinik')
          ? Carbon::parse($request->post('tglregister_permohonan_uji_klinik'))->format('Y')
          : date('Y')
      );
      $current_global = GlobalLabSequence::getCurrentNumber($seqYear);

      // Handle start number for first year (koneksi seq terpisah — tidak tahan lock transaksi luar)
      if ($current_global == 0 && $seqYear == ($start_num->year_start_number ?? $seqYear)) {
        GlobalLabSequence::raiseLastNumberToAtLeast((int) ($start_num->count_start_number ?? 0), $seqYear);
      }

      // Get next number for klinik dengan lab_id dari laboratorium klinik
      // Get laboratorium klinik untuk mendapatkan lab_id
      $labKlinik = Laboratorium::where('kode_laboratorium', 'KLI')->first();
      $klinik_lab_id = $labKlinik ? $labKlinik->id_laboratorium : null;
      $set_count = GlobalLabSequence::getNextNumber($seqYear, $klinik_lab_id, 'klinik', null);

      $count_pasien = Pasien::nextNoRekamMedis();

      $romanMonths = [
        1 => 'I',
        2 => 'II',
        3 => 'III',
        4 => 'IV',
        5 => 'V',
        6 => 'VI',
        7 => 'VII',
        8 => 'VIII',
        9 => 'IX',
        10 => 'X',
        11 => 'XI',
        12 => 'XII'
      ];

      $currentMonth = date('n'); // Mendapatkan bulan saat ini dalam format numerik (1-12)
      $romanMonth = $romanMonths[$currentMonth]; // Mendapatkan bulan dalam format Romawi

      // Format: {no_lab}/{jumlah terakhir permohonan uji klinik}
      // no_lab = kode laboratorium klinik dari global_lab_sequence (dari lab_id)
      // jumlah terakhir permohonan uji klinik = total count dari tb_permohonan_uji_klinik_2 + 1

      // Get laboratorium klinik untuk mendapatkan lab_id dan kode_laboratorium
      $labKlinik = Laboratorium::where('kode_laboratorium', 'KLI')->first();
      $klinik_lab_id = $labKlinik ? $labKlinik->id_laboratorium : null;

