        //   } catch (RequestException $e) {
        //       // Menangani error
        //       // dd($e->getResponse()->getBody()->getContents());


        //       if ($e->hasResponse()) {
        //           return response()->json(['status' => false, 'pesan' => $e->getResponse()->getBody()->getContents(), 'error' => $e->getMessage()], 200);
        //       } else {
        //           return response()->json(['status' => false, 'pesan' => $e->getMessage(), 'error' => $e->getMessage()], 200);
        //       }

        //       // $store_pasien = $post_newpasien->save();

        //   }


        // }

        $store_pasien = true;
        $post->pasien_permohonan_uji_klinik = $request->post('pasien_permohonan_uji_klinik');


      }

      // Simpan data permohonan uji klinik
      $simpan = $post->save();

      if ($simpan && $nomorLabManual !== '') {
        NomerLabSequence::raiseLastNumberToAtLeast((int) $nomorLabManual, (int) $seqYear);
      }

      // Pada saat pendaftaran klinik baru, naikkan number_sampling_success +1
      // (walaupun belum ada pengambilan sampel atau status 'berhasil')
      try {
        // Jumlah pendaftaran klinik pada tahun berjalan (setelah tersimpan termasuk current)
        $newCount = PermohonanUjiKlinik2::where(DB::raw('YEAR(created_at)'), '=', date('Y'))->count();

        // Cari record resampling=0 (pengambilan awal). Jika belum ada, buat placeholder.
        $firstSampling = \Smt\Masterweb\Models\PengambilanSampleKlinik::where('permohonan_uji_klinik_id', $post->id_permohonan_uji_klinik)
          ->where('resampling', 0)
          ->orderBy('created_at', 'asc')
          ->first();

        if (!$firstSampling) {
          $firstSampling = new \Smt\Masterweb\Models\PengambilanSampleKlinik();
          $firstSampling->id_pengambilan_sample_klinik = \Ramsey\Uuid\Uuid::uuid4()->toString();
          $firstSampling->permohonan_uji_klinik_id = $post->id_permohonan_uji_klinik;
          $firstSampling->resampling = 0;
          $firstSampling->pasien_permohonan_uji_klinik = $post->pasien_permohonan_uji_klinik ?? null;
          $firstSampling->status_sampling = $firstSampling->status_sampling ?? null; // belum ada status
        }

        $namaPengambil = trim((string) ($request->post('petugas_pengambil_sampel') ?? ''));
        if ($namaPengambil !== ''
            && !$this->isUrineOnlyPetugasSelection($namaPengambil)
            && !$this->isBlankPetugasSelection($namaPengambil)
            && !$this->isDiisiPelangganPetugasSelection($namaPengambil)) {
          $firstSampling->petugas_name = $namaPengambil;
        } elseif ($this->isBlankPetugasSelection($namaPengambil)
            || $this->isUrineOnlyPetugasSelection($namaPengambil)
            || $this->isDiisiPelangganPetugasSelection($namaPengambil)) {
          $firstSampling->petugas_name = null;
        } elseif (empty($firstSampling->petugas_name)) {
          $firstSampling->petugas_name = $request->post('petugas_penerima');
        }
        // Set nilai akumulasi pada placeholder
        $firstSampling->number_sampling_success = $newCount;
        $firstSampling->save();

        // Sinkronkan ke seluruh record terkait permohonan yang sama
        \Smt\Masterweb\Models\PengambilanSampleKlinik::where('permohonan_uji_klinik_id', $post->id_permohonan_uji_klinik)
          ->whereNull('deleted_at')
          ->update(['number_sampling_success' => $newCount]);
      } catch (\Exception $e) {
        // Abaikan jika terjadi error agar pendaftaran tetap lanjut
      }

      // Update reference_id in global_lab_sequence_detail after saving
      $sequence_detail = GlobalLabSequenceDetail::where('sequence_number', $set_count)
        ->where('year', $seqYear)
        ->where('lab_type', 'klinik')
        ->whereNull('reference_id')
        ->orderBy('created_at', 'desc')
        ->first();

      if ($sequence_detail) {
        $sequence_detail->update(['reference_id' => $post->id_permohonan_uji_klinik]);
      }

      // simpan number_klinik — wajib sama dengan set_count (bukan input form yang bisa stale)
      $number_klinik = new NumberKlinik();
      $number_klinik->new_number = $set_count;
      $number_klinik->last_number = $set_count;
      $number_klinik->id_permohonan_uji_klinik = $post->id_permohonan_uji_klinik;
      $number_klinik->save();

      //simpan ke verifikasi
      $startDate = Carbon::parse($request->post('tglregister_permohonan_uji_klinik'))->format('Y-m-d H:i:s');
      if ($request->post('tglregister_permohonan_uji_klinik')) {
        $verificationActivitySample = new VerificationActivitySample();
        $verificationActivitySample->id = Uuid::uuid4()->toString();
        $verificationActivitySample->id_verification_activity = 1; // Pendaftaran / Registrasi
        $verificationActivitySample->start_date = $startDate;
        $verificationActivitySample->stop_date = Carbon::parse($startDate)->addMinutes(5)->format('Y-m-d H:i:s');
        $verificationActivitySample->nama_petugas = $request->post('petugas_penerima');
        $verificationActivitySample->is_klinik = $post->id_permohonan_uji_klinik;
        $verificationActivitySample->is_done = 1;
        // Simpan ke database
        $verificationActivitySample->save();

        if ($request->post('mode_pengambilan_sampel') !== 'dibawa_pelanggan') {
          if ($this->isUrineOnlyPetugasSelection($request->post('petugas_pengambil_sampel'))) {
            $this->markPengambilSampleSkipped($post->id_permohonan_uji_klinik);
          } else {
            $this->seedPengambilSampleVerificationAtRegistration(
              $post->id_permohonan_uji_klinik,
              $request->post('petugas_pengambil_sampel'),
              $request->post('mode_pengambilan_sampel'),
              $request->post('tglregister_permohonan_uji_klinik')
            );
          }
        } else {
          $this->seedPengambilSampleVerificationAtRegistration(
            $post->id_permohonan_uji_klinik,
            self::PETUGAS_PENGAMBIL_DIISI_PELANGGAN,
            $request->post('mode_pengambilan_sampel'),
            $request->post('tglregister_permohonan_uji_klinik')
          );
        }
      }

      DB::commit();

      if ($simpan && $store_pasien) {
        // Tentukan redirect URL berdasarkan doctor_type
        if ($request->post('doctor_type') === 'lab') {
          if ($request->post('isPerwakilanDokter') == true){
            // Dokter lab redirect ke add-parameter
            $noRegister = $post->noregister_permohonan_uji_klinik;
            $redirectUrl = url('/elits-permohonan-uji-klinik-2/add-parameter') .
                          '?complete-step=1&id_pasien=' . $pasien->id_pasien .
                          '&no_reg=' . urlencode($noRegister);
          } else {
             // Dokter lab redirect ke list - kirim WhatsApp ke dokter DKTR
            // Panggil setelah response dikirim untuk menghindari blocking
            $redirectUrl = url('/elits-permohonan-uji-klinik/registrasi');
            
            // Kirim WhatsApp setelah response (gunakan register_shutdown_function atau queue)
            // Untuk debugging, kita panggil langsung dulu
            $this->sendWhatsAppToDokter($post->id_permohonan_uji_klinik, $pasien, $post->noregister_permohonan_uji_klinik);
          }
        } else {
          // Dokter rujukan redirect ke add-parameter
          $noRegister = $post->noregister_permohonan_uji_klinik;
          $redirectUrl = url('/elits-permohonan-uji-klinik-2/add-parameter') .
                        '?complete-step=1&id_pasien=' . $pasien->id_pasien .
                        '&no_reg=' . urlencode($noRegister);
        }

        return response()->json([
          'status' => true,
          'pesan' => "Data permohonan uji klinik berhasil disimpan!",
          'id' => $pasien->id_pasien,
          'doctor_type' => $request->post('doctor_type'),
          'redirect_url' => $redirectUrl
        ], 200);
      } else {
        return response()->json(['status' => false, 'pesan' => "Data permohonan uji klinik tidak berhasil disimpan!","id"=>$pasien->id_pasien], 200);
      }
    } catch (\Exception $e) {
      DB::rollback();
      Log::error('Gagal simpan pendaftaran klinik', [
        'message' => $e->getMessage(),
        'file' => $e->getFile(),
        'line' => $e->getLine(),
      ]);
      return response()->json([
        'status' => false,
        'pesan' => 'System gagal melakukan penyimpanan!',
        'error' => $e->getMessage(),
      ], 200);
    }
  }




