      })
      ->join('ms_parameter_paket_klinik', function ($join) {
        $join->on('ms_parameter_paket_klinik.id_parameter_paket_klinik', '=', 'tb_permohonan_uji_paket_klinik.parameter_paket_klinik')
          ->whereNull('ms_parameter_paket_klinik.deleted_at')
          ->whereNull('tb_permohonan_uji_paket_klinik.deleted_at');
      })
      ->where('tb_permohonan_uji_paket_klinik.type_permohonan_uji_paket_klinik', "P")
      ->select(
        'ms_parameter_paket_klinik.name_parameter_paket_klinik',
        'tb_permohonan_uji_paket_klinik.parameter_paket_klinik',
        'tb_permohonan_uji_paket_klinik.harga_permohonan_uji_paket_klinik',
        DB::raw('count(tb_permohonan_uji_paket_klinik.parameter_paket_klinik) as count_method')
      )
      ->groupBy(
        'ms_parameter_paket_klinik.name_parameter_paket_klinik',
        'tb_permohonan_uji_paket_klinik.parameter_paket_klinik',
        'tb_permohonan_uji_paket_klinik.harga_permohonan_uji_paket_klinik'
      )
      ->get();

    foreach ($parameterPaket as $valuePaket) {
      $nilaiPermohonanUjiKlinik["name_item"] = $valuePaket->name_parameter_paket_klinik;
      $nilaiPermohonanUjiKlinik["count_item"] = $valuePaket->count_method;
      $nilaiPermohonanUjiKlinik["price_item"] = $valuePaket->harga_permohonan_uji_paket_klinik;
      $nilaiPermohonanUjiKlinik["total"] = $valuePaket->harga_permohonan_uji_paket_klinik * $valuePaket->count_method;

      array_push($value_items, $nilaiPermohonanUjiKlinik);
    }

    return view('masterweb::module.admin.laboratorium.permohonan-uji-klinik-2.read', [
      'item' => $item,
      // 'tgl_register' => $tgl_register,
      // 'tgl_pengambilan' => $tgl_pengambilan,
      // 'data_parameter_jenis' => $data_parameter_jenis,
      // 'data_parameter_satuan' => $data_parameter_satuan,
      'data_permohonan_uji_paket_klinik' => $data_permohonan_uji_paket_klinik,
      // 'tgl_pengujian' => $tgl_pengujian,
      // 'tgl_spesimen_darah' => $tgl_spesimen_darah,
      // 'tgl_spesimen_urine' => $tgl_spesimen_urine,
      'data_detail_uji_paket' => $data_permohonan_uji_paket_klinik,
      'value_items' => $value_items,
      'arr_permohonan_parameter' => $arr_permohonan_parameter,
    ]);
    // return "coba";
  }

  function print($id) {}

  /**
   * Show the form for editing the specified resource.
   *
   * @param  int  $id
   * @return \Illuminate\Http\Response
   */
  public function edit($id)
  {
    $item = PermohonanUjiKlinik2::findOrFail($id);
    $pasien = Pasien::where('id_pasien', $item->pasien_permohonan_uji_klinik)->first();
    $verifikasi = VerificationActivitySample::where('is_klinik', $id)
      ->where('id_verification_activity', 1)
      ->first();

    $petugasPenerima = $this->getPetugasAdministrasi();
    $petugasPengambilSampel = $this->getPetugasPengambilKlinik();

    if ($verifikasi && !empty($verifikasi->nama_petugas)) {
      $savedNama = trim($verifikasi->nama_petugas);
      if (!in_array($savedNama, $petugasPenerima)) {
        array_unshift($petugasPenerima, $savedNama);
      }
    }

    $verifikasiPengambil = VerificationActivitySample::where('is_klinik', $id)
      ->where('id_verification_activity', 6)
      ->where(function ($q) {
        $q->where('resampling', 0)->orWhereNull('resampling');
      })
      ->orderBy('start_date', 'desc')
      ->first();

    if ($verifikasiPengambil && !empty($verifikasiPengambil->nama_petugas)) {
      $savedPengambil = trim($verifikasiPengambil->nama_petugas);
      if ($savedPengambil !== '' && !in_array($savedPengambil, $petugasPengambilSampel)) {
        array_unshift($petugasPengambilSampel, $savedPengambil);
      }
    }

    $numberSettings = KlinikNumberSettings::getSettings();

    $isEdit = true;
    $seqYear = GlobalLabSequence::resolveYear($item->tglregister_permohonan_uji_klinik ?? $item->created_at);
    $spesimenUrut = $item->resolveSpesimenUrut();
    $labUrut = $item->resolveLabUrut();
    $nomor_spesimen_preview = $spesimenUrut !== '' ? ('03/' . $spesimenUrut . '/' . $seqYear) : '';
    $nomor_lab_preview = $labUrut !== '' ? ('449.5/03/' . $labUrut . '/' . $seqYear) : '';
    $nomor_register_preview = $item->getDisplayNoregister($numberSettings);
    $nomor_lab_manual_default = $labUrut;
    $nomor_spesimen_manual_default = $spesimenUrut;
    $nextLabNumber = $labUrut !== '' ? (int) $labUrut : 0;
    $nextSpesimenNumber = $spesimenUrut !== '' ? (int) $spesimenUrut : 0;
    $lastLabNumber = NomerLabSequence::resolveMaxIssuedLabNumber($seqYear);

    $code = $nomor_register_preview !== '' && $nomor_register_preview !== '-'
      ? $nomor_register_preview
      : $item->noregister_permohonan_uji_klinik;
    $set_count = $item->nourut_permohonan_uji_klinik;
    $count_pasien = $pasien ? ($pasien->no_rekammedis_pasien ?? '') : '';

    $tglRegister = Carbon::parse($item->tglregister_permohonan_uji_klinik);

    $tgllahirUi = null;
    if ($pasien && !empty($pasien->tgllahir_pasien)) {
      try {
        $tgllahirUi = Carbon::parse($pasien->tgllahir_pasien)->format('d/m/Y');
      } catch (\Throwable $e) {
        $tgllahirUi = $pasien->tgllahir_pasien;
      }
    }

    $pasienPayload = $pasien ? [
      'id_pasien' => $pasien->id_pasien,
      'id_satu_sehat' => $pasien->id_pasien_satu_sehat,
      'nik_pasien' => $pasien->nik_pasien,
      'no_rekammedis_pasien' => $pasien->no_rekammedis_pasien,
      'nama_pasien' => $pasien->nama_pasien,
      'gender_pasien' => $pasien->gender_pasien,
      'tgllahir_pasien' => $tgllahirUi,
      'tmpt_lahir' => $pasien->tmpt_lahir,
      'pekerjaan' => $pasien->pekerjaan,
      'phone_pasien' => $pasien->phone_pasien,
      'alamat_pasien' => $pasien->alamat_pasien,
      'alamat_lengkap' => Smt::alamatLengkapPasien($pasien),
      'wilayah_id' => $pasien->wilayah_id,
    ] : [];

    $klinikEditData = [
      'id_permohonan' => $item->id_permohonan_uji_klinik,
      'is_haji' => (int) ($item->is_haji ?? 0) === 1,
      'id_haji' => $item->id_permohonan_uji_klinik_haji,
      'doctor_type' => ((int) ($item->is_haji ?? 0) === 1)
        ? 'rujukan'
        : ($item->doctor_type ?: null),
      'noregister' => $code,
      'nomor_spesimen_manual' => $spesimenUrut,
      'nomor_lab_manual' => $labUrut,
      'spesimen_urut' => $spesimenUrut,
      'lab_urut' => $labUrut,
      'nomor_spesimen_preview' => $nomor_spesimen_preview,
      'nomor_lab_preview' => $nomor_lab_preview,
      'nomer_lab' => $nomor_lab_preview,
      'tglregister_display' => $tglRegister->format('d/m/Y H:i'),
      'tglregister' => $tglRegister->format('Y-m-d H:i:s'),
      'petugas_penerima' => $verifikasi ? ($verifikasi->nama_petugas ?? '') : '',
      'petugas_pengambil_sampel' => (Smt::isUrineOnlySample($id) && $verifikasiPengambil && (int) $verifikasiPengambil->is_done === 1)
        ? self::PETUGAS_PENGAMBIL_URINE_ONLY
        : (($verifikasiPengambil && !empty($verifikasiPengambil->nama_petugas))
            ? $verifikasiPengambil->nama_petugas
            : ((($item->mode_pengambilan_sampel ?? '') === 'dibawa_pelanggan')
                ? self::PETUGAS_PENGAMBIL_DIISI_PELANGGAN
                : '')),
      'mode_pengambilan_sampel' => $item->mode_pengambilan_sampel ?? '',
      'biaya_pengambilan_sampel' => $item->biaya_pengambilan_sampel ?? 20000,
      'umurtahun' => $item->umurtahun_pasien_permohonan_uji_klinik,
      'umurbulan' => $item->umurbulan_pasien_permohonan_uji_klinik,
      'umurhari' => $item->umurhari_pasien_permohonan_uji_klinik,
      'metode_pembayaran' => $item->metode_pembayaran,
      'request_pasien' => $item->request_pasien_permohonan_uji_klinik ?? '',
      'kirim_hasil_whatsapp' => (string) ($item->kirim_hasil_whatsapp ?? 0),
      'nama_dokter_pengirim' => $item->nama_dokter_pengirim_permohonan_uji_klinik,
      'hp_dokter_pengirim' => $item->hp_dokter_pengirim_permohonan_uji_klinik,
      'diagnosa' => $item->diagnosa_permohonan_uji_klinik,
      'tipe_pemeriksaan_prolanis' => $item->tipe_pemeriksaan_prolanis,
      'is_perwakilan' => !empty($item->nama_perwakilan_permohonan_uji_klinik),
      'is_perwakilan_dokter' => ((int) ($item->is_haji ?? 0) !== 1)
        && $item->doctor_type === 'lab'
        && !empty($item->diagnosa_permohonan_uji_klinik),
      'perwakilan' => [
        'nama' => $item->nama_perwakilan_permohonan_uji_klinik,
        'gender' => $item->gender_perwakilan_permohonan_uji_klinik,
        'tanggal_lahir' => $item->tanggal_lahir_perwakilan_permohonan_uji_klinik,
        'alamat' => $item->alamat_perwakilan_permohonan_uji_klinik,
        'status_hubungan' => $item->status_hubungan_perwakilan_permohonan_uji_klinik,
        'status_hubungan_lainnya' => $item->status_hubungan_lainnya_permohonan_uji_klinik,
      ],
      'pasien' => $pasienPayload,
      'nourut' => $item->nourut_permohonan_uji_klinik,
    ];

    return view('masterweb::module.admin.laboratorium.permohonan-uji-klinik-2.add', compact(
      'isEdit',
      'item',
      'pasien',
      'verifikasi',
      'code',
      'set_count',
      'count_pasien',
      'petugasPenerima',
      'petugasPengambilSampel',
      'numberSettings',
      'klinikEditData',
      'nomor_lab_preview',
      'nomor_spesimen_preview',
      'nomor_register_preview',
      'nomor_lab_manual_default',
      'nomor_spesimen_manual_default',
      'nextLabNumber',
      'nextSpesimenNumber',
      'lastLabNumber',
      'seqYear'
    ));
  }

  /**
   * Update the specified resource in storage.
   *
   * @param  \Illuminate\Http\Request  $request
   * @param  int  $id
   * @return \Illuminate\Http\Response
   */

  public function update(Request $request, $id)
  {
    // dd($request->all());
      $existingHaji = PermohonanUjiKlinik2::find($id);
      if ($existingHaji && (int) ($existingHaji->is_haji ?? 0) === 1) {
        $request->merge([
          'doctor_type' => 'rujukan',
          'is_haji' => 1,
        ]);
      }

      // Validasi input
      $validator = $this->rules($request->all());

      if ($validator->fails()) {
          return response()->json(['status' => false, 'pesan' => $validator->errors()], 422);
      }

      DB::beginTransaction();

      try {
          $post = PermohonanUjiKlinik2::findOrFail($id);

          $nomorLabManual = preg_replace('/\D+/', '', (string) $request->post('nomor_lab_manual', ''));
          $nomorSpesimenManual = preg_replace('/\D+/', '', (string) $request->post('nomor_spesimen_manual', ''));
          $seqYear = GlobalLabSequence::resolveYear(
            $request->post('tglregister_permohonan_uji_klinik') ?: ($post->tglregister_permohonan_uji_klinik ?? $post->created_at)
          );

          $existingSpesimenUrut = $post->resolveSpesimenUrut();
          $existingLabUrut = $post->resolveLabUrut();
          $spesimenBumpedWarning = null;

          // Edit: hanya resolve ulang bila user benar-benar mengubah angka (hindari geser saat ubah field lain).
          // Field nomor kosong = abaikan, nomor lama tetap (tidak error, tidak auto-ganti).
          if ($nomorSpesimenManual !== '') {
            if ((string) $nomorSpesimenManual !== (string) $existingSpesimenUrut) {
              $requestedSpesimen = (int) $nomorSpesimenManual;
              $nomorSpesimenManual = (string) GlobalLabSequence::resolveUniqueSpesimenNumber(
                $nomorSpesimenManual,
                $seqYear,
                $post->id_permohonan_uji_klinik ?? null
              );
              $post->nomor_spesimen_manual = $nomorSpesimenManual;
              $post->is_nomor_spesimen_manual = 1;
              $post->nourut_permohonan_uji_klinik = (int) $nomorSpesimenManual;

              $labPart = $nomorLabManual !== '' ? $nomorLabManual : $existingLabUrut;
              $post->noregister_permohonan_uji_klinik = $labPart !== ''
                ? ($nomorSpesimenManual . ' / ' . $labPart)
                : $nomorSpesimenManual;

              GlobalLabSequence::raiseLastNumberToAtLeast((int) $nomorSpesimenManual, $seqYear);

              if ($requestedSpesimen > 0 && (int) $nomorSpesimenManual !== $requestedSpesimen) {
                $spesimenBumpedWarning = 'Nomor spesimen ' . $requestedSpesimen
                  . ' sudah dipakai; disimpan sebagai ' . $nomorSpesimenManual . '.';
              }
            }
          }

          if ($nomorLabManual !== '' && (string) $nomorLabManual !== (string) $existingLabUrut) {
            $this->applyKlinikLabNumberOnEdit($post, $nomorLabManual, (int) $seqYear);

            $spesimenPart = $post->resolveSpesimenUrut();
            if ($spesimenPart !== '') {
              $post->noregister_permohonan_uji_klinik = $spesimenPart . ' / ' . $post->resolveLabUrut();
            }
          }

          // Update data
          if ((int) ($post->is_haji ?? 0) === 1) {
            $post->doctor_type = 'rujukan';
            $post->done_register = true;
          } else {
            $post->doctor_type = $request->post('doctor_type');
            $post->done_register = $request->post('doctor_type') === 'lab' ? false : true;
          }
          // $post->jenis_spesimen = $request->post('jenis_spesimen');
          $post->tglregister_permohonan_uji_klinik = Carbon::parse($request->post('tglregister_permohonan_uji_klinik'))->format('Y-m-d H:i:s');

          // Update field berdasarkan doctor_type
          if ($request->post('doctor_type') === 'lab') {
            // Jika doctor_type adalah 'lab', set field menjadi null
            $post->nama_dokter_pengirim_permohonan_uji_klinik = null;
            $post->hp_dokter_pengirim_permohonan_uji_klinik = null;
            $post->diagnosa_permohonan_uji_klinik = null;
            $post->tipe_pemeriksaan_prolanis = null;
            
            // Jika menggunakan perwakilan dokter, simpan diagnosa dan set done_register
            if ($request->post('isPerwakilanDokter') == true) {
              $post->diagnosa_permohonan_uji_klinik = $request->post('diagnosa_permohonan_uji_klinik_perwakilan')
                ?? $request->post('diagnosa_permohonan_uji_klinik');
              $post->done_register = true;
            }
          } else {
            // Jika doctor_type bukan 'lab', isi field yang terkait dokter pengirim
            $post->nama_dokter_pengirim_permohonan_uji_klinik = $request->post('nama_dokter_pengirim_permohonan_uji_klinik');
            $post->hp_dokter_pengirim_permohonan_uji_klinik = $request->post('hp_dokter_pengirim_permohonan_uji_klinik');
            $post->diagnosa_permohonan_uji_klinik = $request->post('diagnosa_permohonan_uji_klinik');
            $post->tipe_pemeriksaan_prolanis = $request->post('tipe_pemeriksaan_prolanis');
          }
          $post->metode_pembayaran = $request->post('metode_pembayaran');
          $post->mode_pengambilan_sampel = $request->post('mode_pengambilan_sampel');
          $post->biaya_pengambilan_sampel = $request->post('mode_pengambilan_sampel') === 'diambil_lokasi_rumah'
            ? ($request->post('biaya_pengambilan_sampel') ?? 20000)
            : null;
          $post->kirim_hasil_whatsapp = $request->post('kirim_hasil_whatsapp', '0');
          // Cek apakah kolom request_pasien ada di database sebelum set
          if (DB::getSchemaBuilder()->hasColumn('tb_permohonan_uji_klinik_2', 'request_pasien_permohonan_uji_klinik')) {
            $post->request_pasien_permohonan_uji_klinik = $request->post('request_pasien_permohonan_uji_klinik');
          }

          $type_pemeriksaan=$request->post('is_prolanis');

          // if ($type_pemeriksaan=="is_prolanis_gula") {
          //   # code...
          //   $post->is_prolanis_gula=1;
          // }else if ($type_pemeriksaan=="is_prolanis_urine") {
          //   // if ($type_pemeriksaan=="is_prolanis_gula") {
          //     # code...
          //     $post->is_prolanis_urine=1;
          //   // }
          // }

          $hasPerwakilan = $request->has('isPerwakilan');
          
          // Update field perwakilan menggunakan DB::table untuk menghindari error jika kolom belum ada di model fillable
          $updateData = [];
          
          if ($hasPerwakilan){
            // Gunakan nama_perwakian (tanpa 'l') karena itu yang digunakan di form edit
            $post->nama_perwakilan_permohonan_uji_klinik = $request->post('nama_perwakian_permohonan_uji_klinik') ?? $request->post('nama_perwakilan_permohonan_uji_klinik');
            $post->tanggal_lahir_perwakilan_permohonan_uji_klinik = $request->post('tanggal_lahir_perwakilan');
            $post->gender_perwakilan_permohonan_uji_klinik = $request->post('gender_perwakilan_permohonan_uji_klinik');
            $post->alamat_perwakilan_permohonan_uji_klinik = $request->post('alamat_perwakilan');
            
            // Cek apakah kolom status_hubungan ada di database
            if (DB::getSchemaBuilder()->hasColumn('tb_permohonan_uji_klinik_2', 'status_hubungan_perwakilan_permohonan_uji_klinik')) {
              $updateData['status_hubungan_perwakilan_permohonan_uji_klinik'] = $request->post('status_hubungan_perwakilan_permohonan_uji_klinik');
            }
            if (DB::getSchemaBuilder()->hasColumn('tb_permohonan_uji_klinik_2', 'status_hubungan_lainnya_permohonan_uji_klinik')) {
              $updateData['status_hubungan_lainnya_permohonan_uji_klinik'] = $request->post('status_hubungan_lainnya_permohonan_uji_klinik');
            }
          }else{
            $post->nama_perwakilan_permohonan_uji_klinik = null;
            $post->tanggal_lahir_perwakilan_permohonan_uji_klinik = null;
            $post->gender_perwakilan_permohonan_uji_klinik = null;
            $post->alamat_perwakilan_permohonan_uji_klinik =null;
            
            // Cek apakah kolom status_hubungan ada di database
            if (DB::getSchemaBuilder()->hasColumn('tb_permohonan_uji_klinik_2', 'status_hubungan_perwakilan_permohonan_uji_klinik')) {
              $updateData['status_hubungan_perwakilan_permohonan_uji_klinik'] = null;
            }
            if (DB::getSchemaBuilder()->hasColumn('tb_permohonan_uji_klinik_2', 'status_hubungan_lainnya_permohonan_uji_klinik')) {
              $updateData['status_hubungan_lainnya_permohonan_uji_klinik'] = null;
            }
          }
          
          // Simpan data
          $post->save();
          
          // Update field status_hubungan menggunakan DB::table jika kolom ada di database
          if (!empty($updateData)) {
            DB::table('tb_permohonan_uji_klinik_2')
              ->where('id_permohonan_uji_klinik', $id)
              ->update($updateData);
          }
          // dd($post);

          //update nama petugas diverifikasi

          $startDate = Carbon::parse($request->post('tglregister_permohonan_uji_klinik'))->format('Y-m-d H:i:s');
          if ($request->post('tglregister_permohonan_uji_klinik')) {
            $verifikasi = VerificationActivitySample::where('is_klinik', $id)
            ->where('id_verification_activity', 1)
            ->first();

            $verifikasi->start_date = $startDate;
            $verifikasi->stop_date = Carbon::parse($startDate)->addMinutes(10)->format('Y-m-d H:i:s');
            $verifikasi->nama_petugas = $request->post('petugas_penerima');
            $verifikasi->updated_at = date('Y-m-d H:i:s');

            $verifikasi->save();
            // dd($verifikasi);
          }

          if ($request->post('mode_pengambilan_sampel') === 'dibawa_pelanggan') {
            $this->seedPengambilSampleVerificationAtRegistration(
              $id,
              self::PETUGAS_PENGAMBIL_DIISI_PELANGGAN,
              $request->post('mode_pengambilan_sampel'),
              $request->post('tglregister_permohonan_uji_klinik')
            );
          } elseif ($this->isUrineOnlyPetugasSelection($request->post('petugas_pengambil_sampel'))) {
            $this->markPengambilSampleSkipped($id);
          } else {
            $this->seedPengambilSampleVerificationAtRegistration(
              $id,
              $request->post('petugas_pengambil_sampel'),
              $request->post('mode_pengambilan_sampel'),
              $request->post('tglregister_permohonan_uji_klinik')
            );
          }

          DB::commit();

          $response = [
            'status' => true,
            'pesan' => 'Data permohonan uji klinik berhasil diubah!'
              . ($spesimenBumpedWarning ? ' ' . $spesimenBumpedWarning : ''),
          ];

          if ((int) ($post->is_haji ?? 0) === 1 && !empty($post->id_permohonan_uji_klinik_haji)) {
            $response['redirect_url'] = route(
              'elits-permohonan-uji-klinik-2.haji.daftar-pasien',
              $post->id_permohonan_uji_klinik_haji
            );
          }

          return response()->json($response, 200);
      } catch (\Exception $e) {
          DB::rollback();
          
          // Log error untuk debugging
          \Log::error('Error updating permohonan uji klinik: ' . $e->getMessage());
          \Log::error('Stack trace: ' . $e->getTraceAsString());

          return response()->json(['status' => false, 'pesan' => 'System gagal melakukan perubahan! Error: ' . $e->getMessage()], 500);
      }
  }


