  /**
   * Store permohonan uji parameter using new checkbox format
   */
  private function storePermohonanUjiParameterNewFormat(Request $request)
  {
    try {
      DB::beginTransaction();

      // Get permohonan uji klinik
      $permohonan_uji_klinik = PermohonanUjiKlinik2::findOrFail($request->permohonan_uji_klinik);

      // Calculate total harga
      $total_harga = 0;
      foreach ($request->jenis_parameters as $id_parameter_paket => $data) {
        if (isset($data['pakets']) && is_array($data['pakets'])) {
          foreach ($data['pakets'] as $value) {
            $parts = explode('_', $value);
            if (count($parts) >= 2) {
              $harga = $parts[1];
              $total_harga += (float)$harga;
            }
          }
        }
      }

      // Update permohonan uji klinik
      $permohonan_uji_klinik->total_harga_permohonan_uji_klinik = $total_harga;
      $permohonan_uji_klinik->status_permohonan_uji_klinik = 'ANALIS';
      $permohonan_uji_klinik->save();

      // Get parameter order if available
      $parameter_order = $request->parameter_order ?? array_keys($request->jenis_parameters);

      // Store permohonan uji paket klinik
      $sorting_index = 1;
      foreach ($parameter_order as $id_parameter_paket) {
        if (!isset($request->jenis_parameters[$id_parameter_paket])) {
          continue;
        }

        $parameter_paket = ParameterPaketKlinik::find($id_parameter_paket);
        if (!$parameter_paket) {
          continue;
        }

        // Create permohonan uji paket klinik
        $permohonan_uji_paket = new PermohonanUjiPaketKlinik();
        $permohonan_uji_paket->permohonan_uji_klinik = $request->permohonan_uji_klinik;
        $permohonan_uji_paket->parameter_paket_klinik = $id_parameter_paket;
        $permohonan_uji_paket->type_permohonan_uji_paket_klinik = 'P'; // Paket
        $permohonan_uji_paket->harga_permohonan_uji_paket_klinik = $parameter_paket->harga_parameter_paket_klinik;
        $permohonan_uji_paket->sorting = $sorting_index++;
        $permohonan_uji_paket->save();

        // Get pasien info for baku mutu matching
        $pasien_umur = $permohonan_uji_klinik->umurtahun_pasien_permohonan_uji_klinik;
        $pasien_gender = $permohonan_uji_klinik->pasien->gender_pasien;

        // Loop through parameter paket jenis klinik
        foreach ($parameter_paket->parameterpaketjenisklinik as $paket_jenis) {
          // Loop through satuan parameter
          foreach ($paket_jenis->parametersatuanpaketklinik as $satuan_paket) {
            // Check baku mutu
            $check_parameter_by_baku_mutu = BakuMutu::where('parameter_jenis_klinik_id', $paket_jenis->parameter_jenis_klinik_id)
              ->where('parameter_satuan_klinik_id', $satuan_paket->parameter_satuan_klinik)
              ->where('is_khusus_baku_mutu', '0')
              ->first();

            if ($check_parameter_by_baku_mutu) {
              $item_parameter_by_baku_mutu = $check_parameter_by_baku_mutu;
            } else {
              $item_parameter_by_baku_mutu = BakuMutu::where('parameter_jenis_klinik_id', $paket_jenis->parameter_jenis_klinik_id)
                ->where('parameter_satuan_klinik_id', $satuan_paket->parameter_satuan_klinik)
                ->where('is_khusus_baku_mutu', '1')
                ->where('gender_baku_mutu', $pasien_gender)
                ->where(function ($query) use ($pasien_umur) {
                  $query->where('minimal_umur_baku_mutu', '<=', $pasien_umur)
                    ->where('maksimal_umur_baku_mutu', '>=', $pasien_umur);
                })
                ->first();
            }

            // Create permohonan uji parameter klinik
            $post_parameter = new PermohonanUjiParameterKlinik();
            $post_parameter->permohonan_uji_klinik = $request->permohonan_uji_klinik;
            $post_parameter->permohonan_uji_paket_klinik = $permohonan_uji_paket->id_permohonan_uji_paket_klinik;
            $post_parameter->parameter_satuan_klinik = $satuan_paket->parameter_satuan_klinik;
            $post_parameter->parameter_paket_klinik = $id_parameter_paket;
            $post_parameter->jenis_parameter_klinik_id = $paket_jenis->parameter_jenis_klinik_id;
            $post_parameter->sort_jenis_klinik = $paket_jenis->sort ?? null;
            $post_parameter->sorting_parameter_satuan = $satuan_paket->sorting ?? null;
            $post_parameter->harga_permohonan_uji_parameter_klinik = $satuan_paket->parametersatuanklinik->harga_satuan_parameter_satuan_klinik;

            if (isset($item_parameter_by_baku_mutu->unit_id)) {
              $post_parameter->satuan_permohonan_uji_parameter_klinik = $item_parameter_by_baku_mutu->unit_id;
              $post_parameter->baku_mutu_permohonan_uji_parameter_klinik = $item_parameter_by_baku_mutu->id_baku_mutu;
            } else {
              $post_parameter->satuan_permohonan_uji_parameter_klinik = null;
              $post_parameter->baku_mutu_permohonan_uji_parameter_klinik = null;
            }

            $post_parameter->save();

            // Check for sub parameters
            $data_parameter_subsatuan = ParameterSubSatuanKlinik::where('parameter_satuan_klinik', $satuan_paket->parameter_satuan_klinik)->get();

            if (count($data_parameter_subsatuan) > 0) {
              foreach ($data_parameter_subsatuan as $value_parameter_subsatuan) {
                $post_parameter_subsatuan = new PermohonanUjiSubParameterKlinik();
                $post_parameter_subsatuan->permohonan_uji_parameter_klinik_id = $post_parameter->id_permohonan_uji_parameter_klinik;
                $post_parameter_subsatuan->parameter_sub_satuan_klinik_id = $value_parameter_subsatuan->id_parameter_sub_satuan_klinik;

                if (isset($item_parameter_by_baku_mutu->id_baku_mutu)) {
                  $item_parameter_subsatuan_by_baku_mutu = BakuMutuDetailParameterKlinik::where('baku_mutu_id', $item_parameter_by_baku_mutu->id_baku_mutu)
                    ->where('parameter_sub_satuan_baku_mutu_detail_parameter_klinik', $value_parameter_subsatuan->id_parameter_sub_satuan_klinik)
                    ->first();

                  if ($item_parameter_subsatuan_by_baku_mutu) {
                    $post_parameter_subsatuan->satuan_permohonan_uji_sub_parameter_klinik = $item_parameter_subsatuan_by_baku_mutu->unit_id_baku_mutu_detail_parameter_klinik;
                    $post_parameter_subsatuan->baku_mutu_permohonan_uji_sub_parameter_klinik = $item_parameter_subsatuan_by_baku_mutu->id_baku_mutu_detail_parameter_klinik;
                  }
                }

                $post_parameter_subsatuan->save();
              }
            }
          }
        }
      }

      DB::commit();

      $this->ensureUrineOnlyPengambilSampleSkipped($permohonan_uji_klinik->id_permohonan_uji_klinik);
      $this->ensureDibawaPelangganPengambilSampleSkipped($permohonan_uji_klinik->id_permohonan_uji_klinik);

      if ($request->complete_step == 1) {
        return response()->json(['status' => true, 'pesan' => 'Berhasil menyimpan data permohonan uji paket klinik!'], 200);
      } else {
        return redirect()
          ->route('elits-permohonan-uji-klinik.index')
          ->with('status', 'Berhasil menyimpan data permohonan uji paket klinik!');
      }
    } catch (\Exception $e) {
      DB::rollback();
      \Log::error('Error storing permohonan uji parameter: ' . $e->getMessage());
      return response()->json(['status' => false, 'pesan' => "System gagal menyimpan data permohonan uji paket klinik! Error: " . $e->getMessage()], 500);
    }
  }

  public function updatePermohonanUjiParameter(Request $request, $id_permohonan_uji_klinik)
  {
    $validator = $this->rules_permohonan_uji_parameter($request->all());

    if ($validator->fails()) {
      return response()->json(['status' => false, 'pesan' => $validator->errors()]);
    } else {
      // dd($request->all());

      DB::beginTransaction();

      try {
