    $data_permohonan_uji_satuan_klinik = PermohonanUjiParameterKlinik::with(['parametersatuanklinik', 'unit'])
      ->where('permohonan_uji_klinik', $id_permohonan_uji_klinik)
      ->orderBy('jenis_parameter_klinik_id', 'ASC')
      ->orderBy('sorting_parameter_satuan', 'ASC')
      ->get();

    foreach ($data_permohonan_uji_satuan_klinik as $value_satuan) {
      $this->normalizePermohonanParameterJenisKlinik($value_satuan);
      $this->ensurePermohonanSubParametersForSatuan($value_satuan, $item_permohonan_uji_klinik);
    }

    /**
     * Prefetch history dan sub-parameter untuk semua parameter sekaligus
     * agar menghindari N+1 query dan potensi timeout, tanpa mengubah data yang ditampilkan.
     */
    $historyByParam = [];
    $subParamsByParam = [];
    $subHistoryBySubParam = [];

    if ($data_permohonan_uji_satuan_klinik->count() > 0) {
      $parameterIds = $data_permohonan_uji_satuan_klinik
        ->pluck('id_permohonan_uji_parameter_klinik')
        ->unique()
        ->values();

      if ($parameterIds->count() > 0) {
        // History untuk parameter utama
        $allHistories = PermohonanUjiParameterKlinikHistory::whereIn('permohonan_uji_parameter_klinik_id', $parameterIds)
          ->orderBy('created_at', 'desc')
          ->get()
          ->groupBy('permohonan_uji_parameter_klinik_id');
        $historyByParam = $allHistories->all();

        // Sub-parameter untuk semua parameter (dengan eager loading relasi untuk menghindari N+1)
        $allSubParams = PermohonanUjiSubParameterKlinik::with(['parametersubsatuanklinik', 'unit'])
          ->whereIn('permohonan_uji_parameter_klinik_id', $parameterIds)
          ->get()
          ->groupBy('permohonan_uji_parameter_klinik_id');
        $subParamsByParam = $allSubParams->all();

        // History untuk semua sub-parameter
        $subParamIds = $allSubParams->flatten()->pluck('id_permohonan_uji_sub_parameter_klinik')->unique()->values();
        if ($subParamIds->count() > 0) {
          $allSubHistories = PermohonanUjiSubParameterKlinikHistory::whereIn('permohonan_uji_sub_parameter_klinik_id', $subParamIds)
            ->orderBy('created_at', 'desc')
            ->get()
            ->groupBy('permohonan_uji_sub_parameter_klinik_id');
          $subHistoryBySubParam = $allSubHistories->all();
        }
      }
    }

    /**
     * Hindari duplikasi baris untuk parameter yang sama ketika ada lebih dari
     * satu record dengan method berbeda:
     *
     * - Jika untuk suatu parameter_satuan_klinik ADA record dengan
     *   hasil_permohonan_uji_parameter_klinik != null / '' maka record
     *   yang hasilnya null / '' disembunyikan (di-skip saat looping).
     * - Jika SEMUA record untuk parameter tersebut hasilnya null / '',
     *   tetap tampilkan satu (melalui logic looping di bawah).
     */
 

    $data_jenis_parameter_klinik = PermohonanUjiParameterKlinik::with('jenisparameterklinik')
      ->where('tb_permohonan_uji_parameter_klinik.permohonan_uji_klinik', $id_permohonan_uji_klinik)
      ->join('ms_parameter_jenis_klinik', 'ms_parameter_jenis_klinik.id_parameter_jenis_klinik', '=', 'tb_permohonan_uji_parameter_klinik.jenis_parameter_klinik_id')
      ->whereNull('ms_parameter_jenis_klinik.deleted_at')
      ->groupBy('tb_permohonan_uji_parameter_klinik.jenis_parameter_klinik_id')
      ->orderByRaw('COALESCE(ms_parameter_jenis_klinik.sort_parameter_jenis_klinik, 999999) ASC')
      ->select('tb_permohonan_uji_parameter_klinik.*')
      ->get();

    if (count($data_permohonan_uji_satuan_klinik) > 0) {
      foreach ($data_jenis_parameter_klinik as $key_jenis_parameter_klinik => $value_jenis_parameter_klinik) {
        # code...
        $parameter_jenis_klinik = [];

        $parameter_jenis_klinik['name_parameter_jenis_klinik'] = $value_jenis_parameter_klinik->jenisparameterklinik->name_parameter_jenis_klinik;
        $parameter_jenis_klinik['id_parameter_jenis_klinik'] = $value_jenis_parameter_klinik->jenisparameterklinik->id_parameter_jenis_klinik;
        $parameter_jenis_klinik['sort_parameter_jenis_klinik'] = $value_jenis_parameter_klinik->jenisparameterklinik->sort_parameter_jenis_klinik ?? 999999;
        $parameter_jenis_klinik['id_parameter_jenis_klinik_parent'] = $value_jenis_parameter_klinik->jenisparameterklinik->id_parameter_jenis_klinik_parent ?? null;
        $parameter_jenis_klinik['item_permohonan_parameter_satuan'] = [];

        foreach ($data_permohonan_uji_satuan_klinik as $key_satuan => $value_satuan) {

          $jenisIdSatuan = $this->resolveEffectiveJenisParameterKlinikId($value_satuan);
          $jenisIdGroup = $value_jenis_parameter_klinik->jenis_parameter_klinik_id
            ?? ($value_jenis_parameter_klinik->jenisparameterklinik->id_parameter_jenis_klinik ?? null);

          if ($jenisIdSatuan == $jenisIdGroup) {

            // Jika parameter ini punya record lain yang hasilnya terisi,
            // maka record yang hasilnya null / '' tidak perlu ditampilkan.
            $paramId = $value_satuan->parameter_satuan_klinik;
            $hasNonNull = $hasNonNullResultByParameter[$paramId] ?? false;
            if (
              $hasNonNull &&
              ($value_satuan->hasil_permohonan_uji_parameter_klinik === null ||
                $value_satuan->hasil_permohonan_uji_parameter_klinik === '')
            ) {
              continue;
            }

            $pasien_umur = $item_permohonan_uji_klinik->umurtahun_pasien_permohonan_uji_klinik;
            $pasien_gender = $item_permohonan_uji_klinik->pasien->gender_pasien;

            $item_permohonan_parameter_satuan = [];
            $item_permohonan_parameter_satuan['id_permohonan_uji_parameter_klinik'] = $value_satuan->id_permohonan_uji_parameter_klinik;
            $item_permohonan_parameter_satuan['permohonan_uji_klinik'] = $value_satuan->permohonan_uji_klinik;
            $item_permohonan_parameter_satuan['permohonan_uji_paket_klinik'] = $value_satuan->permohonan_uji_paket_klinik;
            $item_permohonan_parameter_satuan['parameter_paket_klinik'] = $value_satuan->parameter_paket_klinik;

            $item_permohonan_parameter_satuan['status_verifikasi'] = $value_satuan->status_verifikasi;
            $item_permohonan_parameter_satuan['komentar_verifikasi'] = $value_satuan->komentar_verifikasi;
            $item_permohonan_parameter_satuan['parameter_satuan_klinik'] = $value_satuan->parameter_satuan_klinik;
            // dd($value_satuan->method_permohonan_uji_parameter_klinik);
            $item_permohonan_parameter_satuan['method_permohonan_uji_parameter_klinik'] = $value_satuan->method_permohonan_uji_parameter_klinik;
            $item_permohonan_parameter_satuan['nama_parameter_satuan_klinik'] = $value_satuan->parametersatuanklinik->name_parameter_satuan_klinik ?? null;
            $item_permohonan_parameter_satuan['id_parameter_tms'] = TmsKlinikHelper::resolveTmsIdFromParam($value_satuan);
            $item_permohonan_parameter_satuan['sort_parameter_satuan_klinik'] = $value_satuan->parametersatuanklinik->sort_parameter_satuan_klinik ?? null;
            $item_permohonan_parameter_satuan['sorting_parameter_satuan'] = $value_satuan->sorting_parameter_satuan ?? null;
            $item_permohonan_parameter_satuan['parameter_satuan_klinik_is_option'] = $value_satuan->parametersatuanklinik->is_option ?? 0;
            $item_permohonan_parameter_satuan['parameter_satuan_klinik_option'] = $value_satuan->parametersatuanklinik->option ?? null;
            $item_permohonan_parameter_satuan['parameter_satuan_klinik_requires_nama_jenis'] = (int) ($value_satuan->parametersatuanklinik->requires_nama_jenis ?? 0);
            $item_permohonan_parameter_satuan['requires_nama_jenis'] = (
              (int) ($value_satuan->parametersatuanklinik->requires_nama_jenis ?? 0)
              || (int) ($value_satuan->requires_nama_jenis ?? 0)
            ) ? 1 : 0;
            $item_permohonan_parameter_satuan['metode_parameter_satuan_klinik'] = \Smt\Masterweb\Helpers\Smt::pickMetodeForContext(
              $value_satuan->parametersatuanklinik,
              $item_permohonan_uji_klinik
            );
            $item_permohonan_parameter_satuan['harga_permohonan_uji_parameter_klinik'] = $value_satuan->harga_permohonan_uji_parameter_klinik;
            
            // Jika tidak ada hasil dan tidak ada yang dipilih dari history, gunakan hasil terakhir dari history
            $hasil_parameter = $value_satuan->hasil_permohonan_uji_parameter_klinik;
            $paramHistory = $historyByParam[$value_satuan->id_permohonan_uji_parameter_klinik] ?? collect();

            if (empty($hasil_parameter) && empty($value_satuan->selected_history_id)) {
              $last_history = $paramHistory->first();
                if ($last_history && !empty($last_history->hasil_permohonan_uji_parameter_klinik)) {
                    $hasil_parameter = $last_history->hasil_permohonan_uji_parameter_klinik;
                // Tidak perlu menyimpan kembali ke database di sini, cukup gunakan untuk tampilan
                }
            }
            $item_permohonan_parameter_satuan['hasil_permohonan_uji_parameter_klinik'] = $hasil_parameter;
            
            // Add selected_history_id dan history count untuk status tampilan
            $item_permohonan_parameter_satuan['selected_history_id'] = $value_satuan->selected_history_id ?? null;
            $history_count = $paramHistory instanceof \Illuminate\Support\Collection ? $paramHistory->count() : 0;
            $item_permohonan_parameter_satuan['history_count'] = $history_count;
            $item_permohonan_parameter_satuan['has_selected_history'] = !empty($value_satuan->selected_history_id) && $history_count > 0;
            
            $item_permohonan_parameter_satuan['flag_permohonan_uji_parameter_klinik'] = $value_satuan->flag_permohonan_uji_parameter_klinik;
            $item_permohonan_parameter_satuan['keterangan_permohonan_uji_parameter_klinik'] = $value_satuan->keterangan_permohonan_uji_parameter_klinik;
            $item_permohonan_parameter_satuan['offset_baku_mutu'] = $value_satuan->offset_baku_mutu ?? 'default';

            $id_parameter_jenis_klinik = $value_satuan->jenis_parameter_klinik_id;
            $parameter_satuan_for_bm = (string) $value_satuan->parameter_satuan_klinik;
            if ($is_haji) {
              $parameter_satuan_for_bm = BakuMutuPermohonanKlinikHelper::resolveHajiLookupSatuanId(
                (string) $id_parameter_jenis_klinik,
                $parameter_satuan_for_bm
              );
            }

            // Query baku mutu dengan logic is_haji
            // Jika is_haji = true, cari yang is_haji = 1 terlebih dahulu, jika tidak ada gunakan is_haji = 0 atau null
            $data_parameter_by_baku_mutu = BakuMutu::where('parameter_jenis_klinik_id', $id_parameter_jenis_klinik)
              ->where('parameter_satuan_klinik_id', $parameter_satuan_for_bm);
            
            if ($is_haji) {
              // Cari yang is_haji = 1 terlebih dahulu
              $data_parameter_by_baku_mutu_haji = (clone $data_parameter_by_baku_mutu)->where('is_haji', 1)->get();
              if ($data_parameter_by_baku_mutu_haji->count() > 0) {
                $data_parameter_by_baku_mutu = $data_parameter_by_baku_mutu_haji;
              } else {
                // Jika tidak ada yang is_haji = 1, gunakan yang is_haji = 0 atau null
                $data_parameter_by_baku_mutu = $data_parameter_by_baku_mutu->where(function($query) {
                  $query->where('is_haji', 0)->orWhereNull('is_haji');
                })->get();
              }
            } else {
              $data_parameter_by_baku_mutu = $data_parameter_by_baku_mutu->where(function($query) {
                $query->where('is_haji', 0)->orWhereNull('is_haji');
              })->get();
            }

            // Initialize variables for multiple baku mutu handling
            $multiple_baku_mutu = [];
            $item_parameter_by_baku_mutu = null;
            if (count($data_parameter_by_baku_mutu) > 0) {


             

              // Query untuk is_khusus_baku_mutu = 0 dengan logic is_haji dan gender
              // Prioritas: jika is_haji = true, cari yang is_haji = 1 (tidak peduli is_khusus_baku_mutu)
              // Kemudian sesuaikan berdasarkan gender_baku_mutu: jika ada gender, pilih yang sesuai dengan gender pasien
              // Jika tidak ada yang sesuai gender, pilih yang gender_baku_mutu = null
              if ($is_haji) {
                // Cari yang is_haji = 1 terlebih dahulu (tidak peduli is_khusus_baku_mutu)
                $baku_mutu_haji = BakuMutu::where('parameter_jenis_klinik_id', $id_parameter_jenis_klinik)
                  ->where('parameter_satuan_klinik_id', $parameter_satuan_for_bm)
                  ->where('is_haji', 1)
                  ->whereNull('deleted_at')
                  ->get();
                
                if ($baku_mutu_haji->count() > 0) {
                  // Jika ada yang memiliki gender_baku_mutu sesuai dengan gender pasien, pilih itu
                  $check_parameter_by_baku_mutu = $baku_mutu_haji->where('gender_baku_mutu', $pasien_gender)->first();
                  
                  // Jika tidak ada yang sesuai gender, pilih yang gender_baku_mutu = null
                  if (!$check_parameter_by_baku_mutu) {
                    $check_parameter_by_baku_mutu = $baku_mutu_haji->whereNull('gender_baku_mutu')->first();
                  }
                  
                  // Jika masih tidak ada, ambil yang pertama
                  if (!$check_parameter_by_baku_mutu) {
                    $check_parameter_by_baku_mutu = $baku_mutu_haji->first();
                  }
                } else {
                  // Jika tidak ada yang is_haji = 1, gunakan yang is_haji = 0 atau null dengan logika gender yang sama
                  $baku_mutu_non_haji = BakuMutu::where('parameter_jenis_klinik_id', $id_parameter_jenis_klinik)
                    ->where('parameter_satuan_klinik_id', $parameter_satuan_for_bm)
                    ->where('is_khusus_baku_mutu', '0')
                    ->where(function($query) {
                      $query->where('is_haji', 0)->orWhereNull('is_haji');
                    })
                    ->whereNull('deleted_at')
                    ->get();
                  
                  // Jika ada yang memiliki gender_baku_mutu sesuai dengan gender pasien, pilih itu
                  $check_parameter_by_baku_mutu = $baku_mutu_non_haji->where('gender_baku_mutu', $pasien_gender)->first();
                  
                  // Jika tidak ada yang sesuai gender, pilih yang gender_baku_mutu = null
                  if (!$check_parameter_by_baku_mutu) {
                    $check_parameter_by_baku_mutu = $baku_mutu_non_haji->whereNull('gender_baku_mutu')->first();
                  }
                  
                  // Jika masih tidak ada, ambil yang pertama
                  if (!$check_parameter_by_baku_mutu) {
                    $check_parameter_by_baku_mutu = $baku_mutu_non_haji->first();
                  }
                }
              } else {
                // Jika bukan haji, hanya gunakan yang is_haji = 0 atau null dengan logika gender
                $baku_mutu_non_haji = BakuMutu::where('parameter_jenis_klinik_id', $id_parameter_jenis_klinik)
                  ->where('parameter_satuan_klinik_id', $parameter_satuan_for_bm)
                  ->where('is_khusus_baku_mutu', '0')
                  ->where(function($query) {
                    $query->where('is_haji', 0)->orWhereNull('is_haji');
                  })
                  ->whereNull('deleted_at')
                  ->get();
                
                // Jika ada yang memiliki gender_baku_mutu sesuai dengan gender pasien, pilih itu
                $check_parameter_by_baku_mutu = $baku_mutu_non_haji->where('gender_baku_mutu', $pasien_gender)->first();
                
                // Jika tidak ada yang sesuai gender, pilih yang gender_baku_mutu = null
                if (!$check_parameter_by_baku_mutu) {
                  $check_parameter_by_baku_mutu = $baku_mutu_non_haji->whereNull('gender_baku_mutu')->first();
                }
                
                // Jika masih tidak ada, ambil yang pertama
                if (!$check_parameter_by_baku_mutu) {
                  $check_parameter_by_baku_mutu = $baku_mutu_non_haji->first();
                }
              }



              // cek dulu apakah ada data dengan data khusus sperti general atau specific

              if ($check_parameter_by_baku_mutu) {
                $item_parameter_by_baku_mutu = $check_parameter_by_baku_mutu;
                // General bisa punya >1 baris (Negatif + Pos 1 (+), keduanya is_normal)
                $generalCollection = $is_haji
                  ? (isset($baku_mutu_haji) && $baku_mutu_haji->count() > 0 ? $baku_mutu_haji : ($baku_mutu_non_haji ?? collect()))
                  : ($baku_mutu_non_haji ?? collect());
                $multiple_baku_mutu = $generalCollection->count() > 1
                  ? $generalCollection->values()->toArray()
                  : [];
              } else {
             

                // Cari semua baku mutu khusus untuk parameter ini dengan logic is_haji dan gender
                if ($is_haji) {
                  // Cari yang is_haji = 1 terlebih dahulu
                  $all_baku_mutu_khusus = BakuMutu::where('parameter_jenis_klinik_id', $id_parameter_jenis_klinik)
                    ->where('parameter_satuan_klinik_id', $parameter_satuan_for_bm)
                    ->where('is_khusus_baku_mutu', '1')
                    ->where('is_haji', 1)
                    ->whereNull('deleted_at')
                    ->get();
                  
                  if ($all_baku_mutu_khusus->count() == 0) {
                    // Jika tidak ada yang is_haji = 1, gunakan yang is_haji = 0 atau null
                    $all_baku_mutu_khusus = BakuMutu::where('parameter_jenis_klinik_id', $id_parameter_jenis_klinik)
                      ->where('parameter_satuan_klinik_id', $parameter_satuan_for_bm)
                      ->where('is_khusus_baku_mutu', '1')
                      ->where(function($query) {
                        $query->where('is_haji', 0)->orWhereNull('is_haji');
                      })
                      ->whereNull('deleted_at')
                      ->get();
                  }
                } else {
                  $all_baku_mutu_khusus = BakuMutu::where('parameter_jenis_klinik_id', $id_parameter_jenis_klinik)
                    ->where('parameter_satuan_klinik_id', $parameter_satuan_for_bm)
                    ->where('is_khusus_baku_mutu', '1')
                    ->where(function($query) {
                      $query->where('is_haji', 0)->orWhereNull('is_haji');
                    })
                    ->whereNull('deleted_at')
                    ->get();
                }

                $item_parameter_by_baku_mutu = null;
                $multiple_baku_mutu = [];

                // Selalu simpan semua baku mutu untuk pengecekan
                $multiple_baku_mutu = $all_baku_mutu_khusus->toArray();
                
                // Debug: Log multiple baku mutu data
                if (count($multiple_baku_mutu) > 1) {
                  \Log::info('Multiple Baku Mutu found for parameter: ' . $value_satuan->parametersatuanklinik->name_parameter_satuan_klinik ?? 'Unknown');
                  \Log::info('Total baku mutu count: ' . count($multiple_baku_mutu));
                  \Log::info('Normal baku mutu count: ' . collect($multiple_baku_mutu)->where('is_normal', 1)->count());
                }

                if ($all_baku_mutu_khusus->count() > 1) {
                  $normal_baku_mutu_collection = $all_baku_mutu_khusus->where('is_normal', 1);
                  
                  if ($normal_baku_mutu_collection->count() > 0) {
                    // Cek apakah semua baku mutu dengan is_normal = 1 memiliki data by gender atau by range umur
                    $all_have_gender_or_umur = $normal_baku_mutu_collection->every(function($item) {
                      $has_gender = (isset($item->gender_baku_mutu) && $item->gender_baku_mutu !== null);
                      $has_umur_range = (isset($item->minimal_umur_baku_mutu) && isset($item->maksimal_umur_baku_mutu));
      
                      return $has_gender || $has_umur_range;
                    });
                    
                    // Jika semua memiliki by gender atau by range umur, prioritaskan yang sesuai dengan pasien
                    if ($all_have_gender_or_umur) {
                      // Prioritas 1: Cari yang sesuai dengan gender DAN umur pasien
                      $matched_by_gender_and_umur = $normal_baku_mutu_collection->filter(function($item) use ($pasien_gender, $pasien_umur) {
                        // Gender harus match (tidak null dan sama dengan pasien)
                        $gender_match = isset($item->gender_baku_mutu) && $item->gender_baku_mutu === $pasien_gender;
                        // Umur harus match (jika ada range umur, harus sesuai)
                        $umur_match = (isset($item->minimal_umur_baku_mutu) && isset($item->maksimal_umur_baku_mutu)
                              && $item->minimal_umur_baku_mutu <= $pasien_umur && $item->maksimal_umur_baku_mutu >= $pasien_umur);

                        $umur_match_gen_null = ((isset($item->minimal_umur_baku_mutu) && isset($item->maksimal_umur_baku_mutu)
                            && $item->minimal_umur_baku_mutu <= $pasien_umur && $item->maksimal_umur_baku_mutu >= $pasien_umur)) 
                            && (!isset($item->gender_baku_mutu) || $item->gender_baku_mutu === null);

                        $gen_match_umur_null = (isset($item->gender_baku_mutu) && $item->gender_baku_mutu === $pasien_gender) && (!isset($item->minimal_umur_baku_mutu) || !isset($item->maksimal_umur_baku_mutu));

                        return ($gender_match && $umur_match) || $umur_match_gen_null || $gen_match_umur_null;
                      });

                      
                      if ($matched_by_gender_and_umur->count() > 0) {
                        $item_parameter_by_baku_mutu = $matched_by_gender_and_umur->first();
                      } else {
                        // Prioritas 2: Cari yang sesuai gender saja (tanpa mempertimbangkan umur)
                        $matched_by_gender = $normal_baku_mutu_collection->filter(function($item) use ($pasien_gender) {
                          return isset($item->gender_baku_mutu) && $item->gender_baku_mutu === $pasien_gender;
                        });

                       
                        
                        if ($matched_by_gender->count() > 0) {
                         
                          $item_parameter_by_baku_mutu = $matched_by_gender->first();
                        } else {
                          // Prioritas 3: Cari yang sesuai umur saja (tanpa gender)
                          $matched_by_umur = $normal_baku_mutu_collection->filter(function($item) use ($pasien_umur) {
                            return (!isset($item->minimal_umur_baku_mutu) && !isset($item->maksimal_umur_baku_mutu))
                              || (isset($item->minimal_umur_baku_mutu) && isset($item->maksimal_umur_baku_mutu)
                                  && $item->minimal_umur_baku_mutu <= $pasien_umur && $item->maksimal_umur_baku_mutu >= $pasien_umur);
                          });
                          

                          if ($matched_by_umur->count() > 0) {
                            $item_parameter_by_baku_mutu = $matched_by_umur->first();
                          } else {
                            // Fallback: gunakan yang pertama
                    $item_parameter_by_baku_mutu = $normal_baku_mutu_collection->first();
                          }
                        }
                      }
                    } else {
                      // Jika tidak semua memiliki by gender atau by range umur, gunakan yang pertama
                      $item_parameter_by_baku_mutu = $normal_baku_mutu_collection->first();
                    }
                  } else {
                    // Jika tidak ada yang is_normal = 1, gunakan logika dengan gender
                    // Prioritas 1: Cari yang sesuai dengan gender pasien
                    $item_parameter_by_baku_mutu = $all_baku_mutu_khusus
                      ->where('gender_baku_mutu', $pasien_gender)
                      ->first();
                      
                    // Prioritas 2: Jika tidak ada yang sesuai gender, pilih yang gender_baku_mutu = null
                    if (!$item_parameter_by_baku_mutu) {
                      $item_parameter_by_baku_mutu = $all_baku_mutu_khusus
                        ->whereNull('gender_baku_mutu')
                        ->first();
                    }
                    
                    // Prioritas 3: Jika masih tidak ada, ambil yang pertama
                    if (!$item_parameter_by_baku_mutu) {
                      $item_parameter_by_baku_mutu = $all_baku_mutu_khusus->first();
                    }
                  }
                } else {
                  // Jika hanya ada satu atau tidak ada, gunakan logika dengan is_haji dan gender
                  $item_parameter_by_baku_mutu = $all_baku_mutu_khusus->where('gender_baku_mutu', $pasien_gender)->first();
                  if (!$item_parameter_by_baku_mutu) {
                    $item_parameter_by_baku_mutu = $all_baku_mutu_khusus->whereNull('gender_baku_mutu')->first();
                  }
                  if (!$item_parameter_by_baku_mutu) {
                    $item_parameter_by_baku_mutu = $all_baku_mutu_khusus->first();
                  }
                }
              }
            }

            // jika tidak ada satuan di permohonan uji satuan maka ambil value dari baku mutu
            // jika ada nilai satuan di permohonan uji satuan maka ambil nilai dari tabel itu sendiri
            if ($value_satuan->satuan_permohonan_uji_parameter_klinik != null) {
              $item_permohonan_parameter_satuan['satuan_permohonan_uji_parameter_klinik'] = $value_satuan->satuan_permohonan_uji_parameter_klinik;
              $item_permohonan_parameter_satuan['nama_satuan_permohonan_uji_parameter_klinik'] = $value_satuan->unit->name_unit ?? null;
            } else if (isset($item_parameter_by_baku_mutu->unit_id)) {
              $item_permohonan_parameter_satuan['satuan_permohonan_uji_parameter_klinik'] = $item_parameter_by_baku_mutu->unit_id;
              $item_permohonan_parameter_satuan['nama_satuan_permohonan_uji_parameter_klinik'] = $item_parameter_by_baku_mutu->unit->name_unit ?? null;
            } else {
              $item_permohonan_parameter_satuan['satuan_permohonan_uji_parameter_klinik'] = null;
              $item_permohonan_parameter_satuan['nama_satuan_permohonan_uji_parameter_klinik'] = null;
            }

            $item_permohonan_parameter_satuan['min'] = $item_parameter_by_baku_mutu->min ?? null;
            $item_permohonan_parameter_satuan['max'] = $item_parameter_by_baku_mutu->max ?? null;
            $item_permohonan_parameter_satuan['equal'] = $item_parameter_by_baku_mutu->equal ?? null;
            $keterangan_dilaporan_resolved = $this->resolvedKeteranganDilaporanForSatuan(
              $value_satuan,
              $pasien_gender,
              $pasien_umur,
              (int) ($item_permohonan_uji_klinik->is_haji ?? 0),
              true
            );
            $item_permohonan_parameter_satuan['keterangan_dilaporan_baku_mutu_permohonan_uji_parameter_klinik'] = $keterangan_dilaporan_resolved;
            $item_permohonan_parameter_satuan['nilai_baku_mutu'] = $keterangan_dilaporan_resolved ?? ($item_parameter_by_baku_mutu->nilai_baku_mutu ?? null);
            // Tambahkan id_baku_mutu untuk dikirim ke form, fallback ke nilai yang sudah ada di database
            $item_permohonan_parameter_satuan['id_baku_mutu'] = $item_parameter_by_baku_mutu->id_baku_mutu ?? ($value_satuan->baku_mutu_permohonan_uji_parameter_klinik ?? null);
            $item_permohonan_parameter_satuan['kesimpulan_baku_mutu'] = $item_parameter_by_baku_mutu->kesimpulan_baku_mutu ?? null;
            // Tambahkan number_format dari parameter satuan klinik
            $item_permohonan_parameter_satuan['number_format'] = $value_satuan->parametersatuanklinik->number_format ?? 'en';
            // Tambahkan data multiple baku mutu untuk pengecekan
            $item_permohonan_parameter_satuan['multiple_baku_mutu'] = $multiple_baku_mutu ?? [];
            $item_permohonan_parameter_satuan['has_multiple_baku_mutu'] = count($multiple_baku_mutu ?? []) > 1;

            // menyiapkan data array untuk mapping jika data parameter memiliki subsatuan
            $item_permohonan_parameter_satuan['data_permohonan_uji_subsatuan_klinik'] = [];

            $data_permohonan_uji_subsatuan_klinik = $subParamsByParam[$value_satuan->id_permohonan_uji_parameter_klinik] ?? collect();

            if (count($data_permohonan_uji_subsatuan_klinik)) {
              foreach ($data_permohonan_uji_subsatuan_klinik as $key_subsatuan => $value_subsatuan) {
                $item_permohonan_parameter_subsatuan = [];
                $item_permohonan_parameter_subsatuan['id_permohonan_uji_sub_parameter_klinik'] = $value_subsatuan->id_permohonan_uji_sub_parameter_klinik;
                $item_permohonan_parameter_subsatuan['permohonan_uji_parameter_klinik_id'] = $value_subsatuan->permohonan_uji_parameter_klinik_id;
                $item_permohonan_parameter_subsatuan['parameter_sub_satuan_klinik_id'] = $value_subsatuan->parameter_sub_satuan_klinik_id;
                $item_permohonan_parameter_subsatuan['nama_parameter_sub_satuan_klinik_id'] = $value_subsatuan->parametersubsatuanklinik->name_parameter_sub_satuan_klinik ?? null;
                
                // Jika tidak ada hasil dan tidak ada yang dipilih dari history, gunakan hasil terakhir dari history
                $hasil_sub_parameter = $value_subsatuan->hasil_permohonan_uji_sub_parameter_klinik;
                $subHistories = $subHistoryBySubParam[$value_subsatuan->id_permohonan_uji_sub_parameter_klinik] ?? collect();

                if (empty($hasil_sub_parameter) && empty($value_subsatuan->selected_history_id)) {
                  $last_history = $subHistories->first();
                    if ($last_history && !empty($last_history->hasil_permohonan_uji_sub_parameter_klinik)) {
                        $hasil_sub_parameter = $last_history->hasil_permohonan_uji_sub_parameter_klinik;
                    // Tidak perlu menyimpan kembali ke database, cukup gunakan untuk tampilan
                    }
                }
                $item_permohonan_parameter_subsatuan['hasil_permohonan_uji_sub_parameter_klinik'] = $hasil_sub_parameter;
                
                // Add selected_history_id dan history count untuk tampilan
                $item_permohonan_parameter_subsatuan['selected_history_id'] = $value_subsatuan->selected_history_id ?? null;
                $history_count_sub = $subHistories instanceof \Illuminate\Support\Collection ? $subHistories->count() : 0;
                $item_permohonan_parameter_subsatuan['history_count'] = $history_count_sub;
                $item_permohonan_parameter_subsatuan['has_selected_history'] = !empty($value_subsatuan->selected_history_id) && $history_count_sub > 0;
                
                $item_permohonan_parameter_subsatuan['flag_permohonan_uji_sub_parameter_klinik'] = $value_subsatuan->flag_permohonan_uji_sub_parameter_klinik;
                // $item_permohonan_parameter_subsatuan['baku_mutu_permohonan_uji_sub_parameter_klinik'] = $value_subsatuan->baku_mutu_permohonan_uji_sub_parameter_klinik;
                $item_permohonan_parameter_subsatuan['keterangan_permohonan_uji_sub_parameter_klinik'] = $value_subsatuan->keterangan_permohonan_uji_sub_parameter_klinik;
                $item_permohonan_parameter_subsatuan['offset_baku_mutu'] = $value_subsatuan->offset_baku_mutu ?? 'default';

                // cek data baku mutu jika memiliki data subsatuan dengan nilai rujukan
                if (isset($item_parameter_by_baku_mutu->id_baku_mutu)) {
                  $item_parameter_subsatuan_by_baku_mutu = BakuMutuDetailParameterKlinik::where('baku_mutu_id', $item_parameter_by_baku_mutu->id_baku_mutu)
                    ->where('parameter_sub_satuan_baku_mutu_detail_parameter_klinik', $value_subsatuan->parameter_sub_satuan_klinik_id)
                    ->first();

                  if ($item_parameter_subsatuan_by_baku_mutu) {
                    $item_permohonan_parameter_subsatuan['min_baku_mutu_detail_parameter_klinik'] = $item_parameter_subsatuan_by_baku_mutu->min_baku_mutu_detail_parameter_klinik;
                    $item_permohonan_parameter_subsatuan['max_baku_mutu_detail_parameter_klinik'] = $item_parameter_subsatuan_by_baku_mutu->max_baku_mutu_detail_parameter_klinik;
                    $item_permohonan_parameter_subsatuan['equal_baku_mutu_detail_parameter_klinik'] = $item_parameter_subsatuan_by_baku_mutu->equal_baku_mutu_detail_parameter_klinik;
                    $item_permohonan_parameter_subsatuan['nilai_baku_mutu_detail_parameter_klinik'] = $item_parameter_subsatuan_by_baku_mutu->nilai_baku_mutu_detail_parameter_klinik;
                  } else {
                    $item_permohonan_parameter_subsatuan['min_baku_mutu_detail_parameter_klinik'] = null;
                    $item_permohonan_parameter_subsatuan['max_baku_mutu_detail_parameter_klinik'] = null;
                    $item_permohonan_parameter_subsatuan['equal_baku_mutu_detail_parameter_klinik'] = null;
                    $item_permohonan_parameter_subsatuan['nilai_baku_mutu_detail_parameter_klinik'] = null;
                  }
                } else {
                  $item_permohonan_parameter_subsatuan['min_baku_mutu_detail_parameter_klinik'] = null;
                  $item_permohonan_parameter_subsatuan['max_baku_mutu_detail_parameter_klinik'] = null;
                  $item_permohonan_parameter_subsatuan['equal_baku_mutu_detail_parameter_klinik'] = null;
                  $item_permohonan_parameter_subsatuan['nilai_baku_mutu_detail_parameter_klinik'] = null;
                }

                if ($value_subsatuan->satuan_permohonan_uji_sub_parameter_klinik != null) {
                  $item_permohonan_parameter_subsatuan['satuan_permohonan_uji_sub_parameter_klinik'] = $value_subsatuan->satuan_permohonan_uji_sub_parameter_klinik;

                  $item_permohonan_parameter_subsatuan['nama_satuan_permohonan_uji_sub_parameter_klinik'] = $value_subsatuan->unit->name_unit ?? null;
                } else if (isset($item_parameter_subsatuan_by_baku_mutu->unit_id_baku_mutu_detail_parameter_klinik)) {
                  $item_permohonan_parameter_subsatuan['satuan_permohonan_uji_sub_parameter_klinik'] = $item_parameter_subsatuan_by_baku_mutu->unit_id_baku_mutu_detail_parameter_klinik;

                  $item_permohonan_parameter_subsatuan['nama_satuan_permohonan_uji_sub_parameter_klinik'] = $item_parameter_subsatuan_by_baku_mutu->unit->name_unit ?? null;
                } else {
                  $item_permohonan_parameter_subsatuan['satuan_permohonan_uji_sub_parameter_klinik'] = null;

                  $item_permohonan_parameter_subsatuan['nama_satuan_permohonan_uji_sub_parameter_klinik'] = null;
                }

                // cek dulu punya satuan di subparameter atau tidak
                // jika tidak ada maka ambil ke baku mutu
                // else null
                /* if ($value_subsatuan->satuan_permohonan_uji_sub_parameter_klinik != null) {
                $item_permohonan_parameter_subsatuan['satuan_permohonan_uji_sub_parameter_klinik'] = $value_subsatuan->satuan_permohonan_uji_sub_parameter_klinik;
                } else if (isset($item_parameter_subsatuan_by_baku_mutu->unit_id_baku_mutu_detail_parameter_klinik)) {
                $item_permohonan_parameter_subsatuan['satuan_permohonan_uji_sub_parameter_klinik'] = $item_parameter_subsatuan_by_baku_mutu->unit_id_baku_mutu_detail_parameter_klinik;
                } else {
                $item_permohonan_parameter_subsatuan['satuan_permohonan_uji_sub_parameter_klinik'] = null;
                }

                $item_permohonan_parameter_subsatuan['min_baku_mutu_detail_parameter_klinik'] = $item_parameter_subsatuan_by_baku_mutu->min_baku_mutu_detail_parameter_klinik;
                $item_permohonan_parameter_subsatuan['max_baku_mutu_detail_parameter_klinik'] = $item_parameter_subsatuan_by_baku_mutu->max_baku_mutu_detail_parameter_klinik;
                $item_permohonan_parameter_subsatuan['equal_baku_mutu_detail_parameter_klinik'] = $item_parameter_subsatuan_by_baku_mutu->equal_baku_mutu_detail_parameter_klinik;
                $item_permohonan_parameter_subsatuan['nilai_baku_mutu_detail_parameter_klinik'] = $item_parameter_subsatuan_by_baku_mutu->nilai_baku_mutu_detail_parameter_klinik; */
                $item_permohonan_parameter_satuan['data_permohonan_uji_subsatuan_klinik'][] = $item_permohonan_parameter_subsatuan;
              }
            }

            array_push($parameter_jenis_klinik['item_permohonan_parameter_satuan'], $item_permohonan_parameter_satuan);
            // get data baku mutu untuk menyiapkan data nilai rujukan jika ada dimasukkan jika tidak maka akan dilewati
            // melewati data kondisi pasien berupa umur dan gender dahulu ya kawaaaaan
          }
        }

        array_push($arr_permohonan_parameter, $parameter_jenis_klinik);
      }

    }

    $arr_permohonan_parameter = $this->finalizeArrPermohonanParameterSort($arr_permohonan_parameter, true);

    // Get pengambilan sample data (latest successful)
    $latest_sampling = \Smt\Masterweb\Models\PengambilanSampleKlinik::where('permohonan_uji_klinik_id', $id_permohonan_uji_klinik)
      ->where('status_sampling', 'Berhasil')
      ->whereNull('deleted_at')
      ->orderBy('created_at', 'desc')
      ->first();

    // Get penerimaan sampel data
    $penerimaan_sampel = $item_permohonan_uji_klinik->penerimaan_sampel ?? '';
    $volume_sampel = $item_permohonan_uji_klinik->volume_sampel ?? '';
    $kualitas_sampel = $item_permohonan_uji_klinik->kualitas_sampel ?? '';
    $kualitas_lisis = $item_permohonan_uji_klinik->kualitas_lisis == 1;
    $kualitas_ikterik = $item_permohonan_uji_klinik->kualitas_ikterik == 1;
    $kualitas_lipemik = $item_permohonan_uji_klinik->kualitas_lipemik == 1;
    $kualitas_cukup = $item_permohonan_uji_klinik->kualitas_cukup == 1;
    $kualitas_beku = $item_permohonan_uji_klinik->kualitas_beku == 1;

    // Cache daftar petugas analis klinik agar halaman analis lebih ringan
    $petugas_analis = $this->getPetugasAnalisKlinik();

    // Get current user and check if they have petugas
    $currentUser = Auth::user();
    $userPetugas = null;
    $userPetugasNama = null;
    
    if ($currentUser && $currentUser->petugas) {
      $userPetugas = $currentUser->petugas;
      $userPetugasNama = $userPetugas->nama ?? null;
    }

    $kondisi_pasien = $latest_sampling->kondisi_pasien ?? '';

    $kirim_hasil_whatsapp = (int) ($item_permohonan_uji_klinik->kirim_hasil_whatsapp ?? 0) === 1;
    $phone_pasien_wa = optional($item_permohonan_uji_klinik->pasien)->phone_pasien;
    $bisa_kirim_hasil_whatsapp = $kirim_hasil_whatsapp && !empty($phone_pasien_wa);

    return view('masterweb::module.admin.laboratorium.permohonan-uji-klinik-2.analis-permohonan-uji-paramater-klinik', [
      'item_permohonan_uji_klinik' => $item_permohonan_uji_klinik,
      'tgl_register_permohonan_uji_klinik' => $tgl_register,
      'tgl_pengujian' => $tgl_pengujian,
      'data_verifikasi_analitik' => $data_verifikasi_analitik,
      'nama_analis' => $nama_analis,
      'tgl_spesimen_darah' => $tgl_spesimen_darah,
      'tgl_spesimen_urine' => $tgl_spesimen_urine,
      'data_detail_uji_paket' => $data_permohonan_uji_paket_klinik,
      'arr_permohonan_parameter' => $arr_permohonan_parameter,
      'latest_sampling' => $latest_sampling,
      'tgl_waktu_sampling' => self::formatTanggalWaktuSamplingKlinikDisplay(
        $id_permohonan_uji_klinik,
        $latest_sampling,
        $item_permohonan_uji_klinik
      ),
      'penerimaan_sampel' => $penerimaan_sampel,
      'volume_sampel' => $volume_sampel,
      'kualitas_sampel' => $kualitas_sampel,
      'kualitas_lisis' => $kualitas_lisis,
      'kualitas_ikterik' => $kualitas_ikterik,
      'kualitas_lipemik' => $kualitas_lipemik,
      'kualitas_cukup' => $kualitas_cukup,
      'kualitas_beku' => $kualitas_beku,
      'petugas_analis' => $petugas_analis,
      'user_petugas_nama' => $userPetugasNama,
      'kondisi_pasien' => $kondisi_pasien,
      'kirim_hasil_whatsapp' => $kirim_hasil_whatsapp,
      'bisa_kirim_hasil_whatsapp' => $bisa_kirim_hasil_whatsapp,
      'phone_pasien_wa' => $phone_pasien_wa,
      'info_haji' => $this->resolveInfoHajiForPermohonan($item_permohonan_uji_klinik),
    ]);
  }

  public function createVerificationPermohonanUjiParamaterKlinik($id_permohonan_uji_klinik)
  {
    // Menggunakan logika yang sama dengan createPermohonanUjiAnalis
    // tapi mengarah ke view verification-permohonan-uji-paramater-klinik
    $item_permohonan_uji_klinik = PermohonanUjiKlinik2::with('pasien')->find($id_permohonan_uji_klinik);
    $is_haji = !empty($item_permohonan_uji_klinik->id_permohonan_uji_klinik_haji) || $item_permohonan_uji_klinik->is_haji == 1;
    $tgl_register = Carbon::createFromFormat('Y-m-d H:i:s', $item_permohonan_uji_klinik->tglregister_permohonan_uji_klinik)->isoFormat('D MMMM Y');

    $verificationActivitySample = VerificationActivitySample::where('is_klinik',$id_permohonan_uji_klinik)->where('id_verification_activity',4)->first();
    $nama_verifikator = '';
    $verifikator_locked = false;

    $data_verifikasi_analitik = VerificationActivitySample::where([
      ['is_klinik', '=', $id_permohonan_uji_klinik],
      ['id_verification_activity', '=', 2],
    ])->first();

    if ($data_verifikasi_analitik) {
        $startDate = Carbon::createFromFormat('Y-m-d H:i:s', $data_verifikasi_analitik->stop_date)
            ->addHour()
            ->format('Y-m-d H:i:s');
    } else {
        $startDate = null;
    }

    if (isset($verificationActivitySample)) {
      $nama_verifikator = $verificationActivitySample->nama_petugas ?? '';
      $verifikator_locked = !empty($nama_verifikator);
      if($verificationActivitySample->start_date  !== null){
        $tgl_pengujian = Carbon::createFromFormat('Y-m-d H:i:s',$verificationActivitySample->start_date)->toISOString();
      }else{
        $tgl_pengujian = null;
      }
    }else{
      $tgl_pengujian = null;
    }

    // Jika user terelasi dengan petugas (id_petugas terisi), verifikator otomatis terkunci ke nama sendiri
    $currentUser = Auth::user();
    $userPetugasNama = null;
    if ($currentUser && $currentUser->petugas) {
      $userPetugasNama = trim($currentUser->petugas->nama ?? '');
      if (!empty($userPetugasNama)) {
        $verifikator_locked = true;
        // Jika verifikator belum ada di DB, isi default dengan nama user
        if (empty($nama_verifikator)) {
          $nama_verifikator = $userPetugasNama;
        }
      }
    }

    if ($item_permohonan_uji_klinik->spesimen_darah_permohonan_uji_klinik !== null) {
      $tgl_spesimen_darah = Carbon::createFromFormat('Y-m-d H:i:s', $item_permohonan_uji_klinik->spesimen_darah_permohonan_uji_klinik)->toISOString();
    } else {
      $tgl_spesimen_darah = null;
    }

    if ($item_permohonan_uji_klinik->spesimen_urine_permohonan_uji_klinik !== null) {
      $tgl_spesimen_urine = Carbon::createFromFormat('Y-m-d H:i:s', $item_permohonan_uji_klinik->spesimen_urine_permohonan_uji_klinik)->toISOString();
    } else {
      $tgl_spesimen_urine = null;
    }

    if ($item_permohonan_uji_klinik->name_analis_permohonan_uji_klinik !== null) {
      $nama_analis = $item_permohonan_uji_klinik->name_analis_permohonan_uji_klinik;
    } else {
      $nama_analis = '';
    }

    $data_permohonan_uji_paket_klinik = PermohonanUjiPaketKlinik::where('permohonan_uji_klinik', $id_permohonan_uji_klinik)
      ->whereNull('deleted_at')
      ->get();

    $arr_permohonan_parameter = [];

    $data_permohonan_uji_satuan_klinik = PermohonanUjiParameterKlinik::where('permohonan_uji_klinik', $id_permohonan_uji_klinik)
      ->orderBy('jenis_parameter_klinik_id', 'ASC')
      ->orderBy('sorting_parameter_satuan', 'ASC')
      ->with(['parametersatuanklinik', 'unit'])
      ->get();

    foreach ($data_permohonan_uji_satuan_klinik as $value_satuan) {
      $this->normalizePermohonanParameterJenisKlinik($value_satuan);
      $this->ensurePermohonanSubParametersForSatuan($value_satuan, $item_permohonan_uji_klinik);
    }

    /**
     * Prefetch history dan sub-parameter untuk semua parameter sekaligus
     * agar nilai history_count di halaman verifikasi konsisten dengan halaman analis.
     */
    $historyByParam = [];
    $subParamsByParam = [];
    $subHistoryBySubParam = [];
    if ($data_permohonan_uji_satuan_klinik->count() > 0) {
      $parameterIds = $data_permohonan_uji_satuan_klinik
        ->pluck('id_permohonan_uji_parameter_klinik')
        ->unique()
        ->values();

      if ($parameterIds->count() > 0) {
        // History untuk parameter utama
        $allHistories = PermohonanUjiParameterKlinikHistory::whereIn('permohonan_uji_parameter_klinik_id', $parameterIds)
          ->orderBy('created_at', 'desc')
          ->get()
          ->groupBy('permohonan_uji_parameter_klinik_id');
        $historyByParam = $allHistories->all();

        // Sub-parameter untuk semua parameter (hindari N+1 query)
        $allSubParams = PermohonanUjiSubParameterKlinik::with(['parametersubsatuanklinik', 'unit'])
          ->whereIn('permohonan_uji_parameter_klinik_id', $parameterIds)
          ->get()
          ->groupBy('permohonan_uji_parameter_klinik_id');
        $subParamsByParam = $allSubParams->all();

        // History untuk semua sub-parameter sekaligus
        $subParamIds = $allSubParams->flatten()->pluck('id_permohonan_uji_sub_parameter_klinik')->unique()->values();
        if ($subParamIds->count() > 0) {
          $allSubHistories = PermohonanUjiSubParameterKlinikHistory::whereIn('permohonan_uji_sub_parameter_klinik_id', $subParamIds)
            ->orderBy('created_at', 'desc')
            ->get()
            ->groupBy('permohonan_uji_sub_parameter_klinik_id');
          $subHistoryBySubParam = $allSubHistories->all();
        }
      }
    }

    $data_jenis_parameter_klinik = PermohonanUjiParameterKlinik::where('tb_permohonan_uji_parameter_klinik.permohonan_uji_klinik', $id_permohonan_uji_klinik)
      ->join('ms_parameter_jenis_klinik', 'ms_parameter_jenis_klinik.id_parameter_jenis_klinik', '=', 'tb_permohonan_uji_parameter_klinik.jenis_parameter_klinik_id')
      ->whereNull('ms_parameter_jenis_klinik.deleted_at')
      ->groupBy('tb_permohonan_uji_parameter_klinik.jenis_parameter_klinik_id')
      ->orderByRaw('COALESCE(ms_parameter_jenis_klinik.sort_parameter_jenis_klinik, 999999) ASC')
      ->select('tb_permohonan_uji_parameter_klinik.*')
      ->get();

    if (count($data_permohonan_uji_satuan_klinik) > 0) {
      foreach ($data_jenis_parameter_klinik as $key_jenis_parameter_klinik => $value_jenis_parameter_klinik) {
        $parameter_jenis_klinik = [];

        $parameter_jenis_klinik['name_parameter_jenis_klinik'] = $value_jenis_parameter_klinik->jenisparameterklinik->name_parameter_jenis_klinik;
        $parameter_jenis_klinik['id_parameter_jenis_klinik'] = $value_jenis_parameter_klinik->jenisparameterklinik->id_parameter_jenis_klinik;
        $parameter_jenis_klinik['sort_parameter_jenis_klinik'] = $value_jenis_parameter_klinik->jenisparameterklinik->sort_parameter_jenis_klinik ?? 999999;
        $parameter_jenis_klinik['id_parameter_jenis_klinik_parent'] = $value_jenis_parameter_klinik->jenisparameterklinik->id_parameter_jenis_klinik_parent ?? null;
        $parameter_jenis_klinik['item_permohonan_parameter_satuan'] = [];

        foreach ($data_permohonan_uji_satuan_klinik as $key_satuan => $value_satuan) {

          $jenisIdSatuan = $this->resolveEffectiveJenisParameterKlinikId($value_satuan);
          $jenisIdGroup = $value_jenis_parameter_klinik->jenis_parameter_klinik_id
            ?? ($value_jenis_parameter_klinik->jenisparameterklinik->id_parameter_jenis_klinik ?? null);

          if ($jenisIdSatuan == $jenisIdGroup) {

            $pasien_umur = $item_permohonan_uji_klinik->umurtahun_pasien_permohonan_uji_klinik;
            $pasien_gender = $item_permohonan_uji_klinik->pasien->gender_pasien;

            $item_permohonan_parameter_satuan = [];
            $item_permohonan_parameter_satuan['id_permohonan_uji_parameter_klinik'] = $value_satuan->id_permohonan_uji_parameter_klinik;
            $item_permohonan_parameter_satuan['permohonan_uji_klinik'] = $value_satuan->permohonan_uji_klinik;
            $item_permohonan_parameter_satuan['permohonan_uji_paket_klinik'] = $value_satuan->permohonan_uji_paket_klinik;
            $item_permohonan_parameter_satuan['parameter_paket_klinik'] = $value_satuan->parameter_paket_klinik;
            $item_permohonan_parameter_satuan['parameter_satuan_klinik'] = $value_satuan->parameter_satuan_klinik;
            $item_permohonan_parameter_satuan['method_permohonan_uji_parameter_klinik'] = $value_satuan->method_permohonan_uji_parameter_klinik;
            $item_permohonan_parameter_satuan['nama_parameter_satuan_klinik'] = $value_satuan->parametersatuanklinik->name_parameter_satuan_klinik ?? null;
            $item_permohonan_parameter_satuan['sort_parameter_satuan_klinik'] = $value_satuan->parametersatuanklinik->sort_parameter_satuan_klinik ?? null;
            $item_permohonan_parameter_satuan['parameter_satuan_klinik_is_option'] = $value_satuan->parametersatuanklinik->is_option ?? 0;
            $item_permohonan_parameter_satuan['parameter_satuan_klinik_option'] = $value_satuan->parametersatuanklinik->option ?? null;
            $item_permohonan_parameter_satuan['parameter_satuan_klinik_requires_nama_jenis'] = (int) ($value_satuan->parametersatuanklinik->requires_nama_jenis ?? 0);
            $item_permohonan_parameter_satuan['requires_nama_jenis'] = (
              (int) ($value_satuan->parametersatuanklinik->requires_nama_jenis ?? 0)
              || (int) ($value_satuan->requires_nama_jenis ?? 0)
            ) ? 1 : 0;
            $item_permohonan_parameter_satuan['metode_parameter_satuan_klinik'] = \Smt\Masterweb\Helpers\Smt::pickMetodeForContext(
              $value_satuan->parametersatuanklinik,
              $item_permohonan_uji_klinik
            );
            $item_permohonan_parameter_satuan['ket_default_parameter_satuan_klinik'] = $value_satuan->parametersatuanklinik->ket_default ?? null;
            $item_permohonan_parameter_satuan['harga_permohonan_uji_parameter_klinik'] = $value_satuan->harga_permohonan_uji_parameter_klinik;
            $item_permohonan_parameter_satuan['hasil_permohonan_uji_parameter_klinik'] = $value_satuan->hasil_permohonan_uji_parameter_klinik;
            $item_permohonan_parameter_satuan['flag_permohonan_uji_parameter_klinik'] = $value_satuan->flag_permohonan_uji_parameter_klinik;
            $item_permohonan_parameter_satuan['keterangan_permohonan_uji_parameter_klinik'] = $value_satuan->keterangan_permohonan_uji_parameter_klinik;
            $item_permohonan_parameter_satuan['offset_baku_mutu'] = $value_satuan->offset_baku_mutu ?? 'default';
            $item_permohonan_parameter_satuan['status_verifikasi'] = $value_satuan->status_verifikasi ?? 'pending';
            $item_permohonan_parameter_satuan['komentar_verifikasi'] = $value_satuan->komentar_verifikasi ?? null;

            // Tambahkan informasi history agar badge pengulangan di halaman verifikasi bisa muncul
            $paramHistory = $historyByParam[$value_satuan->id_permohonan_uji_parameter_klinik] ?? collect();
            $history_count = $paramHistory instanceof \Illuminate\Support\Collection ? $paramHistory->count() : 0;
            $item_permohonan_parameter_satuan['history_count'] = $history_count;
            $item_permohonan_parameter_satuan['selected_history_id'] = $value_satuan->selected_history_id ?? null;
            $item_permohonan_parameter_satuan['has_selected_history'] = !empty($value_satuan->selected_history_id) && $history_count > 0;

            $id_parameter_jenis_klinik = $value_satuan->jenis_parameter_klinik_id;

            $bakuMutuResolved = $this->resolveBakuMutuForPermohonanParameter(
              $id_parameter_jenis_klinik,
              $value_satuan->parameter_satuan_klinik,
              $pasien_gender,
              $pasien_umur,
              $is_haji
            );
            $item_parameter_by_baku_mutu = $bakuMutuResolved['selected'];
            $multiple_baku_mutu = $bakuMutuResolved['multiple_baku_mutu'];

            if ($value_satuan->satuan_permohonan_uji_parameter_klinik != null) {
              $item_permohonan_parameter_satuan['satuan_permohonan_uji_parameter_klinik'] = $value_satuan->satuan_permohonan_uji_parameter_klinik;
              $item_permohonan_parameter_satuan['nama_satuan_permohonan_uji_parameter_klinik'] = $value_satuan->unit->name_unit ?? null;
            } else if (isset($item_parameter_by_baku_mutu->unit_id)) {
              $item_permohonan_parameter_satuan['satuan_permohonan_uji_parameter_klinik'] = $item_parameter_by_baku_mutu->unit_id;
              $item_permohonan_parameter_satuan['nama_satuan_permohonan_uji_parameter_klinik'] = $item_parameter_by_baku_mutu->unit->name_unit ?? null;
            } else {
              $item_permohonan_parameter_satuan['satuan_permohonan_uji_parameter_klinik'] = null;
              $item_permohonan_parameter_satuan['nama_satuan_permohonan_uji_parameter_klinik'] = null;
            }

            $item_permohonan_parameter_satuan['min'] = $item_parameter_by_baku_mutu->min ?? null;
            $item_permohonan_parameter_satuan['max'] = $item_parameter_by_baku_mutu->max ?? null;
            $item_permohonan_parameter_satuan['equal'] = $item_parameter_by_baku_mutu->equal ?? null;
            $keterangan_dilaporan_resolved = $this->resolvedKeteranganDilaporanForSatuan(
              $value_satuan,
              $pasien_gender,
              $pasien_umur,
              $is_haji ? 1 : 0,
              true
            );
            $item_permohonan_parameter_satuan['keterangan_dilaporan_baku_mutu_permohonan_uji_parameter_klinik'] = $keterangan_dilaporan_resolved;
            $item_permohonan_parameter_satuan['nilai_baku_mutu'] = $keterangan_dilaporan_resolved ?? ($item_parameter_by_baku_mutu->nilai_baku_mutu ?? null);
            $item_permohonan_parameter_satuan['kesimpulan_baku_mutu'] = $item_parameter_by_baku_mutu->kesimpulan_baku_mutu ?? null;
            $item_permohonan_parameter_satuan['id_baku_mutu'] = $item_parameter_by_baku_mutu->id_baku_mutu ?? ($value_satuan->baku_mutu_permohonan_uji_parameter_klinik ?? null);
            $item_permohonan_parameter_satuan['kesimpulan_baku_mutu'] = $item_parameter_by_baku_mutu->kesimpulan_baku_mutu ?? null;
            // Tambahkan number_format dari parameter satuan klinik
            $item_permohonan_parameter_satuan['number_format'] = $value_satuan->parametersatuanklinik->number_format ?? 'en';
            // Tambahkan data multiple baku mutu untuk pengecekan
            $item_permohonan_parameter_satuan['multiple_baku_mutu'] = $multiple_baku_mutu ?? [];
            $item_permohonan_parameter_satuan['has_multiple_baku_mutu'] = $bakuMutuResolved['has_multiple_baku_mutu'];

            $item_permohonan_parameter_satuan['data_permohonan_uji_subsatuan_klinik'] = [];

            $data_permohonan_uji_subsatuan_klinik = collect($subParamsByParam[$value_satuan->id_permohonan_uji_parameter_klinik] ?? []);

            if (count($data_permohonan_uji_subsatuan_klinik)) {
              foreach ($data_permohonan_uji_subsatuan_klinik as $key_subsatuan => $value_subsatuan) {
                $item_permohonan_parameter_subsatuan = [];
                $item_permohonan_parameter_subsatuan['id_permohonan_uji_sub_parameter_klinik'] = $value_subsatuan->id_permohonan_uji_sub_parameter_klinik;
                $item_permohonan_parameter_subsatuan['permohonan_uji_parameter_klinik_id'] = $value_subsatuan->permohonan_uji_parameter_klinik_id;
                $item_permohonan_parameter_subsatuan['parameter_sub_satuan_klinik_id'] = $value_subsatuan->parameter_sub_satuan_klinik_id;
                $item_permohonan_parameter_subsatuan['nama_parameter_sub_satuan_klinik_id'] = $value_subsatuan->parametersubsatuanklinik->name_parameter_sub_satuan_klinik ?? null;
                
                // Jika tidak ada hasil dan tidak ada yang dipilih dari history, gunakan hasil terakhir dari history
                $hasil_sub_parameter = $value_subsatuan->hasil_permohonan_uji_sub_parameter_klinik;
                if (empty($hasil_sub_parameter) && empty($value_subsatuan->selected_history_id)) {
                    $last_history = collect($subHistoryBySubParam[$value_subsatuan->id_permohonan_uji_sub_parameter_klinik] ?? [])->first();
                    if ($last_history && !empty($last_history->hasil_permohonan_uji_sub_parameter_klinik)) {
                        $hasil_sub_parameter = $last_history->hasil_permohonan_uji_sub_parameter_klinik;
                        // Update hasil di database
                        $value_subsatuan->hasil_permohonan_uji_sub_parameter_klinik = $hasil_sub_parameter;
                        $value_subsatuan->save();
                    }
                }
                $item_permohonan_parameter_subsatuan['hasil_permohonan_uji_sub_parameter_klinik'] = $hasil_sub_parameter;
                
                $item_permohonan_parameter_subsatuan['flag_permohonan_uji_sub_parameter_klinik'] = $value_subsatuan->flag_permohonan_uji_sub_parameter_klinik;
                $item_permohonan_parameter_subsatuan['keterangan_permohonan_uji_sub_parameter_klinik'] = $value_subsatuan->keterangan_permohonan_uji_sub_parameter_klinik;
                $item_permohonan_parameter_subsatuan['offset_baku_mutu'] = $value_subsatuan->offset_baku_mutu ?? 'default';
                $item_permohonan_parameter_subsatuan['status_verifikasi'] = $value_subsatuan->status_verifikasi ?? 'approved';
                $item_permohonan_parameter_subsatuan['komentar_verifikasi'] = $value_subsatuan->komentar_verifikasi ?? null;
                // Tambahkan data multiple baku mutu untuk sub parameter
                $item_permohonan_parameter_subsatuan['has_multiple_baku_mutu'] = $bakuMutuResolved['has_multiple_baku_mutu'];

                if (isset($item_parameter_by_baku_mutu->id_baku_mutu)) {
                  $item_parameter_subsatuan_by_baku_mutu = BakuMutuDetailParameterKlinik::where('baku_mutu_id', $item_parameter_by_baku_mutu->id_baku_mutu)
                    ->where('parameter_sub_satuan_baku_mutu_detail_parameter_klinik', $value_subsatuan->parameter_sub_satuan_klinik_id)
                    ->first();

                  if ($item_parameter_subsatuan_by_baku_mutu) {
                    $item_permohonan_parameter_subsatuan['min_baku_mutu_detail_parameter_klinik'] = $item_parameter_subsatuan_by_baku_mutu->min_baku_mutu_detail_parameter_klinik;
                    $item_permohonan_parameter_subsatuan['max_baku_mutu_detail_parameter_klinik'] = $item_parameter_subsatuan_by_baku_mutu->max_baku_mutu_detail_parameter_klinik;
                    $item_permohonan_parameter_subsatuan['equal_baku_mutu_detail_parameter_klinik'] = $item_parameter_subsatuan_by_baku_mutu->equal_baku_mutu_detail_parameter_klinik;
                    $item_permohonan_parameter_subsatuan['nilai_baku_mutu_detail_parameter_klinik'] = $item_parameter_subsatuan_by_baku_mutu->nilai_baku_mutu_detail_parameter_klinik;
                  } else {
                    $item_permohonan_parameter_subsatuan['min_baku_mutu_detail_parameter_klinik'] = null;
                    $item_permohonan_parameter_subsatuan['max_baku_mutu_detail_parameter_klinik'] = null;
                    $item_permohonan_parameter_subsatuan['equal_baku_mutu_detail_parameter_klinik'] = null;
                    $item_permohonan_parameter_subsatuan['nilai_baku_mutu_detail_parameter_klinik'] = null;
                  }
                } else {
                  $item_permohonan_parameter_subsatuan['min_baku_mutu_detail_parameter_klinik'] = null;
                  $item_permohonan_parameter_subsatuan['max_baku_mutu_detail_parameter_klinik'] = null;
                  $item_permohonan_parameter_subsatuan['equal_baku_mutu_detail_parameter_klinik'] = null;
                  $item_permohonan_parameter_subsatuan['nilai_baku_mutu_detail_parameter_klinik'] = null;
                }

                if ($value_subsatuan->satuan_permohonan_uji_sub_parameter_klinik != null) {
                  $item_permohonan_parameter_subsatuan['satuan_permohonan_uji_sub_parameter_klinik'] = $value_subsatuan->satuan_permohonan_uji_sub_parameter_klinik;
                  $item_permohonan_parameter_subsatuan['nama_satuan_permohonan_uji_sub_parameter_klinik'] = $value_subsatuan->unit->name_unit ?? null;
                } else if (isset($item_parameter_subsatuan_by_baku_mutu->unit_id_baku_mutu_detail_parameter_klinik)) {
                  $item_permohonan_parameter_subsatuan['satuan_permohonan_uji_sub_parameter_klinik'] = $item_parameter_subsatuan_by_baku_mutu->unit_id_baku_mutu_detail_parameter_klinik;
                  $item_permohonan_parameter_subsatuan['nama_satuan_permohonan_uji_sub_parameter_klinik'] = $item_parameter_subsatuan_by_baku_mutu->unit->name_unit ?? null;
                } else {
                  $item_permohonan_parameter_subsatuan['satuan_permohonan_uji_sub_parameter_klinik'] = null;
                  $item_permohonan_parameter_subsatuan['nama_satuan_permohonan_uji_sub_parameter_klinik'] = null;
                }

                $item_permohonan_parameter_satuan['data_permohonan_uji_subsatuan_klinik'][] = $item_permohonan_parameter_subsatuan;
              }
            }

            array_push($parameter_jenis_klinik['item_permohonan_parameter_satuan'], $item_permohonan_parameter_satuan);
          }
        }

        array_push($arr_permohonan_parameter, $parameter_jenis_klinik);
      }

    }

    $arr_permohonan_parameter = $this->finalizeArrPermohonanParameterSort($arr_permohonan_parameter, true);

    $latest_sampling = \Smt\Masterweb\Models\PengambilanSampleKlinik::where('permohonan_uji_klinik_id', $id_permohonan_uji_klinik)
      ->where('status_sampling', 'Berhasil')
      ->whereNull('deleted_at')
      ->orderBy('created_at', 'desc')
      ->first();

    $penerimaan_sampel = $item_permohonan_uji_klinik->penerimaan_sampel ?? '';
    $volume_sampel = $item_permohonan_uji_klinik->volume_sampel ?? '';
    $kualitas_lisis = $item_permohonan_uji_klinik->kualitas_lisis == 1;
    $kualitas_ikterik = $item_permohonan_uji_klinik->kualitas_ikterik == 1;
    $kualitas_lipemik = $item_permohonan_uji_klinik->kualitas_lipemik == 1;
    $kualitas_cukup = $item_permohonan_uji_klinik->kualitas_cukup == 1;
    $kualitas_beku = $item_permohonan_uji_klinik->kualitas_beku == 1;

    // Cache daftar petugas analis klinik agar halaman verifikasi lebih ringan
    $petugas_analis = $this->getPetugasAnalisKlinik();

    $kondisi_pasien = $latest_sampling->kondisi_pasien ?? '';

    // Return view verification-permohonan-uji-paramater-klinik (bukan analis-permohonan-uji-paramater-klinik)
    return view('masterweb::module.admin.laboratorium.permohonan-uji-klinik-2.verification-permohonan-uji-paramater-klinik', [
      'item_permohonan_uji_klinik' => $item_permohonan_uji_klinik,
      'tgl_register_permohonan_uji_klinik' => $tgl_register,
      'tgl_pengujian' => $tgl_pengujian,
      'data_verifikasi_analitik' => $data_verifikasi_analitik,
      'nama_analis' => $nama_analis,
      'nama_verifikator' => $nama_verifikator,
      'verifikator_locked' => $verifikator_locked,
      'user_petugas_nama' => $userPetugasNama,
      'tgl_spesimen_darah' => $tgl_spesimen_darah,
      'tgl_spesimen_urine' => $tgl_spesimen_urine,
      'data_detail_uji_paket' => $data_permohonan_uji_paket_klinik,
      'arr_permohonan_parameter' => $arr_permohonan_parameter,
      'latest_sampling' => $latest_sampling,
      'tgl_waktu_sampling' => self::formatTanggalWaktuSamplingKlinikDisplay(
        $id_permohonan_uji_klinik,
        $latest_sampling,
        $item_permohonan_uji_klinik
      ),
      'penerimaan_sampel' => $penerimaan_sampel,
      'volume_sampel' => $volume_sampel,
      'kualitas_lisis' => $kualitas_lisis,
      'kualitas_ikterik' => $kualitas_ikterik,
      'kualitas_lipemik' => $kualitas_lipemik,
      'kualitas_cukup' => $kualitas_cukup,
      'kualitas_beku' => $kualitas_beku,
      'petugas_analis' => $petugas_analis,
      'kondisi_pasien' => $kondisi_pasien,
      'info_haji' => $this->resolveInfoHajiForPermohonan($item_permohonan_uji_klinik),
    ]);
  }

  public function storePermohonanUjiAnalis(Request $request, $id_permohonan_uji_klinik)
  {
    // Validasi: Analis harus diisi
    $nama_analis = $request->post('analis_permohonan_uji_klinik');

    // Cek apakah analis diisi dari dropdown
    if (empty($nama_analis)) {
      // Cek fallback ke verification activity step 2 (Pemeriksaan)
      $verifikasi_pemeriksaan = \Smt\Masterweb\Models\VerificationActivitySample::where([
        ['is_klinik', '=', $id_permohonan_uji_klinik],
        ['id_verification_activity', '=', 2], // Step 2: Pemeriksaan / Analitik
      ])->first();

      if ($verifikasi_pemeriksaan && $verifikasi_pemeriksaan->nama_petugas) {
        $nama_analis = $verifikasi_pemeriksaan->nama_petugas;
      } else {
        // Jika tidak ada analis sama sekali, return error
        return response()->json([
          'status' => false,
          'pesan' => 'Analis harus diisi terlebih dahulu sebelum menyimpan hasil.'
        ]);
      }
    }

    // dd($request->all());
    // try {
      DB::beginTransaction();

      $post = PermohonanUjiKlinik2::find($id_permohonan_uji_klinik);

      if ($request->post('tglpengujian_permohonan_uji_klinik') !== null) {
        $tglpengujian_permohonan_uji_klinik = Carbon::createFromFormat('d/m/Y H:i', $request->post('tglpengujian_permohonan_uji_klinik'))->format('Y-m-d H:i');
      } else {
        $tglpengujian_permohonan_uji_klinik = null;
      }

      $post->tglpengujian_permohonan_uji_klinik = $tglpengujian_permohonan_uji_klinik;
      $is_not_darah = $request->post('is_not_darah');
      if (!isset($is_not_darah) && $request->post('spesimen_darah_permohonan_uji_klinik') !== null) {
        $spesimen_darah_permohonan_uji_klinik = Carbon::createFromFormat('d/m/Y H:i', $request->post('spesimen_darah_permohonan_uji_klinik'))->format('Y-m-d H:i');
      } else {
        $spesimen_darah_permohonan_uji_klinik = null;
      }

      $post->spesimen_darah_permohonan_uji_klinik = $spesimen_darah_permohonan_uji_klinik;
      $is_not_urine = $request->post('is_not_urine');

      if (!isset($is_not_urine) && $request->post('spesimen_urine_permohonan_uji_klinik') !== null) {
        $spesimen_urine_permohonan_uji_klinik = Carbon::createFromFormat('d/m/Y H:i', $request->post('spesimen_urine_permohonan_uji_klinik'))->format('Y-m-d H:i');
      } else {
        $spesimen_urine_permohonan_uji_klinik = null;
      }

      // Simpan nama analis ke permohonan uji klinik
      $post->name_analis_permohonan_uji_klinik = $nama_analis;

      $post->spesimen_urine_permohonan_uji_klinik = $spesimen_urine_permohonan_uji_klinik;
      
      // Simpan catatan hasil (+ flag apakah masih mengikuti master default)
      if ($request->has('catatan_hasil')) {
        $submittedCatatan = (string) $request->post('catatan_hasil');
        $post->catatan_hasil = $submittedCatatan;

        if (Schema::hasColumn('tb_permohonan_uji_klinik_2', 'catatan_hasil_from_master')) {
          $parameterIds = PermohonanUjiParameterKlinik::query()
            ->where('permohonan_uji_klinik', $id_permohonan_uji_klinik)
            ->whereNull('deleted_at')
            ->pluck('parameter_satuan_klinik')
            ->filter()
            ->map(function ($v) {
              return (string) $v;
            })
            ->unique()
            ->values()
            ->all();
          $defaultCatatan = Smt::buildDefaultCatatanHasilFromParameters($parameterIds);
          $post->catatan_hasil_from_master = (
            Smt::normalizeCatatanHasilText($submittedCatatan)
            === Smt::normalizeCatatanHasilText($defaultCatatan)
          ) ? 1 : 0;
        }
      }
      
      // Simpan kesimpulan hasil
      $post->kesimpulan_hasil = $request->post('kesimpulan_hasil');

      if ($request->has('keterangan_metode') && Schema::hasColumn('tb_permohonan_uji_klinik_2', 'keterangan_metode')) {
        $post->keterangan_metode = $request->post('keterangan_metode');
      }

      // Simpan flag kirim hasil WhatsApp (bisa diubah dari halaman analis)
      if ($request->has('kirim_hasil_whatsapp')) {
        $post->kirim_hasil_whatsapp = (int) $request->post('kirim_hasil_whatsapp', 0) === 1 ? 1 : 0;
      }
      
      // Cek apakah ini "selesai" atau "simpan sementara"
      $isSelesai = $request->post('is_selesai') == '1' || $request->post('is_selesai') === 1;
      
      // Jika selesai, update status dan VerificationActivitySample
      // Jika simpan sementara, hanya simpan data tanpa update status dan step
      if ($isSelesai) {
        $post->status_permohonan_uji_klinik = 'SELESAI';

        // Step 3 (Pemeriksa Sampel / Input Output Hasil Px)
        $verifikasi_hasil_px = VerificationActivitySample::where('is_klinik', $id_permohonan_uji_klinik)
          ->where('id_verification_activity', 3)
          ->where(function ($q) {
            $q->where('resampling', 0)->orWhereNull('resampling');
          })
          ->first();

        if (!empty($post->tglpengujian_permohonan_uji_klinik)) {
          $startDate = Carbon::parse($post->tglpengujian_permohonan_uji_klinik)->format('Y-m-d H:i:s');
        } elseif ($verifikasi_hasil_px && !empty($verifikasi_hasil_px->start_date)) {
          $startDate = Carbon::parse($verifikasi_hasil_px->start_date)->format('Y-m-d H:i:s');
        } else {
          $startDate = DateHelper::clockOnRegisterDate(DateHelper::permohonanAnchorAt($post))->format('Y-m-d H:i:s');
        }

        $stopDate = Carbon::createFromFormat('Y-m-d H:i:s', $startDate)
          ->addMinutes(10)
          ->format('Y-m-d H:i:s');
        $namaPetugasPemeriksa = $nama_analis
          ? self::resolvePetugasCanonicalName($nama_analis)
          : null;

        if ($verifikasi_hasil_px == null) {
          $verificationActivitySamplePX = new VerificationActivitySample();
          $verificationActivitySamplePX->id = Uuid::uuid4()->toString();
          $verificationActivitySamplePX->id_verification_activity = 3;
          $verificationActivitySamplePX->start_date = $startDate;
          $verificationActivitySamplePX->stop_date = $stopDate;
          $verificationActivitySamplePX->nama_petugas = $namaPetugasPemeriksa;
          $verificationActivitySamplePX->is_klinik = $id_permohonan_uji_klinik;
          $verificationActivitySamplePX->is_done = 1;
          $verificationActivitySamplePX->save();
        } else {
          $verifikasi_hasil_px->start_date = $startDate;
          $verifikasi_hasil_px->stop_date = $stopDate;
          if ($namaPetugasPemeriksa !== null) {
            $verifikasi_hasil_px->nama_petugas = $namaPetugasPemeriksa;
          }
          $verifikasi_hasil_px->is_done = 1;
          $verifikasi_hasil_px->save();
        }
      }
      // Jika simpan sementara, status tetap tidak berubah (tidak update status dan VerificationActivitySample)

      $simpan = $post->save();

      if (count($request->permohonan_uji_parameter_klinik ?? []) > 0) {
        foreach ($request->permohonan_uji_parameter_klinik as $key_permohonan_uji_parameter_klinik => $value_permohonan_uji_parameter_klinik) {
          if (isset($request->parameter_sub_satuan_klinik_id[$value_permohonan_uji_parameter_klinik])) {
            foreach ($request->parameter_sub_satuan_klinik_id[$value_permohonan_uji_parameter_klinik] as $key_parameter_sub_satuan_klinik => $value_parameter_sub_satuan_klinik) {
              $check_pu_sub_parameter = PermohonanUjiSubParameterKlinik::where('permohonan_uji_parameter_klinik_id', $request->permohonan_uji_parameter_klinik[$value_permohonan_uji_parameter_klinik])
                ->where('id_permohonan_uji_sub_parameter_klinik', $request->parameter_sub_satuan_klinik_id[$value_permohonan_uji_parameter_klinik][$value_parameter_sub_satuan_klinik])
                ->first();

              if (isset($check_pu_sub_parameter)) {
                $post_detail_sub_pupark = $check_pu_sub_parameter;
                $post_detail_sub_pupark->hasil_permohonan_uji_sub_parameter_klinik = $request->hasil_permohonan_uji_sub_parameter_klinik[$value_permohonan_uji_parameter_klinik][$value_parameter_sub_satuan_klinik] ?? null;
                $post_detail_sub_pupark->flag_permohonan_uji_sub_parameter_klinik = $request->flag_permohonan_uji_sub_parameter_klinik[$value_permohonan_uji_parameter_klinik][$value_parameter_sub_satuan_klinik] ?? null;
                $post_detail_sub_pupark->satuan_permohonan_uji_sub_parameter_klinik = $request->satuan_permohonan_uji_sub_parameter_klinik[$value_permohonan_uji_parameter_klinik][$value_parameter_sub_satuan_klinik] ?? null;
                $post_detail_sub_pupark->baku_mutu_permohonan_uji_sub_parameter_klinik = $request->baku_mutu_permohonan_uji_sub_parameter_klinik[$value_permohonan_uji_parameter_klinik][$value_parameter_sub_satuan_klinik] ?? null;

                $check_detail_pupark_for_sub = PermohonanUjiParameterKlinik::where('permohonan_uji_klinik', $id_permohonan_uji_klinik)
                  ->where('id_permohonan_uji_parameter_klinik', $request->permohonan_uji_parameter_klinik[$value_permohonan_uji_parameter_klinik])
                  ->first();
                if ($check_detail_pupark_for_sub && $check_detail_pupark_for_sub->parameter_satuan_klinik) {
                  $parameter_satuan_klinik = ParameterSatuanKlinik::where('id_parameter_satuan_klinik', $check_detail_pupark_for_sub->parameter_satuan_klinik)->first();
                  $post_detail_sub_pupark->keterangan_permohonan_uji_sub_parameter_klinik = ($parameter_satuan_klinik && $parameter_satuan_klinik->ket_default_parameter_satuan_klinik)
                    ? $parameter_satuan_klinik->ket_default_parameter_satuan_klinik
                    : null;
                } else {
                  $post_detail_sub_pupark->keterangan_permohonan_uji_sub_parameter_klinik = null;
                }

                $post_detail_sub_pupark->offset_baku_mutu = $request->offset_baku_mutu_sub[$value_permohonan_uji_parameter_klinik][$value_parameter_sub_satuan_klinik] ?? 'default';
                $post_detail_sub_pupark->save();
              }
            }
          } else {
            $check_detail_pupark = PermohonanUjiParameterKlinik::where('permohonan_uji_klinik', $id_permohonan_uji_klinik)
              ->where('id_permohonan_uji_parameter_klinik', $request->permohonan_uji_parameter_klinik[$value_permohonan_uji_parameter_klinik])
              ->first();

            if (!$check_detail_pupark) {
              continue;
            }

            $post_detail_pupark = $check_detail_pupark;
            $post_detail_pupark->hasil_permohonan_uji_parameter_klinik = $request->hasil_permohonan_uji_parameter_klinik[$value_permohonan_uji_parameter_klinik] ?? null;
            $post_detail_pupark->flag_permohonan_uji_parameter_klinik = "-";
            $post_detail_pupark->method_permohonan_uji_parameter_klinik = $request->method_permohonan_uji_parameter_klinik[$value_permohonan_uji_parameter_klinik] ?? $post_detail_pupark->method_permohonan_uji_parameter_klinik;
            $post_detail_pupark->satuan_permohonan_uji_parameter_klinik = $request->satuan_permohonan_uji_parameter_klinik[$value_permohonan_uji_parameter_klinik] ?? $post_detail_pupark->satuan_permohonan_uji_parameter_klinik;
            $post_detail_pupark->baku_mutu_permohonan_uji_parameter_klinik = $request->baku_mutu_permohonan_uji_parameter_klinik[$value_permohonan_uji_parameter_klinik] ?? $post_detail_pupark->baku_mutu_permohonan_uji_parameter_klinik;

            if ($post_detail_pupark->parameter_satuan_klinik) {
              $parameter_satuan_klinik = ParameterSatuanKlinik::where('id_parameter_satuan_klinik', $post_detail_pupark->parameter_satuan_klinik)->first();
              $post_detail_pupark->keterangan_permohonan_uji_parameter_klinik = ($parameter_satuan_klinik && $parameter_satuan_klinik->ket_default_parameter_satuan_klinik)
                ? $parameter_satuan_klinik->ket_default_parameter_satuan_klinik
                : null;
            } else {
              $post_detail_pupark->keterangan_permohonan_uji_parameter_klinik = null;
            }

            $post_detail_pupark->offset_baku_mutu = $request->offset_baku_mutu_param[$value_permohonan_uji_parameter_klinik] ?? 'default';
            $post_detail_pupark->save();
          }
        }
      }

      DB::commit();

      try {
        $this->syncAnalisHasilToSatuSehat($request, $post, $id_permohonan_uji_klinik);
      } catch (\Throwable $e) {
        \Log::warning('Satu Sehat dilewati setelah simpan analis: ' . $e->getMessage(), [
          'permohonan_id' => $id_permohonan_uji_klinik,
        ]);
      }


      if ($simpan == true) {
        $response = [
          'status' => true, 
          'pesan' => "Data permohonan uji klinik untuk analis berhasil diubah!"
        ];
        
        // Jika selesai, tambahkan redirect URL ke halaman verifikasi
        if ($isSelesai) {
          $response['redirect_url'] = url('/elits-permohonan-uji-klinik-2/verification/' . $id_permohonan_uji_klinik);
        }
        
        return response()->json($response, 200);
      } else {
        return response()->json(['status' => false, 'pesan' => "Data permohonan uji klinik untuk analis tidak berhasil diubah!"], 200);
      }
    // } catch (\Exception $e) {
    //   DB::rollback();

    //   return response()->json(['status' => false, 'pesan' => 'System gagal melakukan perubahan!'], 200);
    // }
  }

  /**
   * Kirim Observation/DiagnosticReport ke Satu Sehat setelah hasil analis tersimpan.
   * Gagal/duplikat tidak boleh menggagalkan simpan lokal.
   */
  private function syncAnalisHasilToSatuSehat(Request $request, PermohonanUjiKlinik2 $post, $id_permohonan_uji_klinik): void
  {
    if (!SatuSehatHelper::isEnabled() || config('services.satu_sehat.version') !== 'prd') {
      return;
    }

    $idPasienSatuSehat = optional($post->pasien)->id_pasien_satu_sehat;
    if (empty($idPasienSatuSehat)) {
      return;
    }

    $encounterId = $post->id_satu_sehat_encounter ?? null;
    $encounter = json_decode($post->encounter_json_satu_sehat, true);
    $encounterDisplay = $encounter['class']['display'] ?? null;
    if (empty($encounterId) || empty($encounterDisplay)) {
      return;
    }

    $namaAnalisNormalized = str_replace(',', '', (string) $request->analis_permohonan_uji_klinik);
    $practitioner = SatuSehatPractitioner::query()
      ->whereRaw("REPLACE(name_petugas, ',', '') = ?", [$namaAnalisNormalized])
      ->first();
    $practitionerCode = $practitioner->code_satu_sehat_practitioner ?? null;
    if (empty($practitionerCode)) {
      return;
    }

    $tglIso = null;
    $tglRaw = $request->post('tglpengujian_permohonan_uji_klinik');
    if (!empty($tglRaw)) {
      try {
        $tglIso = Carbon::createFromFormat('d/m/Y H:i', $tglRaw)->toIso8601String();
      } catch (\Throwable $e) {
        try {
          $tglIso = Carbon::parse($tglRaw)->toIso8601String();
        } catch (\Throwable $e2) {
          $tglIso = Carbon::now()->toIso8601String();
        }
      }
    } elseif (!empty($post->tglpengujian_permohonan_uji_klinik)) {
      $tglIso = Carbon::parse($post->tglpengujian_permohonan_uji_klinik)->toIso8601String();
    } else {
      $tglIso = Carbon::now()->toIso8601String();
    }

    $observationResults = [];
    $codingParameters = [];
    $postedLoincCodes = [];
    $paramIds = $request->permohonan_uji_parameter_klinik ?? [];
    if (!is_array($paramIds) || empty($paramIds)) {
      return;
    }

    foreach ($paramIds as $value_permohonan_uji_parameter_klinik) {
      if (isset($request->parameter_sub_satuan_klinik_id[$value_permohonan_uji_parameter_klinik])) {
        continue;
      }

      $hasil_parameter = $request->hasil_permohonan_uji_parameter_klinik[$value_permohonan_uji_parameter_klinik] ?? null;
      if ($hasil_parameter === null || $hasil_parameter === '') {
        continue;
      }

      $paramRow = PermohonanUjiParameterKlinik::where('permohonan_uji_klinik', $id_permohonan_uji_klinik)
        ->where('id_permohonan_uji_parameter_klinik', $value_permohonan_uji_parameter_klinik)
        ->first();
      if (!$paramRow) {
        continue;
      }

      $parameter = ParameterSatuanKlinik::query()
        ->where('id_parameter_satuan_klinik', $paramRow->parameter_satuan_klinik)
        ->first();
      if (!$parameter) {
        continue;
      }

      $codeIonic = trim((string) \Smt\Masterweb\Helpers\Smt::pickLoincForContext($parameter, $post));
      if ($codeIonic === '' || $codeIonic === '-' || isset($postedLoincCodes[$codeIonic])) {
        continue;
      }

      $observationId = $this->createObservation(
        $paramRow,
        $codeIonic,
        $parameter->name_parameter_satuan_klinik,
        $idPasienSatuSehat,
        $practitionerCode,
        $encounterId,
        $encounterDisplay,
        $tglIso,
        (float) $hasil_parameter,
        "microliter",
        "uL"
      );

      $postedLoincCodes[$codeIonic] = true;
      if ($observationId) {
        $observationResults[] = ["reference" => "Observation/" . $observationId];
        $codingParameters[] = [
          "system" => "http://loinc.org",
          "code" => $codeIonic,
          "display" => $parameter->name_parameter_satuan_klinik,
        ];
      }
    }

    if (empty($observationResults)) {
      return;
    }

    $serviceRequests = [];
    $pakets = PermohonanUjiPaketKlinik::query()
      ->where('permohonan_uji_klinik', $post->id_permohonan_uji_klinik)
      ->get(['id_service_request']);
    foreach ($pakets as $paket) {
      if (!empty($paket->id_service_request)) {
        $serviceRequests[] = ["reference" => "ServiceRequest/" . $paket->id_service_request];
      }
    }
    if (empty($serviceRequests)) {
      return;
    }

    try {
      $this->createDiagnosticReport(
        $post,
        $codingParameters,
        $idPasienSatuSehat,
        $encounterId,
        $tglIso,
        $practitionerCode,
        $observationResults,
        $post->id_spesimen,
        $serviceRequests
      );
    } catch (\Throwable $e) {
      \Log::warning('Satu Sehat DiagnosticReport dilewati: ' . $e->getMessage(), [
        'permohonan_id' => $id_permohonan_uji_klinik,
      ]);
    }
  }

  public function storeVerificationPermohonanUjiParamaterKlinik(Request $request, $id_permohonan_uji_klinik)
  {
    // Validasi: Verifikator harus diisi
    $nama_verifikator = $request->post('verifikator_permohonan_uji_klinik');

    if (empty($nama_verifikator)) {
      return response()->json([
        'status' => false,
        'pesan' => 'Verifikator harus diisi terlebih dahulu sebelum menyimpan verifikasi.'
      ]);
    }

    DB::beginTransaction();

    try {
      $post = PermohonanUjiKlinik2::find($id_permohonan_uji_klinik);

      if (!$post) {
        DB::rollBack();
        return response()->json([
          'status' => false,
          'pesan' => 'Data permohonan uji klinik tidak ditemukan.'
        ], 404);
      }

      // Simpan nama verifikator (bisa disimpan di field terpisah atau di verification activity)
      // Untuk sementara, kita simpan di verification activity step 4
      // Note: is_done akan di-set setelah pengecekan status verifikasi
      $verifikasi = VerificationActivitySample::where([
        ['is_klinik', '=', $id_permohonan_uji_klinik],
        ['id_verification_activity', '=', 4],
      ])->first();

      if (isset($verifikasi)) {
        $verifikasi->nama_petugas = $nama_verifikator
          ? self::resolvePetugasCanonicalName($nama_verifikator)
          : $nama_verifikator;
        // is_done akan di-set setelah pengecekan status verifikasi
        $verifikasi->save();
      } else {
        $verificationActivitySamplePX = new VerificationActivitySample();
        $verificationActivitySamplePX->id = Uuid::uuid4()->toString();
        $verificationActivitySamplePX->id_verification_activity = 4;

        // Tanggal registrasi + jam klik (bukan hari ini)
        $startDate = DateHelper::clockOnRegisterDate(DateHelper::permohonanAnchorAt($post))->format('Y-m-d H:i:s');

        // Set start_date
        $verificationActivitySamplePX->start_date = $startDate;

        // Tambahkan 10 menit untuk stop_date
        $verificationActivitySamplePX->stop_date = Carbon::createFromFormat('Y-m-d H:i:s', $startDate)
        ->addMinutes(10) // Menambahkan 10 menit
        ->format('Y-m-d H:i:s');

        $verificationActivitySamplePX->nama_petugas = $nama_verifikator
          ? self::resolvePetugasCanonicalName($nama_verifikator)
          : null;
        $verificationActivitySamplePX->is_klinik = $id_permohonan_uji_klinik;
        // $verificationActivitySamplePX->is_done = 1;

        $verificationActivitySamplePX->save();
        $verifikasi = $verificationActivitySamplePX;
      }

      // Update status verifikasi dan komentar untuk setiap parameter
      $hasNonApprovedStatus = false; // Flag untuk menandai ada status yang bukan approved

      $permohonanParams = $request->permohonan_uji_parameter_klinik;
      if (is_array($permohonanParams) && count($permohonanParams) > 0) {
        foreach ($permohonanParams as $key_permohonan_uji_parameter_klinik => $value_permohonan_uji_parameter_klinik) {
          // Cek apakah ada sub parameter
          if (isset($request->parameter_sub_satuan_klinik_id[$value_permohonan_uji_parameter_klinik])) {
            // Update sub parameter
            foreach ($request->parameter_sub_satuan_klinik_id[$value_permohonan_uji_parameter_klinik] as $key_parameter_sub_satuan_klinik => $value_parameter_sub_satuan_klinik) {
              $check_pu_sub_parameter = PermohonanUjiSubParameterKlinik::where('permohonan_uji_parameter_klinik_id', $value_permohonan_uji_parameter_klinik)
                ->where('id_permohonan_uji_sub_parameter_klinik', $value_parameter_sub_satuan_klinik)
                ->first();

              if ($check_pu_sub_parameter) {
                // Update hasil jika ada koreksi
                if (isset($request->hasil_permohonan_uji_sub_parameter_klinik[$value_permohonan_uji_parameter_klinik][$value_parameter_sub_satuan_klinik])) {
                  $check_pu_sub_parameter->hasil_permohonan_uji_sub_parameter_klinik = $request->hasil_permohonan_uji_sub_parameter_klinik[$value_permohonan_uji_parameter_klinik][$value_parameter_sub_satuan_klinik];
                }

                // Update offset_baku_mutu jika ada perubahan
                if (isset($request->offset_baku_mutu_sub[$value_permohonan_uji_parameter_klinik][$value_parameter_sub_satuan_klinik])) {
                  $check_pu_sub_parameter->offset_baku_mutu = $request->offset_baku_mutu_sub[$value_permohonan_uji_parameter_klinik][$value_parameter_sub_satuan_klinik];
                }

                // Copy keterangan dari ParameterSatuanKlinik untuk sub parameter
                $check_detail_pupark_for_sub = PermohonanUjiParameterKlinik::where('permohonan_uji_klinik', $id_permohonan_uji_klinik)
                  ->where('id_permohonan_uji_parameter_klinik', $value_permohonan_uji_parameter_klinik)
                  ->first();
                if ($check_detail_pupark_for_sub && $check_detail_pupark_for_sub->parameter_satuan_klinik) {
                  $parameter_satuan_klinik = ParameterSatuanKlinik::where('id_parameter_satuan_klinik', $check_detail_pupark_for_sub->parameter_satuan_klinik)->first();
                  if ($parameter_satuan_klinik && $parameter_satuan_klinik->ket_default_parameter_satuan_klinik) {
                    $check_pu_sub_parameter->keterangan_permohonan_uji_sub_parameter_klinik = $parameter_satuan_klinik->ket_default_parameter_satuan_klinik;
                  }
                }

                // Simpan status verifikasi dan komentar
                if (isset($request->status_verifikasi_sub[$value_permohonan_uji_parameter_klinik][$value_parameter_sub_satuan_klinik])) {
                  $status_verifikasi_sub = $request->status_verifikasi_sub[$value_permohonan_uji_parameter_klinik][$value_parameter_sub_satuan_klinik];
                  $check_pu_sub_parameter->status_verifikasi = $status_verifikasi_sub;

                  // Cek jika status bukan approved
                  if ($status_verifikasi_sub != 'approved') {
                    $hasNonApprovedStatus = true;
                  }
                }
                if (isset($request->komentar_verifikasi_sub[$value_permohonan_uji_parameter_klinik][$value_parameter_sub_satuan_klinik])) {
                  $check_pu_sub_parameter->komentar_verifikasi = $request->komentar_verifikasi_sub[$value_permohonan_uji_parameter_klinik][$value_parameter_sub_satuan_klinik];
                }

                $check_pu_sub_parameter->save();
              }
            }
          } else {
            // Update parameter utama
            $check_detail_pupark = PermohonanUjiParameterKlinik::where('permohonan_uji_klinik', $id_permohonan_uji_klinik)
              ->where('id_permohonan_uji_parameter_klinik', $value_permohonan_uji_parameter_klinik)
              ->first();

            if ($check_detail_pupark) {
              // Update hasil jika ada koreksi
              if (isset($request->hasil_permohonan_uji_parameter_klinik[$value_permohonan_uji_parameter_klinik])) {
                $check_detail_pupark->hasil_permohonan_uji_parameter_klinik = $request->hasil_permohonan_uji_parameter_klinik[$value_permohonan_uji_parameter_klinik];
              }

              // Update method jika ada perubahan
              if (isset($request->method_permohonan_uji_parameter_klinik[$value_permohonan_uji_parameter_klinik])) {
                $check_detail_pupark->method_permohonan_uji_parameter_klinik = $request->method_permohonan_uji_parameter_klinik[$value_permohonan_uji_parameter_klinik];
              }

              // Update offset_baku_mutu jika ada perubahan
              if (isset($request->offset_baku_mutu_param[$value_permohonan_uji_parameter_klinik])) {
                $check_detail_pupark->offset_baku_mutu = $request->offset_baku_mutu_param[$value_permohonan_uji_parameter_klinik];
              }

              // Copy keterangan dari ParameterSatuanKlinik untuk parameter utama
              if ($check_detail_pupark->parameter_satuan_klinik) {
                $parameter_satuan_klinik = ParameterSatuanKlinik::where('id_parameter_satuan_klinik', $check_detail_pupark->parameter_satuan_klinik)->first();
                if ($parameter_satuan_klinik && $parameter_satuan_klinik->ket_default_parameter_satuan_klinik) {
                  $check_detail_pupark->keterangan_permohonan_uji_parameter_klinik = $parameter_satuan_klinik->ket_default_parameter_satuan_klinik;
                }
              }

              // Simpan status verifikasi dan komentar
              if (isset($request->status_verifikasi_param[$value_permohonan_uji_parameter_klinik])) {
                $status_verifikasi_param = $request->status_verifikasi_param[$value_permohonan_uji_parameter_klinik];
                $check_detail_pupark->status_verifikasi = $status_verifikasi_param;

                // Cek jika status bukan approved
                if ($status_verifikasi_param != 'approved') {
                  $hasNonApprovedStatus = true;
                }
              }
              if (isset($request->komentar_verifikasi_param[$value_permohonan_uji_parameter_klinik])) {
                $check_detail_pupark->komentar_verifikasi = $request->komentar_verifikasi_param[$value_permohonan_uji_parameter_klinik];
              }

              $check_detail_pupark->save();
            }
          }
        }
      }

      // Jika ada status verifikasi yang bukan "approved", kembalikan ke step 3 (Input Analis) dan step 4 (Verifikasi)
      if ($hasNonApprovedStatus) {
        // Set is_done = 0 untuk step 3 (Input Analis)
        $input_analis = VerificationActivitySample::where([
          ['is_klinik', '=', $id_permohonan_uji_klinik],
          ['id_verification_activity', '=', 3],
        ])->first();

        if ($input_analis) {
          $input_analis->is_done = 0;
          $input_analis->save();
        }

        // Set is_done = 0 untuk step 4 (Verifikasi) agar bisa dikoreksi kembali
        if ($verifikasi) {
          $verifikasi->is_done = 0;
          $verifikasi->save();
        }
      } else {
        // Jika semua status approved dan user klik Selesai, selesaikan step 4 (Verifikasi)
        if ($verifikasi && ($request->post('is_selesai') == 1 || $request->post('is_selesai') === '1')) {
          $verifikasi->is_done = 1;
          $verifikasi->save();

          $this->finalizeKlinikVerificationStep4(
            $id_permohonan_uji_klinik,
            $nama_verifikator,
            $request->post('tglpengujian_permohonan_uji_klinik'),
            $verifikasi
          );
        }
      }

      // Simpan catatan hasil
      if ($request->has('catatan_hasil')) {
        $post->catatan_hasil = $request->post('catatan_hasil');
      }

      // Simpan kesimpulan hasil
      $post->kesimpulan_hasil = $request->post('kesimpulan_hasil');

      if ($request->has('keterangan_metode') && Schema::hasColumn('tb_permohonan_uji_klinik_2', 'keterangan_metode')) {
        $post->keterangan_metode = $request->post('keterangan_metode');
      }
      $post->save();

      DB::commit();

      // Return response dengan informasi apakah ada yang perlu diperbaiki
      if ($hasNonApprovedStatus) {
        return response()->json([
          'status' => true,
          'pesan' => 'Verifikasi berhasil disimpan. Terdapat parameter yang perlu diperbaiki, permohonan dikembalikan ke step Input Analis dan Verifikasi untuk dikoreksi kembali.',
          'kembali_ke_pemeriksaan' => true,
          'redirect_url' => route('elits-permohonan-uji-klinik-2.create-permohonan-uji-analis2', $id_permohonan_uji_klinik),
        ]);
      } else {
        $redirectVerification = route('elits-permohonan-uji-klinik-2.verification', $id_permohonan_uji_klinik);
        $isSelesaiRequest = $request->post('is_selesai') == 1 || $request->post('is_selesai') === '1';

        return response()->json([
          'status' => true,
          'pesan' => $isSelesaiRequest
            ? 'Verifikasi berhasil diselesaikan.'
            : 'Verifikasi berhasil disimpan.',
          'redirect_url' => $redirectVerification,
        ]);
      }

    } catch (\Throwable $e) {
      DB::rollBack();
      Log::error('Error storing verification klinik: ' . $e->getMessage(), [
        'exception' => $e,
        'permohonan_id' => $id_permohonan_uji_klinik,
        'trace' => $e->getTraceAsString(),
      ]);
      return response()->json([
        'status' => false,
        'pesan' => 'Terjadi kesalahan saat menyimpan verifikasi: ' . $e->getMessage()
      ], 500);
    }
  }

  private function isSatuSehatDuplicateObservation($errorMsg): bool
  {
    $errorMsg = strtolower((string) $errorMsg);

    return strpos($errorMsg, 'duplicate') !== false
      || strpos($errorMsg, '20002') !== false;
  }

  private function findExistingSatuSehatObservationId($patientId, $encounterId, $ionicCode)
  {
    $ionicCode = trim((string) $ionicCode);
    if ($ionicCode === '' || $ionicCode === '-' || $patientId === '' || $encounterId === '') {
      return null;
    }

    try {
      $response = $this->satuSehatHelper->get('Observation', [
        'subject' => 'Patient/' . $patientId,
        'encounter' => 'Encounter/' . $encounterId,
        'code' => 'http://loinc.org|' . $ionicCode,
      ]);

      if (!isset($response['status_code']) || (int) $response['status_code'] !== 200) {
        return null;
      }

      $entries = $response['body']['entry'] ?? [];
      if (!is_array($entries) || empty($entries)) {
        return null;
      }

      $first = $entries[0]['resource']['id'] ?? null;

      return $first ? (string) $first : null;
    } catch (\Throwable $e) {
      return null;
    }
  }

  private function extractSatuSehatErrorMessage($response): string
  {
    $body = $response['body'] ?? [];
    if (!is_array($body)) {
      return trim((string) $body);
    }

    $issue = $body['issue'][0] ?? [];
    $parts = [
      $issue['details']['text'] ?? null,
      $issue['diagnostics'] ?? null,
      $issue['details']['coding'][0]['display'] ?? null,
      $body['error'] ?? null,
      $body['message'] ?? null,
    ];

    foreach ($parts as $part) {
      $part = trim((string) $part);
      if ($part !== '') {
        return $part;
      }
    }

    return json_encode($body);
  }

  private function createObservation($parameter, $ionicCode, $parameterName, $patientId, $practitionerId, $encounterId, $encounterDisplay, $datetime, $result, $resultUnit, $resultCode)
  {
    $ionicCode = trim((string) $ionicCode);
    if ($ionicCode === '' || $ionicCode === '-') {
      return null;
    }

    $data = [
      "resourceType" => "Observation",
      "status" => "final",
      "category" => [
        [
          "coding" => [
            [
              "system" => "http://terminology.hl7.org/CodeSystem/observation-category",
              "code" => "laboratory",
              "display" => "Laboratory"
            ]
          ]
        ]
      ],
      "code" => [
        "coding" => [
          [
            "system" => "http://loinc.org",
            "code" => $ionicCode,
            "display" => $parameterName
          ]
        ]
      ],
      "subject" => [
        "reference" => "Patient/".$patientId
      ],
      "performer" => [
        [
          "reference" => "Practitioner/".$practitionerId
        ]
      ],
      "encounter" => [
        "reference" => "Encounter/".$encounterId,
        "display" => $encounterDisplay
      ],
      "effectiveDateTime" => $datetime,
      "issued" => $datetime,
      "valueQuantity" => [
        "value" => $result,
        "unit" => $resultUnit,
        "system" => "http://unitsofmeasure.org",
        "code" => $resultCode
      ]
    ];

    try {
      $idObservation = trim((string) ($parameter->id_observation ?? ''));
      if ($idObservation !== '') {
        $data['id'] = $idObservation;
        $response = $this->satuSehatHelper->put('Observation', $idObservation, $data);

        if (isset($response['status_code']) && (int) $response['status_code'] === 200) {
          return $idObservation;
        }

        \Log::warning('Satu Sehat update Observation gagal, lanjut tanpa memblokir simpan.', [
          'id_observation' => $idObservation,
          'error' => $this->extractSatuSehatErrorMessage($response),
        ]);

        return $idObservation;
      }

      $response = $this->satuSehatHelper->post('Observation', $data);

      if (isset($response['status_code']) && (int) $response['status_code'] === 201) {
        $parameter->id_observation = $response['body']['id'] ?? null;
        $parameter->save();

        return $response['body']['id'] ?? null;
      }

      $errorMsg = $this->extractSatuSehatErrorMessage($response);
      if ($this->isSatuSehatDuplicateObservation($errorMsg)) {
        $existingId = $this->findExistingSatuSehatObservationId($patientId, $encounterId, $ionicCode);
        if ($existingId) {
          $parameter->id_observation = $existingId;
          $parameter->save();

          return $existingId;
        }

        \Log::info('Satu Sehat Observation sudah ada (duplicate 20002), dilewati.', [
          'parameter' => $parameterName,
          'loinc' => $ionicCode,
          'encounter' => $encounterId,
        ]);

        return null;
      }

      \Log::warning('Satu Sehat Observation gagal, simpan lokal tetap dilanjutkan.', [
        'parameter' => $parameterName,
        'loinc' => $ionicCode,
        'error' => $errorMsg,
      ]);
    } catch (\Throwable $e) {
      \Log::warning('Satu Sehat Observation exception, simpan lokal tetap dilanjutkan.', [
        'parameter' => $parameterName,
        'error' => $e->getMessage(),
      ]);
    }

    return null;
  }

  private function createDiagnosticReport($permohonanUji, $codingParameters, $patientId, $encounterId, $datePengujian, $practitionerId, $observations, $specimenId, $serviceRequests)
  {
      $diagnosticReport = [
        "resourceType" => "DiagnosticReport",
        "identifier" => [
          [
            "system" => "http://sys-ids.kemkes.go.id/diagnostic/".config("services.satu_sehat.org_id")."/lab",
            "use" => "official",
            "value" => $permohonanUji->noregister_permohonan_uji_klinik // id permohonan uji
          ]
        ],
        "status" => "final",
        "category" => [
          [
            "coding" => [
              [
                "system" => "http://terminology.hl7.org/CodeSystem/v2-0074",
                "code" => "LAB", // Lab
                "display" => "Laboratory" // Laboratory
              ]
            ]
          ]
        ],
        "code" => [
          "coding" => $codingParameters
        ],
        "subject" => [
          "reference" => "Patient/".$patientId
        ],
        "encounter" => [
          "reference" => "Encounter/".$encounterId
        ],
        "effectiveDateTime" => $datePengujian,
        "issued" => $datePengujian,
        "performer" => [
          [
            "reference" => "Practitioner/".$practitionerId
          ],
          [
            "reference" => "Organization/".config("services.satu_sehat.org_id")
          ]
        ],
        "basedOn" => $serviceRequests,
        "result" => $observations,
        "specimen" => "",
        "conclusionCode" => [
          [
            "coding" => [
              [
                "system" => "http://snomed.info/sct",
                "code" => "260347006",
                "display" => "+"
              ]
            ]
          ]
        ]
      ];

      if ($specimenId == ""){
        unset($diagnosticReport['specimen']);
      }else{
        $idSpecimenArray = explode(',', $specimenId);
        $speciments = [];
        foreach ($idSpecimenArray as $idSpecimen){
          $speciments[] = ["reference" => "Specimen/".$idSpecimen];
        }
        $diagnosticReport["specimen"] = $speciments;
      }

    $idDiagnosticReport = $permohonanUji->id_diagnostic_report;
    if ($idDiagnosticReport != null or $idDiagnosticReport != ""){
      $diagnosticReport['id'] = $idDiagnosticReport;
      $response = $this->satuSehatHelper->put('DiagnosticReport', $idDiagnosticReport, $diagnosticReport);

      if (isset($response['status_code']) && $response['status_code'] != '200'){
        $errorMsg = $response['body']['issue'][0]['details']['text'] ?? ($response['body']['error'] ?? 'Unknown Error');
        throw new Exception("Gagal update diagnostic report!, ". $errorMsg);
      }
    }

    $response = $this->satuSehatHelper->post('DiagnosticReport', $diagnosticReport);
    if (isset($response['status_code']) && $response['status_code'] == '201'){
      $permohonanUji->id_diagnostic_report = $response['body']["id"] ?? null;
      $permohonanUji->save();
    }else{
      $errorMsg = $response['body']['issue'][0]['details']['text'] ?? ($response['body']['error'] ?? 'Unknown Error');
      throw new Exception("Gagal membuat diagnostic report! " . $errorMsg);
    }

  }

  /**
   * Pengaturan cetak hasil (font, spacing, margin baris, margin halaman).
   */
  private function buildHasilColumnWidths(PermohonanUjiKlinik2 $item): array
  {
    $config = [
      'pemeriksaan'  => ['column' => 'lebar_kolom_pemeriksaan_hasil_permohonan_uji_klinik',  'default' => 24, 'min' => 10, 'max' => 45],
      'hasil'        => ['column' => 'lebar_kolom_hasil_hasil_permohonan_uji_klinik',        'default' => 10, 'min' => 5,  'max' => 25],
      'satuan'       => ['column' => 'lebar_kolom_satuan_hasil_permohonan_uji_klinik',       'default' => 14, 'min' => 5,  'max' => 25],
      'metode'       => ['column' => 'lebar_kolom_metode_hasil_permohonan_uji_klinik',       'default' => 12, 'min' => 5,  'max' => 25],
      'nilai_normal' => ['column' => 'lebar_kolom_nilai_normal_hasil_permohonan_uji_klinik', 'default' => 26, 'min' => 15, 'max' => 50],
    ];

    $widths = [];
    foreach ($config as $key => $meta) {
      $raw = Schema::hasColumn('tb_permohonan_uji_klinik_2', $meta['column'])
        ? ($item->{$meta['column']} ?? $meta['default'])
        : $meta['default'];
      $widths[$key] = max($meta['min'], min($meta['max'], (float) $raw));
    }

    return $widths;
  }

  /**
   * Ambil data pasien terbaru dari master untuk cetak hasil (tempat lahir, pekerjaan, alamat).
   */
  private function refreshPasienRelationForCetakHasil(PermohonanUjiKlinik2 $permohonan): void
  {
    $pasienId = $permohonan->pasien_permohonan_uji_klinik ?? null;
    if (!$pasienId) {
      return;
    }

    $freshPasien = Pasien::query()
      ->where('id_pasien', $pasienId)
      ->whereNull('deleted_at')
      ->first();

    if ($freshPasien) {
      $permohonan->setRelation('pasien', $freshPasien);
    }
  }

  /**
   * Sinkronkan profil pasien dari form pendaftaran permohonan uji klinik.
   */
  private function syncPasienProfileFromPermohonanRequest(Pasien $pasien, Request $request): void
  {
    $updateData = [];

    if ($request->has('desa_pasien') && !empty($request->post('desa_pasien'))) {
      $updateData['wilayah_id'] = $request->post('desa_pasien');
    } elseif ($request->has('kecamatan_pasien') && !empty($request->post('kecamatan_pasien'))) {
      $updateData['wilayah_id'] = $request->post('kecamatan_pasien');
    } elseif ($request->has('kabupaten_pasien') && !empty($request->post('kabupaten_pasien'))) {
      $updateData['wilayah_id'] = $request->post('kabupaten_pasien');
    } elseif ($request->has('provinsi_pasien') && !empty($request->post('provinsi_pasien'))) {
      $updateData['wilayah_id'] = $request->post('provinsi_pasien');
    }

    if ($request->exists('phone_pasien')) {
      $updateData['phone_pasien'] = $request->post('phone_pasien');
    }
    if ($request->exists('pekerjaan')) {
      $updateData['pekerjaan'] = $request->post('pekerjaan');
    }
    if ($request->exists('tmpt_lahir')) {
      $updateData['tmpt_lahir'] = $request->post('tmpt_lahir');
    }
    if ($request->exists('alamat_pasien')) {
      $updateData['alamat_pasien'] = Smt::sanitizeAlamatPasien(
        $request->post('alamat_pasien'),
        $pasien->tgllahir_pasien
      );
    }

    if (!empty($updateData)) {
      $pasien->update($updateData);
    }
  }

  /**
   * Stream PDF hasil klinik.
   * Disclaimer TTE/BSrE di kop sementara dimatikan.
   *
   * @param  \Barryvdh\DomPDF\PDF  $pdf
   * @param  string  $filename
   * @param  array  $extraHeaders
   * @return \Illuminate\Http\Response
   */
  private function streamHasilKlinikPdf($pdf, $filename = 'hasil.pdf', array $extraHeaders = [])
  {
    // TTE/BSrE overlay sementara dihilangkan dari kop hasil
    // return Smt::streamPdfWithBsreLastPageFooter($pdf, $filename, $extraHeaders);

    $output = $pdf->output();
    $headers = array_merge([
      'Content-Type' => 'application/pdf',
      'Content-Disposition' => 'inline; filename="' . $filename . '"',
      'Content-Length' => strlen($output),
    ], $extraHeaders);

    return new \Illuminate\Http\Response($output, 200, $headers);
  }

  private function resolveHasilSideMargin($value): float
  {
    if ($value === null || $value === '') {
      return 32.0;
    }

    $margin = (float) $value;
    // Default lama 20px terasa sempit di cetakan
    if ($margin === 20.0) {
      return 32.0;
    }

    return $margin;
  }

  private function buildHasilPrintViewSettings(PermohonanUjiKlinik2 $item, bool $forceKop = false): array
  {
    $legacyPadding = $item->padding_hasil_permohonan_uji_klinik;
    $fallbackRowPadding = ($legacyPadding === null || (float) $legacyPadding === 4.0) ? 1.0 : (float) $legacyPadding;

    $resolveRowPadding = function (?float $specific) use ($fallbackRowPadding, $legacyPadding) {
      if ($specific !== null) {
        return (float) $specific;
      }
      if ($legacyPadding !== null) {
        return (float) $legacyPadding;
      }
      return $fallbackRowPadding;
    };

    return [
      'fontsizeHasil' => (float) ($item->fontsize_hasil_permohonan_uji_klinik ?? 12),
      'showKop' => $forceKop ? 1 : (int) ($item->show_kop_hasil_permohonan_uji_klinik ?? 1),
      'lineHeightHasil' => (float) ($item->line_height_hasil_permohonan_uji_klinik ?? 1.5),
      'paddingHasil' => (float) ($legacyPadding ?? 4.0),
      'paddingTopHasil' => $resolveRowPadding(
        $item->padding_top_hasil_permohonan_uji_klinik !== null
          ? (float) $item->padding_top_hasil_permohonan_uji_klinik
          : null
      ),
      'paddingBottomHasil' => $resolveRowPadding(
        $item->padding_bottom_hasil_permohonan_uji_klinik !== null
          ? (float) $item->padding_bottom_hasil_permohonan_uji_klinik
          : null
      ),
      'marginLeftHasil' => $this->resolveHasilSideMargin($item->margin_left_hasil_permohonan_uji_klinik ?? null),
      'marginRightHasil' => $this->resolveHasilSideMargin($item->margin_right_hasil_permohonan_uji_klinik ?? null),
      'lebarKolomHasil' => $this->buildHasilColumnWidths($item),
      // backward compat
      'lebarKolomSatuanHasil' => $this->buildHasilColumnWidths($item)['satuan'],
    ];
  }

  /**
   * Simpan pengaturan ukuran font untuk cetak hasil pemeriksaan.
   */
  public function saveFontsizeHasil(Request $request, $id_permohonan_uji_klinik)
  {
    $normalize = [];
    if ($request->has('line_height')) {
      $lineHeight = (float) $request->input('line_height');
      if ($lineHeight < 0.5) {
        $normalize['line_height'] = 1;
      }
    }
    if ($request->has('fontsize')) {
      $fontSize = (float) $request->input('fontsize');
      if ($fontSize < 6 || $fontSize > 20) {
        $normalize['fontsize'] = max(6, min(20, $fontSize > 0 ? $fontSize : 12));
      }
    }
    if (!empty($normalize)) {
      $request->merge($normalize);
    }

    $validated = $request->validate([
      'fontsize'       => 'required|numeric|min:6|max:20',
      'show_kop'       => 'nullable|in:0,1',
      'line_height'    => 'nullable|numeric|min:0.5|max:3.0',
      'padding'        => 'nullable|numeric|min:0|max:20',
      'padding_top'    => 'nullable|numeric|min:0|max:20',
      'padding_bottom' => 'nullable|numeric|min:0|max:20',
      'margin_left'    => 'nullable|numeric|min:0|max:60',
      'margin_right'   => 'nullable|numeric|min:0|max:60',
      'lebar_kolom_pemeriksaan'  => 'nullable|numeric|min:10|max:45',
      'lebar_kolom_hasil'        => 'nullable|numeric|min:5|max:25',
      'lebar_kolom_satuan'       => 'nullable|numeric|min:5|max:25',
      'lebar_kolom_metode'       => 'nullable|numeric|min:5|max:25',
      'lebar_kolom_nilai_normal' => 'nullable|numeric|min:15|max:50',
    ]);

    $item = PermohonanUjiKlinik2::find($id_permohonan_uji_klinik);

    if (!$item) {
      return response()->json(['status' => false, 'pesan' => 'Data tidak ditemukan.'], 404);
    }

    $item->fontsize_hasil_permohonan_uji_klinik    = $validated['fontsize'];
    $item->show_kop_hasil_permohonan_uji_klinik    = isset($validated['show_kop']) ? (int) $validated['show_kop'] : 1;
    $item->line_height_hasil_permohonan_uji_klinik = isset($validated['line_height']) ? (float) $validated['line_height'] : 1.5;
    $item->padding_top_hasil_permohonan_uji_klinik = isset($validated['padding_top'])
      ? (float) $validated['padding_top']
      : (isset($validated['padding']) ? (float) $validated['padding'] : null);
    $item->padding_bottom_hasil_permohonan_uji_klinik = isset($validated['padding_bottom'])
      ? (float) $validated['padding_bottom']
      : (isset($validated['padding']) ? (float) $validated['padding'] : null);
    $item->margin_left_hasil_permohonan_uji_klinik = isset($validated['margin_left'])
      ? (float) $validated['margin_left']
      : ($item->margin_left_hasil_permohonan_uji_klinik ?? 32);
    $item->margin_right_hasil_permohonan_uji_klinik = isset($validated['margin_right'])
      ? (float) $validated['margin_right']
      : ($item->margin_right_hasil_permohonan_uji_klinik ?? 32);
    $lebarKolomMap = [
      'lebar_kolom_pemeriksaan'  => 'lebar_kolom_pemeriksaan_hasil_permohonan_uji_klinik',
      'lebar_kolom_hasil'        => 'lebar_kolom_hasil_hasil_permohonan_uji_klinik',
      'lebar_kolom_satuan'       => 'lebar_kolom_satuan_hasil_permohonan_uji_klinik',
      'lebar_kolom_metode'       => 'lebar_kolom_metode_hasil_permohonan_uji_klinik',
      'lebar_kolom_nilai_normal' => 'lebar_kolom_nilai_normal_hasil_permohonan_uji_klinik',
    ];
    foreach ($lebarKolomMap as $requestKey => $dbColumn) {
      if (isset($validated[$requestKey]) && Schema::hasColumn('tb_permohonan_uji_klinik_2', $dbColumn)) {
        $item->{$dbColumn} = (float) $validated[$requestKey];
      }
    }
    $item->padding_hasil_permohonan_uji_klinik = isset($validated['padding'])
      ? (float) $validated['padding']
      : round(((float) $item->padding_top_hasil_permohonan_uji_klinik + (float) $item->padding_bottom_hasil_permohonan_uji_klinik) / 2, 1);
    $item->save();

    // Simpan data hasil sementara (yang belum disimpan ke DB) ke session untuk preview
    $tempHasilJson    = $request->input('temp_hasil');
    $tempSubHasilJson = $request->input('temp_sub_hasil');

    if ($tempHasilJson) {
      $parsed = json_decode($tempHasilJson, true);
      if (is_array($parsed) && count($parsed) > 0) {
        session(['preview_temp_hasil_' . $id_permohonan_uji_klinik => $parsed]);
      }
    }

    if ($tempSubHasilJson) {
      $parsed = json_decode($tempSubHasilJson, true);
      if (is_array($parsed) && count($parsed) > 0) {
        session(['preview_temp_sub_hasil_' . $id_permohonan_uji_klinik => $parsed]);
      }
    }

    $tempOffsetParamJson = $request->input('temp_offset_param');
    if ($tempOffsetParamJson) {
      $parsed = json_decode($tempOffsetParamJson, true);
      if (is_array($parsed)) {
        session(['preview_temp_offset_param_' . $id_permohonan_uji_klinik => $parsed]);
      }
    }

    $tempOffsetSubJson = $request->input('temp_offset_sub');
    if ($tempOffsetSubJson) {
      $parsed = json_decode($tempOffsetSubJson, true);
      if (is_array($parsed)) {
        session(['preview_temp_offset_sub_' . $id_permohonan_uji_klinik => $parsed]);
      }
    }

    $tempMethodJson = $request->input('temp_method');
    if ($tempMethodJson) {
      $parsed = json_decode($tempMethodJson, true);
      if (is_array($parsed) && count($parsed) > 0) {
        session(['preview_temp_method_' . $id_permohonan_uji_klinik => $parsed]);
      }
    }

    // Catatan & kesimpulan dari form (belum disimpan ke DB) untuk preview
    if ($request->exists('catatan_hasil')) {
      session(['preview_temp_catatan_hasil_' . $id_permohonan_uji_klinik => $request->input('catatan_hasil', '')]);
    }
    if ($request->exists('kesimpulan_hasil')) {
      session(['preview_temp_kesimpulan_hasil_' . $id_permohonan_uji_klinik => $request->input('kesimpulan_hasil', '')]);
    }
    if ($request->exists('keterangan_metode')) {
      session(['preview_temp_keterangan_metode_' . $id_permohonan_uji_klinik => $request->input('keterangan_metode', '')]);
    }

    return response()->json([
      'status'         => true,
      'pesan'          => 'Pengaturan berhasil disimpan.',
      'fontsize'       => $item->fontsize_hasil_permohonan_uji_klinik,
      'show_kop'       => $item->show_kop_hasil_permohonan_uji_klinik,
      'line_height'    => $item->line_height_hasil_permohonan_uji_klinik,
      'padding'        => $item->padding_hasil_permohonan_uji_klinik,
      'padding_top'    => $item->padding_top_hasil_permohonan_uji_klinik,
      'padding_bottom' => $item->padding_bottom_hasil_permohonan_uji_klinik,
      'margin_left'    => $item->margin_left_hasil_permohonan_uji_klinik,
      'margin_right'   => $item->margin_right_hasil_permohonan_uji_klinik,
      'lebar_kolom'    => $this->buildHasilColumnWidths($item),
    ]);
  }

  public function updateNoregister(Request $request, $id_permohonan_uji_klinik)
  {
    $post = PermohonanUjiKlinik2::find($id_permohonan_uji_klinik);
    if (!$post) {
      return response()->json(['status' => false, 'pesan' => 'Data tidak ditemukan'], 404);
    }
    $field = $request->input('field');
    $value = $request->input('value');
    if ($field === 'nomor_lab_manual') {
      $seqYear = GlobalLabSequence::resolveYear(
        $post->tglregister_permohonan_uji_klinik ?? $post->created_at ?? date('Y')
      );
      $labInt = NomerLabSequence::resolveUniqueLabNumber(
        $value,
        (int) $seqYear,
        $post->id_permohonan_uji_klinik
      );
      $post->nomor_lab_manual = (string) $labInt;
      $post->is_nomor_lab_manual = 1;
      if (Schema::hasColumn('tb_permohonan_uji_klinik_2', 'nomer_lab')) {
        $post->nomer_lab = $labInt;
      }
      $post->save();
      return response()->json(['status' => true, 'pesan' => 'No. Lab berhasil disimpan', 'value' => (string) $labInt]);
    } elseif ($field === 'nomor_spesimen_manual') {
      $seqYear = GlobalLabSequence::resolveYear(
        $post->tglregister_permohonan_uji_klinik ?? $post->created_at ?? date('Y')
      );
      $spesimenInt = GlobalLabSequence::resolveUniqueSpesimenNumber(
        $value,
        (int) $seqYear,
        $post->id_permohonan_uji_klinik
      );
      $post->nomor_spesimen_manual = (string) $spesimenInt;
      $post->is_nomor_spesimen_manual = 1;
      $post->noregister_permohonan_uji_klinik = (string) $spesimenInt;
      $post->save();
      GlobalLabSequence::raiseLastNumberToAtLeast($spesimenInt, (int) $seqYear);
      return response()->json(['status' => true, 'pesan' => 'No. Spesimen berhasil disimpan', 'value' => (string) $spesimenInt]);
    }
    return response()->json(['status' => false, 'pesan' => 'Field tidak dikenali'], 422);
  }

