  public function convertToRoman($integer)
  {
    // Convert the integer into an integer (just to make sure)
    $integer = intval($integer);
    $result = '';

    // Create a lookup array that contains all of the Roman numerals.
    $lookup = array(
      'M' => 1000,
      'CM' => 900,
      'D' => 500,
      'CD' => 400,
      'C' => 100,
      'XC' => 90,
      'L' => 50,
      'XL' => 40,
      'X' => 10,
      'IX' => 9,
      'V' => 5,
      'IV' => 4,
      'I' => 1,
    );

    foreach ($lookup as $roman => $value) {
      // Determine the number of matches
      $matches = intval($integer / $value);

      // Add the same number of characters to the string
      $result .= str_repeat($roman, $matches);

      // Set the integer to be the remainder of the integer and the value
      $integer = $integer % $value;
    }

    // The Roman numeral should be built, return it
    return $result;
  }

  public function getDataPermohonanUjiKlinikPayment(Request $request)
  {
    $id_permohonan_uji_klinik = $request->permohonan_uji_klinik_id;
    $itemPermohonanUjiKlinik = PermohonanUjiKlinik2::with([
      'pasien',
      'permohonanujipaketklinik' => function($query) {
        $query->whereNull('deleted_at')
              ->with([
                'parameterpaketklinik',
                'parameterpaketextra',
                'permohonanujiparameterklinik' => function($q) {
                  $q->whereNull('deleted_at')
                    ->with('parametersatuanklinik');
                }
              ]);
      }
    ])->findOrFail($id_permohonan_uji_klinik);

    // Check if status is "sudah terdiagnosis"
    $isSudahTerdiagnosis = false;
    if ($itemPermohonanUjiKlinik->doctor_type == 'lab') {
      if ($itemPermohonanUjiKlinik->done_register == true || $itemPermohonanUjiKlinik->done_register == 1) {
        $isSudahTerdiagnosis = true;
      }
    } else {
      // Jika bukan dari lab, berarti dari rujukan dokter (sudah terdiagnosis)
      $isSudahTerdiagnosis = true;
    }

    // Get packages and parameters data (only if sudah terdiagnosis)
    $items = [];
    if ($isSudahTerdiagnosis && $itemPermohonanUjiKlinik->permohonanujipaketklinik) {
      foreach ($itemPermohonanUjiKlinik->permohonanujipaketklinik as $paket) {
        if ($paket->type_permohonan_uji_paket_klinik == 'P') {
          // Package type - check if it's paket extra
          if ($paket->parameter_paket_extra && $paket->parameterpaketextra) {
            // Paket Extra
            $harga = (int) ($paket->harga_permohonan_uji_paket_klinik ?? 0);
            $items[] = [
              'type' => 'Paket Extra',
              'name' => $paket->parameterpaketextra->nama_parameter_paket_extra ?? '-',
              'harga' => $harga,
              'harga_custom' => rupiah($harga),
            ];
          } else {
            // Regular Package
            $harga = (int) ($paket->harga_permohonan_uji_paket_klinik ?? 0);
            $items[] = [
              'type' => 'Paket',
              'name' => $paket->parameterpaketklinik ? $paket->parameterpaketklinik->name_parameter_paket_klinik : '-',
              'harga' => $harga,
              'harga_custom' => rupiah($harga),
            ];
          }
        } else {
          // Custom/Parameter type
          if ($paket->permohonanujiparameterklinik && $paket->permohonanujiparameterklinik->count() > 0) {
            foreach ($paket->permohonanujiparameterklinik as $param) {
              $harga = (int) ($param->harga_permohonan_uji_parameter_klinik ?? 0);
              $items[] = [
                'type' => 'Parameter',
                'name' => $param->parametersatuanklinik ? $param->parametersatuanklinik->name_parameter_satuan_klinik : '-',
                'harga' => $harga,
                'harga_custom' => rupiah($harga),
              ];
            }
          }
        }
      }
    }

    // Get biaya_pengambilan_sampel
    $biaya_pengambilan_sampel_raw = DB::table('tb_permohonan_uji_klinik_2')
      ->where('id_permohonan_uji_klinik', $id_permohonan_uji_klinik)
      ->value('biaya_pengambilan_sampel');
    
    $biaya_pengambilan_sampel = (int) ($biaya_pengambilan_sampel_raw ?? 0);

    // Jumlahkan harga dari detail item (sumber kebenaran di UI)
    $sum_items = 0;
    foreach ($items as $itemRow) {
      $sum_items += (int) ($itemRow['harga'] ?? 0);
    }
    
    // total_harga di header kadang belum tersinkron; pakai max(header, sum items)
    $total_harga_header = (int) ($itemPermohonanUjiKlinik->total_harga_permohonan_uji_klinik ?? 0);
    $total_harga_parameter = max($total_harga_header, $sum_items);
    $total_akhir = $total_harga_parameter + $biaya_pengambilan_sampel;

    // Perbaiki header jika kosong/tertinggal dibanding detail
    if ($total_harga_header !== $total_harga_parameter) {
      try {
        $itemPermohonanUjiKlinik->total_harga_permohonan_uji_klinik = $total_harga_parameter;
        $itemPermohonanUjiKlinik->save();
      } catch (\Throwable $e) {
        // ignore sync header failure; response tetap pakai total terhitung
      }
    }

    $paymentSync = KlinikPaymentHelper::syncWithTotal($id_permohonan_uji_klinik, (int) $total_akhir);
    $sudah_dibayar = $paymentSync['sudah_dibayar'];
    $sisa_tagihan = $paymentSync['sisa_tagihan'];

    // Get nama petugas from VerificationActivitySample with id_verification_activity = 1
    $verification_activity = VerificationActivitySample::where('is_klinik', $id_permohonan_uji_klinik)
      ->where('id_verification_activity', 1)
      ->first();
    
    $nama_petugas = $verification_activity ? ($verification_activity->nama_petugas ?? Auth::user()->name) : Auth::user()->name;
    $id_petugas = Auth::user()->id; // Keep using Auth::user()->id() for nota_petugas

    $nama_pasien = $itemPermohonanUjiKlinik->pasien
      ? $itemPermohonanUjiKlinik->pasien->nama_pasien
      : ($itemPermohonanUjiKlinik->nama_pasien ?? '-');

    $data = [
      'id_permohonan_uji_klinik' => $itemPermohonanUjiKlinik->id_permohonan_uji_klinik ?? null,
      'nota_petugas' => $id_petugas,
      'nota_namapetugas' => $nama_petugas,
      'nama_pasien' => $nama_pasien,
      'alamat_pasien' => $itemPermohonanUjiKlinik->pasien ? Smt::alamatLengkapPasien($itemPermohonanUjiKlinik->pasien) : null,
      'total_harga_parameter' => $total_harga_parameter,
      'biaya_pengambilan_sampel' => $biaya_pengambilan_sampel,
      'total_harga' => $total_akhir,
      'total_harga_custom' => $total_akhir != null ? rupiah($total_akhir) : 'Rp. 0',
      'sudah_dibayar' => $sudah_dibayar,
      'sudah_dibayar_custom' => rupiah($sudah_dibayar),
      'sisa_tagihan' => $sisa_tagihan,
      'sisa_tagihan_custom' => rupiah($sisa_tagihan),
      'is_sudah_terdiagnosis' => $isSudahTerdiagnosis,
      'items' => $items,
    ];

    return response()->json($data);
  }

  public function storeDataPermohonanUjiKlinikPayment(Request $request)
  {
    // Hanya Bendahara (BNDR) yang boleh mengkonfirmasi pembayaran
    $userLevel = Auth::user()->getlevel->level ?? null;
    if ($userLevel !== 'BNDR') {
      return response()->json([
        'status' => false,
        'pesan' => 'Konfirmasi pembayaran hanya dapat dilakukan oleh Bendahara Penerimaan.',
      ], 403);
    }

    // Get total_harga from either parameter name
    $total_harga = $request->total_harga ?? $request->total_harga_permohonan_uji_payment_klinik ?? 0;
    $terbayar = $request->terbayar_permohonan_uji_payment_klinik ?? $total_harga;

    $terbayar = str_replace('.', '', $terbayar); // jadi "40000"
    $terbayar = (int) $terbayar; // jadi integer 40000
    $total_harga = (int) str_replace('.', '', (string) $total_harga);

    // Validate id_permohonan_uji_klinik
    if (empty($request->id_permohonan_uji_klinik)) {
      return response()->json(['status' => false, 'pesan' => 'ID Permohonan Uji Klinik tidak ditemukan!'], 200);
    }

    // Mulai DB transaction
    DB::beginTransaction();

    try {
      $permohonan_uji_klinik = PermohonanUjiKlinik2::find($request->id_permohonan_uji_klinik);
      if (!$permohonan_uji_klinik) {
        DB::rollBack();
        return response()->json(['status' => false, 'pesan' => 'Data permohonan uji klinik tidak ditemukan!'], 200);
      }

      $biaya_pengambilan = (int) ($permohonan_uji_klinik->biaya_pengambilan_sampel ?? 0);
      $total_tagihan = (int) ($permohonan_uji_klinik->total_harga_permohonan_uji_klinik ?? 0) + $biaya_pengambilan;
      // Jika request tidak mengirim total, pakai tagihan DB (boleh 0 untuk gratis/BPJS)
      if (!$request->filled('total_harga') && !$request->filled('total_harga_permohonan_uji_payment_klinik')) {
        $total_harga = $total_tagihan;
      }
      $total_harga = max(0, (int) $total_harga);

      $existingPayment = PermohonanUjiPaymentKlinik::where('permohonan_uji_klinik_id', $request->id_permohonan_uji_klinik)
        ->whereNull('deleted_at')
        ->orderBy('created_at', 'asc')
        ->lockForUpdate()
        ->first();

      $paymentSync = KlinikPaymentHelper::syncWithTotal($request->id_permohonan_uji_klinik, $total_harga);
      $sudah_dibayar = $paymentSync['sudah_dibayar'];
      $sisa = $paymentSync['sisa_tagihan'];

      // Refresh existing payment setelah sync (bisa berubah jika ada overpay setelah edit)
      if ($existingPayment) {
        $existingPayment->refresh();
      }

      // Tagihan Rp 0: langsung tandai lunas (boleh tanpa nominal > 0)
      if ($total_harga <= 0) {
        if ($existingPayment) {
          $existingPayment->total_harga_permohonan_uji_payment_klinik = 0;
          $existingPayment->terbayar_permohonan_uji_payment_klinik = 0;
          $existingPayment->nota_petugas_permohonan_uji_payment_klinik = $request->nota_petugas_permohonan_uji_payment_klinik ?? auth()->id();
          $existingPayment->date_done_estimation_permohonan_uji_payment_klinik = date('Y-m-d H:i:s', time());
          $existingPayment->save();
        } else {
          $max_nota = (int) PermohonanUjiPaymentKlinik::max('no_nota_permohonan_uji_payment_klinik');
          $post = new PermohonanUjiPaymentKlinik();
          $post->permohonan_uji_klinik_id = $request->id_permohonan_uji_klinik;
          $post->no_nota_permohonan_uji_payment_klinik = $max_nota + 1;
          $post->nota_petugas_permohonan_uji_payment_klinik = $request->nota_petugas_permohonan_uji_payment_klinik ?? auth()->id();
          $post->total_harga_permohonan_uji_payment_klinik = 0;
          $post->terbayar_permohonan_uji_payment_klinik = 0;
          $post->date_done_estimation_permohonan_uji_payment_klinik = date('Y-m-d H:i:s', time());
          $post->save();
        }

        $permohonan_uji_klinik->status_pembayaran = '1';
        $permohonan_uji_klinik->save();
        DB::commit();

        return response()->json([
          'status' => true,
          'pesan' => 'Tagihan Rp 0 berhasil diproses dan ditandai Lunas.',
        ], 200);
      }

      // Sudah lunas: jangan tambah terbayar lagi (cegah dobel dari double-submit / bayar ulang)
      if ($sisa <= 0 && $sudah_dibayar > 0) {
        $permohonan_uji_klinik->status_pembayaran = '1';
        $permohonan_uji_klinik->save();
        DB::commit();

        return response()->json([
          'status' => true,
          'pesan' => 'Tagihan sudah lunas. Tidak ada pembayaran tambahan yang disimpan.',
        ], 200);
      }

      // Nominal yang boleh ditambahkan maksimal sisa tagihan
      $tambahan = min(max(0, $terbayar), $sisa > 0 ? $sisa : $total_harga);

      if ($existingPayment) {
        // Pembayaran lanjutan (mis. setelah tambah parameter): tambahkan ke yang sudah dibayar
        $existingPayment->nota_petugas_permohonan_uji_payment_klinik = $request->nota_petugas_permohonan_uji_payment_klinik ?? auth()->id();
        $existingPayment->total_harga_permohonan_uji_payment_klinik = $total_harga;
        $existingPayment->terbayar_permohonan_uji_payment_klinik = $sudah_dibayar + $tambahan;
        $existingPayment->date_done_estimation_permohonan_uji_payment_klinik = date('Y-m-d H:i:s', time());
        $existingPayment->save();

        PermohonanUjiPaymentKlinik::where('permohonan_uji_klinik_id', $request->id_permohonan_uji_klinik)
          ->where('id_permohonan_uji_payment_klinik', '!=', $existingPayment->id_permohonan_uji_payment_klinik)
          ->whereNull('deleted_at')
          ->update(['deleted_at' => now()]);

        $total_terbayar_akhir = (int) $existingPayment->terbayar_permohonan_uji_payment_klinik;
      } else {
        $max_nota = (int) PermohonanUjiPaymentKlinik::max('no_nota_permohonan_uji_payment_klinik');

        $post = new PermohonanUjiPaymentKlinik();
        $post->permohonan_uji_klinik_id = $request->id_permohonan_uji_klinik;
        $post->no_nota_permohonan_uji_payment_klinik = $max_nota + 1;
        $post->nota_petugas_permohonan_uji_payment_klinik = $request->nota_petugas_permohonan_uji_payment_klinik ?? auth()->id();
        $post->total_harga_permohonan_uji_payment_klinik = $total_harga;
        $post->terbayar_permohonan_uji_payment_klinik = $tambahan;
        $post->date_done_estimation_permohonan_uji_payment_klinik = date('Y-m-d H:i:s', time());
        $post->save();

        $total_terbayar_akhir = $tambahan;
      }

      if ($total_terbayar_akhir >= $total_harga) {
        $permohonan_uji_klinik->status_pembayaran = '1';
      } else {
        $permohonan_uji_klinik->status_pembayaran = '0';
      }
      $permohonan_uji_klinik->save();

      DB::commit();

      return response()->json(['status' => true, 'pesan' => 'Proses pembayaran berhasil disimpan!'], 200);
    } catch (\Exception $e) {
      DB::rollBack();

      return response()->json(['status' => false, 'pesan' => 'Proses pembayaran tidak berhasil disimpan! Error: ' . $e->getMessage()], 200);
    }
  }

  public function getPaymentDetail(Request $request)
  {
    try {
      $id_permohonan_uji_klinik = $request->permohonan_uji_klinik_id;

      \Log::info('Payment Detail Request for ID: ' . $id_permohonan_uji_klinik);

      // Get permohonan data with pasien and packages/parameters relations
      $permohonan = PermohonanUjiKlinik2::with([
        'pasien',
        'permohonanujipaketklinik' => function($query) {
          $query->whereNull('deleted_at')
                ->with([
                  'parameterpaketklinik',
                  'parameterpaketextra',
                  'permohonanujiparameterklinik' => function($q) {
                    $q->whereNull('deleted_at')
                      ->with('parametersatuanklinik');
                  }
                ]);
        }
      ])->find($id_permohonan_uji_klinik);

      \Log::info('Permohonan Found: ' . ($permohonan ? 'YES' : 'NO'));

      if (!$permohonan) {
        return response()->json(['status' => false, 'pesan' => 'Data tidak ditemukan!'], 200);
      }

      // Get payment records
      $payments = PermohonanUjiPaymentKlinik::where('permohonan_uji_klinik_id', $id_permohonan_uji_klinik)
                                            ->orderBy('created_at', 'desc')
                                            ->get();

      \Log::info('Payments Count: ' . $payments->count());

      $payment_details = [];
      $total_paid = 0;

      // Get nama petugas from VerificationActivitySample with id_verification_activity = 1
      $verification_activity = VerificationActivitySample::where('is_klinik', $id_permohonan_uji_klinik)
        ->where('id_verification_activity', 1)
        ->first();
      
      $default_nama_petugas = $verification_activity ? ($verification_activity->nama_petugas ?? 'Unknown') : 'Unknown';

      foreach ($payments as $payment) {
        $total_paid += $payment->terbayar_permohonan_uji_payment_klinik ?? 0;

        // Get petugas name from VerificationActivitySample, fallback to User if not found
        $petugas_name = $default_nama_petugas;
        if ($petugas_name == 'Unknown') {
          $petugas = User::find($payment->nota_petugas_permohonan_uji_payment_klinik);
          $petugas_name = $petugas ? $petugas->name : 'Unknown';
        }

        // Safe date formatting
        $created_date = '-';
        if ($payment->created_at) {
          try {
            $created_date = $payment->created_at->format('d/m/Y H:i');
          } catch (\Exception $e) {
            $created_date = date('d/m/Y H:i', strtotime($payment->created_at));
          }
        }

        $payment_details[] = [
          'no_nota' => $payment->no_nota_permohonan_uji_payment_klinik ?? '-',
          'total_harga' => $payment->total_harga_permohonan_uji_payment_klinik ?? 0,
          'terbayar' => $payment->terbayar_permohonan_uji_payment_klinik ?? 0,
          'kembalian' => ($payment->terbayar_permohonan_uji_payment_klinik ?? 0) - ($payment->total_harga_permohonan_uji_payment_klinik ?? 0),
          'petugas' => $petugas_name,
          'tanggal' => $payment->date_done_estimation_permohonan_uji_payment_klinik ?? '-',
          'created_at' => $created_date,
        ];
      }

      // Get packages and parameters data
      $items = [];
      if ($permohonan->permohonanujipaketklinik) {
        foreach ($permohonan->permohonanujipaketklinik as $paket) {
          if ($paket->type_permohonan_uji_paket_klinik == 'EP') {
            // Extra Package
            $items[] = [
              'type' => 'Paket Extra',
              'name' => $paket->parameterpaketextra ? $paket->parameterpaketextra->nama_parameter_paket_extra : '-',
              'harga' => $paket->harga_permohonan_uji_paket_klinik ?? 0,
            ];
          } elseif ($paket->type_permohonan_uji_paket_klinik == 'P') {
            // Package type
            $items[] = [
              'type' => 'Paket',
              'name' => $paket->parameterpaketklinik ? $paket->parameterpaketklinik->name_parameter_paket_klinik : '-',
              'harga' => $paket->harga_permohonan_uji_paket_klinik ?? 0,
            ];
          } else {
            // Custom/Parameter type
            if ($paket->permohonanujiparameterklinik && $paket->permohonanujiparameterklinik->count() > 0) {
              foreach ($paket->permohonanujiparameterklinik as $param) {
                $items[] = [
                  'type' => 'Parameter',
                  'name' => $param->parametersatuanklinik ? $param->parametersatuanklinik->name_parameter_satuan_klinik : '-',
                  'harga' => $param->harga_permohonan_uji_parameter_klinik ?? 0,
                ];
              }
            }
          }
        }
      }

      // Get biaya_pengambilan_sampel
      $biaya_pengambilan_sampel = (int) ($permohonan->biaya_pengambilan_sampel ?? 0);
      
      // Calculate total akhir: harga parameter + biaya pengambilan sampel
      $total_harga_parameter = $permohonan->total_harga_permohonan_uji_klinik ?? 0;
      $total_akhir = $total_harga_parameter + $biaya_pengambilan_sampel;

      // Get nama pasien safely
      $nama_pasien = '-';
      if ($permohonan->pasien) {
        $nama_pasien = $permohonan->pasien->nama_pasien ?? '-';
      }

      $data = [
        'nama_pasien' => $nama_pasien,
        'no_register' => $permohonan->noregister_permohonan_uji_klinik ?? '-',
        'total_harga_parameter' => $total_harga_parameter,
        'biaya_pengambilan_sampel' => $biaya_pengambilan_sampel,
        'total_tagihan' => $total_akhir,
        'total_tagihan_formatted' => rupiah($total_akhir),
        'total_terbayar' => $total_paid,
        'total_terbayar_formatted' => rupiah($total_paid),
        'status_pembayaran' => $permohonan->status_pembayaran ?? 0,
        'payments' => $payment_details,
        'items' => $items, // Add items (packages/parameters) to response
      ];

      return response()->json(['status' => true, 'data' => $data], 200);
    } catch (\Exception $e) {
      // Log the error for debugging
      \Log::error('Payment Detail Error: ' . $e->getMessage());
      \Log::error('Stack trace: ' . $e->getTraceAsString());

      return response()->json([
        'status' => false,
        'pesan' => 'Terjadi kesalahan saat mengambil data pembayaran: ' . $e->getMessage()
      ], 200);
    }
  }

  public function updateDataPermohonanUjiKlinikPayment(Request $request)
  {
    abort_unless((auth()->user()->getlevel->level ?? null) === 'BNDR', 403);

    if ($request->terbayar_permohonan_uji_payment_klinik == 0) {
      return redirect()->route('elits-permohonan-uji-klinik-2.index')->with(['error' => 'Pembayaran gagal, nominal harus diisi!']);
    }

    $permohonan_uji_klinik = PermohonanUjiKlinik2::findOrFail($request->id_permohonan_uji_klinik);
    if (($request->total_terbayar + $request->terbayar_permohonan_uji_payment_klinik) > $permohonan_uji_klinik->total_harga_permohonan_uji_klinik) {
      return redirect()->route('elits-permohonan-uji-klinik-2.index')->with(['error' => 'Pembayaran gagal, nominal terlalu besar!']);
    }

    if ($request->terbayar_permohonan_uji_payment_klinik < 0) {
      return redirect()->route('elits-permohonan-uji-klinik-2.index')->with(['error' => 'Pembayaran gagal, nominal tidak boleh mines!']);
    }

    // Mulai DB transaction
    DB::beginTransaction();

    try {
      // update ke payment
      $post = PermohonanUjiPaymentKlinik::where('permohonan_uji_klinik_id', $request->id_permohonan_uji_klinik)->first();
      $post->nota_petugas_permohonan_uji_payment_klinik = auth()->id();
      $post->total_harga_permohonan_uji_payment_klinik = $request->total_harga_permohonan_uji_payment_klinik;
      $post->terbayar_permohonan_uji_payment_klinik += $request->terbayar_permohonan_uji_payment_klinik;
      $post->date_done_estimation_permohonan_uji_payment_klinik = date('Y-m-d H:i:s', time());
      $simpan = $post->save();

      // Update is_paid pada permohonan uji klinik
      if (($request->total_terbayar + $request->terbayar_permohonan_uji_payment_klinik) == $request->total_harga_permohonan_uji_payment_klinik) {
        $permohonan_uji_klinik->status_pembayaran = '1';
        $permohonan_uji_klinik->save();
      }

      // Commit transaksi jika semua operasi berhasil
      DB::commit();

      return redirect()->route('elits-permohonan-uji-klinik-2.index')->with(['status' => 'Proses pembayaran berhasil disimpan!']);
    } catch (\Exception $e) {
      // Rollback transaksi jika terjadi kesalahan
      DB::rollBack();

      return redirect()->route('elits-permohonan-uji-klinik-2.index')->with(['error' => 'Proses pembayaran tidak berhasil disimpan!']);
    }
  }


  public function createPermohonanUjiRekomendasiDokter($id_permohonan_uji_klinik)
  {
    $item = PermohonanUjiKlinik2::find($id_permohonan_uji_klinik);
    $tgl_register = Carbon::createFromFormat('Y-m-d H:i:s', $item->tglregister_permohonan_uji_klinik)->isoFormat('D MMMM YYYY');

    if ($item->tglpengujian_permohonan_uji_klinik !== null) {
      $tgl_pengujian = Carbon::createFromFormat('Y-m-d H:i:s', $item->tglpengujian_permohonan_uji_klinik)->isoFormat('D/M/Y HH:mm');
    } else {
      $tgl_pengujian = '';
    }

    if ($item->spesimen_darah_permohonan_uji_klinik !== null) {
      $tgl_spesimen_darah = Carbon::createFromFormat('Y-m-d H:i:s', $item->spesimen_darah_permohonan_uji_klinik)->isoFormat('D/M/Y HH:mm');
    } else {
      $tgl_spesimen_darah = '-';
    }

    if ($item->spesimen_urine_permohonan_uji_klinik !== null) {
      $tgl_spesimen_urine = Carbon::createFromFormat('Y-m-d H:i:s', $item->spesimen_urine_permohonan_uji_klinik)->isoFormat('D/M/Y HH:mm');
    } else {
      $tgl_spesimen_urine = '-';
    }

    $data_permohonan_uji_paket_klinik = PermohonanUjiPaketKlinik::where('permohonan_uji_klinik', $id_permohonan_uji_klinik)
      ->whereNull('deleted_at')
      ->get();

    $arr_permohonan_parameter = [];

    $data_permohonan_uji_satuan_klinik = PermohonanUjiParameterKlinik::where('permohonan_uji_klinik', $id_permohonan_uji_klinik)
      ->orderBy('jenis_parameter_klinik_id', 'ASC')
      ->orderBy('sorting_parameter_satuan', 'ASC')
      ->get();

    $data_jenis_parameter_klinik = PermohonanUjiParameterKlinik::where('permohonan_uji_klinik', $id_permohonan_uji_klinik)
      ->groupBy('jenis_parameter_klinik_id')
      ->orderBy('sort_jenis_klinik', 'ASC')
      ->get();




    $item_permohonan_uji_klinik = PermohonanUjiKlinik2::find($id_permohonan_uji_klinik);

    if (count($data_permohonan_uji_satuan_klinik) > 0) {
      foreach ($data_jenis_parameter_klinik as $key_jenis_parameter_klinik => $value_jenis_parameter_klinik) {
        # code...
        $parameter_jenis_klinik = [];
        $parameter_jenis_klinik['name_parameter_jenis_klinik'] = $value_jenis_parameter_klinik->jenisparameterklinik->name_parameter_jenis_klinik;
        $parameter_jenis_klinik['id_parameter_jenis_klinik'] = $value_jenis_parameter_klinik->jenisparameterklinik->id_parameter_jenis_klinik;
        $parameter_jenis_klinik['item_permohonan_parameter_satuan'] = [];

        foreach ($data_permohonan_uji_satuan_klinik as $key_satuan => $value_satuan) {

          if ($value_satuan->jenis_parameter_klinik_id == $value_jenis_parameter_klinik->jenisparameterklinik->id_parameter_jenis_klinik) {

            $pasien_umur = $item_permohonan_uji_klinik->umurtahun_pasien_permohonan_uji_klinik;
            $pasien_gender = $item_permohonan_uji_klinik->pasien->gender_pasien;

            $item_permohonan_parameter_satuan = [];
            $item_permohonan_parameter_satuan['id_permohonan_uji_parameter_klinik'] = $value_satuan->id_permohonan_uji_parameter_klinik;
            $item_permohonan_parameter_satuan['permohonan_uji_klinik'] = $value_satuan->permohonan_uji_klinik;
            $item_permohonan_parameter_satuan['permohonan_uji_paket_klinik'] = $value_satuan->permohonan_uji_paket_klinik;
            $item_permohonan_parameter_satuan['parameter_paket_klinik'] = $value_satuan->parameter_paket_klinik;
            $item_permohonan_parameter_satuan['parameter_satuan_klinik'] = $value_satuan->parameter_satuan_klinik;
            $item_permohonan_parameter_satuan['nama_parameter_satuan_klinik'] = $value_satuan->parametersatuanklinik->name_parameter_satuan_klinik ?? null;
            $item_permohonan_parameter_satuan['parameter_satuan_klinik_is_option'] = $value_satuan->parametersatuanklinik->is_option ?? 0;
            $item_permohonan_parameter_satuan['parameter_satuan_klinik_option'] = $value_satuan->parametersatuanklinik->option ?? null;
            $item_permohonan_parameter_satuan['parameter_satuan_klinik_requires_nama_jenis'] = (int) ($value_satuan->parametersatuanklinik->requires_nama_jenis ?? 0);
            $item_permohonan_parameter_satuan['requires_nama_jenis'] = (
              (int) ($value_satuan->parametersatuanklinik->requires_nama_jenis ?? 0)
              || (int) ($value_satuan->requires_nama_jenis ?? 0)
            ) ? 1 : 0;
            $item_permohonan_parameter_satuan['method_permohonan_uji_parameter_klinik'] = $value_satuan->method_permohonan_uji_parameter_klinik;
            $item_permohonan_parameter_satuan['metode_parameter_satuan_klinik'] = \Smt\Masterweb\Helpers\Smt::pickMetodeForContext(
              $value_satuan->parametersatuanklinik,
              $item_permohonan_uji_klinik
            );
            $item_permohonan_parameter_satuan['harga_permohonan_uji_parameter_klinik'] = $value_satuan->harga_permohonan_uji_parameter_klinik;
            $item_permohonan_parameter_satuan['hasil_permohonan_uji_parameter_klinik'] = $value_satuan->hasil_permohonan_uji_parameter_klinik;
            $item_permohonan_parameter_satuan['flag_permohonan_uji_parameter_klinik'] = $value_satuan->flag_permohonan_uji_parameter_klinik;
            $item_permohonan_parameter_satuan['keterangan_permohonan_uji_parameter_klinik'] = $value_satuan->keterangan_permohonan_uji_parameter_klinik;
            $item_permohonan_parameter_satuan['offset_baku_mutu'] = $value_satuan->offset_baku_mutu ?? 'default';

            $id_parameter_jenis_klinik = $value_satuan->jenis_parameter_klinik_id;

            $data_parameter_by_baku_mutu = BakuMutu::where('parameter_jenis_klinik_id', $id_parameter_jenis_klinik)
              ->where('parameter_satuan_klinik_id', $value_satuan->parameter_satuan_klinik)
              ->get();

            $item_parameter_by_baku_mutu = null;
            if (count($data_parameter_by_baku_mutu) > 0) {

              $check_parameter_by_baku_mutu = BakuMutu::where('parameter_jenis_klinik_id', $id_parameter_jenis_klinik)
                ->where('parameter_satuan_klinik_id', $value_satuan->parameter_satuan_klinik)
                ->where('is_khusus_baku_mutu', '0')
                ->first();

              // cek dulu apakah ada data dengan data khusus sperti general atau specific

              if ($check_parameter_by_baku_mutu) {
                $item_parameter_by_baku_mutu = $check_parameter_by_baku_mutu;
                $generalRows = $data_parameter_by_baku_mutu->where('is_khusus_baku_mutu', '0')->values();
                $multiple_baku_mutu = $generalRows->count() > 1 ? $generalRows->toArray() : [];
              } else {
                $item_parameter_by_baku_mutu = BakuMutu::where('parameter_jenis_klinik_id', $id_parameter_jenis_klinik)
                  ->where('parameter_satuan_klinik_id', $value_satuan->parameter_satuan_klinik)
                  ->where('is_khusus_baku_mutu', '1')
                  ->where('gender_baku_mutu', $pasien_gender)
                  ->where(function ($query) use ($pasien_umur) {
                    $query->where('minimal_umur_baku_mutu', '<=', $pasien_umur)
                      ->where('maksimal_umur_baku_mutu', '>=', $pasien_umur);
                  })
                  ->first();
                if (!isset($item_parameter_by_baku_mutu)) {
                  $item_parameter_by_baku_mutu = BakuMutu::where('parameter_jenis_klinik_id', $id_parameter_jenis_klinik)
                    ->where('parameter_satuan_klinik_id', $value_satuan->parameter_satuan_klinik)
                    ->where('is_khusus_baku_mutu', '1')
                    ->where('gender_baku_mutu', $pasien_gender)
                    ->first();
                }
              }
            }

            // jika tidak ada satuan di permohonan uji satuan maka ambil value dari baku mutu
            // jika ada nilai satuan di permohonan uji satuan maka ambil nilai dari tabel itu sendiri
            if ($value_satuan->satuan_permohonan_uji_parameter_klinik != null) {
              $item_permohonan_parameter_satuan['satuan_permohonan_uji_parameter_klinik'] = $value_satuan->satuan_permohonan_uji_parameter_klinik;
              $item_permohonan_parameter_satuan['nama_satuan_permohonan_uji_parameter_klinik'] = $value_satuan->unit->name_unit ?? null;
            } else if (isset($item_parameter_by_baku_mutu->unit_id)) {
              $item_permohonan_parameter_satuan['satuan_permohonan_uji_parameter_klinik'] = $item_parameter_by_baku_mutu->unit_id;
              $item_permohonan_parameter_satuan['nama_satuan_permohonan_uji_parameter_klinik'] = $item_parameter_by_baku_mutu->unit->name_unit ?? null;
            } else {
              $item_permohonan_parameter_satuan['satuan_permohonan_uji_parameter_klinik'] = null;
              $item_permohonan_parameter_satuan['nama_satuan_permohonan_uji_parameter_klinik'] = null;
            }

            $item_permohonan_parameter_satuan['min'] = $item_parameter_by_baku_mutu->min ?? null;
            $item_permohonan_parameter_satuan['max'] = $item_parameter_by_baku_mutu->max ?? null;
            $item_permohonan_parameter_satuan['equal'] = $item_parameter_by_baku_mutu->equal ?? null;
            $keterangan_dilaporan_resolved = $this->resolvedKeteranganDilaporanForSatuan(
              $value_satuan,
              $pasien_gender,
              $pasien_umur,
              (int) ($item_permohonan_uji_klinik->is_haji ?? 0),
              true
            );
            $item_permohonan_parameter_satuan['keterangan_dilaporan_baku_mutu_permohonan_uji_parameter_klinik'] = $keterangan_dilaporan_resolved;
            $item_permohonan_parameter_satuan['nilai_baku_mutu'] = $keterangan_dilaporan_resolved ?? ($item_parameter_by_baku_mutu->nilai_baku_mutu ?? null);
            // Tambahkan id_baku_mutu untuk dikirim ke form, fallback ke nilai yang sudah ada di database
            $item_permohonan_parameter_satuan['id_baku_mutu'] = $item_parameter_by_baku_mutu->id_baku_mutu ?? ($value_satuan->baku_mutu_permohonan_uji_parameter_klinik ?? null);
            $item_permohonan_parameter_satuan['kesimpulan_baku_mutu'] = $item_parameter_by_baku_mutu->kesimpulan_baku_mutu ?? null;
            // Tambahkan number_format dari parameter satuan klinik
            $item_permohonan_parameter_satuan['number_format'] = $value_satuan->parametersatuanklinik->number_format ?? 'en';
            // Tambahkan data multiple baku mutu untuk pengecekan
            $item_permohonan_parameter_satuan['multiple_baku_mutu'] = $multiple_baku_mutu ?? [];
            $item_permohonan_parameter_satuan['has_multiple_baku_mutu'] = count($multiple_baku_mutu ?? []) > 1;

            // menyiapkan data array untuk mapping jika data parameter memiliki subsatuan
            $item_permohonan_parameter_satuan['data_permohonan_uji_subsatuan_klinik'] = [];

            $data_permohonan_uji_subsatuan_klinik = PermohonanUjiSubParameterKlinik::where('permohonan_uji_parameter_klinik_id', $value_satuan->id_permohonan_uji_parameter_klinik)
