  public function printPermohonanUjiKlinikNota($id_permohonan_uji_klinik)
  {
    $item_permohonan_uji_klinik = PermohonanUjiKlinik2::find($id_permohonan_uji_klinik);


    $itemPermohonanUjiPaymentKlinik = PermohonanUjiPaymentKlinik::where('permohonan_uji_klinik_id', $id_permohonan_uji_klinik)
      ->whereNull('deleted_at')
      ->orderBy('created_at', 'asc')
      ->first();

    $biaya_pengambilan_nota = (int) ($item_permohonan_uji_klinik->biaya_pengambilan_sampel ?? 0);
    $total_harga_nota = (int) ($item_permohonan_uji_klinik->total_harga_permohonan_uji_klinik ?? 0) + $biaya_pengambilan_nota;
    // Normalisasi terbayar vs total (data lama bisa overpay setelah edit parameter)
    $paymentSyncNota = KlinikPaymentHelper::syncWithTotal($id_permohonan_uji_klinik, $total_harga_nota);
