  public function printPermohonanUjiKlinikFormulir($id_permohonan_uji_klinik)
  {
    $item_permohonan_uji_klinik = PermohonanUjiKlinik2::find($id_permohonan_uji_klinik);
    $item_pasien = Pasien::find($item_permohonan_uji_klinik->pasien_permohonan_uji_klinik);
    // dd($parameter_paket_klinik->id_jenis_parameter_klinik);
    $nama_petugas = auth()->user()->name;
    $permohonanUjiPaketKlinik = PermohonanUjiPaketKlinik::query()
      ->where('permohonan_uji_klinik', '=', $id_permohonan_uji_klinik)
      ->pluck('parameter_paket_klinik')
      ->toArray();

    $umurPerwakilan = '-';
    if (isset($item_permohonan_uji_klinik->tanggal_lahir_perwakilan_permohonan_uji_klinik)){
      $tanggalLahir = new DateTime($item_permohonan_uji_klinik->tanggal_lahir_perwakilan_permohonan_uji_klinik);
      $sekarang = new DateTime();
      $umurPerwakilan = $sekarang->diff($tanggalLahir)->y;
    }

    $nama_petugas_lab = VerificationActivitySample::where('is_klinik', $id_permohonan_uji_klinik)
      ->where('id_verification_activity', 1)
      ->first();

    if ($nama_petugas_lab){
      $nama_petugas_lab = $nama_petugas_lab->nama_petugas;
    }

    $verificationActivity = VerificationActivitySample::query()
            ->where('is_klinik', '=', $id_permohonan_uji_klinik)
            ->get();

    $nama_petugas_registrasi = $verificationActivity
        ->where('id_verification_activity', '=', 1)
        ->first()
        ->nama_petugas ?? "...................";

    $pengambilanSample = PengambilanSampleKlinik::where('permohonan_uji_klinik_id', $id_permohonan_uji_klinik)
        ->where('status_sampling', 'Berhasil')->first();

    if (!$pengambilanSample) {
      $pengambilanSample = PengambilanSampleKlinik::where('permohonan_uji_klinik_id', $id_permohonan_uji_klinik)
        ->where('resampling', 0)
        ->orderBy('created_at', 'asc')
        ->first();
    }

    $vaPengambilSample = VerificationActivitySample::where('is_klinik', $id_permohonan_uji_klinik)
      ->where('id_verification_activity', 6)
      ->where(function ($q) {
        $q->where('resampling', 0)->orWhereNull('resampling');
      })
      ->orderBy('start_date', 'desc')
      ->first();

    $namaPetugasPengambilCetak = $this->resolveNamaPetugasPengambilForCetak(
      $id_permohonan_uji_klinik,
      $pengambilanSample,
      $vaPengambilSample
    );

    $jenis_sample = Smt::resolveJenisSampleForPermohonan($id_permohonan_uji_klinik, $pengambilanSample);

    $petugasConsent = Smt::resolveTindakanMedisConsentPetugas($namaPetugasPengambilCetak);
    $petugasMenerangkan = $petugasConsent['label'];
    $petugas = $petugasConsent['nama'];

    // Generate QR code with mobile sampling URL
    $mobileSamplingUrl = route('mobile.sampling.klinik.scan', ['id' => $id_permohonan_uji_klinik]);
    $qrCode = Builder::create()
            ->data($id_permohonan_uji_klinik)
            ->encoding(new Encoding('UTF-8'))
            ->errorCorrectionLevel(new ErrorCorrectionLevelHigh())
            ->size(600)
            ->margin(2)

            ->build();
    $qrBase64 = base64_encode($qrCode->getString());

    // Load category layout from database for consistent item ordering
    $categoryLayouts = \Smt\Masterweb\Models\ParameterCategoryLayout::where('is_active', 1)
      ->orderBy('sort_order', 'asc')
      ->with(['categoryItems' => function($query) {
        $query->with('parameterPaketKlinik')
          ->orderBy('row_position', 'asc')
          ->orderBy('column_position', 'asc')
          ->orderBy('sort_order', 'asc');
      }])
      ->get();

    $pdf = PDF::loadView('masterweb::module.admin.laboratorium.permohonan-uji-klinik-2.formatPrint.formulir', [
      "item_permohonan_uji_klinik" => $item_permohonan_uji_klinik,
      "item_pasien" => $item_pasien,
      "nama_petugas" => $nama_petugas,
      "umur_perwakilan_permohonan_uji_klinik" => $umurPerwakilan,
      "permohonanUjiPaketKlinik" => $permohonanUjiPaketKlinik,
      "nama_petugas_lab" => $nama_petugas_lab,
      "nama_petugas_registrasi" => $nama_petugas_registrasi,
      "qr_code" => $qrBase64,
      "jenis_sample"=> $jenis_sample,
      "petugas_menerangkan"=> $petugasMenerangkan,
      "petugas"=> $petugas,
      "use_pengambil_petugas" => $petugasConsent['use_pengambil'],
      "categoryLayouts" => $categoryLayouts,
    ]);

    return $pdf->stream();
  }

  public function printLembarPersetujuan($id_permohonan_uji_klinik)
  {
    $item_permohonan_uji_klinik = PermohonanUjiKlinik2::find($id_permohonan_uji_klinik);
    $item_pasien = Pasien::find($item_permohonan_uji_klinik->pasien_permohonan_uji_klinik);

    $nama_petugas_lab = VerificationActivitySample::where('is_klinik', $id_permohonan_uji_klinik)
      ->where('id_verification_activity', 1)
      ->first();

    if ($nama_petugas_lab){
      $nama_petugas_lab = $nama_petugas_lab->nama_petugas;
    }

    $nama_petugas_registrasi = VerificationActivitySample::where('is_klinik', $id_permohonan_uji_klinik)
      ->where('id_verification_activity', 1)
      ->first();
    $namaPetugasRegistrasi = ($nama_petugas_registrasi && $nama_petugas_registrasi->nama_petugas)
      ? $nama_petugas_registrasi->nama_petugas
      : null;

    $pengambilanSample = PengambilanSampleKlinik::where('permohonan_uji_klinik_id', $id_permohonan_uji_klinik)
      ->where('status_sampling', 'Berhasil')->first();

    $jenis_sample = Smt::resolveJenisSampleForPermohonan($id_permohonan_uji_klinik, $pengambilanSample);

    $petugasConsent = Smt::resolveInformedConsentPetugas(
      is_array($jenis_sample) ? $jenis_sample : [],
      $namaPetugasRegistrasi,
      $this->resolveNamaPetugasPengambilForCetak($id_permohonan_uji_klinik, $pengambilanSample)
    );

    $pdf = PDF::loadView('masterweb::module.admin.laboratorium.permohonan-uji-klinik-2.formatPrint.lembar-persetujuan', [
      "item_permohonan_uji_klinik" => $item_permohonan_uji_klinik,
      "item_pasien" => $item_pasien,
      "nama_petugas_lab" => $nama_petugas_lab,
      "petugas_menerangkan" => $petugasConsent['label'],
      "petugas" => $petugasConsent['nama'],
      "use_pengambil_petugas" => $petugasConsent['use_pengambil'],
    ]);

    return $pdf->stream();
  }

