  /**
   * Cetak hasil diperbolehkan jika analis menandai SELESAI atau validasi (verification activity 5) sudah selesai.
   * Link PDF untuk WhatsApp dibuat setelah step 5; tanpa pengecualian ini permohonan bisa 403 walau sudah divalidasi.
   */
  private function permohonanKlinik2BolehCetakHasil(string $id_permohonan_uji_klinik, ?PermohonanUjiKlinik2 $row = null): bool
  {
      $row = $row ?? PermohonanUjiKlinik2::find($id_permohonan_uji_klinik);
      if (!$row) {
          return false;
      }
      if (trim((string) ($row->status_permohonan_uji_klinik ?? '')) === 'SELESAI') {
          return true;
      }

      return VerificationActivitySample::query()
          ->where('is_klinik', '=', $id_permohonan_uji_klinik)
          ->where('id_verification_activity', '=', 5)
          ->where('is_done', '=', 1)
          ->exists();
  }

  /**
   * Buat/update VerificationActivitySample step 6 saat pendaftaran:
   * isi nama pengambil sampel; tanggal pakai placeholder (wajib NOT NULL di DB),
   * jam pengambilan sebenarnya diisi saat step pengambilan (is_done = 1).
   */
  private function isUrineOnlyPetugasSelection(?string $value): bool
  {
    return trim((string) $value) === self::PETUGAS_PENGAMBIL_URINE_ONLY;
  }

  private function isBlankPetugasSelection(?string $value): bool
  {
    return trim((string) $value) === self::PETUGAS_PENGAMBIL_BLANK;
  }

  private function isDiisiPelangganPetugasSelection(?string $value): bool
  {
    return trim((string) $value) === self::PETUGAS_PENGAMBIL_DIISI_PELANGGAN;
  }

  public static function labelPetugasPengambil(?string $value): string
  {
    $value = trim((string) $value);
    if ($value === self::PETUGAS_PENGAMBIL_DIISI_PELANGGAN) {
      return self::PETUGAS_PENGAMBIL_DIISI_PELANGGAN_LABEL;
    }
    if ($value === self::PETUGAS_PENGAMBIL_URINE_ONLY) {
      return 'Urin saja (tidak perlu petugas)';
    }
    if ($value === self::PETUGAS_PENGAMBIL_BLANK) {
      return '......';
    }

    return $value !== '' ? $value : '-';
  }

  /**
   * Nama petugas pengambil untuk cetak consent/formulir.
   * Prioritas: pilihan saat registrasi (VA step 6), lalu data sampling sebenarnya.
   */
  private function resolveNamaPetugasPengambilForCetak(
    string $id_permohonan_uji_klinik,
    $pengambilanSample = null,
    $vaPengambilSample = null
  ): ?string {
    if ($vaPengambilSample === null) {
      $vaPengambilSample = VerificationActivitySample::where('is_klinik', $id_permohonan_uji_klinik)
        ->where('id_verification_activity', 6)
        ->where(function ($q) {
          $q->where('resampling', 0)->orWhereNull('resampling');
        })
        ->orderBy('start_date', 'desc')
        ->first();
    }

    $namaVa = trim((string) optional($vaPengambilSample)->nama_petugas);
    if ($namaVa !== '') {
      if ($this->isBlankPetugasSelection($namaVa) || $this->isUrineOnlyPetugasSelection($namaVa)) {
        return self::PETUGAS_PENGAMBIL_BLANK;
      }
      if ($this->isDiisiPelangganPetugasSelection($namaVa)) {
        return self::PETUGAS_PENGAMBIL_DIISI_PELANGGAN_LABEL;
      }
      return $namaVa;
    }

    if ($pengambilanSample === null) {
      $pengambilanSample = PengambilanSampleKlinik::where('permohonan_uji_klinik_id', $id_permohonan_uji_klinik)
        ->where(function ($q) {
          $q->where('resampling', 0)->orWhereNull('resampling');
        })
        ->orderBy('created_at', 'asc')
        ->first();
    }

    $namaSampling = trim((string) optional($pengambilanSample)->petugas_name);
    if ($namaSampling !== ''
        && !$this->isBlankPetugasSelection($namaSampling)
        && !$this->isUrineOnlyPetugasSelection($namaSampling)) {
      return $namaSampling;
    }

    return self::PETUGAS_PENGAMBIL_BLANK;
  }

  /**
   * Nama petugas pengambil dari registrasi untuk pre-fill dropdown verifikasi
   * (abaikan placeholder ...... dan Urin saja).
   */
  private function resolvePrefillPetugasPengambilForVerification(
    array $listVerifications = [],
    $pengambilanSampleKlinik = null,
    $permohonan = null
  ): string {
    $va = $listVerifications[6] ?? null;
    $namaVa = trim((string) optional($va)->nama_petugas);
    if ($namaVa !== ''
        && !$this->isBlankPetugasSelection($namaVa)
        && !$this->isUrineOnlyPetugasSelection($namaVa)) {
      return $namaVa;
    }

    $namaSampling = trim((string) optional($pengambilanSampleKlinik)->petugas_name);
    if ($namaSampling !== ''
        && !$this->isBlankPetugasSelection($namaSampling)
        && !$this->isUrineOnlyPetugasSelection($namaSampling)) {
      return $namaSampling;
    }

    if ($permohonan && ($permohonan->mode_pengambilan_sampel ?? '') === 'dibawa_pelanggan') {
      return self::PETUGAS_PENGAMBIL_DIISI_PELANGGAN;
    }

    return '';
  }

  /**
   * Pastikan nama petugas ada di daftar dropdown; kembalikan nama dengan casing dari daftar jika cocok.
   */
  private function ensurePetugasNameInList(array $list, string $nama): array
  {
    $nama = trim($nama);
    if ($nama === '') {
      return ['list' => $list, 'nama' => ''];
    }

    foreach ($list as $existing) {
      if (strcasecmp(trim((string) $existing), $nama) === 0) {
        return ['list' => $list, 'nama' => (string) $existing];
      }
    }

    $list[] = $nama;

    return ['list' => $list, 'nama' => $nama];
  }

  private function seedPengambilSampleVerificationAtRegistration(
    string $id_permohonan_uji_klinik,
    ?string $namaPetugasPengambil,
    ?string $modePengambilanSampel = null,
    ?string $tglRegister = null
  ): void {
    if ($modePengambilanSampel === 'dibawa_pelanggan') {
      $this->markPengambilSampleSkipped($id_permohonan_uji_klinik, self::PETUGAS_PENGAMBIL_DIISI_PELANGGAN_LABEL);
      return;
    }

    if ($this->isUrineOnlyPetugasSelection($namaPetugasPengambil)) {
      $this->markPengambilSampleSkipped($id_permohonan_uji_klinik);
      return;
    }

    $nama = trim((string) ($namaPetugasPengambil ?? ''));
    if ($nama === '') {
      throw new \InvalidArgumentException('Petugas pengambil sampel wajib diisi.');
    }
    if ($this->isBlankPetugasSelection($nama)) {
      $nama = self::PETUGAS_PENGAMBIL_BLANK;
    }

    $placeholderStart = null;
    if (!empty($tglRegister)) {
      try {
        $placeholderStart = Carbon::parse($tglRegister)->format('Y-m-d H:i:s');
      } catch (\Throwable $e) {
        $placeholderStart = null;
      }
    }
    if ($placeholderStart === null) {
      $permohonan = PermohonanUjiKlinik2::find($id_permohonan_uji_klinik);
      if ($permohonan && !empty($permohonan->tglregister_permohonan_uji_klinik)) {
        try {
          $placeholderStart = Carbon::parse($permohonan->tglregister_permohonan_uji_klinik)->format('Y-m-d H:i:s');
        } catch (\Throwable $e) {
          $placeholderStart = Carbon::now()->format('Y-m-d H:i:s');
        }
      } else {
        $placeholderStart = Carbon::now()->format('Y-m-d H:i:s');
      }
    }
    $placeholderStop = Carbon::parse($placeholderStart)->addMinutes(10)->format('Y-m-d H:i:s');

    $existing = VerificationActivitySample::where('is_klinik', $id_permohonan_uji_klinik)
      ->where('id_verification_activity', 6)
      ->where(function ($q) {
        $q->where('resampling', 0)->orWhereNull('resampling');
      })
      ->orderBy('start_date', 'desc')
      ->first();

    if ($existing) {
      $existing->nama_petugas = $nama;
      if (empty($existing->start_date)) {
        $existing->start_date = $placeholderStart;
        $existing->stop_date = $placeholderStop;
      }
      $existing->save();
      return;
    }

    $verificationActivitySample = new VerificationActivitySample();
    $verificationActivitySample->id = Uuid::uuid4()->toString();
    $verificationActivitySample->id_verification_activity = 6;
    $verificationActivitySample->start_date = $placeholderStart;
    $verificationActivitySample->stop_date = $placeholderStop;
    $verificationActivitySample->nama_petugas = $nama;
    $verificationActivitySample->is_klinik = $id_permohonan_uji_klinik;
    $verificationActivitySample->is_done = 0;
    if (DB::getSchemaBuilder()->hasColumn('tb_verification_activity_samples', 'resampling')) {
      $verificationActivitySample->resampling = 0;
    }
    $verificationActivitySample->save();
  }

  /**
   * Tanggal pengujian untuk form analis — selaras dengan step Pemeriksa Sampel (verification activity 3).
   */
  private function resolveTanggalPengujianForAnalisForm(
    string $id_permohonan_uji_klinik,
    PermohonanUjiKlinik2 $permohonan,
    ?string $requestJam = null
  ): ?string {
    $requestJam = trim((string) $requestJam);
    if ($requestJam !== '') {
      if (preg_match('/^\d{1,2}:\d{2}(?::\d{2})?$/', $requestJam)) {
        return DateHelper::clockOnRegisterDate(
          DateHelper::permohonanAnchorAt($permohonan),
          $requestJam
        )->format('Y-m-d H:i:s');
      }
      foreach (['Y-m-d H:i:s', 'Y-m-d H:i', 'd/m/Y H:i'] as $format) {
        try {
          return Carbon::createFromFormat($format, $requestJam)->format('Y-m-d H:i:s');
        } catch (\Throwable $e) {
        }
      }
      try {
        return Carbon::parse($requestJam)->format('Y-m-d H:i:s');
      } catch (\Throwable $e) {
      }
    }

    $pemeriksaanSample = VerificationActivitySample::where('is_klinik', $id_permohonan_uji_klinik)
      ->where('id_verification_activity', 3)
      ->where(function ($q) {
        $q->where('resampling', 0)->orWhereNull('resampling');
      })
      ->orderBy('start_date', 'desc')
      ->first();

    if ($pemeriksaanSample && !empty($pemeriksaanSample->start_date)) {
      return Carbon::parse($pemeriksaanSample->start_date)->format('Y-m-d H:i:s');
    }

    if (!empty($permohonan->tglpengujian_permohonan_uji_klinik)) {
      return Carbon::parse($permohonan->tglpengujian_permohonan_uji_klinik)->format('Y-m-d H:i:s');
    }

    $pengolahSample = VerificationActivitySample::where('is_klinik', $id_permohonan_uji_klinik)
      ->where('id_verification_activity', 2)
      ->where(function ($q) {
        $q->where('resampling', 0)->orWhereNull('resampling');
      })
      ->orderBy('start_date', 'desc')
      ->first();

    if ($pengolahSample && !empty($pengolahSample->stop_date)) {
      return Carbon::parse($pengolahSample->stop_date)->format('Y-m-d H:i:s');
    }

    return DateHelper::clockOnRegisterDate(DateHelper::permohonanAnchorAt($permohonan))->format('Y-m-d H:i:s');
  }

  /**
   * Petugas & waktu pemeriksaan untuk cetak: dari verification activity 3, fallback ke kolom permohonan (input analis).
   */
  private function markPengambilSampleSkipped(string $id_permohonan_uji_klinik, ?string $namaPetugasOverride = null): void
  {
    $existing = VerificationActivitySample::where('is_klinik', $id_permohonan_uji_klinik)
      ->where('id_verification_activity', 6)
      ->where(function ($q) {
        $q->where('resampling', 0)->orWhereNull('resampling');
      })
      ->first();

    if ($existing && (int) $existing->is_done === 1) {
      return;
    }

    $permohonan = PermohonanUjiKlinik2::find($id_permohonan_uji_klinik);
    if (!$permohonan) {
      return;
    }

    $regDate = $permohonan->tglregister_permohonan_uji_klinik
      ? Carbon::parse($permohonan->tglregister_permohonan_uji_klinik)->format('Y-m-d H:i:s')
      : Carbon::now()->format('Y-m-d H:i:s');

    $petugasRegistrasi = VerificationActivitySample::where('is_klinik', $id_permohonan_uji_klinik)
      ->where('id_verification_activity', 1)
      ->where(function ($q) {
        $q->where('resampling', 0)->orWhereNull('resampling');
      })
      ->value('nama_petugas');

    $namaPetugas = trim((string) ($namaPetugasOverride ?? ''));
    if ($namaPetugas === '') {
      $namaPetugas = $petugasRegistrasi ?: '-';
    }

    if ($existing) {
      $existing->is_done = 1;
      $existing->start_date = $existing->start_date ?: $regDate;
      $existing->stop_date = $existing->stop_date ?: Carbon::parse($regDate)->addMinute()->format('Y-m-d H:i:s');
      if (!$existing->nama_petugas) {
        $existing->nama_petugas = $namaPetugas;
      }
      $existing->save();
      return;
    }

    $verificationActivitySample = new VerificationActivitySample();
    $verificationActivitySample->id = Uuid::uuid4()->toString();
    $verificationActivitySample->id_verification_activity = 6;
    $verificationActivitySample->start_date = $regDate;
    $verificationActivitySample->stop_date = Carbon::parse($regDate)->addMinute()->format('Y-m-d H:i:s');
    $verificationActivitySample->nama_petugas = $namaPetugas;
    $verificationActivitySample->is_klinik = $id_permohonan_uji_klinik;
    $verificationActivitySample->is_done = 1;
    if (DB::getSchemaBuilder()->hasColumn('tb_verification_activity_samples', 'resampling')) {
      $verificationActivitySample->resampling = 0;
    }
    $verificationActivitySample->save();
  }

  private function ensureUrineOnlyPengambilSampleSkipped(string $id_permohonan_uji_klinik): void
  {
    if (!Smt::isUrineOnlySample($id_permohonan_uji_klinik)) {
      return;
    }

    $this->markPengambilSampleSkipped($id_permohonan_uji_klinik);
  }

  /**
   * Mode "Dibawa Pelanggan Sendiri": lewati pengambilan sampel, lanjut ke penerimaan.
   */
  public function ensureDibawaPelangganPengambilSampleSkipped(string $id_permohonan_uji_klinik): void
  {
    $permohonan = PermohonanUjiKlinik2::find($id_permohonan_uji_klinik);
    if (!$permohonan || ($permohonan->mode_pengambilan_sampel ?? '') !== 'dibawa_pelanggan') {
      return;
    }

    $this->markPengambilSampleSkipped($id_permohonan_uji_klinik, self::PETUGAS_PENGAMBIL_DIISI_PELANGGAN_LABEL);
  }

  private function resolvePemeriksaanKlinikUntukCetak($verificationActivity, PermohonanUjiKlinik2 $item_permohonan_uji_klinik): array
  {
      $va = $verificationActivity->where('id_verification_activity', '=', 3)->first();
      $nama = ($va && $va->nama_petugas !== null && $va->nama_petugas !== '') ? $va->nama_petugas : null;
      $tanggalStart = ($va && $va->start_date !== null && $va->start_date !== '') ? $va->start_date : null;

      if ($nama === null || $nama === '') {
          $nama = $item_permohonan_uji_klinik->name_analis_permohonan_uji_klinik ?? null;
      }
      if (empty($tanggalStart) && $item_permohonan_uji_klinik->tglpengujian_permohonan_uji_klinik !== null) {
          $tanggalStart = $item_permohonan_uji_klinik->tglpengujian_permohonan_uji_klinik;
      }

      return [
          'nama_petugas_pemeriksa' => ($nama !== null && $nama !== '')
            ? self::resolvePetugasCanonicalName($nama)
            : '...................',
          'tanggal_pemeriksaan_sample_start' => $tanggalStart,
      ];
  }

  /**
   * Ambil daftar petugas analis klinik (role 3 + lab klinik), dengan cache singkat.
   */
  private function getPetugasAnalisKlinik()
  {
      return \Cache::remember('puk2.petugas_analis_klinik', now()->addMinutes(10), function () {
          $labKlinikId = 'bbed2259-2826-4711-b0fc-abdad5aace22';
          $labKlinikIdFromCode = Laboratorium::query()
              ->where('kode_laboratorium', 'KLI')
              ->value('id_laboratorium');

          return Petugas::query()
              ->select(['id_petugas', 'nama', 'nip', 'role', 'lab_id'])
              ->whereNotNull('role')
              ->get()
              ->filter(function ($petugas) use ($labKlinikId, $labKlinikIdFromCode) {
                  $roles = is_array($petugas->role) ? $petugas->role : json_decode($petugas->role, true);
                  $hasRole3 = is_array($roles) && in_array('3', $roles);
                  if (!$hasRole3) {
                      return false;
                  }

                  $labIds = is_array($petugas->lab_id) ? $petugas->lab_id : json_decode($petugas->lab_id, true);
                  if (!is_array($labIds)) {
                      $labIds = $labIds ? [$labIds] : [];
                  }

                  return in_array($labKlinikId, $labIds) || ($labKlinikIdFromCode && in_array($labKlinikIdFromCode, $labIds));
              })
              ->map(function ($petugas) {
                  return [
                      'id_petugas' => $petugas->id_petugas,
                      'nama' => $petugas->nama,
                      'nip' => $petugas->nip ?? '',
                  ];
              })
              ->sortBy('nama')
              ->values();
      });
  }

  /**
   * Cache in-memory per request untuk lookup baku mutu per pasangan jenis+satuan.
   * Mengurangi query berulang di loop parameter besar tanpa mengubah hasil.
   */
  /**
   * Filter query klinik berdasarkan pemeriksaan haji.
   * $flag: '1' = hanya haji, '0' = non-haji, selain itu = tidak difilter.
   * $filterHaji: id rombongan (opsional, hanya relevan jika $flag = '1').
   *
   * @param  \Illuminate\Database\Eloquent\Builder|\Illuminate\Database\Query\Builder  $query
   * @param  mixed  $flag
   * @param  mixed  $filterHaji
   * @return void
   */
  private function applyPemeriksaanHajiFilter($query, $flag, $filterHaji = null): void
  {
    $flag = is_string($flag) || is_numeric($flag) ? (string) $flag : '';

    if ($flag === '1') {
      $query->where(function ($q) {
        $q->where('tb_permohonan_uji_klinik_2.is_haji', 1)
          ->orWhereNotNull('tb_permohonan_uji_klinik_2.id_permohonan_uji_klinik_haji');
      });

      if ($filterHaji && $filterHaji !== 'all') {
        $query->where('tb_permohonan_uji_klinik_2.id_permohonan_uji_klinik_haji', $filterHaji);
      }
      return;
    }

    if ($flag === '0') {
      $query->where(function ($q) {
        $q->where('tb_permohonan_uji_klinik_2.is_haji', 0)
          ->orWhereNull('tb_permohonan_uji_klinik_2.is_haji');
      })->whereNull('tb_permohonan_uji_klinik_2.id_permohonan_uji_klinik_haji');
    }
  }

  /**
   * Info keterangan haji + rombongan (nama_haji dari master).
   *
   * @param  object|null  $permohonan  PermohonanUjiKlinik2 / item verification
   * @return array{is_haji:bool,nama_haji:?string,tgl_haji:?string,id_haji:?string}
   */
  private function resolveInfoHajiForPermohonan($permohonan): array
  {
    $empty = [
      'is_haji' => false,
      'nama_haji' => null,
      'tgl_haji' => null,
      'id_haji' => null,
    ];

    if (!$permohonan) {
      return $empty;
    }

    $idHaji = $permohonan->id_permohonan_uji_klinik_haji ?? null;
    $isHaji = ((int) ($permohonan->is_haji ?? 0) === 1) || !empty($idHaji);

    if (!$isHaji) {
      return $empty;
    }

    $namaHaji = null;
    $tglHaji = null;
    if (!empty($idHaji)) {
      $master = PermohonanUjiKlinikHaji::where('id_permohonan_uji_klinik_haji', $idHaji)
        ->whereNull('deleted_at')
        ->first(['nama_haji', 'tgl_haji']);
      if ($master) {
        $namaHaji = $master->nama_haji;
        $tglHaji = $master->tgl_haji;
      }
    }

    return [
      'is_haji' => true,
      'nama_haji' => $namaHaji,
      'tgl_haji' => $tglHaji,
      'id_haji' => $idHaji,
    ];
  }

  /**
   * Prefetch map id_haji => nama_haji untuk badge list.
   *
   * @param  iterable  $rows
   * @return array<string,string>
   */
  private function prefetchNamaHajiMap($rows): array
  {
    $ids = collect($rows)
      ->pluck('id_permohonan_uji_klinik_haji')
      ->filter()
      ->unique()
      ->values()
      ->all();

    if (empty($ids)) {
      return [];
    }

    return PermohonanUjiKlinikHaji::whereIn('id_permohonan_uji_klinik_haji', $ids)
      ->whereNull('deleted_at')
      ->pluck('nama_haji', 'id_permohonan_uji_klinik_haji')
      ->toArray();
  }

  /**
   * HTML badge Haji + rombongan untuk kolom list/datatable.
   */
  private function formatHajiListBadgesHtml($row, array $namaHajiMap = [], string $style = 'simple'): string
  {
    $idHaji = $row->id_permohonan_uji_klinik_haji ?? null;
    $isHaji = ((int) ($row->is_haji ?? 0) === 1) || !empty($idHaji);
    if (!$isHaji) {
      return '';
    }

    static $namaCache = [];

    $nama = '';
    if (!empty($idHaji)) {
      if (isset($namaHajiMap[$idHaji])) {
        $nama = trim((string) $namaHajiMap[$idHaji]);
      } elseif (array_key_exists($idHaji, $namaCache)) {
        $nama = trim((string) ($namaCache[$idHaji] ?? ''));
      } else {
        $namaCache[$idHaji] = PermohonanUjiKlinikHaji::where('id_permohonan_uji_klinik_haji', $idHaji)
          ->whereNull('deleted_at')
          ->value('nama_haji');
        $nama = trim((string) ($namaCache[$idHaji] ?? ''));
      }
    }

    if ($style === 'pill') {
      $html = '<label class="badge badge-warning badge-pill" style="font-size: 13px; padding: 6px 12px;"><i class="fa fa-mosque mr-1"></i>Haji</label>';
      if ($nama !== '') {
        $html .= ' <label class="badge badge-info badge-pill" style="font-size: 13px; padding: 6px 12px;" title="Rombongan haji"><i class="fa fa-users mr-1"></i>'
          . e($nama) . '</label>';
      }

      return $html;
    }

    $html = '<span class="badge badge-warning" title="Pasien haji"><i class="fa fa-mosque mr-1"></i>Haji</span>';
    if ($nama !== '') {
      $html .= ' <span class="badge badge-info" title="Rombongan haji"><i class="fa fa-users mr-1"></i>'
        . e($nama) . '</span>';
    }

    return $html;
  }

  private function getBakuMutuByPair($id_parameter_jenis_klinik, $parameter_satuan_klinik)
  {
      static $cache = [];
      $key = $id_parameter_jenis_klinik . '|' . $parameter_satuan_klinik;

      if (!array_key_exists($key, $cache)) {
          $cache[$key] = BakuMutu::where('parameter_jenis_klinik_id', $id_parameter_jenis_klinik)
              ->where('parameter_satuan_klinik_id', $parameter_satuan_klinik)
              ->whereNull('deleted_at')
              ->get();
      }

      return $cache[$key];
  }

  /**
   * Nilai keterangan_dilaporan untuk cetak: utamakan snapshot DB permohonan.
   * Untuk hasil haji, utamakan baku mutu haji (perbaiki snapshot non-haji bila perlu).
   */
  private function keteranganDilaporanForPrintFromSatuan(
    PermohonanUjiParameterKlinik $value_satuan,
    $pasien_gender,
    $pasien_umur,
    int $is_haji
  ): ?string {
    if ($is_haji === 1) {
      return $this->resolvedKeteranganDilaporanForSatuan(
        $value_satuan,
        $pasien_gender,
        $pasien_umur,
        $is_haji,
        true
      );
    }

    $stored = $value_satuan->keterangan_dilaporan_baku_mutu_permohonan_uji_parameter_klinik ?? null;
    if ($stored !== null && $stored !== '' && $stored !== '-') {
      return $stored;
    }

    return $this->resolvedKeteranganDilaporanForSatuan(
      $value_satuan,
      $pasien_gender,
      $pasien_umur,
      $is_haji,
      true
    );
  }

  /**
   * Nilai normal untuk tampilan/cetak dari snapshot; perbaiki DB jika tidak cocok usia/gender pasien.
   */
  private function resolvedKeteranganDilaporanForSatuan(
    PermohonanUjiParameterKlinik $value_satuan,
    $pasien_gender,
    $pasien_umur,
    int $is_haji,
    bool $persistRepair = false
  ): ?string {
    $allBm = BakuMutuPermohonanKlinikHelper::loadBakuMutuForParameter(
      (string) $value_satuan->jenis_parameter_klinik_id,
      (string) $value_satuan->parameter_satuan_klinik,
      $is_haji
    );
    $massalKeterangan = BakuMutuPermohonanKlinikHelper::resolveMassalKeteranganDilaporan($allBm);
    if ($massalKeterangan !== null && $massalKeterangan !== '') {
      return $massalKeterangan;
    }

    $primary = BakuMutuPermohonanKlinikHelper::resolveMatchedBakuMutu(
      (string) $value_satuan->jenis_parameter_klinik_id,
      (string) $value_satuan->parameter_satuan_klinik,
      $pasien_gender,
      $pasien_umur,
      $is_haji
    );
    $forceHaji = BakuMutuPermohonanKlinikHelper::shouldForceHajiResolve(
      $value_satuan->baku_mutu_permohonan_uji_parameter_klinik ?? null,
      $is_haji,
      $primary
    );

    $stored = $value_satuan->keterangan_dilaporan_baku_mutu_permohonan_uji_parameter_klinik ?? null;
    if (
      !$forceHaji
      && $stored !== null
      && $stored !== ''
      && $stored !== '-'
    ) {
      return $stored;
    }

    if ($persistRepair) {
      return BakuMutuPermohonanKlinikHelper::repairSnapshotIfNeeded(
        $value_satuan,
        $pasien_gender,
        $pasien_umur,
        $is_haji
      );
    }

    return BakuMutuPermohonanKlinikHelper::resolveKeteranganDilaporanForDisplay(
      $value_satuan->keterangan_dilaporan_baku_mutu_permohonan_uji_parameter_klinik,
      $value_satuan->min_baku_mutu_permohonan_uji_parameter_klinik,
      $value_satuan->max_baku_mutu_permohonan_uji_parameter_klinik,
      $value_satuan->baku_mutu_permohonan_uji_parameter_klinik,
      $value_satuan->jenis_parameter_klinik_id,
      $value_satuan->parameter_satuan_klinik,
      $pasien_gender,
      $pasien_umur,
      $is_haji
    );
  }

  /**
   * Resolve baku mutu terpilih untuk parameter (logika sama dengan halaman analis).
   */
  private function resolveBakuMutuForPermohonanParameter(
    $id_parameter_jenis_klinik,
    $parameter_satuan_klinik_id,
    $pasien_gender,
    $pasien_umur,
    $is_haji
  ) {
    $is_haji = (int) $is_haji;
    if ($is_haji === 1) {
      $parameter_satuan_klinik_id = BakuMutuPermohonanKlinikHelper::resolveHajiLookupSatuanId(
        (string) $id_parameter_jenis_klinik,
        (string) $parameter_satuan_klinik_id
      );
    }

    $data_parameter_by_baku_mutu = BakuMutu::where('parameter_jenis_klinik_id', $id_parameter_jenis_klinik)
      ->where('parameter_satuan_klinik_id', $parameter_satuan_klinik_id);

    if ($is_haji) {
      $data_parameter_by_baku_mutu_haji = (clone $data_parameter_by_baku_mutu)->where('is_haji', 1)->whereNull('deleted_at')->get();
      if ($data_parameter_by_baku_mutu_haji->count() > 0) {
        $data_parameter_by_baku_mutu = $data_parameter_by_baku_mutu_haji;
      } else {
        $data_parameter_by_baku_mutu = $data_parameter_by_baku_mutu->where(function ($query) {
          $query->where('is_haji', 0)->orWhereNull('is_haji');
        })->whereNull('deleted_at')->get();
      }
    } else {
      $data_parameter_by_baku_mutu = $data_parameter_by_baku_mutu->where(function ($query) {
        $query->where('is_haji', 0)->orWhereNull('is_haji');
      })->whereNull('deleted_at')->get();
    }

    $multiple_baku_mutu = [];
    $item_parameter_by_baku_mutu = null;

    if (count($data_parameter_by_baku_mutu) > 0) {
      if ($is_haji) {
        $baku_mutu_haji = BakuMutu::where('parameter_jenis_klinik_id', $id_parameter_jenis_klinik)
          ->where('parameter_satuan_klinik_id', $parameter_satuan_klinik_id)
          ->where('is_haji', 1)
          ->whereNull('deleted_at')
          ->get();

        if ($baku_mutu_haji->count() > 0) {
          $check_parameter_by_baku_mutu = $baku_mutu_haji->where('gender_baku_mutu', $pasien_gender)->first();
          if (!$check_parameter_by_baku_mutu) {
            $check_parameter_by_baku_mutu = $baku_mutu_haji->whereNull('gender_baku_mutu')->first();
          }
          if (!$check_parameter_by_baku_mutu) {
            $check_parameter_by_baku_mutu = $baku_mutu_haji->first();
          }
        } else {
          $baku_mutu_non_haji = BakuMutu::where('parameter_jenis_klinik_id', $id_parameter_jenis_klinik)
            ->where('parameter_satuan_klinik_id', $parameter_satuan_klinik_id)
            ->where('is_khusus_baku_mutu', '0')
            ->where(function ($query) {
              $query->where('is_haji', 0)->orWhereNull('is_haji');
            })
            ->whereNull('deleted_at')
            ->get();

          $check_parameter_by_baku_mutu = $baku_mutu_non_haji->where('gender_baku_mutu', $pasien_gender)->first();
          if (!$check_parameter_by_baku_mutu) {
            $check_parameter_by_baku_mutu = $baku_mutu_non_haji->whereNull('gender_baku_mutu')->first();
          }
          if (!$check_parameter_by_baku_mutu) {
            $check_parameter_by_baku_mutu = $baku_mutu_non_haji->first();
          }
        }
      } else {
        $baku_mutu_non_haji = BakuMutu::where('parameter_jenis_klinik_id', $id_parameter_jenis_klinik)
          ->where('parameter_satuan_klinik_id', $parameter_satuan_klinik_id)
          ->where('is_khusus_baku_mutu', '0')
          ->where(function ($query) {
            $query->where('is_haji', 0)->orWhereNull('is_haji');
          })
          ->whereNull('deleted_at')
          ->get();

        $check_parameter_by_baku_mutu = $baku_mutu_non_haji->where('gender_baku_mutu', $pasien_gender)->first();
        if (!$check_parameter_by_baku_mutu) {
          $check_parameter_by_baku_mutu = $baku_mutu_non_haji->whereNull('gender_baku_mutu')->first();
        }
        if (!$check_parameter_by_baku_mutu) {
          $check_parameter_by_baku_mutu = $baku_mutu_non_haji->first();
        }
      }

      if ($check_parameter_by_baku_mutu) {
        $item_parameter_by_baku_mutu = $check_parameter_by_baku_mutu;
        // General bisa punya >1 baris (mis. Kristal: Negatif + Pos 1 (+), keduanya is_normal)
        // — tetap kirim semua agar checkBakuMutu mencocokkan semua equal/range.
        $generalCollection = $is_haji
          ? (isset($baku_mutu_haji) && $baku_mutu_haji->count() > 0 ? $baku_mutu_haji : ($baku_mutu_non_haji ?? collect()))
          : ($baku_mutu_non_haji ?? collect());
        $multiple_baku_mutu = $generalCollection->count() > 1
          ? $generalCollection->values()->toArray()
          : [];
      } else {
        if ($is_haji) {
          $all_baku_mutu_khusus = BakuMutu::where('parameter_jenis_klinik_id', $id_parameter_jenis_klinik)
            ->where('parameter_satuan_klinik_id', $parameter_satuan_klinik_id)
            ->where('is_khusus_baku_mutu', '1')
            ->where('is_haji', 1)
            ->whereNull('deleted_at')
            ->get();

          if ($all_baku_mutu_khusus->count() == 0) {
            $all_baku_mutu_khusus = BakuMutu::where('parameter_jenis_klinik_id', $id_parameter_jenis_klinik)
              ->where('parameter_satuan_klinik_id', $parameter_satuan_klinik_id)
              ->where('is_khusus_baku_mutu', '1')
              ->where(function ($query) {
                $query->where('is_haji', 0)->orWhereNull('is_haji');
              })
              ->whereNull('deleted_at')
              ->get();
          }
        } else {
          $all_baku_mutu_khusus = BakuMutu::where('parameter_jenis_klinik_id', $id_parameter_jenis_klinik)
            ->where('parameter_satuan_klinik_id', $parameter_satuan_klinik_id)
            ->where('is_khusus_baku_mutu', '1')
            ->where(function ($query) {
              $query->where('is_haji', 0)->orWhereNull('is_haji');
            })
            ->whereNull('deleted_at')
            ->get();
        }

        $multiple_baku_mutu = $all_baku_mutu_khusus->toArray();

        if ($all_baku_mutu_khusus->count() > 1) {
          $normal_baku_mutu_collection = $all_baku_mutu_khusus->where('is_normal', 1);

          if ($normal_baku_mutu_collection->count() > 0) {
            $all_have_gender_or_umur = $normal_baku_mutu_collection->every(function ($item) {
              $has_gender = (isset($item->gender_baku_mutu) && $item->gender_baku_mutu !== null);
              $has_umur_range = (isset($item->minimal_umur_baku_mutu) && isset($item->maksimal_umur_baku_mutu));

              return $has_gender || $has_umur_range;
            });

            if ($all_have_gender_or_umur) {
              $matched_by_gender_and_umur = $normal_baku_mutu_collection->filter(function ($item) use ($pasien_gender, $pasien_umur) {
                $gender_match = isset($item->gender_baku_mutu) && $item->gender_baku_mutu === $pasien_gender;
                $umur_match = (isset($item->minimal_umur_baku_mutu) && isset($item->maksimal_umur_baku_mutu)
                      && $item->minimal_umur_baku_mutu <= $pasien_umur && $item->maksimal_umur_baku_mutu >= $pasien_umur);
                $umur_match_gen_null = ((isset($item->minimal_umur_baku_mutu) && isset($item->maksimal_umur_baku_mutu)
                    && $item->minimal_umur_baku_mutu <= $pasien_umur && $item->maksimal_umur_baku_mutu >= $pasien_umur))
                    && (!isset($item->gender_baku_mutu) || $item->gender_baku_mutu === null);
                $gen_match_umur_null = (isset($item->gender_baku_mutu) && $item->gender_baku_mutu === $pasien_gender) && (!isset($item->minimal_umur_baku_mutu) || !isset($item->maksimal_umur_baku_mutu));

                return ($gender_match && $umur_match) || $umur_match_gen_null || $gen_match_umur_null;
              });

              if ($matched_by_gender_and_umur->count() > 0) {
                $item_parameter_by_baku_mutu = $matched_by_gender_and_umur->first();
              } else {
                $matched_by_gender = $normal_baku_mutu_collection->filter(function ($item) use ($pasien_gender) {
                  return isset($item->gender_baku_mutu) && $item->gender_baku_mutu === $pasien_gender;
                });

                if ($matched_by_gender->count() > 0) {
                  $item_parameter_by_baku_mutu = $matched_by_gender->first();
                } else {
                  $matched_by_umur = $normal_baku_mutu_collection->filter(function ($item) use ($pasien_umur) {
                    return (!isset($item->minimal_umur_baku_mutu) && !isset($item->maksimal_umur_baku_mutu))
                      || (isset($item->minimal_umur_baku_mutu) && isset($item->maksimal_umur_baku_mutu)
                          && $item->minimal_umur_baku_mutu <= $pasien_umur && $item->maksimal_umur_baku_mutu >= $pasien_umur);
                  });

                  if ($matched_by_umur->count() > 0) {
                    $item_parameter_by_baku_mutu = $matched_by_umur->first();
                  } else {
                    $item_parameter_by_baku_mutu = $normal_baku_mutu_collection->first();
                  }
                }
              }
            } else {
              $item_parameter_by_baku_mutu = $normal_baku_mutu_collection->first();
            }
          } else {
            $item_parameter_by_baku_mutu = $all_baku_mutu_khusus
              ->where('gender_baku_mutu', $pasien_gender)
              ->first();

            if (!$item_parameter_by_baku_mutu) {
              $item_parameter_by_baku_mutu = $all_baku_mutu_khusus
                ->whereNull('gender_baku_mutu')
                ->first();
            }

            if (!$item_parameter_by_baku_mutu) {
              $item_parameter_by_baku_mutu = $all_baku_mutu_khusus->first();
            }
          }
        } else {
          $item_parameter_by_baku_mutu = $all_baku_mutu_khusus->where('gender_baku_mutu', $pasien_gender)->first();
          if (!$item_parameter_by_baku_mutu) {
            $item_parameter_by_baku_mutu = $all_baku_mutu_khusus->whereNull('gender_baku_mutu')->first();
          }
          if (!$item_parameter_by_baku_mutu) {
            $item_parameter_by_baku_mutu = $all_baku_mutu_khusus->first();
          }
        }
      }
    }

    return [
      'selected' => $item_parameter_by_baku_mutu,
      'multiple_baku_mutu' => $multiple_baku_mutu,
      'has_multiple_baku_mutu' => count($multiple_baku_mutu) > 1,
    ];
  }

  public function printPermohonanUjiKlinikHasil(Request $request, $id_permohonan_uji_klinik)
  {
        // mode=preview → return HTML view langsung (tanpa cek status SELESAI), untuk popup review
        $isPreviewMode = $request->input('mode') === 'preview';

        // force_kop=1 → paksa kop surat selalu tampil (dipakai pada link WhatsApp)
        $forceKop = (int) $request->input('force_kop', 0);

        $validated = $request->validate([
          'signoption' => 'nullable|integer|min:0|max:1',
        ]);

        $signoption = $validated['signoption'] ?? 0;

        $item_permohonan_uji_klinik = PermohonanUjiKlinik2::with('pasien')->find($id_permohonan_uji_klinik);

        // Validasi: Pastikan hasil sudah selesai sebelum bisa di-print
        if (!$item_permohonan_uji_klinik) {
            abort(404, 'Permohonan Uji Klinik tidak ditemukan');
        }

        $this->refreshPasienRelationForCetakHasil($item_permohonan_uji_klinik);

        // Cetak/preview selalu diizinkan (meski belum sampai analis / hasil masih kosong).
        // Parameter tetap tampil dengan kolom HASIL kosong; WhatsApp resmi tetap digate di tempat lain.


        // Build No. Laboratorium: 449.5/03/{nomer_lab}/{year}
        // Gunakan method helper untuk mendapatkan nomor lab (manual atau otomatis)
        $yearNow = Carbon::now()->format('Y');
        $nomerLabValue = $item_permohonan_uji_klinik->getNomorLab();
        $nomerLab = $nomerLabValue
            ? (is_numeric($nomerLabValue) ? str_pad($nomerLabValue, 3, '0', STR_PAD_LEFT) : $nomerLabValue)
            : '&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;';
        $no_LHU = '449.5/03/' . $nomerLab . '/' . $yearNow;

        $verificationActivity = VerificationActivitySample::query()
            ->where('is_klinik', '=', $id_permohonan_uji_klinik)
            ->get();
        $verificationByStep = $verificationActivity->keyBy('id_verification_activity');

        $vaPengambil = $verificationByStep->get(6);
        $nama_petugas_pengambil_sample = $vaPengambil->nama_petugas ?? "...................";

        $tanggal_pengambilan_sample_start = $vaPengambil->start_date ?? null;

        $tanggal_pengambilan_sample = $tanggal_pengambilan_sample_start
          ? \Carbon\Carbon::parse($tanggal_pengambilan_sample_start)->isoFormat('DD MMMM YYYY HH:mm')
          : '-';


        $resolvedPemeriksaan = $this->resolvePemeriksaanKlinikUntukCetak($verificationActivity, $item_permohonan_uji_klinik);
        $nama_petugas_pemeriksa = $resolvedPemeriksaan['nama_petugas_pemeriksa'];
        $tanggal_pemeriksaan_sample_start = $resolvedPemeriksaan['tanggal_pemeriksaan_sample_start'];

        $nama_petugas_verifikator = optional($verificationByStep->get(4))->nama_petugas ?? "-";
        if ($nama_petugas_verifikator !== '-' && $nama_petugas_verifikator !== '') {
          $nama_petugas_verifikator = self::resolvePetugasCanonicalName($nama_petugas_verifikator);
        }

        $tanggal_pemeriksaan_sample = $tanggal_pemeriksaan_sample_start 
          ? \Carbon\Carbon::parse($tanggal_pemeriksaan_sample_start)->isoFormat('DD MMMM YYYY HH:mm')
          : '-';

        if ($item_permohonan_uji_klinik->tglpengujian_permohonan_uji_klinik !== null) {
          $tgl_pengujian = Carbon::createFromFormat('Y-m-d H:i:s', $item_permohonan_uji_klinik->tglpengujian_permohonan_uji_klinik)->isoFormat('D MMMM Y HH:mm');
        } else {
          $tgl_pengujian = '';
        }

        if ($item_permohonan_uji_klinik->spesimen_darah_permohonan_uji_klinik !== null) {
          $tgl_spesimen_darah = Carbon::createFromFormat('Y-m-d H:i:s', $item_permohonan_uji_klinik->spesimen_darah_permohonan_uji_klinik)->isoFormat('D MMMM Y HH:mm');
        } else {
          $tgl_spesimen_darah = '-';
        }

        if ($item_permohonan_uji_klinik->spesimen_urine_permohonan_uji_klinik !== null) {
          $tgl_spesimen_urine = Carbon::createFromFormat('Y-m-d H:i:s', $item_permohonan_uji_klinik->spesimen_urine_permohonan_uji_klinik)->isoFormat('D MMMM Y HH:mm');
        } else {
          $tgl_spesimen_urine = '-';
        }

        $data_permohonan_uji_parameter_klinik = PermohonanUjiParameterKlinik::where('permohonan_uji_klinik', $id_permohonan_uji_klinik)
          ->whereHas('parametersatuanklinik', function ($query) {
            return $this->applyKlinikPrintParameterSatuanConstraint($query)
              ->orderBy('sort_parameter_satuan_klinik', 'asc');
          })
          ->whereNull('deleted_at')
          ->where('permohonan_uji_klinik', $id_permohonan_uji_klinik)
          ->get();

        $data_parameter_satuan = \Cache::remember('puk2.data_parameter_satuan_klinik', now()->addMinutes(10), function () {
          return ParameterSatuanKlinik::whereNull('deleted_at')
            ->orderBy('sort_parameter_satuan_klinik', 'asc')
            ->get();
        });

        $arr_permohonan_parameter = [];
        // Urutan dari halaman elits-parameter-satuan-klinik/reorder
        $data_permohonan_uji_satuan_klinik = PermohonanUjiParameterKlinik::where('permohonan_uji_klinik', $id_permohonan_uji_klinik)
          ->join('ms_parameter_satuan_klinik', 'tb_permohonan_uji_parameter_klinik.parameter_satuan_klinik', '=', 'ms_parameter_satuan_klinik.id_parameter_satuan_klinik')
          ->where(function ($q) {
            $q->where('ms_parameter_satuan_klinik.jenis_pemeriksaan_parameter_satuan_klinik', '0')
              ->orWhere(function ($q2) {
                $q2->whereNotIn('ms_parameter_satuan_klinik.jenis_pemeriksaan_parameter_satuan_klinik', ['1', '2'])
                  ->where(function ($q3) {
                    $q3->whereNull('ms_parameter_satuan_klinik.name_parameter_satuan_klinik')
                      ->orWhereRaw('LOWER(ms_parameter_satuan_klinik.name_parameter_satuan_klinik) NOT LIKE ?', ['rapid antigen%']);
                  })
                  ->whereExists(function ($exists) {
                    // COLLATE: ms_parameter_sub_satuan_klinik = utf8mb4_general_ci,
                    // ms_parameter_satuan_klinik.id = utf8mb4_unicode_ci
                    $exists->select(DB::raw(1))
                      ->from('ms_parameter_sub_satuan_klinik as msub_klinik_print')
                      ->whereRaw(
                        'msub_klinik_print.parameter_satuan_klinik COLLATE utf8mb4_unicode_ci = ms_parameter_satuan_klinik.id_parameter_satuan_klinik'
                      )
                      ->whereNull('msub_klinik_print.deleted_at');
                  });
              });
          })
          ->whereNull('ms_parameter_satuan_klinik.deleted_at')
          ->whereNull('tb_permohonan_uji_parameter_klinik.deleted_at')
          ->orderBy('ms_parameter_satuan_klinik.sort_parameter_satuan_klinik', 'asc')
          ->with(['parametersatuanklinik', 'unit'])
          ->select('tb_permohonan_uji_parameter_klinik.*')
          ->get();

        foreach ($data_permohonan_uji_satuan_klinik as $value_satuan) {
          $this->normalizePermohonanParameterJenisKlinik($value_satuan);
          $this->ensurePermohonanSubParametersForSatuan($value_satuan, $item_permohonan_uji_klinik);
        }

        // Prefetch seluruh sub-parameter agar tidak query per baris parameter
        $subsByParameterId = collect();
        if ($data_permohonan_uji_satuan_klinik->count() > 0) {
          $parameterIdsForSubs = $data_permohonan_uji_satuan_klinik
            ->pluck('id_permohonan_uji_parameter_klinik')
            ->filter()
            ->unique()
            ->values();

          if ($parameterIdsForSubs->count() > 0) {
            $subsByParameterId = PermohonanUjiSubParameterKlinik::query()
              ->whereIn('permohonan_uji_parameter_klinik_id', $parameterIdsForSubs)
              ->with(['parametersubsatuanklinik', 'unit'])
              ->get()
              ->groupBy('permohonan_uji_parameter_klinik_id');
          }
        }



        $data_jenis_parameter_klinik = PermohonanUjiParameterKlinik::where('permohonan_uji_klinik', $id_permohonan_uji_klinik)
          ->groupBy('jenis_parameter_klinik_id')
          ->orderBy('sort_jenis_klinik', 'ASC')
          ->with('jenisparameterklinik')
          ->whereHas('parametersatuanklinik', function ($query) {
            return $this->applyKlinikPrintParameterSatuanConstraint($query)
              ->orderBy('sort_parameter_satuan_klinik', 'asc');
          })
          ->get();

        if (count($data_permohonan_uji_satuan_klinik) > 0) {
          $sortMapById = $this->buildPrintSatuanSortMapById();
          $sortMapByName = $this->buildPrintSatuanSortMapByName();

          foreach ($data_jenis_parameter_klinik as $key_jenis_parameter_klinik => $value_jenis_parameter_klinik) {
            $parameter_jenis_klinik = [];
            $parameter_jenis_klinik['name_parameter_jenis_klinik'] = $value_jenis_parameter_klinik->jenisparameterklinik->name_parameter_jenis_klinik;
            $parameter_jenis_klinik['id_parameter_jenis_klinik'] = $value_jenis_parameter_klinik->jenisparameterklinik->id_parameter_jenis_klinik;
            $parameter_jenis_klinik['sort_parameter_jenis_klinik'] = $value_jenis_parameter_klinik->jenisparameterklinik->sort_parameter_jenis_klinik;
            $parameter_jenis_klinik['id_parameter_jenis_klinik_parent'] = $value_jenis_parameter_klinik->jenisparameterklinik->id_parameter_jenis_klinik_parent;
            $parameter_jenis_klinik['item_permohonan_parameter_satuan'] = [];

            foreach ($data_permohonan_uji_satuan_klinik as $key_satuan => $value_satuan) {

              $jenisIdSatuan = $this->resolveEffectiveJenisParameterKlinikId($value_satuan);
              $jenisIdGroup = $value_jenis_parameter_klinik->jenis_parameter_klinik_id
                ?? ($value_jenis_parameter_klinik->jenisparameterklinik->id_parameter_jenis_klinik ?? null);

              if ($jenisIdSatuan == $jenisIdGroup) {

                $pasien_umur = $item_permohonan_uji_klinik->umurtahun_pasien_permohonan_uji_klinik;
                $pasien_gender = $item_permohonan_uji_klinik->pasien->gender_pasien;

                $item_permohonan_parameter_satuan = [];
                $item_permohonan_parameter_satuan['id_permohonan_uji_parameter_klinik'] = $value_satuan->id_permohonan_uji_parameter_klinik;
                $item_permohonan_parameter_satuan['permohonan_uji_klinik'] = $value_satuan->permohonan_uji_klinik;
                $item_permohonan_parameter_satuan['permohonan_uji_paket_klinik'] = $value_satuan->permohonan_uji_paket_klinik;
                $item_permohonan_parameter_satuan['parameter_paket_klinik'] = $value_satuan->parameter_paket_klinik;
                $item_permohonan_parameter_satuan['method_permohonan_uji_parameter_klinik'] = $value_satuan->method_permohonan_uji_parameter_klinik;
                $item_permohonan_parameter_satuan['parameter_satuan_klinik'] = $value_satuan->parameter_satuan_klinik;
                $item_permohonan_parameter_satuan['nama_parameter_satuan_klinik'] = $value_satuan->parametersatuanklinik->name_parameter_satuan_klinik ?? null;
                $item_permohonan_parameter_satuan['sort_parameter_satuan_klinik'] = $value_satuan->parametersatuanklinik->sort_parameter_satuan_klinik ?? null;
                $item_permohonan_parameter_satuan['metode_parameter_satuan_klinik'] = \Smt\Masterweb\Helpers\Smt::pickMetodeForContext(
              $value_satuan->parametersatuanklinik,
              $item_permohonan_uji_klinik
            );
                $item_permohonan_parameter_satuan['harga_permohonan_uji_parameter_klinik'] = $value_satuan->harga_permohonan_uji_parameter_klinik;
                $item_permohonan_parameter_satuan['hasil_permohonan_uji_parameter_klinik'] = $value_satuan->hasil_permohonan_uji_parameter_klinik;
                $item_permohonan_parameter_satuan['flag_permohonan_uji_parameter_klinik'] = $value_satuan->flag_permohonan_uji_parameter_klinik;
                $item_permohonan_parameter_satuan['keterangan_permohonan_uji_parameter_klinik'] = $value_satuan->keterangan_permohonan_uji_parameter_klinik;
                $item_permohonan_parameter_satuan['offset_baku_mutu'] = $value_satuan->offset_baku_mutu ?? 'default';

                $id_parameter_jenis_klinik = $jenisIdSatuan;
                $is_haji_print = (
                  (int) ($item_permohonan_uji_klinik->is_haji ?? 0) === 1
                  || !empty($item_permohonan_uji_klinik->id_permohonan_uji_klinik_haji)
                ) ? 1 : 0;

                $bakuMutuResolved = $this->resolveBakuMutuForPermohonanParameter(
                  $id_parameter_jenis_klinik,
                  $value_satuan->parameter_satuan_klinik,
                  $pasien_gender,
                  $pasien_umur,
                  $is_haji_print
                );
                $item_parameter_by_baku_mutu = $bakuMutuResolved['selected'];
                $multiple_baku_mutu = $bakuMutuResolved['multiple_baku_mutu'];

                // jika tidak ada satuan di permohonan uji satuan maka ambil value dari baku mutu
                // jika ada nilai satuan di permohonan uji satuan maka ambil nilai dari tabel itu sendiri
                if ($value_satuan->satuan_permohonan_uji_parameter_klinik != null) {
                  $item_permohonan_parameter_satuan['satuan_permohonan_uji_parameter_klinik'] = $value_satuan->satuan_permohonan_uji_parameter_klinik;
                  $item_permohonan_parameter_satuan['nama_satuan_permohonan_uji_parameter_klinik'] = $value_satuan->unit->name_unit ?? null;
                } else if (isset($item_parameter_by_baku_mutu->unit_id)) {
                  $item_permohonan_parameter_satuan['satuan_permohonan_uji_parameter_klinik'] = $item_parameter_by_baku_mutu->unit_id;
                  $item_permohonan_parameter_satuan['nama_satuan_permohonan_uji_parameter_klinik'] = $item_parameter_by_baku_mutu->unit->name_unit ?? null;
                } else {
                  $item_permohonan_parameter_satuan['satuan_permohonan_uji_parameter_klinik'] = null;
                  $item_permohonan_parameter_satuan['nama_satuan_permohonan_uji_parameter_klinik'] = null;
                }

                $forceHajiRanges = BakuMutuPermohonanKlinikHelper::shouldForceHajiResolve(
                  $value_satuan->baku_mutu_permohonan_uji_parameter_klinik ?? null,
                  $is_haji_print,
                  $item_parameter_by_baku_mutu
                );
                if ($forceHajiRanges && $item_parameter_by_baku_mutu) {
                  $item_permohonan_parameter_satuan['min'] = $item_parameter_by_baku_mutu->min ?? null;
                  $item_permohonan_parameter_satuan['max'] = $item_parameter_by_baku_mutu->max ?? null;
                  $item_permohonan_parameter_satuan['equal'] = $item_parameter_by_baku_mutu->equal ?? null;
                } else {
                  $item_permohonan_parameter_satuan['min'] = $value_satuan->min_baku_mutu_permohonan_uji_parameter_klinik
                    ?? ($item_parameter_by_baku_mutu->min ?? null);
                  $item_permohonan_parameter_satuan['max'] = $value_satuan->max_baku_mutu_permohonan_uji_parameter_klinik
                    ?? ($item_parameter_by_baku_mutu->max ?? null);
                  $item_permohonan_parameter_satuan['equal'] = $value_satuan->equal_baku_mutu_permohonan_uji_parameter_klinik
                    ?? ($item_parameter_by_baku_mutu->equal ?? null);
                }
                $item_permohonan_parameter_satuan['is_normal'] = (int) ($item_parameter_by_baku_mutu->is_normal ?? 0);
                $item_permohonan_parameter_satuan['pasien_gender'] = $pasien_gender;
                $item_permohonan_parameter_satuan['pasien_umur'] = $pasien_umur;
                $keterangan_dilaporan_resolved = $this->keteranganDilaporanForPrintFromSatuan(
                  $value_satuan,
                  $pasien_gender,
                  $pasien_umur,
                  $is_haji_print
                );
                $item_permohonan_parameter_satuan['keterangan_dilaporan_baku_mutu_permohonan_uji_parameter_klinik'] = $keterangan_dilaporan_resolved;
                $item_permohonan_parameter_satuan['nilai_baku_mutu'] = $keterangan_dilaporan_resolved ?? ($item_parameter_by_baku_mutu->nilai_baku_mutu ?? null);
                $item_permohonan_parameter_satuan['kesimpulan_baku_mutu'] = $item_parameter_by_baku_mutu->kesimpulan_baku_mutu ?? null;
                $item_permohonan_parameter_satuan['ket_default_parameter_satuan_klinik'] =
                    $value_satuan->parametersatuanklinik->ket_default_parameter_satuan_klinik
                    ?? $value_satuan->parametersatuanklinik->ket_default
                    ?? null;
                // Tambahkan number_format dari parameter satuan klinik (untuk parsing desimal)
                $item_permohonan_parameter_satuan['number_format'] = $value_satuan->parametersatuanklinik->number_format ?? 'en';
                // Tambahkan data multiple baku mutu untuk pengecekan
                $item_permohonan_parameter_satuan['multiple_baku_mutu'] = $multiple_baku_mutu ?? [];
                $item_permohonan_parameter_satuan['has_multiple_baku_mutu'] = $bakuMutuResolved['has_multiple_baku_mutu'];
                $item_permohonan_parameter_satuan['is_baku_mutu_berdasarkan_gender'] = false;
                if (!empty($multiple_baku_mutu) && is_array($multiple_baku_mutu)) {
                  foreach ($multiple_baku_mutu as $bmRow) {
                    if (!empty($bmRow['gender_baku_mutu'])) {
                      $item_permohonan_parameter_satuan['is_baku_mutu_berdasarkan_gender'] = true;
                      break;
                    }
                  }
                }

                // menyiapkan data array untuk mapping jika data parameter memiliki subsatuan
                $item_permohonan_parameter_satuan['data_permohonan_uji_subsatuan_klinik'] = [];

                $data_permohonan_uji_subsatuan_klinik = $subsByParameterId->get($value_satuan->id_permohonan_uji_parameter_klinik, collect());

                if (count($data_permohonan_uji_subsatuan_klinik)) {
                  foreach ($data_permohonan_uji_subsatuan_klinik as $key_subsatuan => $value_subsatuan) {
                    $item_permohonan_parameter_subsatuan = [];
                    $item_permohonan_parameter_subsatuan['id_permohonan_uji_sub_parameter_klinik'] = $value_subsatuan->id_permohonan_uji_sub_parameter_klinik;
                    $item_permohonan_parameter_subsatuan['permohonan_uji_parameter_klinik_id'] = $value_subsatuan->permohonan_uji_parameter_klinik_id;
                    $item_permohonan_parameter_subsatuan['parameter_sub_satuan_klinik_id'] = $value_subsatuan->parameter_sub_satuan_klinik_id;
                    $item_permohonan_parameter_subsatuan['nama_parameter_sub_satuan_klinik_id'] = $value_subsatuan->parametersubsatuanklinik->name_parameter_sub_satuan_klinik ?? null;
                    $item_permohonan_parameter_subsatuan['sort_parameter_sub_satuan_klinik'] = $value_subsatuan->parametersubsatuanklinik->sort_parameter_sub_satuan_klinik ?? null;
                    $hasil_sub_parameter = $value_subsatuan->hasil_permohonan_uji_sub_parameter_klinik;
                    if (($hasil_sub_parameter === null || $hasil_sub_parameter === '' || $hasil_sub_parameter === '-')
                      && empty($value_subsatuan->selected_history_id)) {
                      $last_history = PermohonanUjiSubParameterKlinikHistory::where(
                        'permohonan_uji_sub_parameter_klinik_id',
                        $value_subsatuan->id_permohonan_uji_sub_parameter_klinik
                      )
                        ->whereNull('deleted_at')
                        ->orderBy('created_at', 'desc')
                        ->first();
                      if ($last_history && !empty($last_history->hasil_permohonan_uji_sub_parameter_klinik)) {
                        $hasil_sub_parameter = $last_history->hasil_permohonan_uji_sub_parameter_klinik;
                      }
                    }
                    $item_permohonan_parameter_subsatuan['hasil_permohonan_uji_sub_parameter_klinik'] = $hasil_sub_parameter;
                    $item_permohonan_parameter_subsatuan['flag_permohonan_uji_sub_parameter_klinik'] = $value_subsatuan->flag_permohonan_uji_sub_parameter_klinik;
                    // $item_permohonan_parameter_subsatuan['baku_mutu_permohonan_uji_sub_parameter_klinik'] = $value_subsatuan->baku_mutu_permohonan_uji_sub_parameter_klinik;
                    $item_permohonan_parameter_subsatuan['keterangan_permohonan_uji_sub_parameter_klinik'] = $value_subsatuan->keterangan_permohonan_uji_sub_parameter_klinik;
                    $item_permohonan_parameter_subsatuan['offset_baku_mutu'] = $value_subsatuan->offset_baku_mutu ?? 'default';
                    // Tambahkan data multiple baku mutu untuk sub parameter
                    $item_permohonan_parameter_subsatuan['has_multiple_baku_mutu'] = count($multiple_baku_mutu ?? []) > 1;
                    $item_permohonan_parameter_subsatuan['multiple_baku_mutu'] = $multiple_baku_mutu ?? [];

                    // cek data baku mutu jika memiliki data subsatuan dengan nilai rujukan
                    if (isset($item_parameter_by_baku_mutu->id_baku_mutu)) {
                      $item_parameter_subsatuan_by_baku_mutu = BakuMutuDetailParameterKlinik::where('baku_mutu_id', $item_parameter_by_baku_mutu->id_baku_mutu)
                        ->where('parameter_sub_satuan_baku_mutu_detail_parameter_klinik', $value_subsatuan->parameter_sub_satuan_klinik_id)
                        ->first();

                      if ($item_parameter_subsatuan_by_baku_mutu) {
                        $item_permohonan_parameter_subsatuan['min_baku_mutu_detail_parameter_klinik'] = $item_parameter_subsatuan_by_baku_mutu->min_baku_mutu_detail_parameter_klinik;
                        $item_permohonan_parameter_subsatuan['max_baku_mutu_detail_parameter_klinik'] = $item_parameter_subsatuan_by_baku_mutu->max_baku_mutu_detail_parameter_klinik;
                        $item_permohonan_parameter_subsatuan['equal_baku_mutu_detail_parameter_klinik'] = $item_parameter_subsatuan_by_baku_mutu->equal_baku_mutu_detail_parameter_klinik;
                        $item_permohonan_parameter_subsatuan['nilai_baku_mutu_detail_parameter_klinik'] = $item_parameter_subsatuan_by_baku_mutu->nilai_baku_mutu_detail_parameter_klinik;
                      } else {
                        $item_permohonan_parameter_subsatuan['min_baku_mutu_detail_parameter_klinik'] = null;
                        $item_permohonan_parameter_subsatuan['max_baku_mutu_detail_parameter_klinik'] = null;
                        $item_permohonan_parameter_subsatuan['equal_baku_mutu_detail_parameter_klinik'] = null;
                        $item_permohonan_parameter_subsatuan['nilai_baku_mutu_detail_parameter_klinik'] = null;
                      }
                    } else {
                      $item_permohonan_parameter_subsatuan['min_baku_mutu_detail_parameter_klinik'] = null;
                      $item_permohonan_parameter_subsatuan['max_baku_mutu_detail_parameter_klinik'] = null;
                      $item_permohonan_parameter_subsatuan['equal_baku_mutu_detail_parameter_klinik'] = null;
                      $item_permohonan_parameter_subsatuan['nilai_baku_mutu_detail_parameter_klinik'] = null;
                    }

                    if ($value_subsatuan->satuan_permohonan_uji_sub_parameter_klinik != null) {
                      $item_permohonan_parameter_subsatuan['satuan_permohonan_uji_sub_parameter_klinik'] = $value_subsatuan->satuan_permohonan_uji_sub_parameter_klinik;

                      $item_permohonan_parameter_subsatuan['nama_satuan_permohonan_uji_sub_parameter_klinik'] = $value_subsatuan->unit->name_unit ?? null;
                    } else if (isset($item_parameter_subsatuan_by_baku_mutu->unit_id_baku_mutu_detail_parameter_klinik)) {
                      $item_permohonan_parameter_subsatuan['satuan_permohonan_uji_sub_parameter_klinik'] = $item_parameter_subsatuan_by_baku_mutu->unit_id_baku_mutu_detail_parameter_klinik;

                      $item_permohonan_parameter_subsatuan['nama_satuan_permohonan_uji_sub_parameter_klinik'] = $item_parameter_subsatuan_by_baku_mutu->unit->name_unit ?? null;
                    } else {
                      $item_permohonan_parameter_subsatuan['satuan_permohonan_uji_sub_parameter_klinik'] = null;

                      $item_permohonan_parameter_subsatuan['nama_satuan_permohonan_uji_sub_parameter_klinik'] = null;
                    }

                    // cek dulu punya satuan di subparameter atau tidak
                    // jika tidak ada maka ambil ke baku mutu
                    // else null
                    /* if ($value_subsatuan->satuan_permohonan_uji_sub_parameter_klinik != null) {
                    $item_permohonan_parameter_subsatuan['satuan_permohonan_uji_sub_parameter_klinik'] = $value_subsatuan->satuan_permohonan_uji_sub_parameter_klinik;
                    } else if (isset($item_parameter_subsatuan_by_baku_mutu->unit_id_baku_mutu_detail_parameter_klinik)) {
                    $item_permohonan_parameter_subsatuan['satuan_permohonan_uji_sub_parameter_klinik'] = $item_parameter_subsatuan_by_baku_mutu->unit_id_baku_mutu_detail_parameter_klinik;
                    } else {
                    $item_permohonan_parameter_subsatuan['satuan_permohonan_uji_sub_parameter_klinik'] = null;
                    }

                    $item_permohonan_parameter_subsatuan['min_baku_mutu_detail_parameter_klinik'] = $item_parameter_subsatuan_by_baku_mutu->min_baku_mutu_detail_parameter_klinik;
                    $item_permohonan_parameter_subsatuan['max_baku_mutu_detail_parameter_klinik'] = $item_parameter_subsatuan_by_baku_mutu->max_baku_mutu_detail_parameter_klinik;
                    $item_permohonan_parameter_subsatuan['equal_baku_mutu_detail_parameter_klinik'] = $item_parameter_subsatuan_by_baku_mutu->equal_baku_mutu_detail_parameter_klinik;
                    $item_permohonan_parameter_subsatuan['nilai_baku_mutu_detail_parameter_klinik'] = $item_parameter_subsatuan_by_baku_mutu->nilai_baku_mutu_detail_parameter_klinik; */
                    $item_permohonan_parameter_satuan['data_permohonan_uji_subsatuan_klinik'][] = $item_permohonan_parameter_subsatuan;
                  }
                }

                array_push($parameter_jenis_klinik['item_permohonan_parameter_satuan'], $item_permohonan_parameter_satuan);
                // get data baku mutu untuk menyiapkan data nilai rujukan jika ada dimasukkan jika tidak maka akan dilewati
                // melewati data kondisi pasien berupa umur dan gender dahulu ya kawaaaaan
              }
            }

            //ururutkan berdasarkan urutan global halaman reorder (bukan sort mentah duplikat master)
            usort($parameter_jenis_klinik['item_permohonan_parameter_satuan'], function ($a, $b) use ($sortMapById, $sortMapByName) {
              return $this->comparePrintSatuanSortItems($a, $b, $sortMapById, $sortMapByName);
            });

            array_push($arr_permohonan_parameter, $parameter_jenis_klinik);
            // // Debug hasil array setelah diurutkan
          }

          // Urutan global mengikuti halaman elits-parameter-satuan-klinik/reorder
          $arr_permohonan_parameter = $this->finalizeArrPermohonanParameterSort($arr_permohonan_parameter);

        }

        // ===== OVERRIDE DENGAN DATA SEMENTARA DARI SESSION (mode=preview) =====
        // Harus dilakukan SEBELUM filter empty groups, agar grup yang belum punya hasil di DB
        // tetap muncul dengan nilai sementara dari form.
        if ($isPreviewMode) {
          if (session()->has('preview_temp_catatan_hasil_' . $id_permohonan_uji_klinik)) {
            $item_permohonan_uji_klinik->catatan_hasil = session('preview_temp_catatan_hasil_' . $id_permohonan_uji_klinik);
          }
          if (session()->has('preview_temp_kesimpulan_hasil_' . $id_permohonan_uji_klinik)) {
            $item_permohonan_uji_klinik->kesimpulan_hasil = session('preview_temp_kesimpulan_hasil_' . $id_permohonan_uji_klinik);
          }
          if (session()->has('preview_temp_keterangan_metode_' . $id_permohonan_uji_klinik)) {
            $item_permohonan_uji_klinik->keterangan_metode = session('preview_temp_keterangan_metode_' . $id_permohonan_uji_klinik);
          }

          $tempHasil    = session('preview_temp_hasil_' . $id_permohonan_uji_klinik, []);
          $tempSubHasil = session('preview_temp_sub_hasil_' . $id_permohonan_uji_klinik, []);
          $tempMethod   = session('preview_temp_method_' . $id_permohonan_uji_klinik, []);
          $tempOffsetParam = session('preview_temp_offset_param_' . $id_permohonan_uji_klinik, []);
          $tempOffsetSub   = session('preview_temp_offset_sub_' . $id_permohonan_uji_klinik, []);

          if (!empty($tempHasil) || !empty($tempSubHasil) || !empty($tempMethod) || !empty($tempOffsetParam) || !empty($tempOffsetSub)) {
            foreach ($arr_permohonan_parameter as &$group) {
              if (!isset($group['item_permohonan_parameter_satuan'])) continue;
              foreach ($group['item_permohonan_parameter_satuan'] as &$param) {
                $paramId = $param['id_permohonan_uji_parameter_klinik'] ?? null;

                // Override nilai hasil utama jika ada di session
                if ($paramId && isset($tempHasil[$paramId])) {
                  $param['hasil_permohonan_uji_parameter_klinik'] = $tempHasil[$paramId];
                }

                // Override offset baku mutu parameter utama
                if ($paramId && isset($tempOffsetParam[$paramId])) {
                  $param['offset_baku_mutu'] = $tempOffsetParam[$paramId];
                }

                // Override metode jika ada di session
                if ($paramId && isset($tempMethod[$paramId])) {
                  $param['method_permohonan_uji_parameter_klinik'] = $tempMethod[$paramId];
                }

                // Override nilai sub-parameter
                if (isset($param['data_permohonan_uji_subsatuan_klinik']) && is_array($param['data_permohonan_uji_subsatuan_klinik'])) {
                  foreach ($param['data_permohonan_uji_subsatuan_klinik'] as &$sub) {
                    $subId = $sub['id_permohonan_uji_sub_parameter_klinik'] ?? null;
                    if ($subId && isset($tempSubHasil[$subId])) {
                      $sub['hasil_permohonan_uji_sub_parameter_klinik'] = $tempSubHasil[$subId];
                    }
                    if ($subId && isset($tempOffsetSub[$subId])) {
                      $sub['offset_baku_mutu'] = $tempOffsetSub[$subId];
                    }
                  }
                  unset($sub);
                }
              }
              unset($param);
            }
            unset($group);
          }
        }

        // Tampilkan semua grup yang punya parameter (hasil kosong tetap dicetak sebagai baris kosong)
        $arr_permohonan_parameter = array_filter($arr_permohonan_parameter, function ($group) {
          return !empty($group['item_permohonan_parameter_satuan'])
            && is_array($group['item_permohonan_parameter_satuan']);
        });
        
        // Re-index array after filtering
        $arr_permohonan_parameter = array_values($arr_permohonan_parameter);

        // ===== DETEKSI & PEMISAHAN PARAMETER NARKOBA =====
        // Pisahkan grup narkoba dari arr_permohonan_parameter berdasarkan nama group
        $mapping_patterns_narkoba = [
            'methamphetamine' => 'Methamphetamine/MET',
          'met'             => 'Methamphetamine/MET',
          'cocaine'         => 'Cocaine',
          'cannabinoids'    => 'Cannabinoids/Marijuana/THC',
          'marijuana'       => 'Cannabinoids/Marijuana/THC',
          'thc'             => 'Cannabinoids/Marijuana/THC',
          'morphine'        => 'Morphine/MOP',
          'mop'             => 'Morphine/MOP',
          'amphetamine'     => 'Amphetamine/AMP',
          'amp'             => 'Amphetamine/AMP',
            'benzodiazepines' => 'Benzodiazepines/BZO',
          'bzo'             => 'Benzodiazepines/BZO',
          ];

        $dataNarkoba         = [];
        $mapping_narkoba     = [];
        $has_narkoba         = false;
        $has_non_narkoba     = false;
        $arr_parameter_umum  = []; // arr_permohonan_parameter tanpa grup narkoba

          foreach ($arr_permohonan_parameter as $group) {
          $group_name_lower = strtolower($group['name_parameter_jenis_klinik'] ?? '');
          $is_narkoba_group  = strpos($group_name_lower, 'narkoba') !== false
            || strpos($group_name_lower, 'narkotika') !== false;

          if ($is_narkoba_group) {
            $has_narkoba = true;
            // Kumpulkan data parameter narkoba (hasil utama dan/atau per sub-parameter)
            foreach ($group['item_permohonan_parameter_satuan'] ?? [] as $param) {
              $nama_param_utama = $param['nama_parameter_satuan_klinik'] ?? '';
              $hasil_utama      = $param['hasil_permohonan_uji_parameter_klinik'] ?? null;
              $rows_narkoba     = [];

              if ($hasil_utama !== null && $hasil_utama !== '' && $hasil_utama !== '-') {
                $rows_narkoba[] = [
                  'nama'  => $nama_param_utama,
                  'hasil' => $hasil_utama,
                ];
              } else {
                $subs = $param['data_permohonan_uji_subsatuan_klinik'] ?? [];
                if (isset($subs['id_permohonan_uji_sub_parameter_klinik'])) {
                  $subs = [$subs];
                }
                foreach (is_array($subs) ? $subs : [] as $sub) {
                  if (!is_array($sub)) {
                    continue;
                  }
                  $hSub = $sub['hasil_permohonan_uji_sub_parameter_klinik'] ?? null;
                  if ($hSub === null || $hSub === '' || $hSub === '-') {
                    continue;
                  }
                  $namaSub = $sub['nama_parameter_sub_satuan_klinik_id'] ?? '';
                  if ($namaSub === '') {
                    continue;
                  }
                  $rows_narkoba[] = ['nama' => $namaSub, 'hasil' => $hSub];
                }
              }

              foreach ($rows_narkoba as $rowN) {
                $nama_param  = $rowN['nama'];
                $hasil       = $rowN['hasil'];
                $nama_lower  = strtolower($nama_param);
                $mapped_name = $nama_param;
                foreach ($mapping_patterns_narkoba as $pattern => $mapped) {
                  if (strpos($nama_lower, $pattern) !== false) {
                    $mapped_name = $mapped;
                    break;
                  }
                }
                $mapping_narkoba[$nama_param] = $mapped_name;
                $dataNarkoba[]                = [
                  'nama_parameter_satuan_klinik'          => $nama_param,
                  'hasil_permohonan_uji_parameter_klinik' => $hasil,
                ];
              }
            }
          } else {
            $has_non_narkoba = true;
            $arr_parameter_umum[] = $group;
          }
        }

        // Jika ada grup narkoba, hapus dari tampilan utama
        if ($has_narkoba) {
          $arr_permohonan_parameter = $arr_parameter_umum;
        }

        // Hitung apakah murni hanya tes narkoba
        $is_only_narkoba = $has_narkoba && !$has_non_narkoba;

        // Format tanggal & jam khusus untuk halaman narkoba
        $tanggal_pemeriksaan_narkoba = '';
        $jam_pemeriksaan_narkoba     = '';
        if ($has_narkoba && isset($tanggal_pemeriksaan_sample_start) && $tanggal_pemeriksaan_sample_start) {
            try {
            $tanggal_pemeriksaan_narkoba = \Carbon\Carbon::parse($tanggal_pemeriksaan_sample_start)->isoFormat('D MMMM Y');
            $jam_pemeriksaan_narkoba     = \Carbon\Carbon::parse($tanggal_pemeriksaan_sample_start)->format('H:i');
            } catch (\Exception $e) {
            $tanggal_pemeriksaan_narkoba = '';
            $jam_pemeriksaan_narkoba     = '';
            }
          }

        // Jika HANYA tes Narkoba (tidak ada parameter umum), gunakan view khusus narkoba
        if ($is_only_narkoba) {
          // Generate QR Code
          $url = config("app.url");
          if (config("app.env") == "local") {
            $url .= ":8000";
          }
          $url .= "/elits-signature/progress/" . $id_permohonan_uji_klinik . "/1";

          $result = Builder::create()
            ->data($url)
            ->encoding(new Encoding('UTF-8'))
            ->errorCorrectionLevel(new ErrorCorrectionLevelHigh())
            ->size(600)
            ->margin(2)
            ->build();
          $qrBase64 = base64_encode($result->getString());

          $narkobaViewData = array_merge([
              'item_permohonan_uji_klinik'  => $item_permohonan_uji_klinik,
              'no_LHU'                      => $no_LHU,
              'dataNarkoba'                 => $dataNarkoba,
              'mapping'                     => $mapping_narkoba,
              'tanggal_pemeriksaan_sample'  => $tanggal_pemeriksaan_narkoba,
              'jam_pemeriksaan_sample'      => $jam_pemeriksaan_narkoba,
              'nama_petugas_pemeriksa'      => $nama_petugas_pemeriksa,
              'nama_petugas_verifikator'    => $nama_petugas_verifikator,
              'signOption'                  => 0,
          ], $this->buildHasilPrintViewSettings($item_permohonan_uji_klinik, $forceKop));

          // Mode preview: return PDF inline (izinkan embed dalam iframe)
          if ($isPreviewMode) {
              $pdf = PDF::loadView('masterweb::module.admin.laboratorium.permohonan-uji-klinik-2.formatPrint.hasil-klinik-narkoba', $narkobaViewData);
              return $this->streamHasilKlinikPdf($pdf, 'preview-narkoba.pdf', [
                'X-Frame-Options' => 'SAMEORIGIN',
                'Content-Security-Policy' => "frame-ancestors 'self'",
              ]);
          }

          if (!$signoption) {
            $pdf = PDF::loadView('masterweb::module.admin.laboratorium.permohonan-uji-klinik-2.formatPrint.hasil-klinik-narkoba', $narkobaViewData);
            return $this->streamHasilKlinikPdf($pdf);
          }

          $pdf = PDF::loadView('masterweb::module.admin.laboratorium.permohonan-uji-klinik-2.formatPrint.hasil-klinik-narkoba', [
            'item_permohonan_uji_klinik'  => $item_permohonan_uji_klinik,
            'no_LHU'                      => $no_LHU,
