          //   // permintaan kedua
          //   $no_LHU->nomer_LHU = '449.5/&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;5.22/' . $romawi_bulan . '/' . Carbon::now()->format('Y');

          //   $no_LHU->permohonan_uji_klinik_id = $id_permohonan_uji_klinik;
