          //   $get_pisah2_lhu = $explode_nomor_lhu[2];
          //   $get_pisah3_lhu = $explode_nomor_lhu[3];

          //   $no_LHU = $get_pisah0_lhu . '/&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;5.22/' . $get_pisah2_lhu . '/' . $get_pisah3_lhu;
          // }

          $url = config("app.url");

          if (config("app.env") == "local"){
            $url .= ":8000";
          }

          $url .= "/elits-signature/progress/".$id_permohonan_uji_klinik."/1";

          $result = Builder::create()
            ->data($url)
            ->encoding(new Encoding('UTF-8'))
            ->errorCorrectionLevel(new ErrorCorrectionLevelHigh())
            ->size(600)
            // ->logoPath( public_path('assets/admin/images/logo/silaboy_mini_bg_white.png'))
            // ->logoResizeToWidth(200)
            // ->logoPunchoutBackground(true)
            ->margin(2)

            ->build();
          $qrBase64 = base64_encode($result->getString());


          // Siapkan data view yang dipakai baik oleh preview HTML maupun PDF
          $viewData = array_merge([
              'item_permohonan_uji_klinik'           => $item_permohonan_uji_klinik,
              'data_permohonan_uji_parameter_klinik' => $data_permohonan_uji_parameter_klinik,
              'tgl_pengujian'                        => $tgl_pengujian,
              'tgl_spesimen_darah'                   => $tgl_spesimen_darah,
              'tgl_spesimen_urine'                   => $tgl_spesimen_urine,
              'data_parameter_satuan'                => $data_parameter_satuan,
              'arr_permohonan_parameter'             => $arr_permohonan_parameter,
              'no_LHU'                               => $no_LHU,
              'signOption'                           => 0,
              'nama_petugas_pengambil_sample'        => $nama_petugas_pengambil_sample,
              'tanggal_pengambilan_sample'           => $tanggal_pengambilan_sample,
              'nama_petugas_pemeriksa'               => $nama_petugas_pemeriksa,
              'tanggal_pemeriksaan_sample'           => $tanggal_pemeriksaan_sample,
              'nama_petugas_verifikator'             => $nama_petugas_verifikator,
              // Data narkoba untuk halaman kedua (jika ada tes narkoba bercampur)
              'dataNarkoba'                          => $dataNarkoba,
              'mapping_narkoba'                      => $mapping_narkoba,
              'tanggal_pemeriksaan_narkoba'          => $tanggal_pemeriksaan_narkoba,
              'jam_pemeriksaan_narkoba'              => $jam_pemeriksaan_narkoba,
          ], $this->buildHasilPrintViewSettings($item_permohonan_uji_klinik, $forceKop));

          // Jika mode=preview, return PDF inline (izinkan embed dalam iframe)
          if ($isPreviewMode) {
              $pdf = PDF::loadView('masterweb::module.admin.laboratorium.permohonan-uji-klinik-2.formatPrint.hasil-klinik', $viewData);
              return $this->streamHasilKlinikPdf($pdf, 'preview-hasil.pdf', [
                'X-Frame-Options' => 'SAMEORIGIN',
                'Content-Security-Policy' => "frame-ancestors 'self'",
              ]);
          }

          if (!$signoption){
            $pdf = PDF::loadView('masterweb::module.admin.laboratorium.permohonan-uji-klinik-2.formatPrint.hasil-klinik', $viewData);

            return $this->streamHasilKlinikPdf($pdf);
          }


          // BSRE DISABLED TEMPORARILY - Langsung return PDF tanpa tanda tangan elektronik
