  public function label(Request $request)
  {
    if (request()->ajax()) {
      $query = PermohonanUjiKlinik2::query()
        ->with('pasien')
        ->whereNull('deleted_at')
        ->orderBy('tglregister_permohonan_uji_klinik', 'desc')
        ->orderBy('nourut_permohonan_uji_klinik', 'desc');

      return Datatables::of($query)
        ->filter(function ($instance) use ($request) {
          $keyword = $request->input('search.value');
          if (empty($keyword) && is_string($request->get('search'))) {
            $keyword = $request->get('search');
          }

          if (empty($keyword)) {
            return;
          }

          $instance->whereHas('pasien', function ($pasienQuery) use ($keyword) {
            $pasienQuery->where('nama_pasien', 'like', '%' . $keyword . '%')
              ->orWhere('no_rekammedis_pasien', 'like', '%' . $keyword . '%')
              ->orWhere('tgllahir_pasien', 'like', '%' . $keyword . '%');
          });
        })
        ->addColumn('set_checkbox', function ($data) {
          return '<input type="checkbox" class="form-control checkbox-label" name="checkbox_label[' . $data->id_permohonan_uji_klinik . ']" value="' . $data->id_permohonan_uji_klinik . '">';
        })
        ->addColumn('nama_pasien', function ($data) {
          $nama = optional($data->pasien)->nama_pasien ?: '-';

          return '<div class="text-center">' . e($nama) . '</div>';
        })
        ->addColumn('no_rekammedis_pasien', function ($data) {
          $noRm = optional($data->pasien)->no_rekammedis_pasien ?: '-';

          return '<div class="text-center">' . e($noRm) . '</div>';
        })
        ->addColumn('tgllahir_pasien', function ($data) {
          $tgllahir = optional($data->pasien)->tgllahir_pasien;
          $formatted = '-';

          if (!empty($tgllahir)) {
            try {
              $formatted = Carbon::createFromFormat('Y-m-d', $tgllahir)->isoFormat('D MMMM YYYY');
            } catch (\Exception $e) {
              try {
                $formatted = Carbon::parse($tgllahir)->isoFormat('D MMMM YYYY');
              } catch (\Exception $e2) {
                $formatted = $tgllahir;
              }
            }
          }

          return '<div class="text-center">' . e($formatted) . '</div>';
        })
        ->addColumn('tgl_pemeriksaan', function ($data) {
          $formatted = '-';

          if (!empty($data->created_at)) {
            try {
              $formatted = Carbon::parse($data->created_at)->format('d-m-Y, H:i:s');
            } catch (\Exception $e) {
              $formatted = (string) $data->created_at;
            }
          }

          return '<div class="text-center">' . e($formatted) . '</div>';
        })
        ->rawColumns(['set_checkbox', 'nama_pasien', 'no_rekammedis_pasien', 'tgllahir_pasien', 'tgl_pemeriksaan'])
        ->addIndexColumn()
        ->make(true);
    }

    return view('masterweb::module.admin.laboratorium.permohonan-uji-klinik-2.label.index');
  }

  public function printLabel(Request $request)
  {
    // dd($request->all());
    $id_permohonan_uji_klinik_string = $request->permohonan_uji_klinik;
    $id_permohonan_uji_klinik_arr = explode(",", $id_permohonan_uji_klinik_string);


    $i = 0;
    foreach ($id_permohonan_uji_klinik_arr as $id_permohonan_uji_klinik) {
      $get_data[$i] = PermohonanUjiKlinik2::where('id_permohonan_uji_klinik', $id_permohonan_uji_klinik)->first();
      $i++;
    }

    // dd($get_data);
    // Array baru untuk menyimpan label (1 label per jenis sampel)
    $label_data = [];
    
    if (count($get_data) > 0) {
      for ($i = 0; $i < count($get_data); $i++) {
        // Format tanggal lahir pasien (tetap dipakai di beberapa view)
        $original_tgllahir = $get_data[$i]->pasien->tgllahir_pasien;
        if (!empty($original_tgllahir)) {
          try {
            $formatted_tgllahir = Carbon::createFromFormat("Y-m-d", $original_tgllahir)->format("d-m-Y");
          } catch (\Exception $e) {
            $formatted_tgllahir = $original_tgllahir;
          }
        } else {
          $formatted_tgllahir = $original_tgllahir;
        }

        // Nama & alamat ditampilkan utuh; penyesuaian ukuran font dilakukan di view (JS)
        $shortened_name = $get_data[$i]->pasien->nama_pasien;
        $shortened_address = $get_data[$i]->pasien->alamat_pasien;

        // ====== Tambahan data khusus untuk label barcode ======

        // 1) Kode barcode tabung: {DDMM lahir}{nomor spesimen 5}{kode jenis 1} → 2602039022 (Serum)
        $baseLabelCode = TmsKlinikHelper::labelRegisterCode($get_data[$i]);

        // 2) Singkatan gender pasien (L/P) untuk ditampilkan di samping nama
        $gender_abbr = $get_data[$i]->pasien->gender_pasien ?? null;

        // 3) Jenis sampel — logic sama dengan data-formulir:
        //    prioritas PengambilanSampleKlinik status Berhasil, fallback Smt::getJenisSampelFromParameter
        $pengambilanSampleLabel = PengambilanSampleKlinik::where('permohonan_uji_klinik_id', $get_data[$i]->id_permohonan_uji_klinik)
          ->where('status_sampling', 'Berhasil')
          ->first();

        $jenis_sample_array = [];
        if (isset($pengambilanSampleLabel->jenis_sample)) {
          $decoded = json_decode($pengambilanSampleLabel->jenis_sample, true);
          $jenis_sample_array = is_array($decoded) ? $decoded : [$pengambilanSampleLabel->jenis_sample];
        } else {
          $fromParam = Smt::getJenisSampelFromParameter($get_data[$i]->id_permohonan_uji_klinik);
          $jenis_sample_array = !empty($fromParam) ? (is_array($fromParam) ? $fromParam : [$fromParam]) : [];
        }

        if (empty($jenis_sample_array)) {
          $jenis_sample_array = [null];
        }

        // Normalisasi jenis (Plasma vs Plasma NaF punya digit barcode berbeda: 3 vs 8)
        $normalizedSamples = [];
        foreach ($jenis_sample_array as $js) {
          if ($js === null || $js === '') {
            if (!in_array(null, $normalizedSamples, true)) {
              $normalizedSamples[] = null;
            }
            continue;
          }
          $canon = TmsKlinikHelper::normalizeSpecimenType((string) $js);
          if ($canon === 'Lainnya') {
            $canon = trim((string) $js);
          }
          if ($canon !== '' && !in_array($canon, $normalizedSamples, true)) {
            $normalizedSamples[] = $canon;
          }
        }
        if (!empty($normalizedSamples)) {
          $jenis_sample_array = $normalizedSamples;
        }

        // 4) Kumpulkan parameter per jenis_sampel
        //    - Paket: tampilkan nama paket, dikelompokkan ke jenis_sampel paket tersebut
        //    - Non-paket: tampilkan nama parameter satuan, dikelompokkan ke jenis_sampel-nya
        $data_permohonan_uji_paket_klinik = \Smt\Masterweb\Models\PermohonanUjiPaketKlinik::where('permohonan_uji_klinik', $get_data[$i]->id_permohonan_uji_klinik)
          ->with(['parameterpaketklinik', 'parameterjenisklinik'])
          ->whereNull('deleted_at')
          ->get();

        // labelParametersByJenis[jenis_sampel] = [nama parameter/paket]
        // '__other__' = parameter tanpa jenis_sampel (masuk semua label)
        $labelParametersByJenis = [];
        $isHajiLabel = (int) ($get_data[$i]->is_haji ?? 0) === 1;

        foreach ($data_permohonan_uji_paket_klinik as $paket) {
          $data_parameters = \Smt\Masterweb\Models\PermohonanUjiParameterKlinik::where('permohonan_uji_klinik', $get_data[$i]->id_permohonan_uji_klinik)
            ->where('permohonan_uji_paket_klinik', $paket->id_permohonan_uji_paket_klinik)
            ->with(['parametersatuanklinik'])
            ->whereNull('deleted_at')
            ->get();

          $packageName = $paket->parameterpaketklinik->name_parameter_paket_klinik ?? '-';
          $isPaket = ($paket->type_permohonan_uji_paket_klinik ?? '') === 'P';

          if ($isPaket && $packageName !== '-') {
            $labelName = $packageName;
            $jenisAdded = false;
            foreach ($data_parameters as $param) {
              $rawJenis = \Smt\Masterweb\Helpers\Smt::pickJenisSampelRawForContext(
                $param->parametersatuanklinik,
                $isHajiLabel
              );
              if (empty($rawJenis)) {
                continue;
              }
              $arr = is_array($rawJenis) ? $rawJenis : (json_decode($rawJenis, true) ?? [$rawJenis]);
              foreach ($arr as $j) {
                $j = trim((string) $j);
                if ($j === '') {
                  continue;
                }
                $jenisAdded = true;
                if (!isset($labelParametersByJenis[$j])) {
                  $labelParametersByJenis[$j] = [];
                }
                if (!in_array($labelName, $labelParametersByJenis[$j])) {
                  $labelParametersByJenis[$j][] = $labelName;
                }
              }
            }
            if (!$jenisAdded) {
              if (!isset($labelParametersByJenis['__other__'])) {
                $labelParametersByJenis['__other__'] = [];
              }
              if (!in_array($labelName, $labelParametersByJenis['__other__'])) {
                $labelParametersByJenis['__other__'][] = $labelName;
              }
            }
          } else {
            foreach ($data_parameters as $param) {
              $paramName = $param->parametersatuanklinik->name_parameter_satuan_klinik ?? null;
              if (!$paramName) {
                continue;
              }

              $rawJenis = \Smt\Masterweb\Helpers\Smt::pickJenisSampelRawForContext(
                $param->parametersatuanklinik,
                $isHajiLabel
              );
              if (!empty($rawJenis)) {
                $arr = is_array($rawJenis) ? $rawJenis : (json_decode($rawJenis, true) ?? [$rawJenis]);
                $hasJenis = false;
                foreach ($arr as $j) {
                  $j = trim((string) $j);
                  if ($j !== '') {
                    $hasJenis = true;
                    if (!isset($labelParametersByJenis[$j])) {
                      $labelParametersByJenis[$j] = [];
                    }
                    if (!in_array($paramName, $labelParametersByJenis[$j])) {
                      $labelParametersByJenis[$j][] = $paramName;
                    }
                  }
                }
                if (!$hasJenis) {
                  if (!isset($labelParametersByJenis['__other__'])) {
                    $labelParametersByJenis['__other__'] = [];
                  }
                  if (!in_array($paramName, $labelParametersByJenis['__other__'])) {
                    $labelParametersByJenis['__other__'][] = $paramName;
                  }
                }
              } else {
                if (!isset($labelParametersByJenis['__other__'])) {
                  $labelParametersByJenis['__other__'] = [];
                }
                if (!in_array($paramName, $labelParametersByJenis['__other__'])) {
                  $labelParametersByJenis['__other__'][] = $paramName;
                }
              }
            }
          }
        }

        // Buat 1 label untuk setiap jenis sampel
        foreach ($jenis_sample_array as $jenis_sample_single) {
          // Parameter untuk label ini = parameter milik jenis_sampel ini + bucket __other__
          $paramsForLabel = array_merge(
            $labelParametersByJenis[$jenis_sample_single] ?? [],
            $labelParametersByJenis['__other__'] ?? []
          );
          // Cocokkan juga key asli sebelum normalisasi (master data bisa beda kapitalisasi)
          if ($jenis_sample_single !== null && $jenis_sample_single !== '') {
            foreach ($labelParametersByJenis as $jenisKey => $vals) {
              if ($jenisKey === '__other__' || $jenisKey === $jenis_sample_single) {
                continue;
              }
              if (TmsKlinikHelper::normalizeSpecimenType((string) $jenisKey) === (string) $jenis_sample_single) {
                $paramsForLabel = array_merge($paramsForLabel, $vals);
              }
            }
          }
          // Jika tidak ada sama sekali, tampilkan semua parameter
          if (empty($paramsForLabel)) {
            foreach ($labelParametersByJenis as $key => $vals) {
              if ($key !== '__other__') {
                $paramsForLabel = array_merge($paramsForLabel, $vals);
              }
            }
          }
          $label_parameters_string = implode(', ', array_unique($paramsForLabel));

          // Clone object untuk setiap jenis sampel
          $label_item = clone $get_data[$i];

          // Set data yang sudah diproses
          $label_item->pasien->tgllahir_pasien = $formatted_tgllahir;
          $label_item->pasien->nama_pasien = $shortened_name;
          $label_item->pasien->alamat_pasien = $shortened_address;
          $label_item->label_register_code = TmsKlinikHelper::barcodeForSpesimen(
            $baseLabelCode,
            (string) ($jenis_sample_single ?? ''),
            true
          );
          $label_item->pasien->label_gender_abbr = $gender_abbr;
          $label_item->label_sample_type = $jenis_sample_single;
          $label_item->label_parameters = $label_parameters_string;

          $label_data[] = $label_item;
      }
    }
    }
    
    // Ganti $get_data dengan $label_data yang sudah dipecah per jenis sampel
    $get_data = $label_data;

    return view('masterweb::module.admin.laboratorium.permohonan-uji-klinik-2.label.print-label', compact('get_data'));

    // $pdf = PDF::loadView('masterweb::module.admin.laboratorium.permohonan-uji-klinik-2.label.print-label', compact('get_data'));
    // return $pdf->stream();
  }




  //test coba
  /**
   * Resolve id_parameter_jenis_klinik dari id paket.
   * Form jenis_parameters[] memakai id_parameter_paket_klinik sebagai key, bukan id jenis.
   */
  private function resolveParameterJenisKlinikIdForPaket($packetId, $formKey = null)
  {
    if (!empty($formKey) && ParameterJenisKlinik::where('id_parameter_jenis_klinik', $formKey)->exists()) {
      return $formKey;
    }

    $bridge = ParameterPaketJenisKlinik::where('parameter_paket_klinik_id', $packetId)
      ->orderBy('sort')
      ->first();

    return $bridge ? $bridge->parameter_jenis_klinik_id : null;
  }

  public function storeParameter(Request $request)
  {
    // Inisialisasi total harga
    $total_harga = 0;

    // Mulai DB transaction
    DB::beginTransaction();

    try {

      // Sync paket: hapus yang tidak ada di request agar tidak terduplikasi saat edit
      $requested_packet_ids = [];
      if (isset($request->jenis_parameters)) {
        foreach ($request->jenis_parameters as $value) {
          if (isset($value["pakets"]) && is_array($value["pakets"])) {
            foreach ($value["pakets"] as $packectParameter) {
              $array_packet = explode("_", $packectParameter);
              if (count($array_packet) >= 1) {
                $requested_packet_ids[] = (string) $array_packet[0];
              }
            }
          }
        }
      }

      $existing_pakets_db = PermohonanUjiPaketKlinik::where('permohonan_uji_klinik', $request->post('permohonan_uji_klinik'))
        ->get();

      $paket_ids_to_delete = [];
      foreach ($existing_pakets_db as $paket) {
        $db_packet_id = (string) $paket->parameter_paket_klinik;
