      //         // Tambahkan harga ke total harga dan total harga jenis
      //         $total_harga += $harga_parameter_paket;
      //         $total_harga_jenis += $harga_parameter_paket;

      //         // Simpan data ke model PermohonanUjiParameterKlinik2
      //         $data_paket = [
      //             'id_permohonan_uji_klinik' => $request->permohonan_uji_klinik,
      //             'id_jenis_parameter_klinik' => $jenis_parameter_id,
      //             'id_permohonan_uji_paket_klinik' => $new_paket_id,
      //             'id_parameter_paket_klinik' => $parameter_paket_id,
      //             'harga' => $harga_parameter_paket,
      //         ];

      //         PermohonanUjiParameterKlinik2::create($data_paket);
      //     }

      //     // Update total harga jenis di PermohonanUjiPaketKlinik2
      //     $permohonan_uji_paket->total_harga = $total_harga_jenis;
      //     $permohonan_uji_paket->save();
      // }

      // // Update total harga di PermohonanUjiKlinik2
      // $update_permohonan_uji_klinik = PermohonanUjiKlinik2::findOrFail($request->permohonan_uji_klinik);
      // $update_permohonan_uji_klinik->total_harga_permohonan_uji_klinik = $total_harga;
      // $update_permohonan_uji_klinik->status_permohonan_uji_klinik = 'ANALIS';
      // $update_permohonan_uji_klinik->save();

      // Create Specimen

      // dd($satu_sehat);

      // Commit transaction
      $item_permohonan_uji_klinik->save();
      DB::commit();

      $paymentResponse = [
        'status' => true,
        'pesan' => "Parameter permohonan uji klinik berhasil disimpan!",
        'show_payment' => false,
        'payment_data' => null,
      ];

      // Get permohonan data for payment modal
      $permohonan = PermohonanUjiKlinik2::with('pasien')->find($request->permohonan_uji_klinik);

      // Get biaya_pengambilan_sampel directly from database
      $biaya_pengambilan_sampel_raw = DB::table('tb_permohonan_uji_klinik_2')
        ->where('id_permohonan_uji_klinik', $request->permohonan_uji_klinik)
        ->value('biaya_pengambilan_sampel');

      $biaya_pengambilan_sampel = (int) ($biaya_pengambilan_sampel_raw ?? 0);

      // Calculate total akhir: harga parameter + biaya pengambilan sampel
      $total_harga_parameter = $permohonan->total_harga_permohonan_uji_klinik;
      $total_akhir = $total_harga_parameter + $biaya_pengambilan_sampel;

      // Sinkronkan pembayaran dengan total baru (setelah edit/tambah parameter).
      // Jika total turun, cap terbayar agar tidak melebihi total (hindari Dibayar > Total di nota).
      $paymentSync = KlinikPaymentHelper::syncWithTotal($permohonan->id_permohonan_uji_klinik, (int) $total_akhir);
      $sudah_dibayar = $paymentSync['sudah_dibayar'];
      $sisa_tagihan = $paymentSync['sisa_tagihan'];

      if ($sisa_tagihan > 0) {
        $permohonan->status_pembayaran = '0';
        $permohonan->save();
      } elseif ($sudah_dibayar > 0) {
        $permohonan->status_pembayaran = '1';
        $permohonan->save();
      }

      // Get nama petugas from VerificationActivitySample with id_verification_activity = 1
      $verification_activity = VerificationActivitySample::where('is_klinik', $permohonan->id_permohonan_uji_klinik)
        ->where('id_verification_activity', 1)
        ->first();
      
      $nama_petugas = $verification_activity ? ($verification_activity->nama_petugas ?? auth()->user()->name) : auth()->user()->name;
      $id_petugas = auth()->id(); // Keep using auth()->id() for nota_petugas

      $payment_data = [
        'id_permohonan_uji_klinik' => $permohonan->id_permohonan_uji_klinik,
        'nama_pasien' => $permohonan->pasien->nama_pasien ?? '-',
        'alamat_pasien' => $permohonan->pasien ? Smt::alamatLengkapPasien($permohonan->pasien) : '-',
        'total_harga_parameter' => $total_harga_parameter,
        'biaya_pengambilan_sampel' => $biaya_pengambilan_sampel,
        'total_harga' => $total_akhir,
        'total_harga_custom' => rupiah($total_akhir),
        'sudah_dibayar' => $sudah_dibayar,
        'sudah_dibayar_custom' => rupiah($sudah_dibayar),
        'sisa_tagihan' => $sisa_tagihan,
        'sisa_tagihan_custom' => rupiah($sisa_tagihan),
        'nota_petugas' => $id_petugas,
        'nota_namapetugas' => $nama_petugas,
      ];

      $paymentResponse['payment_data'] = $payment_data;
      $paymentResponse['show_payment'] = false;

      $permohonanId = $request->post('permohonan_uji_klinik');
      $permohonanModel = $item_permohonan_uji_klinik;
      $satusehatPackets = $packetsForSatuSehat;
      $satusehatName = $name_permohonan;
      register_shutdown_function(function () use ($permohonanModel, $permohonanId, $satusehatName, $satusehatPackets) {
        try {
          $this->syncSatuSehatAfterParameterStore(
            $permohonanModel,
            $permohonanId,
            $satusehatName,
            $satusehatPackets
          );
        } catch (\Throwable $satusehatError) {
          \Log::warning('SatuSehat sync skipped after parameter store: ' . $satusehatError->getMessage(), [
            'permohonan_uji_klinik' => $permohonanId,
          ]);
        }
      });

      return response()->json($paymentResponse, 200);
    } catch (\Throwable $e) {
      DB::rollBack();

      \Log::error('Error menyimpan parameter permohonan uji klinik: ' . $e->getMessage(), [
        'permohonan_uji_klinik' => $request->permohonan_uji_klinik,
        'jenis_parameters' => $request->jenis_parameters,
        'trace' => $e->getTraceAsString(),
      ]);

      return response()->json([
        'status' => false,
        'pesan' => 'System gagal menyimpan! ' . $e->getMessage(),
      ], 200);
    }
  }

  /**
   * Sinkronisasi SatuSehat setelah data parameter tersimpan.
   * Gagal di sini tidak membatalkan penyimpanan lokal.
   */
  private function syncSatuSehatAfterParameterStore($item_permohonan_uji_klinik, $permohonanUjiKlinikId, $namePermohonan, array $packetsForSatuSehat)
  {
    if (!$item_permohonan_uji_klinik || empty($item_permohonan_uji_klinik->pasien->id_pasien_satu_sehat)) {
      return;
    }

    if (config('services.satu_sehat.version') !== 'prd') {
      return;
    }

    $encounterId = $item_permohonan_uji_klinik->id_satu_sehat_encounter ?? null;
    $encounterDisplay = 'Permohonanan Pengujian ' . $namePermohonan;
    $practitionerId = null;
    $practitionerName = null;

    if (empty($encounterId)) {
      $pendaftaran = VerificationActivitySample::where('is_klinik', $permohonanUjiKlinikId)
        ->where('id_verification_activity', 1)
        ->first();

      $location_satusehat = SatuSehatLocation::where('name_satusehat_location', 'LIKE', '%Administrasi%')
        ->where('version_satusehat_location', 'prd')
        ->first();

      if ($pendaftaran) {
        $namaPetugas_normalized = str_replace(',', '', $pendaftaran->nama_petugas);
        $practitioner_satusehat = SatuSehatPractitioner::whereRaw("REPLACE(name_petugas, ',', '') LIKE ?", ['%' . $namaPetugas_normalized . '%'])->first();

        if (!$practitioner_satusehat) {
          $petugas = Petugas::where('nama', 'like', '%' . $namaPetugas_normalized . '%')->first();
          if ($petugas && !empty($petugas->code_satu_sehat_practitioner)) {
            $practitioner_satusehat = SatuSehatPractitioner::where('code_satu_sehat_practitioner', $petugas->code_satu_sehat_practitioner)->first();
          }
        }

        if ($practitioner_satusehat && isset($practitioner_satusehat->code_satu_sehat_practitioner)) {
          $practitionerId = $practitioner_satusehat->code_satu_sehat_practitioner;
          $practitionerName = $practitioner_satusehat->name_satu_sehat_practitioner ?? $pendaftaran->name_satu_sehat_practitioner;
        } else {
          $practitionerName = $pendaftaran->nama_petugas;
        }
      }

      if ($location_satusehat) {
        $data = [
          'resourceType' => 'Encounter',
          'status' => 'arrived',
          'subject' => [
            'reference' => 'Patient/' . $item_permohonan_uji_klinik->pasien->id_pasien_satu_sehat,
            'display' => $item_permohonan_uji_klinik->pasien->nama_pasien,
          ],
          'class' => [
            'system' => 'http://terminology.hl7.org/CodeSystem/v3-ActCode',
            'code' => 'PRENC',
            'display' => $encounterDisplay,
          ],
          'participant' => [[
            'type' => [[
              'coding' => [[
                'system' => 'http://terminology.hl7.org/CodeSystem/v3-ParticipationType',
                'code' => 'ADM',
                'display' => 'pendaftaran',
              ]],
            ]],
            'individual' => [
              'reference' => 'Practitioner/' . ($practitionerId ?? ''),
              'display' => $practitionerName ?? 'Administrator',
            ],
          ]],
          'period' => [
            'start' => Carbon::createFromFormat('Y-m-d H:i:s', $item_permohonan_uji_klinik->tglregister_permohonan_uji_klinik)->toIso8601String(),
          ],
          'location' => [[
            'location' => [
              'reference' => 'Location/' . $location_satusehat->kode_satusehat_location,
              'display' => $location_satusehat->name_satusehat_location,
            ],
          ]],
          'statusHistory' => [[
            'status' => 'arrived',
            'period' => [
              'start' => Carbon::createFromFormat('Y-m-d H:i:s', $item_permohonan_uji_klinik->tglregister_permohonan_uji_klinik)->toIso8601String(),
              'end' => Carbon::createFromFormat('Y-m-d H:i:s', $item_permohonan_uji_klinik->tglregister_permohonan_uji_klinik)->toIso8601String(),
            ],
          ]],
          'serviceProvider' => [
            'reference' => 'Organization/' . config('services.satu_sehat.org_id'),
          ],
          'identifier' => [[
            'system' => 'http://sys-ids.kemkes.go.id/encounter/' . config('services.satu_sehat.org_id'),
            'value' => $item_permohonan_uji_klinik->noregister_permohonan_uji_klinik,
          ]],
        ];

        $response = $this->satuSehatHelper->post('Encounter', $data);
        if (($response['status_code'] ?? null) == '201') {
          $encounterId = $response['body']['id'] ?? null;
          $item_permohonan_uji_klinik->id_satu_sehat_encounter = $encounterId;
          $item_permohonan_uji_klinik->encounter_json_satu_sehat = json_encode($response['body']);
          $item_permohonan_uji_klinik->save();
        } else {
          \Log::warning('Encounter creation failed after parameter store. Response: ' . json_encode($response));
        }
      }
    }

    if (empty($packetsForSatuSehat)) {
      return;
    }

    $occurrenceDate = Carbon::createFromFormat('Y-m-d H:i:s', $item_permohonan_uji_klinik->tglregister_permohonan_uji_klinik)->toIso8601String();

    foreach ($packetsForSatuSehat as $packet) {
      try {
        $this->createServiceRequest(
          $item_permohonan_uji_klinik->noregister_permohonan_uji_klinik,
          $item_permohonan_uji_klinik->pasien->id_pasien_satu_sehat,
          $encounterId,
          $encounterDisplay,
          $practitionerId,
          $practitionerName,
          $occurrenceDate,
          $packet['detail_packet'],
          $packet['packet_name'],
          $permohonanUjiKlinikId,
          $packet['parameter_paket_klinik_id']
        );
      } catch (\Throwable $e) {
        \Log::warning('ServiceRequest sync skipped for packet ' . $packet['parameter_paket_klinik_id'] . ': ' . $e->getMessage());
      }
    }
  }

  private function createServiceRequest($identifier, $patientId, $encounterId, $encounterDisplay, $practitionerId, $practitionerName, $date, $coding, $text, $permohonanUjiKlinikId, $parameterPaketKlinikId)
  {
      $data = [
        "resourceType" => "ServiceRequest",
        "identifier" => [
          [
            "system" => "http://sys-ids.kemkes.go.id/servicerequest/".config('services.satu_sehat.org_id'),
            "value" => $identifier,
          ],
        ],
        "status" => "active",
        "intent" => "original-order",
        "priority" => "routine",
        "category" => [
          [
            "coding" => [
              [
                "system" => "http://snomed.info/sct",
                "code" => "108252007",
                "display" => "Laboratory procedure",
              ],
            ],
          ],
        ],
        "code" => [
          "coding" => $coding,
          "text" => $text
        ],
        "subject" => ["reference" => "Patient/".$patientId],
        "occurrenceDateTime" => $date,
        "authoredOn" => $date,
      ];

      // Hanya tambahkan encounter jika encounterId tidak null
      if (!empty($encounterId)) {
        $data["encounter"] = [
          "reference" => "Encounter/".$encounterId,
          "display" => $encounterDisplay ?? "Permohonan Pengujian",
        ];
      }

      // Hanya tambahkan requester dan performer jika practitionerId tidak null
      if (!empty($practitionerId)) {
        $data["requester"] = [
          "reference" => "Practitioner/".$practitionerId,
          "display" => $practitionerName ?? "Practitioner",
        ];
        $data["performer"] = [
          ["reference" => "Practitioner/".$practitionerId, "display" => $practitionerName ?? "Practitioner"],
        ];
      }


      $response = $this->satuSehatHelper->post('ServiceRequest', $data);

      // dd($response);

      if ($response['status_code'] == '201'){
        $permohonanUjiPaketKlinik = PermohonanUjiPaketKlinik::query()->where('permohonan_uji_klinik', '=', $permohonanUjiKlinikId)->where('parameter_paket_klinik', '=', $parameterPaketKlinikId)->first();
        if (isset($permohonanUjiPaketKlinik)){
          $permohonanUjiPaketKlinik->id_service_request = $response['body']["id"];
          $permohonanUjiPaketKlinik->response_service_request = json_encode($response['body']);
          $permohonanUjiPaketKlinik->save();
        }

        return true;
      }else{
        // Log detailed error information
        $errorMessage = "Gagal membuat service request!";
        $errorDetails = [];
        
        if (isset($response['status_code'])) {
          $errorDetails['status_code'] = $response['status_code'];
        }
        
        if (isset($response['body'])) {
          if (is_array($response['body'])) {
            // Extract error message from SatuSehat response
            if (isset($response['body']['issue']) && is_array($response['body']['issue'])) {
              $issues = [];
              foreach ($response['body']['issue'] as $issue) {
                if (isset($issue['details']['text'])) {
                  $issues[] = $issue['details']['text'];
                } elseif (isset($issue['diagnostics'])) {
                  $issues[] = $issue['diagnostics'];
                }
              }
              if (!empty($issues)) {
                $errorMessage .= " Detail: " . implode('; ', $issues);
              }
            }
            $errorDetails['body'] = $response['body'];
          } else {
            $errorDetails['body'] = $response['body'];
          }
        }
        
        // Log error with context
        \Log::error('Error creating ServiceRequest', [
          'permohonan_uji_klinik_id' => $permohonanUjiKlinikId,
          'parameter_paket_klinik_id' => $parameterPaketKlinikId,
          'identifier' => $identifier,
          'patient_id' => $patientId,
          'encounter_id' => $encounterId,
          'practitioner_id' => $practitionerId,
          'response' => $errorDetails,
          'request_data' => $data
        ]);

        return false;
      }
  }

  /**
   * Create Specimen in SatuSehat
   * If creation fails with status "available", retry with status "unavailable"
   *
   * @param string $identifier Specimen identifier
   * @param array $specimens Array of specimen types
   * @param string $collectedDateTime ISO 8601 datetime string
   * @param string $patientId Patient ID in SatuSehat
   * @param string $patientName Patient name
   * @param array $idRequests Array of ServiceRequest references
   * @param string $receivedTime ISO 8601 datetime string for received time
   * @param string $initialStatus Initial status for Specimen ("available" or "unavailable"), default "available"
   * @return array Returns array with 'specimen_ids' and 'service_request_ids' (1:1 mapping)
   */
  private function createSpecimen($identifier, $specimens, $collectedDateTime, $patientId, $patientName, $idRequests, $receivedTime, $initialStatus = "available")
  {

    // Mapping jenis sample Indonesia ke SNOMED CT code
    $specimenCode = [
      "Darah Beku" => [
        "code" => "119294007",
        "display" => "Dried blood specimen"
      ],
      "NaF" => [
        "code" => "129501009",
        "display" => "NaF"
      ],
      "EDTA" => [
        "code" => "69519002",
        "display" => "EDTA"
      ],
      "Urine" => [
        "code" => "78014005",
        "display" => "Urine"
      ],
      "Darah" => [
        "code" => "119297000",
        "display" => "Blood specimen"
      ],
      "Serum" => [
        "code" => "119364003",
        "display" => "Serum specimen"
      ],
      "Plasma" => [
        "code" => "119361006",
        "display" => "Plasma specimen"
      ],
      "Feses" => [
        "code" => "119339001",
        "display" => "Stool specimen"
      ],
      "Swab" => [
        "code" => "258467004",
        "display" => "Swab specimen"
      ]
    ];



    // Normalize specimen names (case-insensitive matching)
    $normalizedSpecimens = [];
    foreach ($specimens as $specimen) {
      $specimenKey = null;
      $specimenTrimmed = trim($specimen);
      foreach (array_keys($specimenCode) as $key) {
        if (strcasecmp($specimenTrimmed, $key) === 0) {
          $specimenKey = $key;
          break;
        }
      }
      if ($specimenKey && !in_array($specimenKey, $normalizedSpecimens)) {
        $normalizedSpecimens[] = $specimenKey;
      } else if (!$specimenKey) {
        \Log::warning('Unknown specimen type: ' . $specimenTrimmed);
      }
    }


    if (empty($normalizedSpecimens)) {
      \Log::warning('No valid specimen codes found for specimens: ' . json_encode($specimens));
      return;
    }

    // Validate and filter idRequests - remove empty ServiceRequest references
    $validIdRequests = [];
    if (!empty($idRequests) && is_array($idRequests)) {
      foreach ($idRequests as $request) {
        if (isset($request['reference'])) {
          $serviceRequestId = str_replace('ServiceRequest/', '', $request['reference']);
          // Only add if ServiceRequest ID is not empty
          if (!empty($serviceRequestId)) {
            $validIdRequests[] = $request;
          }
        }
      }
    }

    // If no valid ServiceRequest IDs, cannot create Specimen (SatuSehat requires request field)
    if (empty($validIdRequests)) {
      \Log::warning('No valid ServiceRequest IDs found for Specimen creation - skipping Specimen creation', [
        'identifier' => $identifier,
        'idRequests' => $idRequests
      ]);
      return; // Cannot create Specimen without ServiceRequest (mandatory field)
    }

    $idSpecimenSatuSehat = [];
    $idServiceRequestSatuSehat = []; // Store ServiceRequest ID for each specimen
    $specimenIndex = 0;

    foreach ($normalizedSpecimens as $specimen){
      // Use one ServiceRequest ID per specimen (1:1 mapping)
      // If there are more specimens than ServiceRequests, use the last ServiceRequest for remaining specimens
      $serviceRequestForSpecimen = [];
      if (!empty($validIdRequests)) {
        $requestIndex = min($specimenIndex, count($validIdRequests) - 1);
        $serviceRequestForSpecimen = [$validIdRequests[$requestIndex]];
      }

      $data = [
        "resourceType" => "Specimen",
        "identifier" => [
          [
            "system" => "http://sys-ids.kemkes.go.id/specimen/".config("services.satu_sehat.org_id"),
            "value" => $identifier,
            "assigner" => [
              "reference" => "Organization/".config("services.satu_sehat.org_id")
            ]
          ]
        ],
        "status" => $initialStatus,
        "type" => [
          "coding" => [
            [
              "system" => "http://snomed.info/sct",
              "code" => $specimenCode[$specimen]["code"],
              "display" => $specimenCode[$specimen]["display"]
            ]
          ]
        ],
        "collection" => [
          "collectedDateTime" => $collectedDateTime,
          "extension" => [
            [
              "url" => "https://fhir.kemkes.go.id/r4/StructureDefinition/CollectorOrganization",
              "valueReference" => [
                "reference" => "Organization/".config("services.satu_sehat.org_id")
              ]
            ]
          ]
        ],
        "subject" => [
          "reference" => "Patient/".$patientId,
          "display" => $patientName
        ],
        "receivedTime" => $receivedTime,
        "request" => $serviceRequestForSpecimen  // One ServiceRequest per Specimen
      ];


      $response = $this->satuSehatHelper->post("Specimen", $data);

      if ($response['status_code'] == '201'){
        $specimenId = $response['body']["id"];
        $idSpecimenSatuSehat[] = $specimenId;

        // Store ServiceRequest ID for this specimen
        if (!empty($serviceRequestForSpecimen)) {
          $serviceRequestId = str_replace('ServiceRequest/', '', $serviceRequestForSpecimen[0]['reference']);
          $idServiceRequestSatuSehat[] = $serviceRequestId;
        }
      }else{
        // Jika gagal dengan status "available", coba lagi dengan status "unavailable"
        \Log::warning('Failed to create specimen with status "available", trying with "unavailable"', [
          'specimen' => $specimen,
          'response' => $response,
          'data' => $data
        ]);

        // Ubah status menjadi "unavailable" dan coba lagi
        $data['status'] = 'unavailable';

        // Pastikan status sudah diubah sebelum dikirim
        \Log::info('Retrying specimen creation with status "unavailable"', [
          'specimen' => $specimen,
          'data_status' => $data['status'],
          'data' => $data
        ]);

        $response = $this->satuSehatHelper->post("Specimen", $data);

        if ($response['status_code'] == '201'){
          $specimenId = $response['body']["id"];
          $idSpecimenSatuSehat[] = $specimenId;

          // Store ServiceRequest ID for this specimen
          if (!empty($serviceRequestForSpecimen)) {
            $serviceRequestId = str_replace('ServiceRequest/', '', $serviceRequestForSpecimen[0]['reference']);
            $idServiceRequestSatuSehat[] = $serviceRequestId;
          }

          \Log::info('Specimen created successfully with status "unavailable"', [
            'specimen' => $specimen,
            'specimen_id' => $specimenId
          ]);
        }else{
          \Log::error('Failed to create specimen in SatuSehat even with status "unavailable"', [
            'specimen' => $specimen,
            'response' => $response,
            'data' => $data
          ]);
          throw new Exception("Gagal membuat spesimen! Response: " . json_encode($response));
        }
      }

      $specimenIndex++; // Increment index for next specimen
    }

    // Tidak menyimpan ke PermohonanUjiKlinik2->id_spesimen lagi
    // Setiap PengambilanSampleKlinik akan menyimpan id_spesimen_satu_sehat sendiri
    // (untuk tracking, bisa tetap disimpan di PermohonanUjiKlinik2 jika diperlukan)

    // Return both specimen IDs and ServiceRequest IDs (1:1 mapping)
    return [
      'specimen_ids' => $idSpecimenSatuSehat,
      'service_request_ids' => $idServiceRequestSatuSehat
    ];
  }

  /**
   * Create Specimen and ServiceRequest for resampling in SatuSehat
   * Called when resampling is done (status_sampling = 'Berhasil' or 'Gagal' and resampling > 0)
   * For 'Gagal' status, Specimen will be created with status "unavailable"
   */
  private function createResamplingSpecimenAndServiceRequest($id_permohonan_uji_klinik, $pengambilan_sample_klinik, $request)
  {
    // Only send if VERSION_SATUSEHAT = prd
    if (config('services.satu_sehat.version') !== 'prd') {
      \Log::info('SatuSehat resampling integration skipped: VERSION_SATUSEHAT is not prd');
      return;
    }



    // Get permohonan uji klinik data
    $item_permohonan_uji_klinik = PermohonanUjiKlinik2::find($id_permohonan_uji_klinik);
    if (!$item_permohonan_uji_klinik) {
      \Log::warning('Permohonan uji klinik not found for resampling: ' . $id_permohonan_uji_klinik);
      return;
    }

    // Get patient data
    $pasien = Pasien::find($item_permohonan_uji_klinik->pasien_permohonan_uji_klinik);
    if (!$pasien || empty($pasien->id_pasien_satu_sehat)) {
      \Log::warning('Patient SatuSehat ID not found for resampling permohonan: ' . $id_permohonan_uji_klinik);
      return;
    }

    $patientId = $pasien->id_pasien_satu_sehat;
    $patientName = $pasien->nama_pasien ?? 'Unknown';

    // Parse jenis_sample (bisa JSON string atau array)
    $jenis_sampel = $pengambilan_sample_klinik->jenis_sample ?? null;
    if (is_string($jenis_sampel)) {
      $decoded = json_decode($jenis_sampel, true);
      $jenis_sampel = $decoded !== null ? $decoded : [$jenis_sampel];
    }
    if (!is_array($jenis_sampel)) {
      $jenis_sampel = $jenis_sampel ? [$jenis_sampel] : [];
    }

    if (empty($jenis_sampel)) {
      \Log::warning('No jenis sample found in PengambilanSampleKlinik for resampling permohonan: ' . $id_permohonan_uji_klinik);
      return;
    }

    // Format collectedDateTime from time_sampling or created_at
    $collectedDateTime = null;
    if (!empty($pengambilan_sample_klinik->time_sampling)) {
      try {
        $collectedDateTime = Carbon::parse($pengambilan_sample_klinik->time_sampling)->toIso8601String();
      } catch (\Exception $e) {
        $collectedDateTime = Carbon::parse($pengambilan_sample_klinik->created_at)->toIso8601String();
      }
    } else {
      $collectedDateTime = Carbon::parse($pengambilan_sample_klinik->created_at)->toIso8601String();
    }
    $receivedTime = $collectedDateTime;

    // Get encounter data - use existing Encounter from permohonan awal
    // For resampling, we use the same Encounter as the original permohonan
    if (empty($item_permohonan_uji_klinik->id_satu_sehat_encounter)) {
      \Log::warning('Encounter SatuSehat ID not found for resampling permohonan: ' . $id_permohonan_uji_klinik . ' - skipping resampling Specimen and ServiceRequest creation');
      return;
    }

    $encounterId = $item_permohonan_uji_klinik->id_satu_sehat_encounter;
    $encounterDisplay = "Permohonan Pengujian Resampling";

    // Get practitioner data (from petugas_name or pendaftaran)
    $practitionerId = null;
    $practitionerName = null;



    if (!empty($pengambilan_sample_klinik->petugas_name)) {
      // Normalize nama petugas untuk matching (hilangkan koma dari kedua sisi)
      $namaPetugas_normalized = str_replace(',', '', $pengambilan_sample_klinik->petugas_name);
      $practitioner = SatuSehatPractitioner::whereRaw("REPLACE(name_petugas, ',', '') LIKE ?", ['%' . $namaPetugas_normalized . '%'])->first();

      // Jika tidak ditemukan dengan like, coba cari dari ms_petugas
      if (!$practitioner) {
        $petugas = Petugas::whereRaw("REPLACE(REPLACE(nama, ',', ' '), '  ', ' ') LIKE ?", ['%' . $namaPetugas_normalized . '%'])->first();
        if ($petugas && !empty($petugas->code_satu_sehat_practitioner)) {
          $practitioner = SatuSehatPractitioner::where('code_satu_sehat_practitioner', $petugas->code_satu_sehat_practitioner)->first();
        }
      }

      if ($practitioner && isset($practitioner->code_satu_sehat_practitioner) && !empty($practitioner->code_satu_sehat_practitioner)) {
        $practitionerId = $practitioner->code_satu_sehat_practitioner;
        $practitionerName = $practitioner->name_petugas ?? $pengambilan_sample_klinik->petugas_name;
      }
    }

    // Fallback: get practitioner from pendaftaran if not found
    if (!$practitionerId) {
      $pendaftaran = VerificationActivitySample::where('is_klinik', $id_permohonan_uji_klinik)
        ->where('id_verification_activity', 1)
        ->first();

      if ($pendaftaran && !empty($pendaftaran->nama_petugas)) {
        // Normalize nama petugas untuk matching (hilangkan koma dari kedua sisi)
        $namaPetugas_normalized = str_replace(',', '', $pendaftaran->nama_petugas);
        $practitioner = SatuSehatPractitioner::whereRaw("REPLACE(name_petugas, ',', '') LIKE ?", ['%' . $namaPetugas_normalized . '%'])->first();

        if (!$practitioner) {
          $petugas = Petugas::whereRaw("REPLACE(REPLACE(nama, ',', ' '), '  ', ' ') LIKE ?", ['%' . $namaPetugas_normalized . '%'])->first();
          if ($petugas && !empty($petugas->code_satu_sehat_practitioner)) {
            $practitioner = SatuSehatPractitioner::where('code_satu_sehat_practitioner', $petugas->code_satu_sehat_practitioner)->first();
          }
        }

        if ($practitioner && isset($practitioner->code_satu_sehat_practitioner) && !empty($practitioner->code_satu_sehat_practitioner)) {
          $practitionerId = $practitioner->code_satu_sehat_practitioner;
          $practitionerName = $practitioner->name_satu_sehat_practitioner ?? $pendaftaran->name_satu_sehat_practitioner;
        }
      }
    }

    if (!$practitionerId) {
      \Log::warning('Practitioner SatuSehat not found for resampling permohonan: ' . $id_permohonan_uji_klinik);
      return;
    }

    // Get all paket klinik for this permohonan to create new ServiceRequest for each
    $permohonanUjiPaketKlinikList = PermohonanUjiPaketKlinik::where('permohonan_uji_klinik', $id_permohonan_uji_klinik)
      ->whereNull('deleted_at')
      ->get();

    if ($permohonanUjiPaketKlinikList->isEmpty()) {
      \Log::warning('No paket klinik found for resampling permohonan: ' . $id_permohonan_uji_klinik);
      return;
    }

    // Create unique UUID for this resampling (used for both ServiceRequest and Specimen)
    $uniqueId = \Ramsey\Uuid\Uuid::uuid4()->toString();

    // Create new ServiceRequest for each paket (without overwriting existing ones)
    $newServiceRequestIds = [];


    foreach ($permohonanUjiPaketKlinikList as $permohonanUjiPaketKlinik) {
      $parameterpaketklinik = ParameterPaketKlinik::find($permohonanUjiPaketKlinik->parameter_paket_klinik);
      if (!$parameterpaketklinik) {
        continue;
      }

      $packetName = $parameterpaketklinik->name_parameter_paket_klinik ?? 'Unknown';

      // Get coding from parameter paket klinik (similar to createServiceRequest)
      $detailPacket = [];
      $detailPacket[] = [
        "system" => "http://snomed.info/sct",
        "code" => "108252007",
        "display" => "Laboratory procedure"
      ];

      // Create unique identifier for resampling ServiceRequest with UUID to ensure absolute uniqueness
      // Use the same UUID for all ServiceRequests in this resampling
      $resamplingIdentifier = $item_permohonan_uji_klinik->noregister_permohonan_uji_klinik . '-RESAMPLE-' . $pengambilan_sample_klinik->resampling . '-' . $uniqueId;

      try {
        // Create ServiceRequest directly without saving to PermohonanUjiPaketKlinik (to avoid overwriting)
        $data = [
          "resourceType" => "ServiceRequest",
          "identifier" => [
            [
              "system" => "http://sys-ids.kemkes.go.id/servicerequest/".config('services.satu_sehat.org_id'),
              "value" => $resamplingIdentifier,
            ],
          ],
          "status" => "active",
          "intent" => "original-order",
          "priority" => "routine",
          "category" => [
            [
              "coding" => [
                [
                  "system" => "http://snomed.info/sct",
                  "code" => "108252007",
                  "display" => "Laboratory procedure",
                ],
              ],
            ],
          ],
          "code" => [
            "coding" => $detailPacket,
            "text" => $packetName
          ],
          "subject" => ["reference" => "Patient/".$patientId],
          "encounter" => [
            "reference" => "Encounter/".$encounterId,
            "display" => $encounterDisplay,
          ],
          "occurrenceDateTime" => $collectedDateTime,
          "authoredOn" => $collectedDateTime,
          "requester" => [
            "reference" => "Practitioner/".$practitionerId,
            "display" => $practitionerName,
          ],
          "performer" => [
            ["reference" => "Practitioner/".$practitionerId, "display" => $practitionerName],
          ]
        ];

        $response = $this->satuSehatHelper->post('ServiceRequest', $data);




        if ($response['status_code'] == '201'){
          $serviceRequestId = $response['body']["id"];
          $newServiceRequestIds[] = ["reference" => "ServiceRequest/" . $serviceRequestId];

          // ServiceRequest ID akan disimpan setelah Specimen dibuat (1:1 mapping dengan spesimen)

          \Log::info('Resampling ServiceRequest created successfully', [
            'permohonan_id' => $id_permohonan_uji_klinik,
            'paket_id' => $permohonanUjiPaketKlinik->parameter_paket_klinik,
            'resampling' => $pengambilan_sample_klinik->resampling,
            'service_request_id' => $serviceRequestId,
            'identifier' => $resamplingIdentifier,
            'collected_datetime' => $collectedDateTime,
            'unique_id' => $uniqueId
          ]);
        } else {
          throw new Exception("Gagal membuat service request untuk resampling! Response: " . json_encode($response));
        }
      } catch (\Exception $e) {
        \Log::error('Error creating ServiceRequest for resampling: ' . $e->getMessage(), [
          'permohonan_id' => $id_permohonan_uji_klinik,
          'paket_id' => $permohonanUjiPaketKlinik->parameter_paket_klinik,
          'resampling' => $pengambilan_sample_klinik->resampling,
          'exception' => $e->getTraceAsString()
        ]);
      }
    }

    // Check if we have valid ServiceRequest IDs before creating Specimen
    if (empty($newServiceRequestIds)) {
      \Log::warning('No ServiceRequest IDs created for resampling - cannot create Specimen (request field is mandatory)', [
        'permohonan_id' => $id_permohonan_uji_klinik,
        'resampling' => $pengambilan_sample_klinik->resampling
      ]);
      return; // Cannot create Specimen without ServiceRequest
    }

    // Create Specimen for resampling with unique identifier using UUID
    // Use the same UUID as ServiceRequest to ensure consistency (already created above)
    $identifier = $item_permohonan_uji_klinik->noregister_permohonan_uji_klinik . '-RESAMPLE-' . $pengambilan_sample_klinik->resampling . '-' . $uniqueId;

    // Determine initial status based on status_sampling
    // If status_sampling is "gagal", use "unavailable", otherwise "available"
    $initialStatus = (strtolower($pengambilan_sample_klinik->status_sampling ?? '') === 'gagal') ? 'unavailable' : 'available';

    try {
      $result = $this->createSpecimen(
        $identifier,
        $jenis_sampel,
        $collectedDateTime,
        $patientId,
        $patientName,
        $newServiceRequestIds,
        $receivedTime,
        $initialStatus
      );

      // Update id_spesimen_satu_sehat and id_service_request_satu_sehat in pengambilan_sample_klinik
      // ServiceRequest ID disimpan sesuai dengan spesimen (1:1 mapping)
      if ($result) {
        // Simpan specimen ID jika ada
        if (!empty($result['specimen_ids'])) {
          $pengambilan_sample_klinik->id_spesimen_satu_sehat = implode(',', $result['specimen_ids']);
        }

        // Simpan ServiceRequest ID jika ada (1:1 mapping dengan spesimen)
        if (!empty($result['service_request_ids'])) {
          $pengambilan_sample_klinik->id_service_request_satu_sehat = implode(',', $result['service_request_ids']);
        }

        // Simpan ServiceRequest ID yang sudah dibuat sebelumnya jika result tidak mengembalikan service_request_ids
        // (untuk memastikan ServiceRequest ID tersimpan meskipun createSpecimen tidak mengembalikannya)
        if (empty($result['service_request_ids']) && !empty($newServiceRequestIds)) {
          $serviceRequestIdsArray = array_map(function($ref) {
            return str_replace('ServiceRequest/', '', $ref['reference']);
          }, $newServiceRequestIds);
          $pengambilan_sample_klinik->id_service_request_satu_sehat = implode(',', array_filter($serviceRequestIdsArray));
        }

        $pengambilan_sample_klinik->save();

        \Log::info('Resampling Specimen and ServiceRequest created successfully with 1:1 mapping', [
          'permohonan_id' => $id_permohonan_uji_klinik,
          'resampling' => $pengambilan_sample_klinik->resampling,
          'specimen_ids' => $result['specimen_ids'] ?? [],
          'service_request_ids' => $result['service_request_ids'] ?? [],
          'id_spesimen_satu_sehat' => $pengambilan_sample_klinik->id_spesimen_satu_sehat,
          'id_service_request_satu_sehat' => $pengambilan_sample_klinik->id_service_request_satu_sehat,
          'identifier' => $identifier,
          'collected_datetime' => $collectedDateTime,
          'unique_id' => $uniqueId,
          'initial_status' => $initialStatus,
          'status_sampling' => $pengambilan_sample_klinik->status_sampling
        ]);
      } else {
        // Jika createSpecimen gagal, tetap simpan ServiceRequest ID yang sudah dibuat
        if (!empty($newServiceRequestIds)) {
          $serviceRequestIdsArray = array_map(function($ref) {
            return str_replace('ServiceRequest/', '', $ref['reference']);
          }, $newServiceRequestIds);
          $pengambilan_sample_klinik->id_service_request_satu_sehat = implode(',', array_filter($serviceRequestIdsArray));
          $pengambilan_sample_klinik->save();
        }

        \Log::warning('createSpecimen returned empty result for resampling, but ServiceRequest IDs saved', [
          'permohonan_id' => $id_permohonan_uji_klinik,
          'resampling' => $pengambilan_sample_klinik->resampling,
          'service_request_ids' => $newServiceRequestIds
        ]);
      }
    } catch (\Exception $e) {
      // Tetap simpan ServiceRequest ID yang sudah dibuat meskipun Specimen gagal
      if (!empty($newServiceRequestIds)) {
        $serviceRequestIdsArray = array_map(function($ref) {
          return str_replace('ServiceRequest/', '', $ref['reference']);
        }, $newServiceRequestIds);
        $pengambilan_sample_klinik->id_service_request_satu_sehat = implode(',', array_filter($serviceRequestIdsArray));
        $pengambilan_sample_klinik->save();
      }

      \Log::error('Error creating Specimen for resampling: ' . $e->getMessage(), [
        'permohonan_id' => $id_permohonan_uji_klinik,
        'resampling' => $pengambilan_sample_klinik->resampling,
        'exception' => $e->getTraceAsString()
      ]);
    }
  }

  /**
   * Send specimen data to SatuSehat from storePermohonanUjiSample
   */
  private function sendSpecimenToSatuSehat($item_permohonan_uji_klinik, $request, $pengambilan_sample_klinik)
  {
    // Only send if VERSION_SATUSEHAT = prd
    if (config('services.satu_sehat.version') !== 'prd') {
      \Log::info('SatuSehat integration skipped: VERSION_SATUSEHAT is not prd');
      return;
    }

    // Get patient data
    $pasien = Pasien::find($item_permohonan_uji_klinik->pasien_permohonan_uji_klinik);
    if (!$pasien || empty($pasien->id_pasien_satu_sehat)) {
      \Log::warning('Patient SatuSehat ID not found for permohonan: ' . $item_permohonan_uji_klinik->id_permohonan_uji_klinik);
      return;
    }

    $patientId = $pasien->id_pasien_satu_sehat;
    $patientName = $pasien->nama_pasien ?? 'Unknown';

    // Parse jenis sample (bisa array atau JSON string)
    $jenis_sampel = $request->jenis_sampel ?? null;
    if (is_string($jenis_sampel)) {
      $decoded = json_decode($jenis_sampel, true);
      $jenis_sampel = $decoded !== null ? $decoded : [$jenis_sampel];
    }
    if (!is_array($jenis_sampel)) {
      $jenis_sampel = $jenis_sampel ? [$jenis_sampel] : [];
    }

    if (empty($jenis_sampel)) {
      \Log::warning('No jenis sample found for permohonan: ' . $item_permohonan_uji_klinik->id_permohonan_uji_klinik);
      return;
    }

    // Get ServiceRequest IDs - filter out null and empty values
    $serviceRequests = PermohonanUjiPaketKlinik::where('permohonan_uji_klinik', $item_permohonan_uji_klinik->id_permohonan_uji_klinik)
      ->whereNotNull('id_service_request')
      ->where('id_service_request', '!=', '')
      ->pluck('id_service_request')
      ->filter(function($id) {
        return !empty($id) && trim($id) !== '';
      })
      ->map(function($id) {
        return ["reference" => "ServiceRequest/" . $id];
      })
      ->values()
      ->toArray();

    // Format collectedDateTime from tgl_sampling and jam_sampling
    $tgl_sampling = $request->tgl_sampling ?? null;
    $jam_sampling = $request->jam_sampling ?? null;

    if ($tgl_sampling && $jam_sampling) {
      try {
        $collectedDateTime = Carbon::createFromFormat('Y-m-d H:i', $tgl_sampling . ' ' . $jam_sampling)->toIso8601String();
      } catch (\Exception $e) {
        $collectedDateTime = Carbon::now()->toIso8601String();
      }
    } else {
      // Fallback to registration date or current time
      $collectedDateTime = $item_permohonan_uji_klinik->tglregister_permohonan_uji_klinik
        ? Carbon::parse($item_permohonan_uji_klinik->tglregister_permohonan_uji_klinik)->toIso8601String()
        : Carbon::now()->toIso8601String();
    }

    $receivedTime = $collectedDateTime; // Use same time for receivedTime

    // Call createSpecimen
    $identifier = $item_permohonan_uji_klinik->noregister_permohonan_uji_klinik;

    // Determine initial status based on status_sampling
    // If status_sampling is "gagal", use "unavailable", otherwise "available"
    $initialStatus = 'available'; // Default untuk sampling normal
    if ($pengambilan_sample_klinik && !empty($pengambilan_sample_klinik->status_sampling)) {
      $initialStatus = (strtolower($pengambilan_sample_klinik->status_sampling) === 'gagal') ? 'unavailable' : 'available';
    }

    $result = $this->createSpecimen(
      $identifier,
      $jenis_sampel,
      $collectedDateTime,
      $patientId,
      $patientName,
      $serviceRequests,
      $receivedTime,
      $initialStatus
    );

    // Update id_spesimen_satu_sehat and id_service_request_satu_sehat in pengambilan_sample_klinik if exists
    // Setiap pengambilan sample punya specimen ID sendiri, bukan dari array di PermohonanUjiKlinik2
    if ($pengambilan_sample_klinik) {
      // Simpan specimen ID langsung dari result createSpecimen (per pengambilan sample)
      if ($result && !empty($result['specimen_ids'])) {
        $pengambilan_sample_klinik->id_spesimen_satu_sehat = implode(',', $result['specimen_ids']);
      }

      // Simpan ServiceRequest ID sesuai dengan spesimen (1:1 mapping)
      if ($result && !empty($result['service_request_ids'])) {
        $pengambilan_sample_klinik->id_service_request_satu_sehat = implode(',', $result['service_request_ids']);
      }

      $pengambilan_sample_klinik->save();
    }
  }

  /**
   * Send specimen to SatuSehat and update ServiceRequest when sampling is completed
   * Called from verificationAnalytic when verification_step = 6 and is_done = 1
   */
  private function sendSpecimenAndUpdateServiceRequest($id_permohonan_uji_klinik, $request, $collectedDateTime)
  {
    // Only send if VERSION_SATUSEHAT = prd
    if (config('services.satu_sehat.version') !== 'prd') {
      \Log::info('SatuSehat integration skipped: VERSION_SATUSEHAT is not prd');
      return;
    }

    // Get permohonan uji klinik data
    $item_permohonan_uji_klinik = PermohonanUjiKlinik2::find($id_permohonan_uji_klinik);
    if (!$item_permohonan_uji_klinik) {
      \Log::warning('Permohonan uji klinik not found: ' . $id_permohonan_uji_klinik);
      return;
    }

    // Get patient data
    $pasien = Pasien::find($item_permohonan_uji_klinik->pasien_permohonan_uji_klinik);
    if (!$pasien || empty($pasien->id_pasien_satu_sehat)) {
      \Log::warning('Patient SatuSehat ID not found for permohonan: ' . $id_permohonan_uji_klinik);
      return;
    }

    $patientId = $pasien->id_pasien_satu_sehat;
    $patientName = $pasien->nama_pasien ?? 'Unknown';

    // Get PengambilanSampleKlinik data (latest one for this permohonan)
    $pengambilan_sample_klinik = PengambilanSampleKlinik::where('permohonan_uji_klinik_id', $id_permohonan_uji_klinik)
      ->orderBy('created_at', 'desc')
      ->first();

    if (!$pengambilan_sample_klinik) {
      \Log::warning('PengambilanSampleKlinik not found for permohonan: ' . $id_permohonan_uji_klinik);
      return;
    }

    // Parse jenis_sample (bisa JSON string atau array)
    $jenis_sampel = $pengambilan_sample_klinik->jenis_sample ?? null;
    if (is_string($jenis_sampel)) {
      $decoded = json_decode($jenis_sampel, true);
      $jenis_sampel = $decoded !== null ? $decoded : [$jenis_sampel];
    }
    if (!is_array($jenis_sampel)) {
      $jenis_sampel = $jenis_sampel ? [$jenis_sampel] : [];
    }

    if (empty($jenis_sampel)) {
      \Log::warning('No jenis sample found in PengambilanSampleKlinik for permohonan: ' . $id_permohonan_uji_klinik);
      return;
    }

    // Get ServiceRequest IDs - prioritize id_service_request_satu_sehat from PengambilanSampleKlinik (for resampling)
    // If not available, fallback to PermohonanUjiPaketKlinik
    $serviceRequests = [];

    if (!empty($pengambilan_sample_klinik->id_service_request_satu_sehat)) {
      // Use ServiceRequest IDs from PengambilanSampleKlinik (for resampling)
      $serviceRequestIds = explode(',', $pengambilan_sample_klinik->id_service_request_satu_sehat);
      $serviceRequests = array_map(function($id) {
        $id = trim($id);
        return !empty($id) ? ["reference" => "ServiceRequest/" . $id] : null;
      }, $serviceRequestIds);
      $serviceRequests = array_filter($serviceRequests); // Remove null values
      $serviceRequests = array_values($serviceRequests); // Re-index array

      \Log::info('Using ServiceRequest IDs from PengambilanSampleKlinik for Specimen creation', [
        'permohonan_id' => $id_permohonan_uji_klinik,
        'service_request_ids' => $serviceRequestIds,
        'resampling' => $pengambilan_sample_klinik->resampling ?? 0
      ]);
    }

    // Fallback to PermohonanUjiPaketKlinik if no ServiceRequest IDs from PengambilanSampleKlinik
    if (empty($serviceRequests)) {
      $serviceRequests = PermohonanUjiPaketKlinik::where('permohonan_uji_klinik', $id_permohonan_uji_klinik)
        ->whereNotNull('id_service_request')
        ->where('id_service_request', '!=', '')
        ->pluck('id_service_request')
        ->filter(function($id) {
          return !empty($id) && trim($id) !== '';
        })
        ->map(function($id) {
          return ["reference" => "ServiceRequest/" . $id];
        })
        ->values()
        ->toArray();
    }

    // Format collectedDateTime (already in Y-m-d H:i:s format)
    $collectedDateTimeIso = Carbon::parse($collectedDateTime)->toIso8601String();
    $receivedTime = $collectedDateTimeIso; // Use same time for receivedTime

    // Call createSpecimen
    $identifier = $item_permohonan_uji_klinik->noregister_permohonan_uji_klinik;

    // Determine initial status based on status_sampling
    // If status_sampling is "gagal", use "unavailable", otherwise "available"
    $initialStatus = 'available'; // Default untuk sampling normal
    if ($pengambilan_sample_klinik && !empty($pengambilan_sample_klinik->status_sampling)) {
      $initialStatus = (strtolower($pengambilan_sample_klinik->status_sampling) === 'gagal') ? 'unavailable' : 'available';
    }

    $result = $this->createSpecimen(
      $identifier,
      $jenis_sampel,
      $collectedDateTimeIso,
      $patientId,
      $patientName,
      $serviceRequests,
      $receivedTime,
      $initialStatus
    );

    // Simpan specimen ID dan ServiceRequest ID sesuai dengan spesimen (1:1 mapping)
    // Setiap pengambilan sample punya specimen ID sendiri, bukan dari array di PermohonanUjiKlinik2
    if ($result) {
      if (!empty($result['specimen_ids'])) {
        $pengambilan_sample_klinik->id_spesimen_satu_sehat = implode(',', $result['specimen_ids']);
      }
      if (!empty($result['service_request_ids'])) {
        $pengambilan_sample_klinik->id_service_request_satu_sehat = implode(',', $result['service_request_ids']);
      }
      $pengambilan_sample_klinik->save();
    }

    // Update ServiceRequest dengan petugas pengambil sample (performer)
    $nama_petugas = $request->get('nama_petugas');
    if (!empty($nama_petugas) && !empty($serviceRequests)) {
      // Get practitioner code from SatuSehatPractitioner
      // Normalize nama petugas untuk matching (hilangkan koma dari kedua sisi)
      $nama_petugas_normalized = str_replace(',', '', $nama_petugas);

      $practitioner = SatuSehatPractitioner::whereRaw("REPLACE(name_petugas, ',', '') LIKE ?", ['%' . $nama_petugas_normalized . '%'])->first();



      // Jika tidak ditemukan dengan like, coba cari dari ms_petugas
      if (!$practitioner) {
        $petugas = Petugas::where('nama', 'like', '%' . $nama_petugas_normalized . '%')->first();
        if ($petugas && !empty($petugas->code_satu_sehat_practitioner)) {
          $practitioner = SatuSehatPractitioner::where('code_satu_sehat_practitioner', $petugas->code_satu_sehat_practitioner)->first();
        }
      }

      // Pastikan $practitioner adalah object dan memiliki code_satu_sehat_practitioner
      if ($practitioner !== null && is_object($practitioner) && isset($practitioner->code_satu_sehat_practitioner) && !empty($practitioner->code_satu_sehat_practitioner)) {
        $practitionerId = $practitioner->code_satu_sehat_practitioner;
        $practitionerName = $practitioner->name_satu_sehat_practitioner ?? $nama_petugas;

        // Update each ServiceRequest
        foreach ($serviceRequests as $serviceRequestRef) {
          $serviceRequestId = str_replace('ServiceRequest/', '', $serviceRequestRef['reference']);

          // Get existing ServiceRequest data
          $permohonanUjiPaketKlinik = PermohonanUjiPaketKlinik::where('permohonan_uji_klinik', $id_permohonan_uji_klinik)
            ->where('id_service_request', $serviceRequestId)
            ->first();

          if ($permohonanUjiPaketKlinik && !empty($permohonanUjiPaketKlinik->response_service_request)) {
            $existingData = json_decode($permohonanUjiPaketKlinik->response_service_request, true);

            // Update performer with sampling practitioner
            $existingData['performer'] = [
              ["reference" => "Practitioner/" . $practitionerId, "display" => $practitionerName]
            ];

            // Update ServiceRequest via PUT
            try {
              $response = $this->satuSehatHelper->put('ServiceRequest', $serviceRequestId, $existingData);

              if ($response['status_code'] == '200' || $response['status_code'] == '201') {
                // Update response_service_request dengan data terbaru
                $permohonanUjiPaketKlinik->response_service_request = json_encode($response['body']);
                $permohonanUjiPaketKlinik->save();

                \Log::info('ServiceRequest updated successfully', [
                  'service_request_id' => $serviceRequestId,
                  'practitioner_id' => $practitionerId,
                  'practitioner_name' => $practitionerName
                ]);
              } else {
                \Log::warning('Failed to update ServiceRequest', [
                  'service_request_id' => $serviceRequestId,
                  'response' => $response
                ]);
              }
            } catch (\Exception $e) {
              \Log::error('Error updating ServiceRequest: ' . $e->getMessage(), [
                'service_request_id' => $serviceRequestId,
                'exception' => $e->getTraceAsString()
              ]);
            }
          }
        }
      } else {
        \Log::warning('Practitioner SatuSehat not found for petugas: ' . $nama_petugas);
      }
    }

    // Update id_spesimen_satu_sehat and id_service_request_satu_sehat in pengambilan_sample_klinik
    // Setiap pengambilan sample punya specimen ID sendiri, bukan dari array di PermohonanUjiKlinik2
    // id_spesimen_satu_sehat dan id_service_request_satu_sehat sudah disimpan dari result createSpecimen (1:1 mapping dengan spesimen)
    // Tidak perlu mengambil dari PermohonanUjiKlinik2->id_spesimen lagi
  }

  public function verification($id)
  {
    abort_unless($this->canAccessKlinikVerifikasi(), 403, 'Verifikasi hanya untuk analis.');

    $item = PermohonanUjiKlinik2::find($id);

    if ($item && isset($item->tglregister_permohonan_uji_klinik)) {
        $tgl_register = Carbon::createFromFormat('Y-m-d H:i:s', $item->tglregister_permohonan_uji_klinik);
    } else {
      $tgl_register = '-';
    }

    $verificationActivitySamples = VerificationActivitySample::where('is_klinik',$id) ->where('resampling', 0)->get();
    $listVerifications = [];
    foreach ($verificationActivitySamples as  $verificationActivitySample){
      $listVerifications[$verificationActivitySample->id_verification_activity] = $verificationActivitySample;
    }


    $verificationActivity = VerificationActivity::all()->keyBy('id');
    // kumpulkan semua pengambilan sample (step 6) untuk menampilkan sampling ulang
    $resampleSamples = VerificationActivitySample::where('is_klinik', $id)
      ->where('id_verification_activity', 6)
      ->where('resampling', '>', 0)
      ->orderBy('start_date')
      ->get();

      $pengambilanSampleKlinik = PengambilanSampleKlinik::where('permohonan_uji_klinik_id', $id)->orderBy('created_at', 'asc')->first();

      $pengambilanSampleUlangKlinik = PengambilanSampleKlinik::where('permohonan_uji_klinik_id', $id)->where('resampling', '>', 0)->orderBy('created_at', 'asc')->get();

    // Get parameters yang diujikan (struktur sama seperti di nota)
    $data_permohonan_uji_paket_klinik = PermohonanUjiPaketKlinik::where('permohonan_uji_klinik', $id)
      ->with(['parameterjenisklinik', 'parameterpaketklinik'])
      ->whereNull('deleted_at')
      ->get();

    $parameters = [];
    foreach ($data_permohonan_uji_paket_klinik as $paket) {
      $data_parameters = PermohonanUjiParameterKlinik::where('permohonan_uji_klinik', $id)
        ->where('permohonan_uji_paket_klinik', $paket->id_permohonan_uji_paket_klinik)
        ->with(['parametersatuanklinik'])
        ->whereNull('deleted_at')
        ->get();

      foreach ($data_parameters as $param) {
        $param->nama_jenis = $paket->parameterjenisklinik->name_parameter_jenis_klinik ?? '-';
        $param->nama_paket = $paket->parameterpaketklinik->name_parameter_paket_klinik ?? '-';
        $parameters[] = $param;
      }
    }

    /**
     * SESUAIKAN URUTAN DENGAN HALAMAN elits-parameter-category-layout
     *
     * Di layout itu, urutan paket klinik diatur lewat ParameterCategoryLayout + ParameterCategoryItem.
     * Di sini kita hanya mengubah urutan array $parameters berdasarkan paket-nya,
     * TANPA mengubah data lain (supaya tidak ganggu route / view lain).
     */
    try {
      $categoryLayouts = \Smt\Masterweb\Models\ParameterCategoryLayout::where('is_active', 1)
        ->orderBy('sort_order', 'asc')
        ->with(['categoryItems' => function ($query) {
          $query->with('parameterPaketKlinik')
            ->orderBy('row_position', 'asc')
            ->orderBy('column_position', 'asc')
            ->orderBy('sort_order', 'asc');
        }])
        ->get();

      // Bangun peta urutan paket berdasarkan layout
      $paketLayoutOrder = [];
      $orderIndex = 1;
      foreach ($categoryLayouts as $category) {
        foreach ($category->categoryItems as $layoutItem) {
          if ($layoutItem->parameterPaketKlinik) {
            $paketId = $layoutItem->parameterPaketKlinik->id_parameter_paket_klinik;
            // Simpan hanya sekali; jika paket muncul beberapa kali, urutan pertama yang dipakai
            if (!isset($paketLayoutOrder[$paketId])) {
              $paketLayoutOrder[$paketId] = $orderIndex++;
            }
          }
        }
      }

      // Urutkan array $parameters sesuai urutan paket di layout
      if (!empty($paketLayoutOrder) && !empty($parameters)) {
        usort($parameters, function ($a, $b) use ($paketLayoutOrder) {
          $idA = $a->parameter_paket_klinik ?? null;
          $idB = $b->parameter_paket_klinik ?? null;

          $orderA = $idA && isset($paketLayoutOrder[$idA]) ? $paketLayoutOrder[$idA] : PHP_INT_MAX;
          $orderB = $idB && isset($paketLayoutOrder[$idB]) ? $paketLayoutOrder[$idB] : PHP_INT_MAX;

          if ($orderA === $orderB) {
            return 0;
          }
          return $orderA <=> $orderB;
        });
      }
    } catch (\Throwable $e) {
      // Kalau gagal ambil layout atau error lain, biarkan urutan default (tidak perlu throw)
    }

    $this->ensureUrineOnlyPengambilSampleSkipped($id);
    $this->ensureDibawaPelangganPengambilSampleSkipped($id);
    $verificationActivitySamples = VerificationActivitySample::where('is_klinik', $id)->where('resampling', 0)->get();
    $listVerifications = [];
    foreach ($verificationActivitySamples as $verificationActivitySample) {
      $listVerifications[$verificationActivitySample->id_verification_activity] = $verificationActivitySample;
    }

    $petugasPenerima = $this->getPetugasPenerimaKlinik();
    if (isset($listVerifications[7]) && !empty($listVerifications[7]->nama_petugas)) {
      $savedPenerima = trim($listVerifications[7]->nama_petugas);
      if ($savedPenerima !== '' && !$this->namaExistsInArray($savedPenerima, $petugasPenerima)) {
        $petugasPenerima[] = $savedPenerima;
      }
    }

    $petugasValidator = $this->getPetugasValidator();

    $petugasPengambilSampel = [];
    if (\Smt\Masterweb\Helpers\SampleCollectorAccess::isKlinik(Auth::user()->getlevel->level ?? null) && empty(Auth::user()->id_petugas)) {
      $petugasPengambilSampel = $this->getPetugasPengambilKlinik();
    } else {
      $vaSource = (isset($verificationActivity[6]) && !empty($verificationActivity[6]->klinik))
        ? $verificationActivity[6]
        : ((isset($verificationActivity[5]) && !empty($verificationActivity[5]->klinik)) ? $verificationActivity[5] : null);
      if ($vaSource) {
        $petugasPengambilSampel = array_values(array_filter(array_map('trim', explode(', ', $vaSource->klinik))));
      }
    }

    $namaPetugasLogin = null;
    if (in_array(Auth::user()->getlevel->level, ['ALAB', 'PLAB', 'ANLS']) && !empty(Auth::user()->id_petugas)) {
      $petugasLogin = Petugas::find(Auth::user()->id_petugas);
      $namaPetugasLogin = $petugasLogin ? trim($petugasLogin->nama) : null;
    }

    $isUrineOnlySample = Smt::isUrineOnlySample($id);
    $isDibawaPelanggan = ($item->mode_pengambilan_sampel ?? '') === 'dibawa_pelanggan';

    $prefillPetugasPengambil = $this->resolvePrefillPetugasPengambilForVerification(
      $listVerifications,
      $pengambilanSampleKlinik,
      $item
    );
    if ($prefillPetugasPengambil !== '' && !$this->isDiisiPelangganPetugasSelection($prefillPetugasPengambil)) {
      $merged = $this->ensurePetugasNameInList($petugasPengambilSampel, $prefillPetugasPengambil);
      $petugasPengambilSampel = $merged['list'];
      $prefillPetugasPengambil = $merged['nama'];
    }

    $kirim_hasil_whatsapp = (int) (optional($item)->kirim_hasil_whatsapp ?? 0) === 1;
    $phone_pasien_wa = optional(optional($item)->pasien)->phone_pasien;
    $validasi_selesai = isset($listVerifications[5]) && (int) $listVerifications[5]->is_done === 1;
    $status_selesai = strtoupper((string) (optional($item)->status_permohonan_uji_klinik ?? '')) === 'SELESAI';
    $bisa_kirim_hasil_whatsapp_manual = !empty($phone_pasien_wa) && ($validasi_selesai || $status_selesai);

    return view('masterweb::module.admin.laboratorium.permohonan-uji-klinik-2.verification', [
      'item' => $item,
      'tgl_register' => $tgl_register,
      'pengambilanSampleKlinik' => $pengambilanSampleKlinik,
      'pengambilanSampleUlangKlinik' => $pengambilanSampleUlangKlinik,
      'listVerifications' => $listVerifications,
      'verificationActivity' => $verificationActivity,
      'resampleSamples' => $resampleSamples,
      'parameters' => $parameters,
      'petugasPenerima' => $petugasPenerima,
      'petugasValidator' => $petugasValidator,
      'petugasPengambilSampel' => $petugasPengambilSampel,
      'prefillPetugasPengambil' => $prefillPetugasPengambil,
      'namaPetugasLogin' => $namaPetugasLogin,
      'isUrineOnlySample' => $isUrineOnlySample,
      'isDibawaPelanggan' => $isDibawaPelanggan,
      'kirim_hasil_whatsapp' => $kirim_hasil_whatsapp,
      'phone_pasien_wa' => $phone_pasien_wa,
      'bisa_kirim_hasil_whatsapp_manual' => $bisa_kirim_hasil_whatsapp_manual,
      'validasi_selesai' => $validasi_selesai,
      'info_haji' => $this->resolveInfoHajiForPermohonan($item),
    ]);
  }

  public function verificationAnalytic(Request $request, $id)
  {

    $request->validate([
      'verification_step' => 'required',
      'start_date' => 'required',
      'stop_date' => 'required',
      'nama_petugas' => 'required'
    ]);




    DB::beginTransaction();
    try {


      // Normalisasi input waktu: terima HH:mm (jam saja), Y-m-d H:i, Y-m-d H:i:s, atau d/m/Y H:i
      $rawStart = (string) $request->get('start_date');
      $rawStop  = (string) $request->get('stop_date');

      $start = null; $stop = null;

      $permohonanForDate = PermohonanUjiKlinik2::find($id);
      $registrationBaseDate = $permohonanForDate && DateHelper::permohonanAnchorAt($permohonanForDate)
        ? Carbon::parse(DateHelper::permohonanAnchorAt($permohonanForDate))->startOfDay()
        : Carbon::today()->startOfDay();

      $existingStep = VerificationActivitySample::where('is_klinik', $id)
        ->where('id_verification_activity', $request->get('verification_step'))
        ->first();
      if ($existingStep && !empty($existingStep->start_date)) {
        $registrationBaseDate = Carbon::parse($existingStep->start_date)->startOfDay();
      }

      // Helper parse menjadi Carbon
      $parseToCarbon = function (?string $val) use ($registrationBaseDate): ?\Carbon\Carbon {
        if (!$val) return null;
        $val = trim($val);
        try {
          if (preg_match('/^\d{2}\/\d{2}\/\d{4}\s+\d{1,2}:\d{2}$/', $val)) { // d/m/Y H:i
            return Carbon::createFromFormat('d/m/Y H:i', $val);
          }
          if (preg_match('/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/', $val)) { // Y-m-d H:i:s
            return Carbon::createFromFormat('Y-m-d H:i:s', $val);
          }
          if (preg_match('/^\d{4}-\d{2}-\d{2} \d{1,2}:\d{2}$/', $val)) { // Y-m-d H:i
            return Carbon::createFromFormat('Y-m-d G:i', $val);
          }
          if (preg_match('/^\d{1,2}:\d{2}$/', $val)) { // HH:mm (jam saja) — tanggal acuan permohonan / tersimpan
            [$h, $m] = explode(':', $val);
            return $registrationBaseDate->copy()->setTime((int) $h, (int) $m, 0);
          }
        } catch (\Throwable $e) {
          return null;
        }
        return null;
      };



      $start = $parseToCarbon($rawStart);
      $stop  = $parseToCarbon($rawStop);

      // Jika stop kosong pada klinik (jam saja), samakan dengan start
      if (!$stop && $start) {
        $stop = $start->copy();
      }

      if (!$start) {
        DB::rollBack();
        return redirect()->back()
          ->withErrors(['start_date' => 'Format jam tidak valid. Gunakan format HH:mm atau dd/mm/yyyy HH:mm.'])
          ->withInput();
      }
      if (!$stop) {
        $stop = $start->copy();
      }

      // Simpan kembali ke bentuk d/m/Y H:i untuk downstream logic yang sudah ada
      $requestStartDate = $start->format('d/m/Y H:i');
      $requestStopDate  = $stop->format('d/m/Y H:i');
      // Klinik: tanggal mulai dan tanggal selesai disamakan
      $requestStopDate  = $requestStartDate;

      // // Khusus resampling pengambil sample (step 6), paksa buat entri baru jika diminta
      // if ((int)$request->get('verification_step') === 6 && (string)$request->get('resample') === '1') {
      //   $verificationActivitySample = new VerificationActivitySample();
      //   $verificationActivitySample->id = Uuid::uuid4()->toString();
      //   $verificationActivitySample->id_verification_activity = 6;
      //   $verificationActivitySample->start_date = Carbon::createFromFormat('d/m/Y H:i', $requestStartDate)->format('Y-m-d H:i:s');
      //   $verificationActivitySample->stop_date = Carbon::createFromFormat('d/m/Y H:i', $requestStopDate)->format('Y-m-d H:i:s');
      //   $verificationActivitySample->nama_petugas = $request->get('nama_petugas');
      //   $verificationActivitySample->is_klinik = $id;
      //   $verificationActivitySample->is_done = 1;
      //   $verificationActivitySample->resampling = 1;
      //   $verificationActivitySample->save();

      //   DB::commit();
      //   return redirect()->back()->with('status', 'Sampling ulang ditambahkan');
      // }

      $is_klinik = VerificationActivitySample::where([
        ['is_klinik', '=', $id],
        ['id_verification_activity', '=', 1],

      ])->first();




      if (isset($is_klinik)) {
        # code...


        // resampling hanya relevan untuk step 6 (sampling); filter ketat membuat step 5 (validasi) tidak ketemu jika resampling NULL
        $data_verifikasiQuery = VerificationActivitySample::where('is_klinik', $id)
          ->where('id_verification_activity', $request->get('verification_step'));
        if ((int) $request->get('verification_step') === 6) {
          $data_verifikasiQuery->where('resampling', $request->get('resampling') ?? 0);
        }
        $data_verifikasi = $data_verifikasiQuery->first();



        if(isset($data_verifikasi) && $data_verifikasi->is_done == 0){

          $data_verifikasi->start_date = Carbon::createFromFormat('d/m/Y H:i', $requestStartDate)->format('Y-m-d H:i:s');
          $data_verifikasi->stop_date = Carbon::createFromFormat('d/m/Y H:i', $requestStopDate)->format('Y-m-d H:i:s');
          $data_verifikasi->nama_petugas = $request->get('nama_petugas');
          if ($request->get('is_selesai') == 1) { $data_verifikasi->is_done = 1; }
          $data_verifikasi->save();

          $data_permohonan_uji_klinik = PermohonanUjiKlinik2::findOrFail($id);

          if($request->get('verification_step') == 3){ //Input / Output Hasil Px
            $data_permohonan_uji_klinik->name_analis_permohonan_uji_klinik =$request->get('nama_petugas');

            $data_permohonan_uji_klinik->save();
          }

        }else if(isset($data_verifikasi) && $data_verifikasi->is_done == 1){
          //update start date, stop date, nama petugas


          $data_verifikasi->start_date = Carbon::createFromFormat('d/m/Y H:i', $requestStartDate)->format('Y-m-d H:i:s');
          $data_verifikasi->stop_date =  Carbon::createFromFormat('d/m/Y H:i', $requestStopDate) ->format('Y-m-d H:i:s');
          $data_verifikasi->nama_petugas = $request->get('nama_petugas');

          $data_permohonan_uji_klinik = PermohonanUjiKlinik2::findOrFail($id);
          // dd($data_permohonan_uji_klinik);

          if($request->get('verification_step') == 1){ //registrasi
            $data_permohonan_uji_klinik->tglregister_permohonan_uji_klinik = Carbon::createFromFormat('d/m/Y H:i', $requestStartDate)->format('Y-m-d H:i:s');

            $data_permohonan_uji_klinik->save();
          }elseif($request->get('verification_step') == 6){ //sample
            $data_permohonan_uji_klinik->tgl_sampling_permohonan_uji_klinik = Carbon::createFromFormat('d/m/Y H:i', $requestStartDate)->format('Y-m-d');
            $data_permohonan_uji_klinik->jam_sampling_permohonan_uji_klinik =Carbon::createFromFormat('d/m/Y H:i', $requestStartDate)->format('H:i:s');
            $data_permohonan_uji_klinik->plebotomist_permohonan_uji_klinik = $request->get('nama_petugas');

            $data_permohonan_uji_klinik->save();
          }elseif($request->get('verification_step') == 3){ //Input / Output Hasil Px
            $data_permohonan_uji_klinik->tglpengujian_permohonan_uji_klinik = Carbon::createFromFormat('d/m/Y H:i', $requestStartDate)->format('Y-m-d H:i:s');
            $data_permohonan_uji_klinik->name_analis_permohonan_uji_klinik = $request->get('nama_petugas');

            $data_permohonan_uji_klinik->save();
          }

          $data_verifikasi->save();
        }else{
          //create
          $verificationActivitySample = new VerificationActivitySample();
          $verificationActivitySample->id = Uuid::uuid4()->toString();
          $verificationActivitySample->id_verification_activity = $request->get('verification_step');
          $verificationActivitySample->start_date = Carbon::createFromFormat('d/m/Y H:i', $requestStartDate)->format('Y-m-d H:i:s');
          $verificationActivitySample->stop_date = Carbon::createFromFormat('d/m/Y H:i', $requestStopDate)->format('Y-m-d H:i:s');
          $verificationActivitySample->nama_petugas = $request->get('nama_petugas');
          //khusus sampling
          if ($request->get('verification_step') == 6){
            $verificationActivitySample->resampling = ( $request->get('resampling')??0);
          }
          $verificationActivitySample->is_klinik = $id;
          $verificationActivitySample->is_done = ($request->get('is_selesai') == 1) ? 1 : 0;

          $verificationActivitySample->save();
          $data_verifikasi = $verificationActivitySample;
        }


        if ($request->get('verification_step') == 6){

          $start_date = Carbon::createFromFormat('d/m/Y H:i', $requestStartDate)->format('Y-m-d H:i:s');
          $stop_date = Carbon::createFromFormat('d/m/Y H:i', $requestStopDate)->format('Y-m-d H:i:s');

          $newStatusHistory = [
            "status" => "in-progress",
            "period" => [
              "start" => Carbon::createFromFormat('Y-m-d H:i:s', $start_date)->toIso8601String(),
              "end" => Carbon::createFromFormat('Y-m-d H:i:s', $stop_date)->toIso8601String()
            ]
          ];



          $this->updateEncounter(
            $id,
           $request->get('nama_petugas'),
            "in-progress",
            "Ruang Pengambilan Sample",
            "OBSENC",
            "Pengambilan Sample",
            "ATND",
            Carbon::createFromFormat('Y-m-d H:i:s', $start_date)->toIso8601String(),
            Carbon::createFromFormat('Y-m-d H:i:s', $stop_date)->toIso8601String(),
            $newStatusHistory
          );

          // Kirim spesimen ke SatuSehat dan update ServiceRequest ketika sampling selesai (is_done = 1)
          try {
            $this->sendSpecimenAndUpdateServiceRequest($id, $request, $start_date);

          } catch (\Exception $e) {
            // Log error tapi tidak gagalkan transaksi
            \Log::error('Error sending specimen and updating ServiceRequest to SatuSehat: ' . $e->getMessage(), [
              'permohonan_id' => $id,
              'exception' => $e->getTraceAsString()
            ]);
            // Tetap lanjutkan transaksi
          }
        }

        if ($request->get('verification_step') == 2){
          // Update Encounter dengan performer PPRF (Petugas pengolah sampel) ketika selesai
          try {
            $start_date = Carbon::createFromFormat('d/m/Y H:i', $requestStartDate)->format('Y-m-d H:i:s');
            $stop_date = Carbon::createFromFormat('d/m/Y H:i', $requestStopDate)->format('Y-m-d H:i:s');

            $newStatusHistory = [
              "status" => "in-progress",
              "period" => [
                "start" => Carbon::createFromFormat('Y-m-d H:i:s', $start_date)->toIso8601String(),
                "end" => Carbon::createFromFormat('Y-m-d H:i:s', $stop_date)->toIso8601String()
              ]
            ];

            \Log::info('Processing verification_step 2 - Adding PPRF performer to Encounter', [
              'permohonan_id' => $id,
              'nama_petugas' => $request->get('nama_petugas'),
              'start_date' => $start_date,
              'stop_date' => $stop_date
            ]);

            $this->updateEncounter(
              $id,
              $request->get('nama_petugas'),
              "in-progress",
              "Ruang Pengolah Sampel",
              "OBSENC",
              "Petugas pengolah sampel",
              "PPRF",
              Carbon::createFromFormat('Y-m-d H:i:s', $start_date)->toIso8601String(),
              Carbon::createFromFormat('Y-m-d H:i:s', $stop_date)->toIso8601String(),
              $newStatusHistory
            );
          } catch (\Exception $e) {
            // Log error tapi tidak gagalkan transaksi
            \Log::error('Error updating Encounter with PPRF performer: ' . $e->getMessage(), [
              'permohonan_id' => $id,
              'nama_petugas' => $request->get('nama_petugas'),
              'exception' => $e->getTraceAsString()
            ]);
            // Tetap lanjutkan transaksi
          }
        }

        if ($request->get('verification_step') == 3){

          // dd($request->get('start_date'));

          $start_date = Carbon::createFromFormat('d/m/Y H:i', $requestStartDate)->format('Y-m-d H:i:s');
          $stop_date = Carbon::createFromFormat('d/m/Y H:i', $requestStopDate)->format('Y-m-d H:i:s');

          $newStatusHistory = [
            "status" => "in-progress",
            "period" => [
              "start" => Carbon::createFromFormat('Y-m-d H:i:s', $start_date)->toIso8601String(),
              "end" => Carbon::createFromFormat('Y-m-d H:i:s', $stop_date)->toIso8601String()
            ]
          ];
          $this->updateEncounter(
            $id,
          $request->get('nama_petugas'),
            "in-progress",
            "Ruang Lab Klinik",
            "OBSENC",
            "Pemeriksaan Sample",
            "analyte",
            Carbon::createFromFormat('Y-m-d H:i:s', $start_date)->toIso8601String(),
            Carbon::createFromFormat('Y-m-d H:i:s', $stop_date)->toIso8601String(),
            $newStatusHistory
          );
        }

        if ($request->get('verification_step') == 4){

          $start_date = Carbon::createFromFormat('d/m/Y H:i', $requestStartDate)->format('Y-m-d H:i:s');
          $stop_date = Carbon::createFromFormat('d/m/Y H:i', $requestStopDate)->format('Y-m-d H:i:s');

          $this->finalizeKlinikVerificationStep4(
            $id,
            $request->get('nama_petugas'),
            $start_date ? Carbon::createFromFormat('Y-m-d H:i:s', $start_date)->format('d/m/Y H:i') : null,
            $data_verifikasi
          );

        }

        if ($request->get('verification_step') == 7){
          // Update Encounter dengan performer PRCP (Petugas penerimaan sampel) ketika selesai
          try {
            $start_date = Carbon::createFromFormat('d/m/Y H:i', $requestStartDate)->format('Y-m-d H:i:s');
            $stop_date = Carbon::createFromFormat('d/m/Y H:i', $requestStopDate)->format('Y-m-d H:i:s');

            $newStatusHistory = [
              "status" => "in-progress",
              "period" => [
                "start" => Carbon::createFromFormat('Y-m-d H:i:s', $start_date)->toIso8601String(),
                "end" => Carbon::createFromFormat('Y-m-d H:i:s', $stop_date)->toIso8601String()
              ]
            ];

            \Log::info('Processing verification_step 7 - Adding PRCP performer to Encounter', [
              'permohonan_id' => $id,
              'nama_petugas' => $request->get('nama_petugas'),
              'start_date' => $start_date,
              'stop_date' => $stop_date
            ]);

            $this->updateEncounter(
              $id,
              $request->get('nama_petugas'),
              "in-progress",
              "Ruang Penerimaan Sampel",
              "OBSENC",
              "Petugas penerimaan sampel",
              "PRCP",
              Carbon::createFromFormat('Y-m-d H:i:s', $start_date)->toIso8601String(),
              Carbon::createFromFormat('Y-m-d H:i:s', $stop_date)->toIso8601String(),
              $newStatusHistory
            );
          } catch (\Exception $e) {
            // Log error tapi tidak gagalkan transaksi
            \Log::error('Error updating Encounter with PRCP performer: ' . $e->getMessage(), [
              'permohonan_id' => $id,
              'nama_petugas' => $request->get('nama_petugas'),
              'exception' => $e->getTraceAsString()
            ]);
            // Tetap lanjutkan transaksi
          }
        }
      }else{
        // Tidak ada activity step 1 — tetap simpan dengan tanggal yang sudah dinormalisasi (termasuk HH:mm)
        $data_verifikasiQuery = VerificationActivitySample::where('is_klinik', $id)
          ->where('id_verification_activity', $request->get('verification_step'));
        if ((int) $request->get('verification_step') === 6) {
          $data_verifikasiQuery->where('resampling', $request->get('resampling') ?? 0);
        }
        $data_verifikasi = $data_verifikasiQuery->first();


        if(isset($data_verifikasi) && $data_verifikasi->is_done == 0){

          $data_verifikasi->start_date = Carbon::createFromFormat('d/m/Y H:i', $requestStartDate)->format('Y-m-d H:i:s');
          $data_verifikasi->stop_date = Carbon::createFromFormat('d/m/Y H:i', $requestStopDate)->format('Y-m-d H:i:s');
          $data_verifikasi->nama_petugas = $request->get('nama_petugas');
          if ($request->get('is_selesai') == 1) { $data_verifikasi->is_done = 1; }
          $data_verifikasi->save();

          $data_permohonan_uji_klinik = PermohonanUjiKlinik2::findOrFail($id);

          if($request->get('verification_step') == 3){ //Input / Output Hasil Px
            $data_permohonan_uji_klinik->name_analis_permohonan_uji_klinik =$request->get('nama_petugas');

            $data_permohonan_uji_klinik->save();
          }

        }else if(isset($data_verifikasi) && $data_verifikasi->is_done == 1){
          //update start date, stop date, nama petugas


          $data_verifikasi->start_date = Carbon::createFromFormat('d/m/Y H:i', $requestStartDate)->format('Y-m-d H:i:s');
          $data_verifikasi->stop_date =  Carbon::createFromFormat('d/m/Y H:i', $requestStopDate) ->format('Y-m-d H:i:s');
          $data_verifikasi->nama_petugas = $request->get('nama_petugas');

          $data_permohonan_uji_klinik = PermohonanUjiKlinik2::findOrFail($id);
          // dd($data_permohonan_uji_klinik);

          if($request->get('verification_step') == 1){ //registrasi
            $data_permohonan_uji_klinik->tglregister_permohonan_uji_klinik = Carbon::createFromFormat('d/m/Y H:i', $requestStartDate)->format('Y-m-d H:i:s');

            $data_permohonan_uji_klinik->save();
          }elseif($request->get('verification_step') == 6){ //sample
            $data_permohonan_uji_klinik->tgl_sampling_permohonan_uji_klinik = Carbon::createFromFormat('d/m/Y H:i', $requestStartDate)->format('Y-m-d');
            $data_permohonan_uji_klinik->jam_sampling_permohonan_uji_klinik =Carbon::createFromFormat('d/m/Y H:i', $requestStartDate)->format('H:i:s');
            $data_permohonan_uji_klinik->plebotomist_permohonan_uji_klinik = $request->get('nama_petugas');

            $data_permohonan_uji_klinik->save();
          }elseif($request->get('verification_step') == 3){ //Input / Output Hasil Px
            $data_permohonan_uji_klinik->tglpengujian_permohonan_uji_klinik = Carbon::createFromFormat('d/m/Y H:i', $requestStartDate)->format('Y-m-d H:i:s');
            $data_permohonan_uji_klinik->name_analis_permohonan_uji_klinik = $request->get('nama_petugas');

            $data_permohonan_uji_klinik->save();
          }

          $data_verifikasi->save();
        }else{
          //create (termasuk step 5 validasi)
          $verificationActivitySample = new VerificationActivitySample();
          $verificationActivitySample->id = Uuid::uuid4()->toString();
          $verificationActivitySample->id_verification_activity = $request->get('verification_step');
          $verificationActivitySample->start_date = Carbon::createFromFormat('d/m/Y H:i', $requestStartDate)->format('Y-m-d H:i:s');
          $verificationActivitySample->stop_date = Carbon::createFromFormat('d/m/Y H:i', $requestStopDate)->format('Y-m-d H:i:s');
          $verificationActivitySample->nama_petugas = $request->get('nama_petugas');
          if ((int) $request->get('verification_step') === 6) {
            $verificationActivitySample->resampling = $request->get('resampling') ?? 0;
          }
          $verificationActivitySample->is_klinik = $id;
          $verificationActivitySample->is_done = ($request->get('is_selesai') == 1) ? 1 : 0;

          $verificationActivitySample->save();
        }


      
      }

      // Side-effect step 5 (SatuSehat / WA / nomer lab) hanya saat Selesai.
      // Jangan gagalkan commit validasi jika integrasi eksternal error.
      if ((int) $request->get('verification_step') === 5 && (int) $request->get('is_selesai') === 1) {
        try {
          $conditions = [
            [
              "code" => "MN000001",
              "display" => "Stabil"
            ]
          ];

          $idConditions = $this->createCondition($id, $conditions);
          $diagnosis = [];

          if (count($idConditions) > 0) {
            foreach ($idConditions as $index => $idCondition) {
              $diagnosis[] = [
                "condition" => [
                  "reference" => "Condition/" . $idCondition,
                  "display" => "Pemeriksaan"
                ],
                "use" => [
                  "coding" => [
                    [
                      "system" => "http://terminology.hl7.org/CodeSystem/diagnosis-role",
                      "code" => "DD",
                      "display" => "Discharge diagnosis"
                    ]
                  ]
                ],
                "rank" => $index + 1
              ];
            }
          }

          $start_date = Carbon::createFromFormat('d/m/Y H:i', $requestStartDate)->format('Y-m-d H:i:s');
          $stop_date = Carbon::createFromFormat('d/m/Y H:i', $requestStopDate)->format('Y-m-d H:i:s');

          $newStatusHistory = [
            "status" => "finished",
            "period" => [
              "start" => Carbon::createFromFormat('Y-m-d H:i:s', $start_date)->toIso8601String(),
              "end" => Carbon::createFromFormat('Y-m-d H:i:s', $stop_date)->toIso8601String()
            ]
          ];

          if (count($diagnosis) > 0) {
            $this->updateEncounterFinished(
              $id,
              $request->get('nama_petugas'),
              "finished",
              "Ruang Lab Klinik",
              "OBSENC",
              "Validasi",
              "analyte",
              Carbon::createFromFormat('Y-m-d H:i:s', $start_date)->toIso8601String(),
              Carbon::createFromFormat('Y-m-d H:i:s', $stop_date)->toIso8601String(),
              $diagnosis,
              $newStatusHistory
            );
          }
        } catch (\Throwable $e) {
          \Log::error('Side-effect SatuSehat validasi (step 5) gagal: ' . $e->getMessage(), [
            'permohonan_id' => $id,
            'exception' => $e->getTraceAsString(),
          ]);
        }

        try {
          $data_permohonan_uji_klinik = PermohonanUjiKlinik2::findOrFail($id);
          $pasien = Pasien::find($data_permohonan_uji_klinik->pasien_permohonan_uji_klinik);

          if ($pasien && !empty($pasien->phone_pasien) && (int) ($data_permohonan_uji_klinik->kirim_hasil_whatsapp ?? 0) === 1) {
            $this->sendPdfHasilToPasien($id, $pasien);
          }
        } catch (\Throwable $e) {
          \Log::error('Kirim PDF WA setelah validasi gagal: ' . $e->getMessage(), ['permohonan_id' => $id]);
        }

        try {
          NomerLabSequence::assignKlinik($id);
        } catch (\Throwable $e) {
          \Log::error('Gagal assign nomer_lab klinik: ' . $e->getMessage(), ['id' => $id]);
        }
      }

      DB::commit();

      if ($request->post('is_selesai') == 1) {
        $statusMessage = ((int) $request->get('verification_step') === 5)
          ? 'Proses pengujian sudah selesai'
          : 'Verifikasi berhasil disimpan!';

        return redirect()->route('elits-permohonan-uji-klinik-2.verification', $id)
          ->with([
            'status' => $statusMessage,
            'status_popup' => 1,
          ]);
      }
      return redirect()->back()->with(['status' => 'Verifikasi berhasil disimpan!']);
    }catch (Exception $exception){
      DB::rollBack();
      return redirect()->back()->withErrors(['error' => $exception->getMessage()]);
    }

  }

  private function updateEncounter($idPermohonanUjiKlinik, $namaPetugas, $status, $ruangan, $class_code, $class_display, $coding_code, $startDate, $endDate, $newStatusHistory)
  {
    $permohonanUjiKlinik = PermohonanUjiKlinik2::query()->where('id_permohonan_uji_klinik', '=', $idPermohonanUjiKlinik)->first();

    if (isset($permohonanUjiKlinik)){
      if (isset($permohonanUjiKlinik->pasien->id_pasien_satu_sehat) and $permohonanUjiKlinik->pasien->id_pasien_satu_sehat != "" and isset($permohonanUjiKlinik->id_satu_sehat_encounter) and $permohonanUjiKlinik->id_satu_sehat_encounter != "") {
        if ( config('services.satu_sehat.version')=="prd") {
          $location_satusehat= SatuSehatLocation::where('name_satusehat_location',"LIKE",'%'.$ruangan.'%')->where('version_satusehat_location','prd')->first();

          // Normalize nama petugas untuk matching (hilangkan koma dari kedua sisi)
          $namaPetugas_normalized = str_replace(',', '', $namaPetugas);
          $practitioner_satusehat = SatuSehatPractitioner::whereRaw("REPLACE(name_petugas, ',', '') LIKE ?", ['%' . $namaPetugas_normalized . '%'])->first();

          // Jika tidak ditemukan dengan like, coba cari dari ms_petugas
          // Normalisasi nama di database juga (hilangkan koma) untuk perbandingan
          if (!$practitioner_satusehat) {
            $petugas = Petugas::whereRaw("REPLACE(REPLACE(nama, ',', ' '), '  ', ' ') LIKE ?", ['%' . $namaPetugas_normalized . '%'])->first();
            if ($petugas && !empty($petugas->code_satu_sehat_practitioner)) {
              $practitioner_satusehat = SatuSehatPractitioner::where('code_satu_sehat_practitioner', $petugas->code_satu_sehat_practitioner)->first();
            }
          }

          // Jika masih tidak ditemukan, coba cari dengan nama asli (dengan koma) dari ms_petugas
          if (!$practitioner_satusehat) {
            $petugas = Petugas::where('nama', 'like', '%' . $namaPetugas . '%')->first();
            if ($petugas && !empty($petugas->code_satu_sehat_practitioner)) {
              $practitioner_satusehat = SatuSehatPractitioner::where('code_satu_sehat_practitioner', $petugas->code_satu_sehat_practitioner)->first();
            }
          }

          $arrayStatusHistory = json_decode($permohonanUjiKlinik->encounter_json_satu_sehat, true);
          $statusHistory = $arrayStatusHistory['statusHistory'];

          $statusHistory[] = $newStatusHistory;

          $participants = $arrayStatusHistory["participant"];
          $display = $arrayStatusHistory["class"]["display"];

          // Tentukan practitioner reference dan display
          $practitionerReference = '';
          $practitionerDisplay = $namaPetugas; // Default: gunakan nama asli dari request (dengan koma jika ada)

          if ($practitioner_satusehat && !empty($practitioner_satusehat->code_satu_sehat_practitioner)) {
            $practitionerReference = "Practitioner/" . $practitioner_satusehat->code_satu_sehat_practitioner;
            // Gunakan name_petugas jika ada, jika tidak gunakan nama asli dari request
            $practitionerDisplay = !empty($practitioner_satusehat->name_satu_sehat_practitioner)
              ? $practitioner_satusehat->name_satu_sehat_practitioner
              : $namaPetugas;
          } else {
            // Jika practitioner tidak ditemukan, log warning tapi tetap tambahkan participant dengan nama asli
            \Log::warning('Practitioner SatuSehat not found for PRCP participant', [
              'permohonan_id' => $idPermohonanUjiKlinik,
              'nama_petugas' => $namaPetugas,
              'coding_code' => $coding_code
            ]);
            // Tetap tambahkan participant meskipun reference kosong (SatuSehat mungkin akan reject, tapi kita log dulu)
          }

          $participants[] = [
            "type" => [
              [
                "coding" => [
                  [
                    "system" => "http://terminology.hl7.org/CodeSystem/v3-ParticipationType",
                    "code" => $coding_code,
                    "display" => $class_display
                  ]
                ]
              ]
            ],
            "individual" => [
              "reference" => $practitionerReference,
              "display" => $practitionerDisplay
            ]
          ];

          \Log::info('Adding participant to Encounter', [
            'permohonan_id' => $idPermohonanUjiKlinik,
            'coding_code' => $coding_code,
            'class_display' => $class_display,
            'practitioner_reference' => $practitionerReference,
            'practitioner_display' => $practitionerDisplay,
            'total_participants' => count($participants)
          ]);

           $data = [
             "resourceType" => "Encounter",
             "id" => $permohonanUjiKlinik->id_satu_sehat_encounter,
             "identifier" => [
               [
                 "system" => "http://sys-ids.kemkes.go.id/encounter/".config('services.satu_sehat.org_id'),
                 "value" => $permohonanUjiKlinik->noregister_permohonan_uji_klinik
               ]
             ],
             "status" => $status,
             "class" => [
               "system" => "http://terminology.hl7.org/CodeSystem/v3-ActCode",
               "code" => $class_code,
               "display" => $display
             ],
             "subject" => [
               "reference" => "Patient/".$permohonanUjiKlinik->pasien->id_pasien_satu_sehat,
               "display" => $permohonanUjiKlinik->pasien->nama_pasien
             ],
             "participant" => $participants,
             "period" => [
               "start" => $startDate,
               "end" => $endDate
             ],
             "location" => [
               [
                 "location" => [
                   "reference" => "Location/".$location_satusehat->kode_satusehat_location,
                   "display" => $location_satusehat->name_satusehat_location
                 ]
               ]
             ],
             "statusHistory" => $statusHistory,
             "serviceProvider" => [
               "reference" => "Organization/".config('services.satu_sehat.org_id')
             ]
           ];

          $response = $this->satuSehatHelper->put('Encounter', $permohonanUjiKlinik->id_satu_sehat_encounter,$data);

          if ($response['status_code'] == '200') {
            $permohonanUjiKlinik->encounter_json_satu_sehat=json_encode($response['body']);
            $permohonanUjiKlinik->save();
          }else{
            throw new Exception("gagal update encounter, ". $response['body']['issue'][0]['details']['text']);
          }

        }
      }
    }
  }

  private function updateEncounterFinished($idPermohonanUjiKlinik, $namaPetugas, $status, $ruangan, $class_code, $class_display, $coding_code, $startDate, $endDate, $diagnosis, $newStatusHistory)
  {
    $permohonanUjiKlinik = PermohonanUjiKlinik2::query()->where('id_permohonan_uji_klinik', '=', $idPermohonanUjiKlinik)->first();

    if (isset($permohonanUjiKlinik)){
      if (isset($permohonanUjiKlinik->pasien->id_pasien_satu_sehat) and $permohonanUjiKlinik->pasien->id_pasien_satu_sehat != "" and isset($permohonanUjiKlinik->id_satu_sehat_encounter) and $permohonanUjiKlinik->id_satu_sehat_encounter != "") {
        if ( config('services.satu_sehat.version')=="prd") {
          $location_satusehat= SatuSehatLocation::where('name_satusehat_location',"LIKE",'%'.$ruangan.'%')->where('version_satusehat_location','prd')->first();

          // Normalize nama petugas untuk matching (hilangkan koma dari kedua sisi)
          $namaPetugas_normalized = str_replace(',', '', $namaPetugas);

          $practitioner_satusehat = SatuSehatPractitioner::whereRaw("REPLACE(name_petugas, ',', '') LIKE ?", ['%' . $namaPetugas_normalized . '%'])->first();

          // Jika tidak ditemukan dengan like, coba cari dari ms_petugas
          // Normalisasi nama di database juga (hilangkan koma) untuk perbandingan
          if (!$practitioner_satusehat) {
            $petugas = Petugas::whereRaw("REPLACE(REPLACE(nama, ',', ' '), '  ', ' ') LIKE ?", ['%' . $namaPetugas_normalized . '%'])->first();
            if ($petugas && !empty($petugas->code_satu_sehat_practitioner)) {
              $practitioner_satusehat = SatuSehatPractitioner::where('code_satu_sehat_practitioner', $petugas->code_satu_sehat_practitioner)->first();
            }
          }

          $arrayStatusHistory = json_decode($permohonanUjiKlinik->encounter_json_satu_sehat, true);
          $statusHistory = $arrayStatusHistory['statusHistory'];

          $statusHistory[] = $newStatusHistory;

          $participants = $arrayStatusHistory["participant"];
          $display = $arrayStatusHistory["class"]["display"];

          $participants[] = [
            "type" => [
              [
                "coding" => [
                  [
                    "system" => "http://terminology.hl7.org/CodeSystem/v3-ParticipationType",
                    "code" => $coding_code,
                    "display" => $class_display
                  ]
                ]
              ]
            ],
            "individual" => [
            "reference" => "Practitioner/".($practitioner_satusehat && isset($practitioner_satusehat->code_satu_sehat_practitioner) ? $practitioner_satusehat->code_satu_sehat_practitioner : ''),
            "display" => ($practitioner_satusehat && isset($practitioner_satusehat->name_satu_sehat_practitioner) ? $practitioner_satusehat->name_satu_sehat_practitioner : $namaPetugas)
            ]
          ];

          $data = [
            "resourceType" => "Encounter",
            "id" => $permohonanUjiKlinik->id_satu_sehat_encounter,
            "identifier" => [
              [
                "system" => "http://sys-ids.kemkes.go.id/encounter/".config('services.satu_sehat.org_id'),
                "value" => $permohonanUjiKlinik->noregister_permohonan_uji_klinik
              ]
            ],
            "status" => $status,
            "class" => [
              "system" => "http://terminology.hl7.org/CodeSystem/v3-ActCode",
              "code" => $class_code,
              "display" => $display
            ],
            "subject" => [
              "reference" => "Patient/".$permohonanUjiKlinik->pasien->id_pasien_satu_sehat,
              "display" => $permohonanUjiKlinik->pasien->nama_pasien
            ],
            "participant" => $participants,
            "period" => [
              "start" => $startDate,
              "end" => $endDate
            ],
            "location" => [
              [
                "location" => [
                  "reference" => "Location/".$location_satusehat->kode_satusehat_location,
                  "display" => $location_satusehat->name_satusehat_location
                ]
              ]
            ],
            "diagnosis" => $diagnosis,
            "statusHistory" => $statusHistory,
            "serviceProvider" => [
              "reference" => "Organization/".config('services.satu_sehat.org_id')
            ]
          ];


          $response = $this->satuSehatHelper->put('Encounter', $permohonanUjiKlinik->id_satu_sehat_encounter, $data);

          if ($response['status_code'] == '200') {
            $permohonanUjiKlinik->encounter_json_satu_sehat=json_encode($response['body']);
            $permohonanUjiKlinik->save();
          }else{
            throw new Exception("gagal update encounter, ". $response['body']['issue'][0]['details']['text']);
          }

        }
      }
    }
  }

  private function createCondition($idPermohonanUjiKlinik, $conditions = [])
  {
    $permohonanUjiKlinik = PermohonanUjiKlinik2::query()->where('id_permohonan_uji_klinik', '=', $idPermohonanUjiKlinik)->first();

    if (isset($permohonanUjiKlinik) and isset($permohonanUjiKlinik->id_satu_sehat_encounter) and $permohonanUjiKlinik->id_satu_sehat_encounter != ""){

      $encounter = json_decode($permohonanUjiKlinik->encounter_json_satu_sehat, true);
      $encounterDisplay = $encounter['class']['display'] ?? '-';

      $idConditions = [];
      foreach ($conditions as $condition){
        $data = [
          "resourceType" => "Condition",
          "clinicalStatus" => [
            "coding" => [
              [
                "system" => "http://terminology.hl7.org/CodeSystem/condition-clinical",
                "code" => "active",
                "display" => "Active"
              ]
            ]
          ],
          "category" => [
            [
              "coding" => [
                [
                  "system" => "http://terminology.hl7.org/CodeSystem/condition-category",
                  "code" => "encounter-diagnosis",
                  "display" => "Encounter Diagnosis"
                ]
              ]
            ]
          ],
          "code" => [
            "coding" => [
              [
                "system" => "http://terminology.kemkes.go.id/CodeSystem/clinical-term",
                "code" => $condition["code"],
                "display" => $condition["display"]
              ]
            ]
          ],
          "subject" => [
            "reference" => "Patient/".$permohonanUjiKlinik->pasien->id_pasien_satu_sehat,
            "display" => $permohonanUjiKlinik->pasien->nama_pasien
          ],
          "encounter" => [
            "reference" => "Encounter/".$permohonanUjiKlinik->id_satu_sehat_encounter,
            "display" => $encounterDisplay
          ]
        ];

        $response = $this->satuSehatHelper->post('Condition', $data);

        if ($response['status_code'] == '201'){
          $idConditions[] = $response["body"]["id"];
        }
      }

      return $idConditions;

    }

    return [];

  }

  public function print_verifikasi($id, Request $request)
  {
    $item = PermohonanUjiKlinik2::find($id);
    
    // Simpan pengaturan showKop saja (kolom ini memang ada di tabel).
    // Pengaturan fontsize & padding hanya dipakai per-request, tidak disimpan ke database.
    if ($request->has('showKop')) {
      $item->show_kop_hasil_permohonan_uji_klinik = $request->showKop == '1' || $request->showKop == 'on' ? 1 : 0;
      $item->save();
    }
    
    // Ambil pengaturan dari database atau request
    $showKop = isset($request->showKop)
      ? (($request->showKop == '1' || $request->showKop == 'on') ? 1 : 0)
      : ($item->show_kop_hasil_permohonan_uji_klinik ?? 1);

    // fontsize & padding: gunakan nilai dari request jika ada, jika tidak fallback ke default
    $fontsize = isset($request->fontsize) ? (float)$request->fontsize : 12.0;
    $padding  = isset($request->padding) ? (float)$request->padding : 5.0;
    
    if ($item && isset($item->tglregister_permohonan_uji_klinik)) {
      try {
        $tgl_register = Carbon::createFromFormat('Y-m-d H:i:s', $item->tglregister_permohonan_uji_klinik);
      } catch (\Exception $e) {
        $tgl_register = Carbon::now();
      }
    } else {
      $tgl_register = Carbon::now();
    }

    $url = config("app.url");
    if (config("app.env") == "local"){
      $url .= ":8000";
    }
    $url .= "/elits-signature/progress/".$id."/1";
    $result = Builder::create()
      ->data($url)
      ->encoding(new Encoding('UTF-8'))
      ->errorCorrectionLevel(new ErrorCorrectionLevelHigh())
      // ->logoPath( asset('assets/admin/images/logo/logo-silaboy.png'))
      ->size(600)
      ->margin(2)
      ->build();
    $qrBase64 = base64_encode($result->getString());

    $verificationActivitySamples = VerificationActivitySample::where('is_klinik', $id)->where('resampling', 0)->get();
    $listVerifications = [];

    if (isset($request->tanggal_cetak_verifikasi)){
      // Handle both Y-m-d (from date input) and d/m/Y formats
      try {
        if (strpos($request->tanggal_cetak_verifikasi, '/') !== false) {
      $date = DateTime::createFromFormat('d/m/Y', $request->tanggal_cetak_verifikasi);
      $formattedDate = $date->format('Y-m-d');
        } else {
          $formattedDate = $request->tanggal_cetak_verifikasi;
        }
      $datePrintVerification = $formattedDate;
      } catch (\Exception $e) {
        $datePrintVerification = Carbon::now()->toDateString();
      }
    }else{
      $datePrintVerification = Carbon::now()->toDateString();
    }

    if (isset($request->signOption) and $request->signOption == 0){
      foreach ($verificationActivitySamples as  $verificationActivitySample){
        $listVerifications[$verificationActivitySample->id_verification_activity] = $verificationActivitySample;
      }

      $signOption = 0;

      $pdf = PDF::loadView('masterweb::module.admin.laboratorium.permohonan-uji-klinik-2.formatPrint.print_verifikasi', compact('item','listVerifications', 'datePrintVerification', 'signOption', 'showKop', 'fontsize', 'padding'));

      return $pdf->stream();
    }


    $dataPetugasBSRE = [];
    foreach ($verificationActivitySamples as  $verificationActivitySample){
      $listVerifications[$verificationActivitySample->id_verification_activity] = $verificationActivitySample;

      $petugas = Petugas::query()->where('nama', '=', $verificationActivitySample->nama_petugas)->get()->first();
      if (isset($petugas)){
        $dataPetugasBSRE[] = [
          'nik' => $petugas->nik,
          'passPhrase' => $petugas->password,
          'tampilan' => 'invisible',
          'reason' => "hasil12121",
          'location' => "boyolali",
          'text' => "hasil22323"
        ];
      }
    }

    if (count($listVerifications) == 7 and count($dataPetugasBSRE) == 7){
      $pdf = PDF::loadView('masterweb::module.admin.laboratorium.permohonan-uji-klinik-2.formatPrint.print_verifikasi', compact('item','listVerifications', 'datePrintVerification', 'qrBase64', 'showKop', 'fontsize', 'padding'));

      $signBSRE = Smt::signBSRE($pdf, $dataPetugasBSRE);

      if (isset($signBSRE["status"]) and $signBSRE["status"] == "success" and isset($signBSRE["data"]) and $signBSRE["data"]["status"] == 200){
        $data =  base64_encode($signBSRE["data"]["file"]);

        return view('masterweb::module.admin.laboratorium.permohonan-uji-klinik-2.formatPrint.blob',
          compact('data')
        );
      }elseif ($signBSRE['status'] == 500){
        return redirect()->back()->with('error-verifikasi', 'errors');
      }else{
        return redirect()->back()->with('error-bsre', 'Dokumen belum bisa ditanda tangani secara elektronik. Harap cek kembali kredensial tanda tangan elektronik untuk setiap petugas!');
      }
    }else{
      if (count($listVerifications) < 7){
        return redirect()->back()->with('error-bsre', 'Dokumen belum bisa ditanda tangani secara elektronik. Harap selesaikan seluruh step verifikasi!');
      }

      if (count($dataPetugasBSRE) < 7){
        return redirect()->back()->with('error-bsre', 'Kredensial untuk tanda tangan elektronik belum lengkap. Harap lengkapi kredensial seluruh petugas!');
      }
    }

    $signOption = 0;
    $pdf = PDF::loadView('masterweb::module.admin.laboratorium.permohonan-uji-klinik-2.formatPrint.print_verifikasi', compact('item','listVerifications', 'datePrintVerification', 'signOption', 'showKop', 'fontsize', 'padding'));

    return $pdf->stream();
  }

  public function createPermohonanUjiSample($id_permohonan_uji_klinik,$count=1)
  {
    $item_permohonan_uji_klinik = PermohonanUjiKlinik2::find($id_permohonan_uji_klinik);

    if ($item_permohonan_uji_klinik
        && (int) $count <= 1
        && ($item_permohonan_uji_klinik->mode_pengambilan_sampel ?? '') === 'dibawa_pelanggan') {
      $this->ensureDibawaPelangganPengambilSampleSkipped($id_permohonan_uji_klinik);
      return redirect()
        ->route('elits-permohonan-uji-klinik-2.create-penerima-sampel', $id_permohonan_uji_klinik)
        ->with('status', 'Sampel dibawa pelanggan sendiri. Pengambilan sampel dilewati, silakan lanjut penerimaan sampel.');
    }

    $resamplingIndex = (int) $count - 1;
    $item_pengambilan_sample = PengambilanSampleKlinik::where('permohonan_uji_klinik_id', $id_permohonan_uji_klinik)
      ->where(function ($q) use ($resamplingIndex) {
        $q->where('resampling', $resamplingIndex);
        if ($resamplingIndex === 0) {
          $q->orWhereNull('resampling');
        }
      })
      ->whereNull('deleted_at')
      ->orderBy('created_at', 'desc')
      ->first();


    if (isset($item_pengambilan_sample)) {
      # code...
      $item_pengambilan_sample=$item_pengambilan_sample;
      }else{
      $item_pengambilan_sample=null;
    }



    $tgl_register = Carbon::createFromFormat('Y-m-d H:i:s', $item_permohonan_uji_klinik->tglregister_permohonan_uji_klinik)->isoFormat('D MMMM Y');

    // Auto-detect jenis sampel dari parameter (haji → jenis_sampel_haji, non-haji → jenis_sampel)
    $auto_jenis_sampel = [];
    $auto_tindakan_medis_khusus = [];
    try {
      $auto_jenis_sampel = \Smt\Masterweb\Helpers\Smt::getJenisSampelFromParameter($id_permohonan_uji_klinik, null);
      $auto_tindakan_medis_khusus = \Smt\Masterweb\Helpers\Smt::mapJenisSampelToTindakanMedis($auto_jenis_sampel);
    } catch (\Throwable $e) {
      // swallow - defaults are fine
    }

    $is_permohonan_haji = (int) ($item_permohonan_uji_klinik->is_haji ?? 0) === 1;

    //ambil data verifikasi sample pendaftaran/registrasi
    $resamplingIndex = max(0, (int) $count - 1);
    $data_verifikasi_registrasi = VerificationActivitySample::where('is_klinik', $id_permohonan_uji_klinik)
      ->where('id_verification_activity', 6)
      ->where(function ($q) use ($resamplingIndex) {
        $q->where('resampling', $resamplingIndex);
        if ($resamplingIndex === 0) {
          $q->orWhereNull('resampling');
        }
      })
      ->orderBy('start_date', 'desc')
      ->first();



    //set tgl pengujian ditambah 1 jam dari stop date sample analitik



    // dd($startHour);
    if (isset($item_pengambilan_sample)) {
      # code...
      if ($item_pengambilan_sample->kondisi_pasien !== null) {
        $kondisi_pasien = $item_pengambilan_sample->kondisi_pasien;
    } else {
      $kondisi_pasien = '';
    }

      if ($item_pengambilan_sample->jenis_sample !== null) {
      // Decode JSON jika berbentuk array, atau convert string ke array
        $jenis_sampel_raw = $item_pengambilan_sample->jenis_sample;
      $jenis_sampel = is_string($jenis_sampel_raw) ? json_decode($jenis_sampel_raw, true) : $jenis_sampel_raw;
      // Jika hasil decode bukan array atau null, buat jadi array dengan satu elemen
      if (!is_array($jenis_sampel)) {
        $jenis_sampel = !empty($jenis_sampel_raw) ? [$jenis_sampel_raw] : [];
      }
    } else {
      $jenis_sampel = [];
    }

      if ($item_pengambilan_sample->status_sampling !== null) {
        $status_sampling = $item_pengambilan_sample->status_sampling;
    } else {
      $status_sampling = '';
    }

    // Get sampling ulang data

      if($item_pengambilan_sample->tindakan_medis_khusus!== null){
        // Parse tindakan_medis_khusus - bisa array, JSON string, atau string biasa
        $tindakan_raw = $item_pengambilan_sample->tindakan_medis_khusus;
        if (is_string($tindakan_raw) && !empty($tindakan_raw)) {
            $decoded = json_decode($tindakan_raw, true);
            $tindakan_medis_khusus = ($decoded !== null && is_array($decoded)) ? $decoded : [$tindakan_raw];
        } elseif (is_array($tindakan_raw)) {
            $tindakan_medis_khusus = $tindakan_raw;
        } else {
            $tindakan_medis_khusus = [];
        }
    } else {
        $tindakan_medis_khusus = [];
      }
      if($item_pengambilan_sample->resample_reason!== null){
        $resample_reason = $item_pengambilan_sample->resample_reason;
      } else {
        $resample_reason = '';
      }
    }else{
      $kondisi_pasien = '';
      $jenis_sampel = [];
      $status_sampling = '';
      $tindakan_medis_khusus = [];
      $resample_reason = '';

    }




    $optionPlebotomist = SatuSehatPractitioner::query()->where('type', '!=', 'adm')->select(['name_petugas'])->get();



    // siapkan daftar petugas pengambil sample dari ms_petugas (role 6 + lab klinik)
    // fallback ke konfigurasi verifikasi step 6/5 jika ms_petugas kosong
    $petugas_pengambil_sample = $this->getPetugasPengambilKlinik();
    if (empty($petugas_pengambil_sample)) {
      $config = VerificationActivity::all();
      foreach ($config as $cfg) {
        if ((int)$cfg->id_verification_activity === 6 || (int)$cfg->id_verification_activity === 5) {
          if (!empty($cfg->klinik)) {
            $petugas_pengambil_sample = array_merge($petugas_pengambil_sample, array_map('trim', explode(', ', $cfg->klinik)));
          }
        }
      }
      $petugas_pengambil_sample = array_values(array_unique(array_filter($petugas_pengambil_sample)));
    }

    // Pre-fill jam_sampling from existing VerificationActivitySample step 6 or PengambilanSampleKlinik
    $jam_sampling = null;
    if ($data_verifikasi_registrasi && $data_verifikasi_registrasi->start_date) {
      $jam_sampling = Carbon::parse($data_verifikasi_registrasi->start_date)->format('Y-m-d H:i');
    } elseif (
      $item_permohonan_uji_klinik
      && !empty($item_permohonan_uji_klinik->tgl_sampling_permohonan_uji_klinik)
      && !empty($item_permohonan_uji_klinik->jam_sampling_permohonan_uji_klinik)
    ) {
      $jam_sampling = Carbon::parse(
        $item_permohonan_uji_klinik->tgl_sampling_permohonan_uji_klinik . ' ' .
        $item_permohonan_uji_klinik->jam_sampling_permohonan_uji_klinik
      )->format('Y-m-d H:i');
    } elseif (isset($item_pengambilan_sample) && $item_pengambilan_sample && $item_pengambilan_sample->time_sampling) {
      $jam_sampling = Carbon::parse($item_pengambilan_sample->time_sampling)->format('Y-m-d H:i');
    }

    $prefill_jam_sampling = null;
    $prefill_petugas = null;
    if (request()->filled('jam_sampling')) {
      $rawJam = trim((string) request()->query('jam_sampling'));
      try {
        if (preg_match('/^\d{2}\/\d{2}\/\d{4} \d{1,2}:\d{2}$/', $rawJam)) {
          $prefill_jam_sampling = Carbon::createFromFormat('d/m/Y H:i', $rawJam)->format('Y-m-d H:i');
        } elseif (preg_match('/^\d{4}-\d{2}-\d{2} \d{1,2}:\d{2}/', $rawJam)) {
          $prefill_jam_sampling = Carbon::parse($rawJam)->format('Y-m-d H:i');
        } elseif (preg_match('/^\d{1,2}:\d{2}$/', $rawJam)) {
          $prefill_jam_sampling = DateHelper::clockOnRegisterDate(
            DateHelper::permohonanAnchorAt($item_permohonan_uji_klinik),
            $rawJam
          )->format('Y-m-d H:i');
        }
        if ($prefill_jam_sampling) {
          $jam_sampling = $prefill_jam_sampling;
        }
      } catch (\Throwable $e) {
      }
    }
    if (request()->has('nama_petugas_pengambil') && request()->query('nama_petugas_pengambil') !== '') {
      $prefill_petugas = trim((string) request()->query('nama_petugas_pengambil'));
      if ($prefill_petugas) {
        $found = false;
        foreach ($petugas_pengambil_sample as $nama) {
          if (strcasecmp(trim($nama), $prefill_petugas) === 0) {
            $prefill_petugas = $nama;
            $found = true;
            break;
          }
        }
        if (!$found) {
          $petugas_pengambil_sample[] = $prefill_petugas;
        }
      }
    }

    if (empty($prefill_petugas) && $data_verifikasi_registrasi && !empty($data_verifikasi_registrasi->nama_petugas)) {
      $prefill_petugas = $data_verifikasi_registrasi->nama_petugas;
    }
    if (empty($prefill_petugas) && $item_permohonan_uji_klinik && !empty($item_permohonan_uji_klinik->plebotomist_permohonan_uji_klinik)) {
      $prefill_petugas = $item_permohonan_uji_klinik->plebotomist_permohonan_uji_klinik;
      if (!in_array($prefill_petugas, $petugas_pengambil_sample, true)) {
        $petugas_pengambil_sample[] = $prefill_petugas;
      }
    }

    // Ikuti jenis sampel dari parameter satuan:
    // - Haji: SELALU dari jenis_sampel_haji (fallback jenis_sampel) agar form sampling menyesuaikan
    // - Non-haji: pakai yang tersimpan; jika kosong baru auto dari parameter
    if ($is_permohonan_haji && !empty($auto_jenis_sampel)) {
      $jenis_sampel = $auto_jenis_sampel;
      if (empty($tindakan_medis_khusus) && !empty($auto_tindakan_medis_khusus)) {
        $tindakan_medis_khusus = $auto_tindakan_medis_khusus;
      } elseif ($is_permohonan_haji && !empty($auto_tindakan_medis_khusus)) {
        // Selaraskan tindakan medis dengan jenis sampel haji dari parameter
        $tindakan_medis_khusus = \Smt\Masterweb\Helpers\Smt::reconcileTindakanMedisWithJenisSampel(
          is_array($tindakan_medis_khusus) ? $tindakan_medis_khusus : [],
          $auto_jenis_sampel
        );
      }
    } elseif (empty($jenis_sampel) && !empty($auto_jenis_sampel)) {
      $jenis_sampel = $auto_jenis_sampel;
    }

    return view('masterweb::module.admin.laboratorium.permohonan-uji-klinik-2.sample-permohonan-uji-paramater-klinik', [
