  /**
   * Normalisasi input jam/tanggal pengambilan sampel ke format Y-m-d H:i.
   * Jam saja (HH:mm) menempel ke tanggal registrasi, bukan hari ini.
   */
  protected function normalizeJamSamplingInput(?string $raw, $registerAt = null): ?string
  {
    if ($raw === null || trim($raw) === '') {
      return null;
    }
    $raw = trim($raw);
    try {
      if (preg_match('/^\d{2}\/\d{2}\/\d{4}/', $raw)) {
        foreach (['d/m/Y H:i', 'd/m/Y G:i'] as $fmt) {
          try {
            return Carbon::createFromFormat($fmt, $raw)->format('Y-m-d H:i');
          } catch (\Throwable $e) {
          }
        }
      }
      if (preg_match('/^\d{4}-\d{2}-\d{2}/', $raw)) {
        return Carbon::parse($raw)->format('Y-m-d H:i');
      }
      if (preg_match('/^\d{1,2}:\d{2}$/', $raw)) {
        return DateHelper::clockOnRegisterDate($registerAt, $raw)->format('Y-m-d H:i');
      }
      return Carbon::parse($raw)->format('Y-m-d H:i');
    } catch (\Throwable $e) {
      return null;
    }
  }

  /**
   * Simpan meta pengambil sample dari halaman verifikasi (sebelum buka halaman Input).
   */
  public function savePengambilSampleMeta(Request $request, string $id)
  {
    $count = (int) $request->input('count', 1);

    $rawJam = trim((string) ($request->input('jam_sampling') ?: $request->input('start_date') ?: ''));
    $rawPetugas = trim((string) ($request->input('nama_petugas_pengambil') ?: $request->input('nama_petugas') ?: ''));

    if ($rawJam === '' || $rawPetugas === '') {
      return response()->json([
        'status' => false,
        'pesan'  => 'Tanggal/jam dan nama petugas pengambil sampel wajib diisi.',
      ], 422);
    }

    $item = PermohonanUjiKlinik2::find($id);
    $jamNormalized = $this->normalizeJamSamplingInput(
      $rawJam,
      $item ? DateHelper::permohonanAnchorAt($item) : null
    );
    if (!$jamNormalized) {
      return response()->json([
        'status' => false,
        'pesan'  => 'Format tanggal/jam tidak valid.',
      ], 422);
    }

    $internal = Request::create('/', 'POST', [
      'jam_sampling'           => $jamNormalized,
      'nama_petugas_pengambil' => $rawPetugas,
      'tgl_sampling'           => substr($jamNormalized, 0, 10),
    ]);

    DB::beginTransaction();
    try {
      $this->upsertVerificationPengambilSample($internal, $id, $count, false);

      $item = PermohonanUjiKlinik2::findOrFail($id);
      $dt = Carbon::createFromFormat('Y-m-d H:i', $jamNormalized);
      $item->tgl_sampling_permohonan_uji_klinik = $dt->format('Y-m-d');
      $item->jam_sampling_permohonan_uji_klinik = $dt->format('H:i:s');
      $item->plebotomist_permohonan_uji_klinik = $rawPetugas;
      $item->save();

      $resamplingIndex = max(0, $count - 1);
      $saved = VerificationActivitySample::where('is_klinik', $id)
        ->where('id_verification_activity', 6)
        ->where(function ($q) use ($resamplingIndex) {
          $q->where('resampling', $resamplingIndex);
          if ($resamplingIndex === 0) {
            $q->orWhereNull('resampling');
          }
        })
        ->orderBy('start_date', 'desc')
        ->first();

      if (!$saved || empty($saved->start_date) || empty($saved->nama_petugas)) {
        throw new \RuntimeException('Data verifikasi pengambil sample gagal disimpan ke database.');
      }

      DB::commit();

      return response()->json([
        'status' => true,
        'pesan'  => 'Data pengambil sampel berhasil disimpan.',
        'jam_sampling' => $jamNormalized,
        'nama_petugas_pengambil' => $rawPetugas,
      ]);
    } catch (\Throwable $e) {
      DB::rollBack();
      return response()->json([
        'status' => false,
        'pesan'  => $e->getMessage(),
      ], 500);
    }
  }

  /**
   * Simpan/update VerificationActivitySample step 6 (jam & petugas pengambil sample).
   */
  protected function upsertVerificationPengambilSample(Request $request, string $id_permohonan_uji_klinik, int $count, bool $markDone = false): void
  {
    $jamSampling   = $request->input('jam_sampling');
    $petugasSampel = $request->input('nama_petugas_pengambil');

    if (empty($jamSampling) && empty($petugasSampel)) {
      return;
    }

    $resamplingIndex = max(0, $count - 1);
    $verifikasiSampel = VerificationActivitySample::where('is_klinik', $id_permohonan_uji_klinik)
      ->where('id_verification_activity', 6)
      ->where(function ($q) use ($resamplingIndex) {
        $q->where('resampling', $resamplingIndex);
        if ($resamplingIndex === 0) {
          $q->orWhereNull('resampling');
        }
      })
      ->orderBy('start_date', 'desc')
      ->first();

    $permohonanPengambil = PermohonanUjiKlinik2::find($id_permohonan_uji_klinik);
    $baseDate = $request->input('tgl_sampling')
      ?: DateHelper::clockOnRegisterDate(
        $permohonanPengambil ? $permohonanPengambil->tglregister_permohonan_uji_klinik : null
      )->format('Y-m-d');
    $sampelStart = null;
    $sampelStop  = null;

    if (!empty($jamSampling)) {
      try {
        if (preg_match('/^\d{4}-\d{2}-\d{2} \d{1,2}:\d{2}$/', $jamSampling)) {
          $sampelStart = Carbon::createFromFormat('Y-m-d H:i', $jamSampling)->format('Y-m-d H:i:s');
        } else {
          $sampelStart = Carbon::createFromFormat('Y-m-d H:i', $baseDate . ' ' . $jamSampling)->format('Y-m-d H:i:s');
        }
        $sampelStop = Carbon::createFromFormat('Y-m-d H:i:s', $sampelStart)->addMinutes(10)->format('Y-m-d H:i:s');
      } catch (\Exception $e) {
        $sampelStart = Carbon::parse($jamSampling)->format('Y-m-d H:i:s');
        $sampelStop  = Carbon::parse($sampelStart)->addMinutes(10)->format('Y-m-d H:i:s');
      }
    }

    $petugasFormatted = !empty($petugasSampel) ? trim((string) $petugasSampel) : null;

    if ($verifikasiSampel) {
      if ($verifikasiSampel->resampling === null) {
        $verifikasiSampel->resampling = $resamplingIndex;
      }
      if ($sampelStart)      { $verifikasiSampel->start_date   = $sampelStart; }
      if ($sampelStop)       { $verifikasiSampel->stop_date    = $sampelStop; }
      if ($petugasFormatted) { $verifikasiSampel->nama_petugas = $petugasFormatted; }
      if ($markDone || $request->is_selesai == 1) {
        $verifikasiSampel->is_done = 1;
      }
      $verifikasiSampel->save();
    } else {
      $verifikasiSampelBaru = new VerificationActivitySample();
      $verifikasiSampelBaru->id                       = Uuid::uuid4()->toString();
      $verifikasiSampelBaru->id_verification_activity = 6;
      $verifikasiSampelBaru->start_date               = $sampelStart;
      $verifikasiSampelBaru->stop_date                = $sampelStop;
      $verifikasiSampelBaru->nama_petugas             = $petugasFormatted;
      $verifikasiSampelBaru->is_klinik                = $id_permohonan_uji_klinik;
      $verifikasiSampelBaru->is_done                  = ($markDone || $request->is_selesai == 1) ? 1 : 0;
      $verifikasiSampelBaru->resampling               = $resamplingIndex;
      $verifikasiSampelBaru->save();
    }
  }

