        // Jika data tidak ditemukan, kembalikan respon error
        if (!$post) {
            return response()->json(['status' => false, 'pesan' => "Data permohonan uji klinik tidak ditemukan!"], 404);
        }

        // Validasi required fields
        if (empty($request->kondisi_pasien)){
          return response()->json(['status' => false, 'pesan' => "Kondisi pasien wajib diisi!"], 200);
        }

        if (empty($request->jenis_sampel)){
          return response()->json(['status' => false, 'pesan' => "Jenis sampel wajib diisi!"], 200);
        }

        if (empty($request->status_sampling)){
          return response()->json(['status' => false, 'pesan' => "Status sampling wajib diisi!"], 200);
        }

        if ($request->is_selesai == 1) {
          if (empty($request->jam_sampling)) {
            return response()->json(['status' => false, 'pesan' => "Tanggal dan jam pengambilan sampel wajib diisi!"], 200);
          }
          if (empty($request->nama_petugas_pengambil)) {
            return response()->json(['status' => false, 'pesan' => "Nama petugas pengambil sampel wajib diisi!"], 200);
          }
        }

        // Format dan simpan data dari request ke dalam model
        // $post->kondisi_pasien = $request->kondisi_pasien;
        // // Simpan jenis_sampel sebagai JSON karena bisa multiple
        // $post->jenis_sampel = is_array($request->jenis_sampel) ? json_encode($request->jenis_sampel) : $request->jenis_sampel;
        // $post->status_sampling = $request->status_sampling;

        // // Optional: simpan tanggal dan jam sampling utama bila disediakan
        // if (!empty($request->tgl_sampling)) {
        //   $post->tgl_sampling_permohonan_uji_klinik = $request->tgl_sampling;
        // }
        // if (!empty($request->jam_sampling)) {
        //   $post->jam_sampling_permohonan_uji_klinik = $request->jam_sampling;
        // }

        // Tentukan tindakan medis khusus
        // $tindakan_medis_khusus = $request->post('tindakan_medis_khusus');
        // if ($tindakan_medis_khusus === 'Lainnya') {
        //   $tindakan_medis_khusus = $request->post('tindakan_medis_khusus_lainnya');
        // }

        // $post->tindakan_medis_khusus = $tindakan_medis_khusus;

        // // Simpan data sampling ulang sebagai JSON
        // if ($request->has('sampling_ulang') && is_array($request->sampling_ulang)) {
        //   // Normalisasi nilai tanggal/waktu sampling ulang bila ada
        //   $normalized = array_map(function($item) {
        //     return [
        //       'kondisi_pasien' => $item['kondisi_pasien'] ?? null,
        //       'jenis_sampel' => $item['jenis_sampel'] ?? null,
        //       'status' => $item['status'] ?? null,
        //       'tanggal' => $item['tanggal'] ?? null,
        //       'waktu' => $item['waktu'] ?? null,
        //     ];
        //   }, $request->sampling_ulang);

        //   $post->sampling_ulang = json_encode($normalized);
        // } else {
        //   $post->sampling_ulang = null;
        // }

        // $simpan = $post->save();

        // catat pengambilan awal (resampling=0) jika bukan gagal
        // if (strtolower($request->status_sampling) !== 'gagal') {
        //   try {
        //     $existing = \Smt\Masterweb\Models\PengambilanSampleKlinik::where('permohonan_uji_klinik_id', $id_permohonan_uji_klinik)
        //       ->where('resampling', 0)
        //       ->first();
        //     if (!$existing) {
        //       \Smt\Masterweb\Models\PengambilanSampleKlinik::create([
        //         'id_pengambilan_sample_klinik' => \Ramsey\Uuid\Uuid::uuid4()->toString(),
        //         'permohonan_uji_klinik_id' => $id_permohonan_uji_klinik,
        //         'jenis_sample' => is_array($post->jenis_sampel) ? json_encode($post->jenis_sampel) : ($post->jenis_sampel ?? null),
        //         'volume_sample' => null,
        //         'signature_pengambil_sample_petugas' => null,
        //         'signature_pengambil_sample_pasien' => null,
        //         'tindakan_medis_khusus' => $post->tindakan_medis_khusus ?? null,
        //         'id_spesimen_satu_sehat' => null,
        //         'pasien_permohonan_uji_klinik' => $post->pasien_permohonan_uji_klinik ?? null,
        //         'resampling' => 0,
        //         'petugas_name' => $post->plebotomist_permohonan_uji_klinik ?? null,
        //         'petugas_id' => null,
        //         'created_at' => now(),
        //         'updated_at' => now(),
        //       ]);
        //     }
        //   } catch (\Throwable $e) {
        //     // ignore if table not yet available or other issues
        //   }
        // }

        // Jika sampling gagal dan user isi resampling, tambahkan verifikasi step 6 (Pengambil Sample)

        // Kirim ke SatuSehat (baik berhasil maupun gagal)
        try {
          // Refresh pengambilan_sample_klinik untuk mendapatkan data terbaru
          if (isset($pengambilan_sample_klinik) && is_object($pengambilan_sample_klinik)) {
            $pengambilan_sample_klinik->refresh();
          }
          $this->sendSpecimenToSatuSehat($item_permohonan_uji_klinik, $request, $pengambilan_sample_klinik ?? null);
        } catch (\Exception $e) {
          // Log error tapi tidak gagalkan transaksi
          \Log::error('Error sending specimen to SatuSehat: ' . $e->getMessage(), [
            'permohonan_id' => $id_permohonan_uji_klinik,
            'exception' => $e->getTraceAsString()
          ]);
          // Tetap lanjutkan commit transaksi
        }

        $this->upsertVerificationPengambilSample($request, $id_permohonan_uji_klinik, (int) $count, $request->is_selesai == 1);

        // Commit transaksi jika semua berhasil
        DB::commit();

        return response()->json(['status' => true, 'pesan' => "Data permohonan uji klinik untuk sample berhasil diubah!"], 200);

    // } catch (\Exception $e) {
