}

  /**
   * Show the form for penerima sampel
   *
   * @param  int  $id_permohonan_uji_klinik
   * @return \Illuminate\Http\Response
   */
  public function createPenerimaSampel($id_permohonan_uji_klinik)
  {
    $this->ensureDibawaPelangganPengambilSampleSkipped($id_permohonan_uji_klinik);
    $item_permohonan_uji_klinik = PermohonanUjiKlinik2::find($id_permohonan_uji_klinik);
    $tgl_register = Carbon::createFromFormat('Y-m-d H:i:s', $item_permohonan_uji_klinik->tglregister_permohonan_uji_klinik)->isoFormat('D MMMM Y');

    // Ambil data VerificationActivitySample step 7 untuk pre-fill jam & petugas
    $data_verifikasi_penerima = VerificationActivitySample::where('is_klinik', $id_permohonan_uji_klinik)
      ->where('id_verification_activity', 7)
      ->first();

    // Buat daftar petugas penerima sampel (analis klinik)
    $petugas_penerima_sampel = $this->getPetugasPenerimaKlinik();
    if ($data_verifikasi_penerima && !empty($data_verifikasi_penerima->nama_petugas)) {
      $savedPenerima = trim($data_verifikasi_penerima->nama_petugas);
      if ($savedPenerima !== '' && !$this->namaExistsInArray($savedPenerima, $petugas_penerima_sampel)) {
        $petugas_penerima_sampel[] = $savedPenerima;
      }
    }

    // Get jenis sampel from latest successful sampling data
    $latest_sampling = \Smt\Masterweb\Models\PengambilanSampleKlinik::where('permohonan_uji_klinik_id', $id_permohonan_uji_klinik)
      ->where('status_sampling', 'Berhasil')
      ->whereNull('deleted_at')
      ->orderBy('created_at', 'desc')
      ->first();

    // Tanggal & waktu sampling: selaras jam Pengambil Sample di halaman verification
    $tgl_waktu_sampling = self::formatTanggalWaktuSamplingKlinikDisplay(
      $id_permohonan_uji_klinik,
      $latest_sampling,
      $item_permohonan_uji_klinik
    );

    $jenis_sampel = '';
    $is_permohonan_haji = (int) ($item_permohonan_uji_klinik->is_haji ?? 0) === 1;
    $jenis_sampel_from_param = \Smt\Masterweb\Helpers\Smt::getJenisSampelFromParameter($id_permohonan_uji_klinik, null);

    // Haji: ikuti jenis sampel dari parameter satuan (jenis_sampel_haji).
    // Non-haji: sampling tersimpan → parameter → permohonan.
    if ($is_permohonan_haji && !empty($jenis_sampel_from_param)) {
      $jenis_sampel = implode(', ', $jenis_sampel_from_param);
    } elseif ($latest_sampling && !empty($latest_sampling->jenis_sample)) {
      if (is_string($latest_sampling->jenis_sample)) {
        $decoded = json_decode($latest_sampling->jenis_sample, true);
        if (is_array($decoded) && !empty($decoded)) {
          $jenis_sampel = implode(', ', $decoded);
        } else {
          $jenis_sampel = $latest_sampling->jenis_sample;
        }
      } elseif (is_array($latest_sampling->jenis_sample)) {
        $jenis_sampel = implode(', ', $latest_sampling->jenis_sample);
      } else {
        $jenis_sampel = $latest_sampling->jenis_sample;
      }
    } elseif (!empty($jenis_sampel_from_param)) {
      $jenis_sampel = implode(', ', $jenis_sampel_from_param);
    } elseif ($item_permohonan_uji_klinik->jenis_sampel !== null) {
      $jenis_sampel = $item_permohonan_uji_klinik->jenis_sampel;
    }

    // Get existing data penerima sampel (now stored as JSON per sample type)
    $penerimaan_sampel = '';
    if ($item_permohonan_uji_klinik->penerimaan_sampel !== null) {
      $penerimaan_sampel = $item_permohonan_uji_klinik->penerimaan_sampel;
    }

    // Get existing data volume sampel (now stored as JSON per sample type)
    $volume_sampel = '';
    if ($item_permohonan_uji_klinik->volume_sampel !== null) {
      $volume_sampel = $item_permohonan_uji_klinik->volume_sampel;
    }

    // Get kualitas sampel data (now stored as JSON per sample type)
    $kualitas_sampel = '';
    if ($item_permohonan_uji_klinik->kualitas_sampel !== null) {
      $kualitas_sampel = $item_permohonan_uji_klinik->kualitas_sampel;
    }

    // Legacy support - old columns (keep for backward compatibility)
    $kualitas_lisis = $item_permohonan_uji_klinik->kualitas_lisis == 1;
    $kualitas_ikterik = $item_permohonan_uji_klinik->kualitas_ikterik == 1;
    $kualitas_lipemik = $item_permohonan_uji_klinik->kualitas_lipemik == 1;
    $kualitas_cukup = $item_permohonan_uji_klinik->kualitas_cukup == 1;
    $kualitas_beku = $item_permohonan_uji_klinik->kualitas_beku == 1;

    // Get all sampling data (for history)
    $all_sampling = \Smt\Masterweb\Models\PengambilanSampleKlinik::where('permohonan_uji_klinik_id', $id_permohonan_uji_klinik)
      ->whereNull('deleted_at')
      ->orderBy('created_at', 'desc')
      ->get();

    // Get parameter and hasil pengujian using Eloquent
    $parameter_results_raw = \Smt\Masterweb\Models\PermohonanUjiParameterKlinik::where('permohonan_uji_klinik', $id_permohonan_uji_klinik)
      ->whereNull('deleted_at')
      ->with(['parametersatuanklinik', 'unit'])
      ->get();

    $parameter_results = $parameter_results_raw->map(function($item) {
      return (object)[
        'id_permohonan_uji_parameter_klinik' => $item->id_permohonan_uji_parameter_klinik,
        'nama_parameter_satuan_klinik' => $item->parametersatuanklinik->nama_parameter_satuan_klinik ?? null,
        'hasil_permohonan_uji_parameter_klinik' => $item->hasil_permohonan_uji_parameter_klinik,
        'nama_satuan_permohonan_uji_parameter_klinik' => $item->unit->name_unit ?? null,
        'tgl_pengujian' => $item->created_at,
      ];
    });

    // Get parameters with package information for display
    $data_permohonan_uji_paket_klinik = \Smt\Masterweb\Models\PermohonanUjiPaketKlinik::where('permohonan_uji_klinik', $id_permohonan_uji_klinik)
      ->with(['parameterpaketklinik', 'parameterjenisklinik'])
      ->whereNull('deleted_at')
      ->get();

    $parameters = [];
    foreach ($data_permohonan_uji_paket_klinik as $paket) {
      $data_parameters = \Smt\Masterweb\Models\PermohonanUjiParameterKlinik::where('permohonan_uji_klinik', $id_permohonan_uji_klinik)
        ->where('permohonan_uji_paket_klinik', $paket->id_permohonan_uji_paket_klinik)
        ->with(['parametersatuanklinik'])
        ->whereNull('deleted_at')
        ->get();

      foreach ($data_parameters as $param) {
        $param->nama_jenis = $paket->parameterjenisklinik->name_parameter_jenis_klinik ?? '-';
        $param->nama_paket = $paket->parameterpaketklinik->name_parameter_paket_klinik ?? '-';
        $parameters[] = $param;
      }
    }



    $kondisi_pasien = $latest_sampling->kondisi_pasien ?? '';

    return view('masterweb::module.admin.laboratorium.permohonan-uji-klinik-2.penerima-sampel', [
      'item_permohonan_uji_klinik' => $item_permohonan_uji_klinik,
      'tgl_register_permohonan_uji_klinik' => $tgl_register,
      'tgl_waktu_sampling' => $tgl_waktu_sampling,
      'jenis_sampel' => $jenis_sampel,
      'penerimaan_sampel' => $penerimaan_sampel,
      'volume_sampel' => $volume_sampel,
      'kualitas_sampel' => $kualitas_sampel,
      'kualitas_lisis' => $kualitas_lisis,
      'kualitas_ikterik' => $kualitas_ikterik,
      'kualitas_lipemik' => $kualitas_lipemik,
      'kualitas_cukup' => $kualitas_cukup,
      'kualitas_beku' => $kualitas_beku,
      'latest_sampling' => $latest_sampling,
      'all_sampling' => $all_sampling,
      'parameter_results' => $parameter_results,
      'parameters' => $parameters,
      'data_verifikasi_penerima' => $data_verifikasi_penerima,
      'petugas_penerima_sampel' => $petugas_penerima_sampel,
      'kondisi_pasien' => $kondisi_pasien,
      'info_haji' => $this->resolveInfoHajiForPermohonan($item_permohonan_uji_klinik),
    ]);
  }

  /**
   * Save signatures for Pengambil Sample (pasien and petugas)
   */
  public function saveSignaturePengambilSample(Request $request, $id_permohonan_uji_klinik)
  {
    try {
      $post = PermohonanUjiKlinik2::find($id_permohonan_uji_klinik);
      if (!$post) {
        return response()->json(['status' => false, 'pesan' => 'Data tidak ditemukan'], 404);
      }

      // Expecting base64 PNGs
      $pasien = $request->input('signature_pasien');
      $petugas = $request->input('signature_petugas');
      $sampling = (int) $request->input('sampling', 0); // 0 = sampling pertama, 1+ = resampling

      if (!$pasien && !$petugas) {
        return response()->json(['status' => false, 'pesan' => 'Tanda tangan kosong'], 422);
      }

      // Cari record PengambilanSampleKlinik berdasarkan resampling flag
      $pengambilanSample = PengambilanSampleKlinik::where('permohonan_uji_klinik_id', $id_permohonan_uji_klinik)
        ->where(function ($q) use ($sampling) {
          $q->where('resampling', $sampling);
          if ($sampling === 0) {
            $q->orWhereNull('resampling');
          }
        })
        ->whereNull('deleted_at')
        ->orderBy('created_at', 'desc')
        ->first();

      // Jika tidak ada, buat record baru
      if (!$pengambilanSample) {
        $pengambilanSample = new PengambilanSampleKlinik();
        $pengambilanSample->id_pengambilan_sample_klinik = \Ramsey\Uuid\Uuid::uuid4()->toString();
        $pengambilanSample->permohonan_uji_klinik_id = $id_permohonan_uji_klinik;
        $pengambilanSample->resampling = $sampling;
        $pengambilanSample->pasien_permohonan_uji_klinik = $post->pasien_permohonan_uji_klinik ?? null;
        $pengambilanSample->petugas_name = $post->plebotomist_permohonan_uji_klinik ?? null;
        $pengambilanSample->status_sampling = 'Berhasil'; // Default status
        $pengambilanSample->jenis_sample = null;
        $pengambilanSample->kondisi_pasien = null;

        // Calculate number_sampling_success
        $pengambilanSample->number_sampling_success = PengambilanSampleKlinik::calculateNumberSamplingSuccess($id_permohonan_uji_klinik);
      }

      // Update signature
      if ($pasien) {
        $pengambilanSample->signature_pengambil_sample_pasien = $pasien; // base64 data URL
      }
      if ($petugas) {
        $pengambilanSample->signature_pengambil_sample_petugas = $petugas; // base64 data URL
      }

      $pengambilanSample->save();

      // Fallback: juga simpan ke tabel utama untuk kompatibilitas
      if ($sampling == 0) {
        if ($pasien) {
          $post->signature_pengambil_sample_pasien = $pasien;
        }
        if ($petugas) {
          $post->signature_pengambil_sample_petugas = $petugas;
        }
      $post->save();
      }

      return response()->json(['status' => true, 'pesan' => 'Tanda tangan tersimpan']);
    } catch (\Exception $e) {
      \Log::error('Save signature error: '.$e->getMessage());
      \Log::error('Save signature trace: '.$e->getTraceAsString());
      return response()->json([
        'status' => false,
        'pesan' => 'Gagal menyimpan tanda tangan: ' . $e->getMessage()
      ], 500);
    }
  }

  /**
   * Check signature status for a permohonan
   */
  public function checkSignatureStatus(Request $request, $id_permohonan_uji_klinik)
  {
    try {
      $sampling = (int) $request->input('sampling', 0);

      $pengambilanSample = PengambilanSampleKlinik::where('permohonan_uji_klinik_id', $id_permohonan_uji_klinik)
        ->where(function ($q) use ($sampling) {
          $q->where('resampling', $sampling);
          if ($sampling === 0) {
            $q->orWhereNull('resampling');
          }
        })
        ->whereNull('deleted_at')
        ->orderBy('created_at', 'desc')
        ->first();

      $has_signatures = false;
      if ($pengambilanSample) {
        $has_signatures = !empty($pengambilanSample->signature_pengambil_sample_pasien) &&
                         !empty($pengambilanSample->signature_pengambil_sample_petugas);
      }

      // Fallback: tanda tangan sampling pertama juga disimpan di tabel permohonan
      if (!$has_signatures && $sampling === 0) {
        $post = PermohonanUjiKlinik2::find($id_permohonan_uji_klinik);
        if ($post) {
          $has_signatures = !empty($post->signature_pengambil_sample_pasien) &&
                           !empty($post->signature_pengambil_sample_petugas);
        }
      }

      return response()->json([
        'status' => true,
        'has_signatures' => $has_signatures
      ]);
    } catch (\Exception $e) {
      \Log::error('Check signature status error: '.$e->getMessage());
      return response()->json([
        'status' => false,
        'has_signatures' => false,
        'pesan' => 'Gagal mengecek status tanda tangan: ' . $e->getMessage()
      ], 500);
    }
  }

  /**
   * Store penerima sampel data
   *
   * @param  \Illuminate\Http\Request  $request
   * @param  int  $id_permohonan_uji_klinik
   * @return \Illuminate\Http\Response
   */
  public function storePenerimaSampel(Request $request, $id_permohonan_uji_klinik)
  {
    // Mulai transaksi database
    DB::beginTransaction();

    try {
        // Temukan data permohonan uji klinik berdasarkan ID
        $this->ensureDibawaPelangganPengambilSampleSkipped($id_permohonan_uji_klinik);
        $post = PermohonanUjiKlinik2::find($id_permohonan_uji_klinik);

        // Jika data tidak ditemukan, kembalikan respon error
        if (!$post) {
            return response()->json(['status' => false, 'pesan' => "Data permohonan uji klinik tidak ditemukan!"], 404);
        }

        // Validasi required fields
        if (empty($request->penerimaan_sampel)){
          return response()->json(['status' => false, 'pesan' => "Penerimaan sampel wajib diisi!"], 200);
        }

        if (empty($request->volume_sampel)){
          return response()->json(['status' => false, 'pesan' => "Volume sampel wajib diisi!"], 200);
        }

        // Format dan simpan data dari request ke dalam model
        // Penerimaan sampel now stored as JSON (per sample type)
        $penerimaan_sampel_data = $request->penerimaan_sampel;
        if (is_array($penerimaan_sampel_data)) {
          $post->penerimaan_sampel = json_encode($penerimaan_sampel_data);
        } else {
          $post->penerimaan_sampel = $penerimaan_sampel_data;
        }

        // Volume sampel now stored as JSON (per sample type)
        $volume_sampel_data = $request->volume_sampel;
        if (is_array($volume_sampel_data)) {
          $post->volume_sampel = json_encode($volume_sampel_data);
        } else {
          $post->volume_sampel = $volume_sampel_data;
        }        // Kualitas sampel now stored as JSON (per sample type)
        $kualitas_sampel_data = $request->kualitas_sampel;
        if (is_array($kualitas_sampel_data)) {
          $post->kualitas_sampel = json_encode($kualitas_sampel_data);
        } else {
          $post->kualitas_sampel = null;
        }

        // Keep legacy columns for backward compatibility
        // Aggregate all quality flags from all sample types
        $all_qualities = [];
        if (is_array($kualitas_sampel_data)) {
          foreach ($kualitas_sampel_data as $sampel_type => $qualities) {
            if (is_array($qualities)) {
              $all_qualities = array_merge($all_qualities, $qualities);
            }
          }
        }
        $post->kualitas_lisis = in_array('Lisis', $all_qualities) ? 1 : 0;
        $post->kualitas_ikterik = in_array('Ikterik', $all_qualities) ? 1 : 0;
        $post->kualitas_lipemik = in_array('Lipemik', $all_qualities) ? 1 : 0;
        $post->kualitas_cukup = in_array('Cukup', $all_qualities) ? 1 : 0;
        $post->kualitas_beku = in_array('Beku', $all_qualities) ? 1 : 0;

        // Simpan catatan hasil
        if ($request->has('catatan_hasil')) {
          $post->catatan_hasil = $request->post('catatan_hasil');
        }

        $simpan = $post->save();

        // Update Specimen di SatuSehat jika VERSION_SATUSEHAT = prd
        if (config('services.satu_sehat.version') === 'prd') {
          try {
            // Cari PengambilanSampleKlinik yang berhasil (status_sampling = 'berhasil')
            // Ambil yang terbaru untuk permohonan ini
            $pengambilanSample = PengambilanSampleKlinik::where('permohonan_uji_klinik_id', $id_permohonan_uji_klinik)
              ->where('status_sampling', 'berhasil')
              ->whereNull('deleted_at')
              ->whereNotNull('id_spesimen_satu_sehat')
              ->where('id_spesimen_satu_sehat', '!=', '')
              ->orderBy('created_at', 'desc')
              ->first();

            if ($pengambilanSample && !empty($pengambilanSample->id_spesimen_satu_sehat)) {
              // Get specimen IDs (bisa multiple, dipisah koma)
              $specimenIds = array_filter(array_map('trim', explode(',', $pengambilanSample->id_spesimen_satu_sehat)));

              // Update setiap specimen
              foreach ($specimenIds as $specimenId) {
                if (empty($specimenId)) continue;

                // Get existing Specimen from SatuSehat
                $getResponse = $this->satuSehatHelper->get('Specimen/' . $specimenId);

                if ($getResponse['status_code'] == 200 && isset($getResponse['body'])) {
                  $existingSpecimen = $getResponse['body'];

                  // Build condition array based on kualitas flags
                  $conditions = [];
                  if ($post->kualitas_cukup) {
                    $conditions[] = ["text" => "Cukup"];
                  }
                  if ($post->kualitas_lisis) {
                    $conditions[] = ["text" => "Lisis"];
                  }
                  if ($post->kualitas_ikterik) {
                    $conditions[] = ["text" => "Ikterik"];
                  }
                  if ($post->kualitas_lipemik) {
                    $conditions[] = ["text" => "Lipemik"];
                  }
                  if ($post->kualitas_beku) {
                    $conditions[] = ["text" => "Beku"];
                  }

                  // Build note text
                  $noteText = "Sampel diterima";
                  $conditionTexts = [];
                  if ($post->kualitas_cukup) $conditionTexts[] = "cukup";
                  if ($post->kualitas_lisis) $conditionTexts[] = "sedikit lisis";
                  if ($post->kualitas_ikterik) $conditionTexts[] = "ikterik";
                  if ($post->kualitas_lipemik) $conditionTexts[] = "lipemik";
                  if ($post->kualitas_beku) $conditionTexts[] = "beku";

                  if (!empty($conditionTexts)) {
                    $noteText .= " dalam kondisi " . implode(", ", $conditionTexts);
                  }

                  if (!empty($post->volume_sampel)) {
                    $noteText .= ". Volume " . $post->volume_sampel;
                  }

                  // Format receivedTime (gunakan waktu sekarang atau dari penerimaan_sampel jika ada)
                  $receivedTime = Carbon::now()->toIso8601String();
                  if (!empty($request->penerimaan_sampel)) {
                    try {
                      // Coba parse format d/m/Y H:i atau Y-m-d H:i:s
                      if (strpos($request->penerimaan_sampel, '/') !== false) {
                        $receivedTime = Carbon::createFromFormat('d/m/Y H:i', $request->penerimaan_sampel)->toIso8601String();
                      } else {
                        $receivedTime = Carbon::parse($request->penerimaan_sampel)->toIso8601String();
                      }
                    } catch (\Exception $e) {
                      // Jika parsing gagal, gunakan waktu sekarang
                      $receivedTime = Carbon::now()->toIso8601String();
                    }
                  }

                  // Update Specimen data
                  $existingSpecimen['receivedTime'] = $receivedTime;
                  if (!empty($conditions)) {
                    $existingSpecimen['condition'] = $conditions;
                  }
                  $existingSpecimen['note'] = [
                    [
                      "text" => $noteText
                    ]
                  ];

                  // Update quantity jika volume_sampel ada
                  if (!empty($post->volume_sampel) && isset($existingSpecimen['collection']['quantity'])) {
                    // Extract numeric value and unit from volume_sampel (e.g., "5 mL" or "5")
                    preg_match('/(\d+(?:\.\d+)?)\s*(mL|ml|L|l|g|kg)?/i', $post->volume_sampel, $matches);
                    if (!empty($matches[1])) {
                      $existingSpecimen['collection']['quantity']['value'] = (float) $matches[1];
                      if (!empty($matches[2])) {
                        $existingSpecimen['collection']['quantity']['unit'] = $matches[2];
                      } else {
                        $existingSpecimen['collection']['quantity']['unit'] = 'mL'; // Default unit
                      }
                    }
                  }

                  // PUT update to SatuSehat
                  $putResponse = $this->satuSehatHelper->put('Specimen', $specimenId, $existingSpecimen);

                  if ($putResponse['status_code'] == 200 || $putResponse['status_code'] == 201) {
                    \Log::info('Specimen updated successfully in SatuSehat', [
                      'specimen_id' => $specimenId,
                      'permohonan_id' => $id_permohonan_uji_klinik
                    ]);
                  } else {
                    \Log::warning('Failed to update Specimen in SatuSehat', [
                      'specimen_id' => $specimenId,
                      'response' => $putResponse
                    ]);
                  }
                } else {
                  \Log::warning('Failed to get existing Specimen from SatuSehat', [
                    'specimen_id' => $specimenId,
                    'response' => $getResponse
                  ]);
                }
              }
            } else {
              \Log::info('No valid specimen ID found for permohonan', [
                'permohonan_id' => $id_permohonan_uji_klinik
              ]);
            }
          } catch (\Exception $e) {
            // Log error tapi tidak gagalkan transaksi
            \Log::error('Error updating Specimen in SatuSehat: ' . $e->getMessage(), [
              'permohonan_id' => $id_permohonan_uji_klinik,
              'exception' => $e->getTraceAsString()
            ]);
            // Tetap lanjutkan transaksi
          }
        }

        // Simpan jam dan petugas penerima sampel ke VerificationActivitySample step 7
        $jamPenerima   = $request->post('jam_penerima');
        $petugasPenerima = $request->post('nama_petugas_penerima');

        if (!empty($jamPenerima) || !empty($petugasPenerima)) {
          $verifikasiPenerima = VerificationActivitySample::where('is_klinik', $id_permohonan_uji_klinik)
            ->where('id_verification_activity', 7)
            ->first();

          // Tanggal acuan: created_at permohonan; jika sudah pernah disimpan, pertahankan tanggal tersimpan.
          $anchorAt = DateHelper::permohonanAnchorAt($post);
          if ($verifikasiPenerima && !empty($verifikasiPenerima->start_date)) {
            $anchorAt = $verifikasiPenerima->start_date;
          } elseif (empty($anchorAt)) {
            $pengambil = VerificationActivitySample::where('is_klinik', $id_permohonan_uji_klinik)
              ->where('id_verification_activity', 6)
              ->where(function ($q) {
                $q->where('resampling', 0)->orWhereNull('resampling');
              })
              ->orderByDesc('start_date')
              ->first();
            if ($pengambil && !empty($pengambil->start_date)) {
              $anchorAt = $pengambil->start_date;
            }
          }

          if (!empty($jamPenerima)) {
            try {
              $penerimaStart = DateHelper::clockOnRegisterDate(
                $anchorAt,
                trim((string) $jamPenerima)
              )->format('Y-m-d H:i:s');
              $penerimaStop  = Carbon::createFromFormat('Y-m-d H:i:s', $penerimaStart)->addMinutes(10)->format('Y-m-d H:i:s');
            } catch (\Exception $e) {
              $penerimaStart = null;
              $penerimaStop  = null;
            }
          } else {
            $penerimaStart = null;
            $penerimaStop  = null;
          }

          $petugasPenerimaFormatted = !empty($petugasPenerima)
            ? self::resolvePetugasCanonicalName($petugasPenerima)
            : null;

          if ($verifikasiPenerima) {
            if ($penerimaStart)              { $verifikasiPenerima->start_date   = $penerimaStart; }
            if ($penerimaStop)               { $verifikasiPenerima->stop_date    = $penerimaStop; }
            if ($petugasPenerimaFormatted)   { $verifikasiPenerima->nama_petugas = $petugasPenerimaFormatted; }
            if ($request->is_selesai == 1) { $verifikasiPenerima->is_done = 1; }
            $verifikasiPenerima->save();
          } else {
            $verifikasiPenerimaBaru = new VerificationActivitySample();
            $verifikasiPenerimaBaru->id                       = Uuid::uuid4()->toString();
            $verifikasiPenerimaBaru->id_verification_activity = 7;
            $verifikasiPenerimaBaru->start_date               = $penerimaStart;
            $verifikasiPenerimaBaru->stop_date                = $penerimaStop;
            $verifikasiPenerimaBaru->nama_petugas             = $petugasPenerimaFormatted;
            $verifikasiPenerimaBaru->is_klinik                = $id_permohonan_uji_klinik;
            $verifikasiPenerimaBaru->is_done                  = ($request->is_selesai == 1) ? 1 : 0;
            $verifikasiPenerimaBaru->resampling               = 0;
            $verifikasiPenerimaBaru->save();
          }
        }

        // Commit transaksi jika semua berhasil
        DB::commit();

        return response()->json(['status' => true, 'pesan' => "Data penerima sampel berhasil disimpan!"], 200);

    } catch (\Exception $e) {
        // Rollback transaksi jika terjadi error
        DB::rollBack();

        // Log error atau lakukan hal lain yang diperlukan
        Log::error('Error saat menyimpan penerima sampel: ' . $e->getMessage());

        return response()->json(['status' => false, 'pesan' => "Data penerima sampel tidak berhasil disimpan!"], 500);
    }
  }

  /**
   * Show the form for doctor diagnosis
   *
   * @param  int  $id
   * @return \Illuminate\Http\Response
   */
  public function diagnosis($id)
  {
    $item = PermohonanUjiKlinik2::find($id);

    if (!$item) {
      return redirect()->route('elits-permohonan-uji-klinik.registrasi')->with('error', 'Data tidak ditemukan');
    }

    $tgl_register = Carbon::createFromFormat('Y-m-d H:i:s', $item->tglregister_permohonan_uji_klinik)->isoFormat('D MMMM Y');
    $code = $item->noregister_permohonan_uji_klinik;

    $pasien = Pasien::where('id_pasien', $item->pasien_permohonan_uji_klinik)->first();

    if ($pasien) {
      $umur = date_diff(date_create(date('Y-m-d')), date_create($pasien->tgllahir_pasien));
      $umur_string = $umur->y . " tahun " . $umur->m . " bulan " . $umur->d . " hari";
    } else {
      $umur_string = "Data pasien tidak ditemukan";
    }

    $parameter_jenis_klinik = ParameterJenisKlinik::with('pakets')->orderBy('created_at', 'asc')->get();
    $parameter_paket_extra = ParameterPaketExtra::with('parameterSubPaketExtra')->orderBy('created_at', 'asc')->get();

    return view('masterweb::module.admin.laboratorium.permohonan-uji-klinik-2.diagnosis', [
      'item' => $item,
      'tgl_register' => $tgl_register,
      'id' => $id,
      'code' => $code,
      'pasien' => $pasien,
      'umur_string' => $umur_string,
      'parameter_paket_extra' => $parameter_paket_extra,
      'parameter_jenis_klinik' => $parameter_jenis_klinik,
    ]);
  }

  /**
   * Store diagnosis from doctor and redirect to parameter page
   *
   * @param  \Illuminate\Http\Request  $request
   * @param  int  $id
   * @return \Illuminate\Http\Response
   */
  public function storeDiagnosis(Request $request, $id)
  {
    DB::beginTransaction();

    try {
      $post = PermohonanUjiKlinik2::find($id);

      if (!$post) {
        return response()->json(['status' => false, 'pesan' => 'Data tidak ditemukan!'], 404);
      }

      // Update field diagnosis (hanya diagnosa saja)
      $post->diagnosa_permohonan_uji_klinik = $request->diagnosa_permohonan_uji_klinik;

      // PENTING: doctor_type tetap 'lab', TIDAK diubah!
      // Yang diubah adalah done_register menjadi true
      $post->done_register = true;

      $post->save();

      DB::commit();

      // Redirect ke halaman parameter (sama seperti create rujukan dokter)
      $urlNextStep = route('elits-permohonan-uji-klinik-2.create-permohonan-uji-klinik-parameter', $id);

      return response()->json([
        'status' => true,
        'pesan' => "Diagnosis berhasil disimpan! Silakan lanjutkan ke halaman parameter.",
        'urlNextStep' => $urlNextStep
      ], 200);

    } catch (\Exception $e) {
      DB::rollback();
      Log::error('Error saat menyimpan diagnosis: ' . $e->getMessage());
      return response()->json(['status' => false, 'pesan' => 'Gagal menyimpan diagnosis! ' . $e->getMessage()], 500);
    }
  }

  /**
   * Send WhatsApp notification to all doctors with DKTR level
   * 
   * @param string $permohonanId
   * @param Pasien $pasien
   * @param string $noRegister
   * @return void
   */
  private function sendWhatsAppToDokter($permohonanId, $pasien, $noRegister)
  {
    try {
      // Debug: Uncomment untuk melihat apakah fungsi dipanggil
      // dd('sendWhatsAppToDokter called', $permohonanId, $pasien->nama_pasien, $noRegister);
      
      Log::info('sendWhatsAppToDokter called', ['permohonan_id' => $permohonanId]);
      
      // Get Wablas configuration
      $wablasHost = config('services.wablas.host');
      $wablasToken = config('services.wablas.token');
      $wablasSecret = config('services.wablas.secret');

      Log::info('Wablas config', [
        'host' => $wablasHost ? 'set' : 'empty',
        'token' => $wablasToken ? 'set' : 'empty',
        'secret' => $wablasSecret ? 'set' : 'empty'
      ]);

      // Check if Wablas is configured
      if (empty($wablasHost) || empty($wablasToken) || empty($wablasSecret)) {
        Log::warning('Wablas configuration is missing. WhatsApp notification skipped.');
        return;
      }

      // Get all users with DKTR level
      $dokters = User::whereHas('getlevel', function ($query) {
        $query->where('level', 'DKTR');
      })
      ->whereNotNull('phone')
      ->where('phone', '!=', '')
      ->get();

      Log::info('Dokters found', ['count' => $dokters->count()]);

      if ($dokters->isEmpty()) {
        Log::info('No doctors with DKTR level and phone number found.');
        return;
      }

         

      // Prepare message content untuk template "send-link"
      $pasienNama = $pasien->nama_pasien ?? 'Pasien';
      $loginUrl = url('/mobile/dokter/login/' . $permohonanId);
      $previewText  = "Permohonan uji klinik baru.\n";
      $previewText .= "No. Reg: {$noRegister}\n";
      $previewText .= "Pasien : {$pasienNama}\n\n";
      $previewText .= "Klik link untuk memilih layanan pemeriksaan.";

      // Prepare data untuk endpoint Wablas send-link
      // Format wajib: message = { text, link } (bukan string / json_encode ganda)
      $data = [];
      foreach ($dokters as $dokter) {
        $phone = $dokter->phone;
        if (!empty($phone)) {
          // Bersihkan karakter non-digit
          $phone = preg_replace('/[^0-9]/', '', $phone);
          // Pastikan diawali 62
          if (substr($phone, 0, 2) !== '62') {
            if (substr($phone, 0, 1) === '0') {
              $phone = '62' . substr($phone, 1);
            } else {
              $phone = '62' . $phone;
            }
          }

          $data[] = [
            'phone' => $phone,
            'message' => [
              'text' => $previewText,
              'link' => $loginUrl,
            ],
          ];
        }
      }
     
      Log::info('Data prepared for send-link', ['data_count' => count($data)]);

      if (empty($data)) {
        Log::info('No valid phone numbers found for doctors.');
        return;
      }

      // Kirim WhatsApp menggunakan Wablas endpoint send-link dengan cURL native
      $url = rtrim($wablasHost, '/') . '/api/v2/send-link';
      $authHeader = $wablasToken . '.' . $wablasSecret;
     // Bangun payload sesuai format Wablas send-link
      $payload = [
        'data' => $data,
      ];

      Log::info('Sending WhatsApp send-link request via cURL', [
        'url' => $url,
        'data_count' => count($data),
      ]);

      $curl = curl_init();
      curl_setopt($curl, CURLOPT_HTTPHEADER, [
        "Authorization: {$authHeader}",
        "Content-Type: application/json",
      ]);
      curl_setopt($curl, CURLOPT_CUSTOMREQUEST, "POST");
      curl_setopt($curl, CURLOPT_RETURNTRANSFER, true);
      curl_setopt($curl, CURLOPT_POSTFIELDS, json_encode($payload, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE));
      curl_setopt($curl, CURLOPT_URL, $url);
      curl_setopt($curl, CURLOPT_SSL_VERIFYHOST, 0);
      curl_setopt($curl, CURLOPT_SSL_VERIFYPEER, 0);

      $result = curl_exec($curl);
      $curlError = curl_error($curl);
      $httpCode = curl_getinfo($curl, CURLINFO_HTTP_CODE);
      curl_close($curl);

      if ($result === false) {
        Log::error('Error sending WhatsApp send-link via cURL', [
          'error' => $curlError,
          'permohonan_id' => $permohonanId,
        ]);
        return;
      }

      $responseBody = json_decode($result, true);

      Log::info('WhatsApp send-link response received', [
        'http_code' => $httpCode,
        'response' => $responseBody,
        'raw_result' => $result,
      ]);

      if ($httpCode === 200 && isset($responseBody['status']) && $responseBody['status'] === true) {
        Log::info('WhatsApp send-link notification sent successfully to doctors', [
          'permohonan_id' => $permohonanId,
          'no_register' => $noRegister,
          'dokters_count' => count($data),
        ]);
        return;
      }

      Log::warning('Wablas send-link API did not return success', [
        'http_code' => $httpCode,
        'response' => $responseBody,
      ]);

    } catch (\Exception $e) {
      Log::error('Error sending WhatsApp notification to doctors: ' . $e->getMessage(), [
        'permohonan_id' => $permohonanId,
        'no_register' => $noRegister,
        'error' => $e->getTraceAsString()
      ]);
      
      // Try alternative method if main method failed
      try {
        Log::info('Trying alternative method after exception');
        $wablasHost = config('services.wablas.host');
        $wablasToken = config('services.wablas.token');
        $wablasSecret = config('services.wablas.secret');
        
        if (!empty($wablasHost) && !empty($wablasToken) && !empty($wablasSecret)) {
          // Get data again for fallback
          $dokters = User::whereHas('getlevel', function ($query) {
            $query->where('level', 'DKTR');
          })
          ->whereNotNull('phone')
          ->where('phone', '!=', '')
          ->get();

          if (!$dokters->isEmpty()) {
            $pasienNama = $pasien->nama_pasien ?? 'Pasien';
            $loginUrl = url('/mobile/dokter/login/' . $permohonanId);
            
            $messageContent = "Halo Dokter,\n\n";
            $messageContent .= "Ada permohonan uji klinik baru yang memerlukan pemilihan layanan pemeriksaan:\n\n";
            $messageContent .= "No. Register: *{$noRegister}*\n";
            $messageContent .= "Nama Pasien: *{$pasienNama}*\n\n";
            $messageContent .= "Silakan klik link berikut untuk melakukan pemilihan layanan pemeriksaan:\n{$loginUrl}";

            $fallbackData = [];
            foreach ($dokters as $dokter) {
              $phone = $dokter->phone;
              if (!empty($phone)) {
                $phone = preg_replace('/[^0-9]/', '', $phone);
                if (substr($phone, 0, 2) !== '62') {
                  if (substr($phone, 0, 1) === '0') {
                    $phone = '62' . substr($phone, 1);
                  } else {
                    $phone = '62' . $phone;
                  }
                }
                $fallbackData[] = [
                  'phone' => $phone,
                  'message' => $messageContent
                ];
              }
            }

            if (!empty($fallbackData)) {
              $this->sendWhatsAppSimple($wablasHost, $wablasToken, $wablasSecret, $fallbackData, $permohonanId, $noRegister);
            }
          }
        }
      } catch (\Exception $fallbackException) {
        Log::error('Fallback method also failed: ' . $fallbackException->getMessage());
      }
      
      // Don't throw exception, just log the error
    }
  }

  /**
   * Selesaikan verifikasi step 4: sinkronkan tanggal, update encounter FHIR, dan kirim WhatsApp ke dokter validasi.
   */
  private function finalizeKlinikVerificationStep4($permohonanId, $namaPetugas, $tglpengujian, $verifikasi)
  {
    try {
      if (!empty($tglpengujian)) {
        try {
          $start_date = Carbon::createFromFormat('d/m/Y H:i', $tglpengujian)->format('Y-m-d H:i:s');
        } catch (\Throwable $ex) {
          try {
            $start_date = Carbon::parse($tglpengujian)->format('Y-m-d H:i:s');
          } catch (\Throwable $ex2) {
            $start_date = !empty($verifikasi->start_date) ? Carbon::parse($verifikasi->start_date)->format('Y-m-d H:i:s') : Carbon::now()->format('Y-m-d H:i:s');
          }
        }
      } elseif (!empty($verifikasi->start_date)) {
        $start_date = Carbon::parse($verifikasi->start_date)->format('Y-m-d H:i:s');
      } else {
        $permohonanForDate = PermohonanUjiKlinik2::find($permohonanId);
        $start_date = DateHelper::clockOnRegisterDate(
          $permohonanForDate ? DateHelper::permohonanAnchorAt($permohonanForDate) : null
        )->format('Y-m-d H:i:s');
      }

      $stop_date = Carbon::createFromFormat('Y-m-d H:i:s', $start_date)->addMinutes(10)->format('Y-m-d H:i:s');

      $verifikasi->start_date = $start_date;
      $verifikasi->stop_date = $stop_date;
      $verifikasi->save();

      $newStatusHistory = [
        'status' => 'in-progress',
        'period' => [
          'start' => Carbon::createFromFormat('Y-m-d H:i:s', $start_date)->toIso8601String(),
          'end' => Carbon::createFromFormat('Y-m-d H:i:s', $stop_date)->toIso8601String(),
        ],
      ];

      $this->updateEncounter(
        $permohonanId,
        $namaPetugas,
        'in-progress',
        'Ruang Lab Klinik',
        'OBSENC',
        'Verifikasi',
        'analyte',
        Carbon::createFromFormat('Y-m-d H:i:s', $start_date)->toIso8601String(),
        Carbon::createFromFormat('Y-m-d H:i:s', $stop_date)->toIso8601String(),
        $newStatusHistory
      );

      $data_permohonan_uji_klinik = PermohonanUjiKlinik2::findOrFail($permohonanId);
      $pasien = Pasien::find($data_permohonan_uji_klinik->pasien_permohonan_uji_klinik);
      $noRegister = $data_permohonan_uji_klinik->noregister_permohonan_uji_klinik;

      $this->sendWhatsAppToDokterValidasi($permohonanId, $pasien, $noRegister);
    } catch (\Exception $e) {
      \Log::error('Error finalizing verification step 4: ' . $e->getMessage());
    }
  }

  /**
   * Send WhatsApp notification to all doctors with DKTR level for validation
   * 
   * @param string $permohonanId
   * @param Pasien $pasien
   * @param string $noRegister
   * @return void
   */
  private function sendWhatsAppToDokterValidasi($permohonanId, $pasien, $noRegister)
  {
    try {
      // Debug: Uncomment untuk melihat apakah fungsi dipanggil
      // dd('sendWhatsAppToDokterValidasi called', $permohonanId, $pasien->nama_pasien, $noRegister);
      
      Log::info('sendWhatsAppToDokterValidasi called', ['permohonan_id' => $permohonanId]);
      
      // Get Wablas configuration
      $wablasHost = config('services.wablas.host');
      $wablasToken = config('services.wablas.token');
      $wablasSecret = config('services.wablas.secret');

      Log::info('Wablas config', [
        'host' => $wablasHost ? 'set' : 'empty',
        'token' => $wablasToken ? 'set' : 'empty',
        'secret' => $wablasSecret ? 'set' : 'empty'
      ]);

      // Check if Wablas is configured
      if (empty($wablasHost) || empty($wablasToken) || empty($wablasSecret)) {
        Log::warning('Wablas configuration is missing. WhatsApp notification skipped.');
        return;
      }

      // Get all users with DKTR level
      $dokters = User::whereHas('getlevel', function ($query) {
        $query->where('level', 'DKTR');
      })
      ->whereNotNull('phone')
      ->where('phone', '!=', '')
      ->get();

      Log::info('Dokters found', ['count' => $dokters->count()]);

      if ($dokters->isEmpty()) {
        Log::info('No doctors with DKTR level and phone number found.');
        return;
      }

         

      // Prepare message content untuk template "send-link"
      $pasienNama = $pasien->nama_pasien ?? 'Pasien';
      $loginUrl = url('/mobile/dokter/login/' . $permohonanId);
      $previewText  = "Permohonan uji klinik baru.\n";
      $previewText .= "No. Reg: {$noRegister}\n";
      $previewText .= "Pasien : {$pasienNama}\n\n";
      $previewText .= "Harus dilakukan validasi untuk pasien tersebut.";

      // Prepare data untuk endpoint Wablas send-link
      // Format wajib: message = { text, link } (bukan string / json_encode ganda)
      $data = [];
      foreach ($dokters as $dokter) {
        $phone = $dokter->phone;
        if (!empty($phone)) {
          // Bersihkan karakter non-digit
          $phone = preg_replace('/[^0-9]/', '', $phone);
          // Pastikan diawali 62
          if (substr($phone, 0, 2) !== '62') {
            if (substr($phone, 0, 1) === '0') {
              $phone = '62' . substr($phone, 1);
            } else {
              $phone = '62' . $phone;
            }
          }

          $data[] = [
            'phone' => $phone,
            'message' => [
              'text' => $previewText,
              'link' => $loginUrl,
            ],
          ];
        }
      }
     
      Log::info('Data prepared for send-link', ['data_count' => count($data)]);

      if (empty($data)) {
        Log::info('No valid phone numbers found for doctors.');
        return;
      }

      // Kirim WhatsApp menggunakan Wablas endpoint send-link dengan cURL native
      $url = rtrim($wablasHost, '/') . '/api/v2/send-link';
      $authHeader = $wablasToken . '.' . $wablasSecret;
     // Bangun payload sesuai format Wablas send-link
      $payload = [
        'data' => $data,
      ];

      Log::info('Sending WhatsApp send-link request via cURL', [
        'url' => $url,
        'data_count' => count($data),
      ]);

      $curl = curl_init();
      curl_setopt($curl, CURLOPT_HTTPHEADER, [
        "Authorization: {$authHeader}",
        "Content-Type: application/json",
      ]);
      curl_setopt($curl, CURLOPT_CUSTOMREQUEST, "POST");
      curl_setopt($curl, CURLOPT_RETURNTRANSFER, true);
      curl_setopt($curl, CURLOPT_POSTFIELDS, json_encode($payload, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE));
      curl_setopt($curl, CURLOPT_URL, $url);
      curl_setopt($curl, CURLOPT_SSL_VERIFYHOST, 0);
      curl_setopt($curl, CURLOPT_SSL_VERIFYPEER, 0);

      $result = curl_exec($curl);
      $curlError = curl_error($curl);
      $httpCode = curl_getinfo($curl, CURLINFO_HTTP_CODE);
      curl_close($curl);

      if ($result === false) {
        Log::error('Error sending WhatsApp send-link via cURL', [
          'error' => $curlError,
          'permohonan_id' => $permohonanId,
        ]);
        return;
      }

      $responseBody = json_decode($result, true);

      Log::info('WhatsApp send-link response received', [
        'http_code' => $httpCode,
        'response' => $responseBody,
        'raw_result' => $result,
      ]);

      if ($httpCode === 200 && isset($responseBody['status']) && $responseBody['status'] === true) {
        Log::info('WhatsApp send-link notification sent successfully to doctors for validation', [
          'permohonan_id' => $permohonanId,
          'no_register' => $noRegister,
          'dokters_count' => count($data),
        ]);
        return;
      }

      Log::warning('Wablas send-link API did not return success', [
        'http_code' => $httpCode,
        'response' => $responseBody,
      ]);

    } catch (\Exception $e) {
      Log::error('Error sending WhatsApp notification to doctors for validation: ' . $e->getMessage(), [
        'permohonan_id' => $permohonanId,
        'no_register' => $noRegister,
        'error' => $e->getTraceAsString()
      ]);
      
      // Try alternative method if main method failed
      try {
        Log::info('Trying alternative method after exception');
        $wablasHost = config('services.wablas.host');
        $wablasToken = config('services.wablas.token');
        $wablasSecret = config('services.wablas.secret');
        
        if (!empty($wablasHost) && !empty($wablasToken) && !empty($wablasSecret)) {
          // Get data again for fallback
          $dokters = User::whereHas('getlevel', function ($query) {
            $query->where('level', 'DKTR');
          })
          ->whereNotNull('phone')
          ->where('phone', '!=', '')
          ->get();

          if (!$dokters->isEmpty()) {
            $pasienNama = $pasien->nama_pasien ?? 'Pasien';
            $loginUrl = url('/mobile/dokter/login/' . $permohonanId);
            
            $messageContent = "Halo Dokter,\n\n";
            $messageContent .= "Ada permohonan uji klinik yang memerlukan validasi:\n\n";
            $messageContent .= "No. Register: *{$noRegister}*\n";
            $messageContent .= "Nama Pasien: *{$pasienNama}*\n\n";
            $messageContent .= "Harus dilakukan validasi untuk pasien tersebut.\n";
            $messageContent .= "Silakan klik link berikut: {$loginUrl}";

            $fallbackData = [];
            foreach ($dokters as $dokter) {
              $phone = $dokter->phone;
              if (!empty($phone)) {
                $phone = preg_replace('/[^0-9]/', '', $phone);
                if (substr($phone, 0, 2) !== '62') {
                  if (substr($phone, 0, 1) === '0') {
                    $phone = '62' . substr($phone, 1);
                  } else {
                    $phone = '62' . $phone;
                  }
                }
                $fallbackData[] = [
                  'phone' => $phone,
                  'message' => $messageContent
                ];
              }
            }

            if (!empty($fallbackData)) {
              $this->sendWhatsAppSimple($wablasHost, $wablasToken, $wablasSecret, $fallbackData, $permohonanId, $noRegister);
            }
          }
        }
      } catch (\Exception $fallbackException) {
        Log::error('Fallback method also failed: ' . $fallbackException->getMessage());
      }
      
      // Don't throw exception, just log the error
    }
  }

  /**
   * Alternative method: Send WhatsApp one by one (if batch fails)
   */
  private function sendWhatsAppOneByOne($wablasHost, $wablasToken, $wablasSecret, $data, $permohonanId, $noRegister)
  {
    try {
      $client = new Client();
      $url = rtrim($wablasHost, '/') . '/api/v2/send-template';
      $authHeader = $wablasToken . '.' . $wablasSecret;

      $successCount = 0;
      $failCount = 0;

      foreach ($data as $item) {
        try {
          $response = $client->post($url, [
            'headers' => [
              'Authorization' => $authHeader,
              'Content-Type' => 'application/json',
            ],
            'json' => [
              'data' => [$item] // Send one at a time
            ],
            'timeout' => 30,
            'verify' => false
          ]);

          $statusCode = $response->getStatusCode();
          $responseBody = json_decode($response->getBody()->getContents(), true);

          if ($statusCode === 200 && isset($responseBody['status']) && $responseBody['status'] === true) {
            $successCount++;
            Log::info('WhatsApp sent successfully to one doctor', [
              'phone' => $item['phone'],
              'response' => $responseBody
            ]);
          } else {
            $failCount++;
            Log::warning('Failed to send WhatsApp to one doctor', [
              'phone' => $item['phone'],
              'status_code' => $statusCode,
              'response' => $responseBody
            ]);
          }
        } catch (\Exception $e) {
          $failCount++;
          Log::error('Error sending WhatsApp to one doctor: ' . $e->getMessage(), [
            'phone' => $item['phone']
          ]);
        }
      }

      Log::info('Alternative method completed', [
        'success_count' => $successCount,
        'fail_count' => $failCount,
        'total' => count($data)
      ]);

    } catch (\Exception $e) {
      Log::error('Error in alternative method (one by one): ' . $e->getMessage());
    }
  }

  /**
   * Fallback method: Send simple text message (without template)
   */
  private function sendWhatsAppSimple($wablasHost, $wablasToken, $wablasSecret, $data, $permohonanId, $noRegister)
  {
    try {
      // Implementasi pakai cURL native, mengikuti contoh Wablas
      $url = rtrim($wablasHost, '/') . '/api/send-message';
      $authHeader = $wablasToken . '.' . $wablasSecret;

      $successCount = 0;
      $failCount = 0;

      foreach ($data as $item) {
        if (empty($item['phone']) || empty($item['message'])) {
          continue;
        }

        $payload = [
          'phone'   => (string) $item['phone'],
          'message' => $item['message'],
          // sesuai contoh: string, bukan boolean
          'isGroup' => 'false',
        ];

        $curl = curl_init();
        curl_setopt($curl, CURLOPT_HTTPHEADER, [
          "Authorization: {$authHeader}",
        ]);
        curl_setopt($curl, CURLOPT_CUSTOMREQUEST, "POST");
        curl_setopt($curl, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($curl, CURLOPT_POSTFIELDS, http_build_query($payload));
        curl_setopt($curl, CURLOPT_URL, $url);
        curl_setopt($curl, CURLOPT_SSL_VERIFYHOST, 0);
        curl_setopt($curl, CURLOPT_SSL_VERIFYPEER, 0);

        $result = curl_exec($curl);
        $curlError = curl_error($curl);
        curl_close($curl);

        if ($result === false) {
          $failCount++;
          Log::error('Error sending simple WhatsApp via cURL', [
            'phone' => $item['phone'],
            'error' => $curlError,
          ]);
          continue;
        }

        $decoded = json_decode($result, true);

        // Jika API mengembalikan struktur dengan key "status"
        $statusOk = is_array($decoded)
          ? ($decoded['status'] ?? true)
          : true;

        if ($statusOk) {
          $successCount++;
          Log::info('Simple WhatsApp sent successfully via cURL', [
            'phone'   => $item['phone'],
            'result'  => $decoded ?? $result,
          ]);
        } else {
          $failCount++;
          Log::warning('Simple WhatsApp failed via cURL', [
            'phone'   => $item['phone'],
            'raw'     => $result,
            'decoded' => $decoded,
          ]);
        }
      }

      Log::info('Simple method completed (cURL)', [
        'success_count' => $successCount,
        'fail_count'    => $failCount,
        'total'         => $successCount + $failCount,
      ]);

    } catch (\Exception $e) {
      Log::error('Error in simple method: ' . $e->getMessage());
    }
  }

  /**
   * Save history for parameter repetition
   */
  public function saveParameterHistory(Request $request, $parameter_id)
  {
    try {
      $isSub = $request->input('is_sub', false);
      
      if ($isSub) {
        $parameter = \Smt\Masterweb\Models\PermohonanUjiSubParameterKlinik::find($parameter_id);
        
        if (!$parameter) {
          return response()->json([
            'status' => false,
            'pesan' => 'Sub Parameter tidak ditemukan'
          ], 404);
        }

        // Get current hasil value from request (if provided) or from model
        // Only hasil is saved to history and reset, keterangan and method remain unchanged
        $current_hasil = $request->input('hasil', $parameter->hasil_permohonan_uji_sub_parameter_klinik);

        // Save only hasil to history
        $history = new PermohonanUjiSubParameterKlinikHistory();
        $history->id_permohonan_uji_sub_parameter_klinik_history = Uuid::uuid4()->toString();
        $history->permohonan_uji_sub_parameter_klinik_id = $parameter_id;
        $history->hasil_permohonan_uji_sub_parameter_klinik = $current_hasil;
        $history->created_by = Auth::id();
        $history->save();

        // Clear only hasil for new input, keep keterangan unchanged
        // IMPORTANT: Keterangan MUST NOT be reset - it remains unchanged in the database
        $parameter->hasil_permohonan_uji_sub_parameter_klinik = null;
        // Keterangan tidak diubah - tetap dipertahankan di database
        // DO NOT reset: $parameter->keterangan_permohonan_uji_sub_parameter_klinik
        $parameter->selected_history_id = null; // Clear selected history
        $parameter->save();
      } else {
        $parameter = PermohonanUjiParameterKlinik::find($parameter_id);
        
        if (!$parameter) {
          return response()->json([
            'status' => false,
            'pesan' => 'Parameter tidak ditemukan'
          ], 404);
        }

        // Get current hasil value from request (if provided) or from model
        // Only hasil is saved to history and reset, keterangan and method remain unchanged
        $current_hasil = $request->input('hasil', $parameter->hasil_permohonan_uji_parameter_klinik);

        // Save only hasil to history
        $history = new PermohonanUjiParameterKlinikHistory();
        $history->id_permohonan_uji_parameter_klinik_history = Uuid::uuid4()->toString();
        $history->permohonan_uji_parameter_klinik_id = $parameter_id;
        $history->hasil_permohonan_uji_parameter_klinik = $current_hasil;
        $history->created_by = Auth::id();
        $history->save();

        // Clear only hasil for new input, keep keterangan and method unchanged
        // IMPORTANT: Keterangan and Method MUST NOT be reset - they remain unchanged in the database
        $parameter->hasil_permohonan_uji_parameter_klinik = null;
        // Keterangan dan method tidak diubah - tetap dipertahankan di database
        // DO NOT reset: $parameter->keterangan_permohonan_uji_parameter_klinik
        // DO NOT reset: $parameter->method_permohonan_uji_parameter_klinik
        $parameter->selected_history_id = null; // Clear selected history
        $parameter->save();
      }

      return response()->json([
        'status' => true,
        'pesan' => 'History berhasil disimpan. Silakan input hasil baru.',
        'history_id' => $history->id ?? $history->id_permohonan_uji_parameter_klinik_history ?? $history->id_permohonan_uji_sub_parameter_klinik_history
      ]);
    } catch (\Exception $e) {
      return response()->json([
        'status' => false,
        'pesan' => 'Error: ' . $e->getMessage()
      ], 500);
    }
  }

  /**
   * Get history for a parameter
   */
  public function getParameterHistory(Request $request, $parameter_id)
  {
    try {
      $isSub = $request->input('is_sub', false);
      
      if ($isSub) {
        $parameter = \Smt\Masterweb\Models\PermohonanUjiSubParameterKlinik::with(['history.creator', 'selectedHistory'])->find($parameter_id);
        
        if (!$parameter) {
          return response()->json([
            'status' => false,
            'pesan' => 'Sub Parameter tidak ditemukan'
          ], 404);
        }

        $histories = $parameter->history->map(function($history) use ($parameter) {
          return [
            'id' => $history->id_permohonan_uji_sub_parameter_klinik_history,
            'hasil' => $history->hasil_permohonan_uji_sub_parameter_klinik,
            'created_at' => $history->created_at ? $history->created_at->format('d/m/Y H:i:s') : '-',
            'created_by' => $history->creator ? $history->creator->name : 'System',
            'is_selected' => $parameter->selected_history_id == $history->id_permohonan_uji_sub_parameter_klinik_history
          ];
        });

        return response()->json([
          'status' => true,
          'data' => $histories,
          'current_result' => $parameter->hasil_permohonan_uji_sub_parameter_klinik,
          'selected_history_id' => $parameter->selected_history_id
        ]);
      } else {
        $parameter = PermohonanUjiParameterKlinik::with(['history.creator', 'selectedHistory'])->find($parameter_id);
        
        if (!$parameter) {
          return response()->json([
            'status' => false,
            'pesan' => 'Parameter tidak ditemukan'
          ], 404);
        }

        $histories = $parameter->history->map(function($history) use ($parameter) {
          return [
            'id' => $history->id_permohonan_uji_parameter_klinik_history,
            'hasil' => $history->hasil_permohonan_uji_parameter_klinik,
            'created_at' => $history->created_at ? $history->created_at->format('d/m/Y H:i:s') : '-',
            'created_by' => $history->creator ? $history->creator->name : 'System',
            'is_selected' => $parameter->selected_history_id == $history->id_permohonan_uji_parameter_klinik_history
          ];
        });

        return response()->json([
          'status' => true,
          'data' => $histories,
          'current_result' => $parameter->hasil_permohonan_uji_parameter_klinik,
          'selected_history_id' => $parameter->selected_history_id
        ]);
      }
    } catch (\Exception $e) {
      \Log::error('Error in getParameterHistory: ' . $e->getMessage(), [
        'trace' => $e->getTraceAsString(),
        'parameter_id' => $parameter_id,
        'is_sub' => $isSub ?? false
      ]);
      return response()->json([
        'status' => false,
        'pesan' => 'Error: ' . $e->getMessage()
      ], 500);
    }
  }

  /**
   * Update kesimpulan hasil
   */
  public function updateKesimpulanHasil(Request $request, $id_permohonan_uji_klinik)
  {
    try {
      $post = PermohonanUjiKlinik2::find($id_permohonan_uji_klinik);
      
      if (!$post) {
        return response()->json([
          'status' => false,
          'pesan' => 'Data permohonan uji klinik tidak ditemukan'
        ], 404);
      }

      // Simpan catatan hasil
      if ($request->has('catatan_hasil')) {
        $post->catatan_hasil = $request->post('catatan_hasil');
      }

      $post->kesimpulan_hasil = $request->post('kesimpulan_hasil');
      $post->save();

      return response()->json([
        'status' => true,
        'pesan' => 'Kesimpulan hasil berhasil disimpan.'
      ]);
    } catch (\Exception $e) {
      \Log::error('Error updating kesimpulan hasil: ' . $e->getMessage());
      return response()->json([
        'status' => false,
        'pesan' => 'Terjadi kesalahan saat menyimpan: ' . $e->getMessage()
      ], 500);
    }
  }

  /**
   * Select a history as the current result
   */
  public function selectParameterHistory(Request $request, $parameter_id)
  {
    try {
      $isSub = $request->input('is_sub', false);
      
      if ($isSub) {
        $parameter = \Smt\Masterweb\Models\PermohonanUjiSubParameterKlinik::find($parameter_id);
        
        if (!$parameter) {
          return response()->json([
            'status' => false,
            'pesan' => 'Sub Parameter tidak ditemukan'
          ], 404);
        }

        $history_id = $request->input('history_id');
        $history = PermohonanUjiSubParameterKlinikHistory::find($history_id);

        if (!$history || $history->permohonan_uji_sub_parameter_klinik_id != $parameter_id) {
          return response()->json([
            'status' => false,
            'pesan' => 'History tidak ditemukan'
          ], 404);
        }

        // Restore only hasil from history (keterangan and method remain unchanged)
        $parameter->hasil_permohonan_uji_sub_parameter_klinik = $history->hasil_permohonan_uji_sub_parameter_klinik;
        // Keterangan tidak diubah
        $parameter->selected_history_id = $history_id;
        $parameter->save();
      } else {
        $parameter = PermohonanUjiParameterKlinik::find($parameter_id);
        
        if (!$parameter) {
          return response()->json([
            'status' => false,
            'pesan' => 'Parameter tidak ditemukan'
          ], 404);
        }

        $history_id = $request->input('history_id');
        $history = PermohonanUjiParameterKlinikHistory::find($history_id);

        if (!$history || $history->permohonan_uji_parameter_klinik_id != $parameter_id) {
          return response()->json([
            'status' => false,
            'pesan' => 'History tidak ditemukan'
          ], 404);
        }

        // Restore only hasil from history (keterangan and method remain unchanged)
        $parameter->hasil_permohonan_uji_parameter_klinik = $history->hasil_permohonan_uji_parameter_klinik;
        // Keterangan dan method tidak diubah
        $parameter->selected_history_id = $history_id;
        $parameter->save();
      }

      return response()->json([
        'status' => true,
        'pesan' => 'History berhasil dipilih sebagai hasil saat ini'
      ]);
    } catch (\Exception $e) {
      return response()->json([
        'status' => false,
        'pesan' => 'Error: ' . $e->getMessage()
      ], 500);
    }
  }

  /**
   * Kirim ulang PDF hasil ke WhatsApp dari halaman verification (manual).
   */
  public function resendHasilWhatsApp(Request $request, $id)
  {
    try {
      $permohonan = PermohonanUjiKlinik2::with('pasien')->find($id);
      if (!$permohonan) {
        return response()->json([
          'status' => false,
          'pesan' => 'Permohonan tidak ditemukan.',
        ], 404);
      }

      $pasien = $permohonan->pasien;
      if (!$pasien || empty($pasien->phone_pasien)) {
        return response()->json([
          'status' => false,
          'pesan' => 'Nomor HP pelanggan kosong. Tidak bisa mengirim WhatsApp.',
        ], 422);
      }

      $validasiSelesai = VerificationActivitySample::where('is_klinik', $id)
        ->where('id_verification_activity', 5)
        ->where(function ($q) {
          $q->where('resampling', 0)->orWhereNull('resampling');
        })
        ->where('is_done', 1)
        ->exists();
      $statusSelesai = strtoupper((string) ($permohonan->status_permohonan_uji_klinik ?? '')) === 'SELESAI';

      if (!$validasiSelesai && !$statusSelesai) {
        return response()->json([
          'status' => false,
          'pesan' => 'Hasil belum selesai divalidasi. Selesaikan validasi terlebih dahulu sebelum mengirim WhatsApp.',
        ], 422);
      }

      $result = $this->sendPdfHasilToPasien($id, $pasien);
      if (!empty($result['success'])) {
        return response()->json([
          'status' => true,
          'pesan' => $result['message'] ?? 'Hasil berhasil dikirim via WhatsApp.',
        ]);
      }

      return response()->json([
        'status' => false,
        'pesan' => $result['message'] ?? 'Gagal mengirim hasil via WhatsApp.',
      ], 500);
    } catch (\Throwable $e) {
      Log::error('resendHasilWhatsApp gagal: ' . $e->getMessage(), [
        'permohonan_id' => $id,
        'trace' => $e->getTraceAsString(),
      ]);

      return response()->json([
        'status' => false,
        'pesan' => 'Terjadi kesalahan saat mengirim WhatsApp: ' . $e->getMessage(),
      ], 500);
    }
  }

  /**
   * Send PDF hasil to pasien via WhatsApp.
   * Generate PDF lokal lalu kirim via Wablas send-document-from-local (base64),
   * karena endpoint send-document menolak URL print (tanpa ekstensi .pdf / tidak publik).
   * Dipanggil juga dari MobileDokterController setelah validasi.
   *
   * @param string $permohonanId
   * @param Pasien $pasien
   * @return array{success:bool,message:string}
   */
  public function sendPdfHasilToPasien($permohonanId, $pasien)
  {
    try {
      Log::info('sendPdfHasilToPasien called', ['permohonan_id' => $permohonanId, 'pasien_id' => $pasien->id_pasien]);

      $wablasHost = config('services.wablas.host');
      $wablasToken = config('services.wablas.token');
      $wablasSecret = config('services.wablas.secret');

      if (empty($wablasHost) || empty($wablasToken) || empty($wablasSecret)) {
        Log::warning('Wablas configuration is missing. WhatsApp PDF notification skipped.');
        return ['success' => false, 'message' => 'Konfigurasi Wablas belum diisi.'];
      }

      if (empty($pasien->phone_pasien)) {
        Log::info('Pasien does not have phone number. WhatsApp PDF notification skipped.', [
          'pasien_id' => $pasien->id_pasien
        ]);
        return ['success' => false, 'message' => 'Nomor HP pelanggan kosong.'];
      }

      $phone = preg_replace('/[^0-9]/', '', $pasien->phone_pasien);
      if (substr($phone, 0, 2) !== '62') {
        if (substr($phone, 0, 1) === '0') {
          $phone = '62' . substr($phone, 1);
        } else {
          $phone = '62' . $phone;
        }
      }

      $permohonan = PermohonanUjiKlinik2::find($permohonanId);
      $namaPasien = $pasien->nama_pasien ?? '-';
      $noRegister = optional($permohonan)->noregister_permohonan_uji_klinik ?? $permohonanId;
      $jamSekarang = Carbon::now()->hour;
      $salam = ($jamSekarang < 10) ? 'pagi' : 'siang';

      $caption = "Selamat {$salam}.\n"
               . "Kami dari Labkes Kab. Magelang.\n"
               . "Mohon ijin menyampaikan hasil pemeriksaan atas nama {$namaPasien} sudah selesai dan sudah dapat diambil.\n"
               . "Berikut terlampir untuk hasilnya.\n"
               . "Terima kasih";

      $safeName = preg_replace('/[^A-Za-z0-9_-]+/', '_', (string) $noRegister);
      $fileName = 'Hasil_Lab_' . $safeName . '.pdf';

      // Generate PDF binary dari endpoint print yang sama (force_kop=1)
      $pdfContent = $this->generatePdfHasilBinary($permohonanId);
      if ($pdfContent === null) {
        Log::error('Gagal generate PDF hasil untuk WhatsApp', ['permohonan_id' => $permohonanId]);
        return ['success' => false, 'message' => 'Gagal membuat PDF hasil.'];
      }

      $pdfSize = strlen($pdfContent);
      Log::info('Preparing to send PDF via Wablas send-document-from-local', [
        'phone' => $phone,
        'permohonan_id' => $permohonanId,
        'file_name' => $fileName,
        'pdf_size_bytes' => $pdfSize,
      ]);

      // Batas Wablas send-document-from-local: 2MB
      if ($pdfSize > (2 * 1024 * 1024)) {
        Log::warning('PDF hasil melebihi 2MB, coba kirim via URL publik .pdf', [
          'permohonan_id' => $permohonanId,
          'pdf_size_bytes' => $pdfSize,
        ]);
        $fallbackOk = $this->sendPdfHasilToPasienViaPublicUrl($wablasHost, $wablasToken, $wablasSecret, $phone, $pdfContent, $fileName, $caption, $permohonanId, $pasien);
        return $fallbackOk
          ? ['success' => true, 'message' => 'Hasil berhasil dikirim via WhatsApp (URL publik).']
          : ['success' => false, 'message' => 'PDF terlalu besar dan gagal dikirim via URL publik.'];
      }

      $authHeader = $wablasToken . '.' . $wablasSecret;

      // Caption dikirim sebagai pesan teks terpisah (from-local tidak punya caption yang andal)
      $this->sendWablasTextMessage($wablasHost, $authHeader, $phone, $caption);

      $formData = [
        'phone' => $phone,
        'file' => base64_encode($pdfContent),
        'data' => json_encode(['name' => $fileName]),
        'name_file' => $fileName,
      ];

      $url = rtrim($wablasHost, '/') . '/api/send-document-from-local';

      $curl = curl_init();
      curl_setopt($curl, CURLOPT_HTTPHEADER, [
        "Authorization: {$authHeader}",
      ]);
      curl_setopt($curl, CURLOPT_CUSTOMREQUEST, "POST");
      curl_setopt($curl, CURLOPT_RETURNTRANSFER, true);
      curl_setopt($curl, CURLOPT_POSTFIELDS, http_build_query($formData));
      curl_setopt($curl, CURLOPT_URL, $url);
      curl_setopt($curl, CURLOPT_SSL_VERIFYHOST, 0);
      curl_setopt($curl, CURLOPT_SSL_VERIFYPEER, 0);
      curl_setopt($curl, CURLOPT_TIMEOUT, 120);

      $result = curl_exec($curl);
      $curlError = curl_error($curl);
      $httpCode = curl_getinfo($curl, CURLINFO_HTTP_CODE);
      curl_close($curl);

      if ($result === false) {
        Log::error('Error sending WhatsApp document via cURL', [
          'error' => $curlError,
          'permohonan_id' => $permohonanId,
          'phone' => $phone
        ]);
        return ['success' => false, 'message' => 'Gagal menghubungi Wablas: ' . $curlError];
      }

      $responseBody = json_decode($result, true);

      Log::info('WhatsApp document response received', [
        'http_code' => $httpCode,
        'response' => $responseBody,
        'raw_result' => $result,
      ]);

      if ($httpCode === 200 && isset($responseBody['status']) && $responseBody['status'] === true) {
        Log::info('WhatsApp PDF hasil sent successfully to pasien', [
          'permohonan_id' => $permohonanId,
          'pasien_id' => $pasien->id_pasien,
          'phone' => $phone
        ]);
        return ['success' => true, 'message' => 'Hasil berhasil dikirim via WhatsApp ke ' . $phone . '.'];
      }

      Log::warning('Wablas send-document-from-local API did not return success', [
        'http_code' => $httpCode,
        'response' => $responseBody,
        'permohonan_id' => $permohonanId
      ]);

      $apiMessage = is_array($responseBody) ? ($responseBody['message'] ?? json_encode($responseBody)) : (string) $result;
      return ['success' => false, 'message' => 'Wablas menolak pengiriman: ' . $apiMessage];

    } catch (\Exception $e) {
      Log::error('Error sending WhatsApp PDF hasil to pasien: ' . $e->getMessage(), [
        'permohonan_id' => $permohonanId,
        'pasien_id' => $pasien->id_pasien ?? null,
        'error' => $e->getTraceAsString()
      ]);
      return ['success' => false, 'message' => 'Error: ' . $e->getMessage()];
    }
  }

  /**
   * Generate binary PDF hasil klinik (sama seperti cetak hasil, force_kop=1).
   *
   * @param string $permohonanId
   * @return string|null
   */
  private function generatePdfHasilBinary($permohonanId)
  {
    try {
      $fakeRequest = Request::create(
        '/print-permohonan-uji-klinik-hasil-2/' . $permohonanId,
        'GET',
        ['signoption' => 0, 'force_kop' => 1]
      );

      if (request() && request()->hasSession()) {
        $fakeRequest->setLaravelSession(request()->session());
      }

      $response = $this->printPermohonanUjiKlinikHasil($fakeRequest, $permohonanId);

      if (!$response || !method_exists($response, 'getContent')) {
        return null;
      }

      $content = $response->getContent();
      if (!is_string($content) || strlen($content) < 5 || substr($content, 0, 4) !== '%PDF') {
        Log::error('generatePdfHasilBinary: output bukan PDF valid', [
          'permohonan_id' => $permohonanId,
          'content_prefix' => is_string($content) ? substr($content, 0, 80) : gettype($content),
        ]);
        return null;
      }

      return $content;
    } catch (\Throwable $e) {
      Log::error('generatePdfHasilBinary failed: ' . $e->getMessage(), [
        'permohonan_id' => $permohonanId,
      ]);
      return null;
    }
  }

  /**
   * Fallback: simpan PDF ke storage publik (ekstensi .pdf) lalu kirim via send-document URL.
   *
   * @return bool
   */
  private function sendPdfHasilToPasienViaPublicUrl($wablasHost, $wablasToken, $wablasSecret, $phone, $pdfContent, $fileName, $caption, $permohonanId, $pasien)
  {
    $relativePath = 'wa-hasil/' . $permohonanId . '/' . $fileName;
    Storage::disk('public')->put($relativePath, $pdfContent);

    $pdfUrl = url('/storage/' . $relativePath);
    $pdfUrl = preg_replace('#^http://#', 'https://', $pdfUrl);

    if (strpos($pdfUrl, 'localhost') !== false || strpos($pdfUrl, '127.0.0.1') !== false) {
      Log::error('Tidak bisa kirim PDF via URL publik karena APP_URL localhost', [
        'pdf_url' => $pdfUrl,
        'permohonan_id' => $permohonanId,
      ]);
      return false;
    }

    $authHeader = $wablasToken . '.' . $wablasSecret;
    $this->sendWablasTextMessage($wablasHost, $authHeader, $phone, $caption);

    $formData = [
      'phone' => $phone,
      'document' => $pdfUrl,
      'caption' => $fileName,
    ];

    $url = rtrim($wablasHost, '/') . '/api/send-document';
    $curl = curl_init();
    curl_setopt($curl, CURLOPT_HTTPHEADER, ["Authorization: {$authHeader}"]);
    curl_setopt($curl, CURLOPT_CUSTOMREQUEST, "POST");
    curl_setopt($curl, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($curl, CURLOPT_POSTFIELDS, http_build_query($formData));
    curl_setopt($curl, CURLOPT_URL, $url);
    curl_setopt($curl, CURLOPT_SSL_VERIFYHOST, 0);
    curl_setopt($curl, CURLOPT_SSL_VERIFYPEER, 0);
    $result = curl_exec($curl);
    $httpCode = curl_getinfo($curl, CURLINFO_HTTP_CODE);
    curl_close($curl);

    $responseBody = json_decode($result, true);
    Log::info('WhatsApp document (public URL fallback) response', [
      'http_code' => $httpCode,
      'response' => $responseBody,
      'pdf_url' => $pdfUrl,
      'permohonan_id' => $permohonanId,
    ]);

    return $httpCode === 200 && isset($responseBody['status']) && $responseBody['status'] === true;
  }

  /**
   * Kirim pesan teks sederhana via Wablas API v1.
   */
  private function sendWablasTextMessage($wablasHost, $authHeader, $phone, $message)
  {
    $url = rtrim($wablasHost, '/') . '/api/send-message';
    $curl = curl_init();
    curl_setopt($curl, CURLOPT_HTTPHEADER, ["Authorization: {$authHeader}"]);
    curl_setopt($curl, CURLOPT_CUSTOMREQUEST, "POST");
    curl_setopt($curl, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($curl, CURLOPT_POSTFIELDS, http_build_query([
      'phone' => $phone,
      'message' => $message,
    ]));
    curl_setopt($curl, CURLOPT_URL, $url);
    curl_setopt($curl, CURLOPT_SSL_VERIFYHOST, 0);
    curl_setopt($curl, CURLOPT_SSL_VERIFYPEER, 0);
    $result = curl_exec($curl);
    $httpCode = curl_getinfo($curl, CURLINFO_HTTP_CODE);
    curl_close($curl);

    Log::info('Wablas caption text sent', [
      'http_code' => $httpCode,
      'phone' => $phone,
      'response' => json_decode($result, true),
    ]);
  }

  /**
   * Urutkan parameter permohonan sesuai panel pendaftaran (ParameterCategoryLayout).
   * Mengelompokkan per kategori layout dan mengurutkan paket mengikuti posisi grid.
   */
  private function reorderPermohonanParameterByCategoryLayout(array $arr_permohonan_parameter): array
  {
    try {
      $categoryLayouts = ParameterCategoryLayout::where('is_active', 1)
        ->orderBy('sort_order', 'asc')
        ->with(['categoryItems' => function ($query) {
          $query->with('parameterPaketKlinik')
            ->orderBy('row_position', 'asc')
            ->orderBy('column_position', 'asc')
            ->orderBy('sort_order', 'asc');
        }])
        ->get();

      if ($categoryLayouts->isEmpty()) {
        return $arr_permohonan_parameter;
      }

      $allSatuan = [];
      foreach ($arr_permohonan_parameter as $jenisGroup) {
        foreach ($jenisGroup['item_permohonan_parameter_satuan'] ?? [] as $satuan) {
          $allSatuan[] = $satuan;
        }
      }

      if (empty($allSatuan)) {
        return $arr_permohonan_parameter;
      }

      $paketLayoutOrder = [];
      $paketCategoryMap = [];
      $orderIndex = 0;

      foreach ($categoryLayouts as $category) {
        foreach ($category->categoryItems as $layoutItem) {
          if ($layoutItem->parameterPaketKlinik) {
            $paketId = $layoutItem->parameterPaketKlinik->id_parameter_paket_klinik;
            if (!isset($paketLayoutOrder[$paketId])) {
              $paketLayoutOrder[$paketId] = $orderIndex++;
              $paketCategoryMap[$paketId] = [
                'category_sort' => (int) ($category->sort_order ?? 999),
                'category_label' => trim(($category->category_code ?? '') . '. ' . ($category->category_name ?? '')),
              ];
            }
          }
        }
      }

      foreach ($allSatuan as &$satuan) {
        $paketId = $satuan['parameter_paket_klinik'] ?? null;
        $satuan['_layout_sort'] = ($paketId && isset($paketLayoutOrder[$paketId]))
          ? $paketLayoutOrder[$paketId]
          : PHP_INT_MAX;
        $satuan['_category_sort'] = ($paketId && isset($paketCategoryMap[$paketId]))
          ? $paketCategoryMap[$paketId]['category_sort']
          : PHP_INT_MAX;
        $satuan['_category_label'] = ($paketId && isset($paketCategoryMap[$paketId]))
          ? $paketCategoryMap[$paketId]['category_label']
          : null;
      }
      unset($satuan);

      usort($allSatuan, function ($a, $b) {
        if ($a['_layout_sort'] !== $b['_layout_sort']) {
          return $a['_layout_sort'] <=> $b['_layout_sort'];
        }

        $sortA = isset($a['sorting_parameter_satuan'])
          ? (int) $a['sorting_parameter_satuan']
          : (isset($a['sort_parameter_satuan_klinik']) ? (int) $a['sort_parameter_satuan_klinik'] : 9999);
        $sortB = isset($b['sorting_parameter_satuan'])
          ? (int) $b['sorting_parameter_satuan']
          : (isset($b['sort_parameter_satuan_klinik']) ? (int) $b['sort_parameter_satuan_klinik'] : 9999);

        return $sortA <=> $sortB;
      });

      $newArr = [];
      $currentCategoryLabel = null;
      $currentGroup = null;

      foreach ($allSatuan as $satuan) {
        $categoryLabel = $satuan['_category_label'];
        if ($categoryLabel === null || $categoryLabel === '. ') {
          $categoryLabel = 'LAINNYA';
        }

        if ($categoryLabel !== $currentCategoryLabel) {
          if ($currentGroup !== null) {
            $newArr[] = $currentGroup;
          }
          $currentCategoryLabel = $categoryLabel;
          $currentGroup = [
            'name_parameter_jenis_klinik' => $categoryLabel,
            'id_parameter_jenis_klinik' => null,
            'sort_parameter_jenis_klinik' => $satuan['_category_sort'] ?? 999999,
            'item_permohonan_parameter_satuan' => [],
          ];
        }

        unset($satuan['_layout_sort'], $satuan['_category_sort'], $satuan['_category_label']);
        $currentGroup['item_permohonan_parameter_satuan'][] = $satuan;
      }

      if ($currentGroup !== null) {
        $newArr[] = $currentGroup;
      }

      return !empty($newArr) ? $newArr : $arr_permohonan_parameter;
    } catch (\Throwable $e) {
      return $arr_permohonan_parameter;
    }
  }

  /**
   * Peta urutan cetak per ID parameter — langsung dari sort master (halaman reorder).
   * Jangan gabung by nama: "Leukosit" Urin Rutin dan "Leukosit" Sedimen punya sort berbeda.
   */
  private function buildPrintSatuanSortMapById(): array
  {
    $map = [];

    $records = ParameterSatuanKlinik::whereNull('deleted_at')
      ->get(['id_parameter_satuan_klinik', 'sort_parameter_satuan_klinik']);

    foreach ($records as $record) {
      $map[(string) $record->id_parameter_satuan_klinik] = (int) ($record->sort_parameter_satuan_klinik ?? 9999);
    }

    return $map;
  }

  /**
   * Peta urutan cetak per nama — fallback saja jika ID master hilang.
   * Ambil sort terkecil per nama kanonik (untuk alias creatinin/creatinine).
   * Jangan dipakai di atas lookup ID (nama sama beda jenis = sort beda).
   */
  private function buildPrintSatuanSortMapByName(): array
  {
    $map = [];
    $records = ParameterSatuanKlinik::whereNull('deleted_at')
      ->orderBy('sort_parameter_satuan_klinik', 'asc')
      ->get(['name_parameter_satuan_klinik', 'sort_parameter_satuan_klinik']);

    foreach ($records as $record) {
      $canonicalName = $this->canonicalPrintSatuanSortName($record->name_parameter_satuan_klinik ?? '');
      if ($canonicalName === '') {
        continue;
      }

      $sort = (int) ($record->sort_parameter_satuan_klinik ?? 9999);
      if (!isset($map[$canonicalName]) || $sort < $map[$canonicalName]) {
        $map[$canonicalName] = $sort;
      }
    }

    return $map;
  }

  private function normalizePrintSatuanName(?string $name): string
  {
    $normalized = trim(preg_replace('/\s+/u', ' ', $name ?? ''));

    return mb_strtolower($normalized, 'UTF-8');
  }

  /**
   * Nama kanonik untuk lookup urutan reorder (gabung varian ejaan / duplikat master).
   */
  private function canonicalPrintSatuanSortName(?string $name): string
  {
    $normalized = $this->normalizePrintSatuanName($name);
    if ($normalized === '') {
      return '';
    }

    static $aliasGroups = [
      'creatinine' => ['creatinine', 'kreatinin'],
    ];

    foreach ($aliasGroups as $canonical => $aliases) {
      if (in_array($normalized, $aliases, true)) {
        return $canonical;
      }
    }

    return $normalized;
  }

  /**
   * Selisih sort duplikat master yang dianggap "salinan jenis lain" (bukan tes berbeda).
   * Contoh: Cholesterol Kimia (86) vs Lemak Darah (5) → pakai 5.
   * Leukosit Sedimen (49) vs Darah Rutin (14) selisih 35 → tetap pakai 49.
   */
  private const PRINT_DUPLICATE_MASTER_SORT_GAP = 50;

  private function resolvePrintSatuanSortValue(array $satuan, array $sortMapById, array $sortMapByName): int
  {
    $id = isset($satuan['parameter_satuan_klinik']) ? (string) $satuan['parameter_satuan_klinik'] : '';
    $idSort = null;

    if ($id !== '' && isset($sortMapById[$id])) {
      $idSort = (int) $sortMapById[$id];
    } elseif (isset($satuan['sort_parameter_satuan_klinik']) && $satuan['sort_parameter_satuan_klinik'] !== null && $satuan['sort_parameter_satuan_klinik'] !== '') {
      $idSort = (int) $satuan['sort_parameter_satuan_klinik'];
    }

    $canonicalName = $this->canonicalPrintSatuanSortName($satuan['nama_parameter_satuan_klinik'] ?? '');
    $nameMinSort = ($canonicalName !== '' && isset($sortMapByName[$canonicalName]))
      ? (int) $sortMapByName[$canonicalName]
      : null;

    if ($idSort !== null) {
      if (
        $nameMinSort !== null
        && $idSort > $nameMinSort
        && ($idSort - $nameMinSort) >= self::PRINT_DUPLICATE_MASTER_SORT_GAP
      ) {
        return $nameMinSort;
      }

      return $idSort;
    }

    if ($nameMinSort !== null) {
      return $nameMinSort;
    }

    if (isset($satuan['sorting_permohonan_uji_parameter_klinik']) && $satuan['sorting_permohonan_uji_parameter_klinik'] !== null && $satuan['sorting_permohonan_uji_parameter_klinik'] !== '') {
      return (int) $satuan['sorting_permohonan_uji_parameter_klinik'];
    }

    if (isset($satuan['sorting_parameter_satuan']) && $satuan['sorting_parameter_satuan'] !== null && $satuan['sorting_parameter_satuan'] !== '') {
      return (int) $satuan['sorting_parameter_satuan'];
    }

    return 9999;
  }

  private function comparePrintSatuanSortItems(array $a, array $b, array $sortMapById, array $sortMapByName): int
  {
    $sortA = $this->resolvePrintSatuanSortValue($a, $sortMapById, $sortMapByName);
    $sortB = $this->resolvePrintSatuanSortValue($b, $sortMapById, $sortMapByName);

    if ($sortA !== $sortB) {
      return $sortA <=> $sortB;
    }

    return strcmp(
      (string) ($a['parameter_satuan_klinik'] ?? ''),
      (string) ($b['parameter_satuan_klinik'] ?? '')
    );
  }

  private function getGroupMinSatuanSort(array $group, array $sortMapById, array $sortMapByName): int
  {
    $min = PHP_INT_MAX;

    foreach ($group['item_permohonan_parameter_satuan'] ?? [] as $satuan) {
      $sort = $this->resolvePrintSatuanSortValue($satuan, $sortMapById, $sortMapByName);
      if ($sort < $min) {
        $min = $sort;
      }
    }

    return $min === PHP_INT_MAX ? 9999 : $min;
  }

  private function resolveEffectiveJenisParameterKlinikId($permohonanParameter): ?string
  {
    if (!empty($permohonanParameter->jenis_parameter_klinik_id)) {
      return $permohonanParameter->jenis_parameter_klinik_id;
    }

    return $permohonanParameter->parametersatuanklinik->parameter_jenis_klinik ?? null;
  }

  /**
   * Backfill jenis_parameter_klinik_id dari master bila kosong di permohonan.
   */
  private function normalizePermohonanParameterJenisKlinik(PermohonanUjiParameterKlinik $permohonanParameter): void
  {
    if (!empty($permohonanParameter->jenis_parameter_klinik_id)) {
      return;
    }

    $jenisFromMaster = $permohonanParameter->parametersatuanklinik->parameter_jenis_klinik ?? null;
    if (empty($jenisFromMaster)) {
      return;
    }

    $permohonanParameter->jenis_parameter_klinik_id = $jenisFromMaster;
    $permohonanParameter->save();
  }

  /**
   * Constraint master parameter untuk cetak/preview HASIL PEMERIKSAAN LABORATORIUM.
   * - jenis 0 (Pemeriksaan Klinik) selalu ikut
   * - jenis lain yang punya sub-parameter (mis. Imunologi salah set Rapid Antigen) juga ikut,
   *   kecuali PCR (1) dan Rapid Antibody (2) yang punya template sendiri
   * - nama "Rapid Antigen" tetap dikecualikan (template khusus)
   */
  private function applyKlinikPrintParameterSatuanConstraint($query)
  {
    return $query->whereNull('deleted_at')
      ->where(function ($q) {
        $q->where('jenis_pemeriksaan_parameter_satuan_klinik', '0')
          ->orWhere(function ($q2) {
            $q2->whereNotIn('jenis_pemeriksaan_parameter_satuan_klinik', ['1', '2'])
              ->where(function ($q3) {
                $q3->whereNull('name_parameter_satuan_klinik')
                  ->orWhereRaw('LOWER(name_parameter_satuan_klinik) NOT LIKE ?', ['rapid antigen%']);
              })
              ->whereExists(function ($exists) {
                // COLLATE: ms_parameter_sub_satuan_klinik = utf8mb4_general_ci,
                // ms_parameter_satuan_klinik.id = utf8mb4_unicode_ci
                $exists->select(DB::raw(1))
                  ->from('ms_parameter_sub_satuan_klinik as msub_klinik_print')
                  ->whereRaw(
                    'msub_klinik_print.parameter_satuan_klinik COLLATE utf8mb4_unicode_ci = ms_parameter_satuan_klinik.id_parameter_satuan_klinik'
                  )
                  ->whereNull('msub_klinik_print.deleted_at');
              });
          });
      });
  }

  /**
   * Pastikan baris sub-parameter permohonan ada jika master punya sub-parameter.
   */
  private function ensurePermohonanSubParametersForSatuan(
    PermohonanUjiParameterKlinik $permohonanParameter,
    ?PermohonanUjiKlinik2 $permohonan = null
  ): void {
    if (empty($permohonanParameter->parameter_satuan_klinik)) {
      return;
    }

    $masterSubs = ParameterSubSatuanKlinik::where('parameter_satuan_klinik', $permohonanParameter->parameter_satuan_klinik)
      ->whereNull('deleted_at')
      ->get();

    if ($masterSubs->isEmpty()) {
      return;
    }

    $existingSubIds = PermohonanUjiSubParameterKlinik::where('permohonan_uji_parameter_klinik_id', $permohonanParameter->id_permohonan_uji_parameter_klinik)
      ->whereNull('deleted_at')
      ->pluck('parameter_sub_satuan_klinik_id')
      ->filter()
      ->all();

    $item_parameter_by_baku_mutu = null;
    if ($permohonan) {
      $pasien_umur = $permohonan->umurtahun_pasien_permohonan_uji_klinik;
      $pasien_gender = $permohonan->pasien->gender_pasien ?? null;
      $jenisId = $this->resolveEffectiveJenisParameterKlinikId($permohonanParameter);
      $is_haji = (int) ($permohonan->is_haji ?? 0);

      if ($jenisId) {
        $bakuMutuResolved = $this->resolveBakuMutuForPermohonanParameter(
          $jenisId,
          $permohonanParameter->parameter_satuan_klinik,
          $pasien_gender,
          $pasien_umur,
          $is_haji
        );
        $item_parameter_by_baku_mutu = $bakuMutuResolved['selected'] ?? null;
      }
    }

    foreach ($masterSubs as $masterSub) {
      if (in_array($masterSub->id_parameter_sub_satuan_klinik, $existingSubIds, true)) {
        continue;
      }

      $post_parameter_subsatuan = new PermohonanUjiSubParameterKlinik();
      $post_parameter_subsatuan->permohonan_uji_parameter_klinik_id = $permohonanParameter->id_permohonan_uji_parameter_klinik;
      $post_parameter_subsatuan->parameter_sub_satuan_klinik_id = $masterSub->id_parameter_sub_satuan_klinik;

      if ($item_parameter_by_baku_mutu && isset($item_parameter_by_baku_mutu->id_baku_mutu)) {
        $item_parameter_subsatuan_by_baku_mutu = BakuMutuDetailParameterKlinik::where('baku_mutu_id', $item_parameter_by_baku_mutu->id_baku_mutu)
          ->where('parameter_sub_satuan_baku_mutu_detail_parameter_klinik', $masterSub->id_parameter_sub_satuan_klinik)
          ->first();

        if ($item_parameter_subsatuan_by_baku_mutu) {
          $post_parameter_subsatuan->satuan_permohonan_uji_sub_parameter_klinik = $item_parameter_subsatuan_by_baku_mutu->unit_id_baku_mutu_detail_parameter_klinik;
          $post_parameter_subsatuan->baku_mutu_permohonan_uji_sub_parameter_klinik = $item_parameter_subsatuan_by_baku_mutu->id_baku_mutu_detail_parameter_klinik;
        }
      }

      $post_parameter_subsatuan->save();
    }
  }

  /**
   * Finalisasi urutan parameter permohonan sesuai halaman elits-parameter-satuan-klinik/reorder.
   * Dipakai di halaman analis, verifikasi, disabled, dan cetak hasil.
   */
  private function finalizeArrPermohonanParameterSort(array $arr_permohonan_parameter, bool $dedupeByParameterName = false): array
  {
    if (empty($arr_permohonan_parameter)) {
      return $arr_permohonan_parameter;
    }

    $sortMapById = $this->buildPrintSatuanSortMapById();
    $sortMapByName = $this->buildPrintSatuanSortMapByName();

    if ($dedupeByParameterName) {
      $arr_permohonan_parameter = collect($arr_permohonan_parameter)
        ->map(function ($group) use ($sortMapById, $sortMapByName) {
          $group['item_permohonan_parameter_satuan'] = collect($group['item_permohonan_parameter_satuan'] ?? [])
            ->unique('nama_parameter_satuan_klinik')
            ->sortBy(function ($param) use ($sortMapById, $sortMapByName) {
              return $this->resolvePrintSatuanSortValue($param, $sortMapById, $sortMapByName);
            })
            ->values()
            ->all();

          return $group;
        })
        ->all();
    }

    return $this->reorderPermohonanParameterBySatuanSort($arr_permohonan_parameter);
  }

  /**
   * Urutkan hasil cetak mengikuti urutan global halaman elits-parameter-satuan-klinik/reorder.
   * Parameter di-sort lintas jenis berdasarkan sort_parameter_satuan_klinik master,
   * lalu dikelompokkan ulang per jenis sesuai urutan global tersebut.
   */
  private function reorderPermohonanParameterBySatuanSort(array $arr_permohonan_parameter): array
  {
    if (empty($arr_permohonan_parameter)) {
      return $arr_permohonan_parameter;
    }

    $sortMapById = $this->buildPrintSatuanSortMapById();
    $sortMapByName = $this->buildPrintSatuanSortMapByName();
    $flat = [];

    foreach ($arr_permohonan_parameter as $group) {
      if (empty($group['item_permohonan_parameter_satuan']) || !is_array($group['item_permohonan_parameter_satuan'])) {
        continue;
      }

      foreach ($group['item_permohonan_parameter_satuan'] as $satuan) {
        $satuan['sort_parameter_satuan_klinik'] = $this->resolvePrintSatuanSortValue($satuan, $sortMapById, $sortMapByName);
        $satuan['_group_meta'] = [
          'name_parameter_jenis_klinik' => $group['name_parameter_jenis_klinik'] ?? '',
          'id_parameter_jenis_klinik' => $group['id_parameter_jenis_klinik'] ?? null,
          'sort_parameter_jenis_klinik' => $group['sort_parameter_jenis_klinik'] ?? 9999,
          'id_parameter_jenis_klinik_parent' => $group['id_parameter_jenis_klinik_parent'] ?? null,
        ];
        $flat[] = $satuan;
      }
    }

    if (empty($flat)) {
      return $arr_permohonan_parameter;
    }

    usort($flat, function ($a, $b) use ($sortMapById, $sortMapByName) {
      return $this->comparePrintSatuanSortItems($a, $b, $sortMapById, $sortMapByName);
    });

    // Gabung parameter ke grup jenis yang sama (hindari header Sedimen/URIN RUTIN berulang
    // saat urutan global satuan menyisipkan antar-jenis).
    $groupMap = [];
    $groupOrder = [];

    foreach ($flat as $satuan) {
      $meta = $satuan['_group_meta'] ?? [];
      unset($satuan['_group_meta']);

      $jenisId = (string) ($meta['id_parameter_jenis_klinik'] ?? '');

      if (!isset($groupMap[$jenisId])) {
        $groupMap[$jenisId] = [
          'name_parameter_jenis_klinik' => $meta['name_parameter_jenis_klinik'] ?? '',
          'id_parameter_jenis_klinik' => $meta['id_parameter_jenis_klinik'] ?? null,
          'sort_parameter_jenis_klinik' => $meta['sort_parameter_jenis_klinik'] ?? 9999,
          'id_parameter_jenis_klinik_parent' => $meta['id_parameter_jenis_klinik_parent'] ?? null,
          'item_permohonan_parameter_satuan' => [],
        ];
        $groupOrder[] = $jenisId;
      }

      $groupMap[$jenisId]['item_permohonan_parameter_satuan'][] = $satuan;
    }

    $newGroups = [];
    foreach ($groupOrder as $jenisId) {
      $newGroups[] = $groupMap[$jenisId];
    }

    if (empty($newGroups)) {
      return $arr_permohonan_parameter;
    }

    $sortMapById = $this->buildPrintSatuanSortMapById();
    $sortMapByName = $this->buildPrintSatuanSortMapByName();

    return $this->reorderPermohonanParameterGroupsByJenisHierarchy($newGroups, $sortMapById, $sortMapByName);
  }

  /**
   * Susun grup jenis: parent dulu (urut min sort satuan reorder page), lalu child di bawah parent.
   */
  private function reorderPermohonanParameterGroupsByJenisHierarchy(
    array $groups,
    array $sortMapById,
    array $sortMapByName
  ): array {
    if (empty($groups)) {
      return $groups;
    }

    $roots = [];
    $childrenByParent = [];

    foreach ($groups as $group) {
      $parentId = $group['id_parameter_jenis_klinik_parent'] ?? null;
      if (!empty($parentId)) {
        $childrenByParent[$parentId][] = $group;
      } else {
        $roots[] = $group;
      }
    }

    $sortGroups = function ($a, $b) use ($sortMapById, $sortMapByName) {
      $sortA = $this->getGroupMinSatuanSort($a, $sortMapById, $sortMapByName);
      $sortB = $this->getGroupMinSatuanSort($b, $sortMapById, $sortMapByName);

      if ($sortA !== $sortB) {
        return $sortA <=> $sortB;
      }

      $jenisA = (int) ($a['sort_parameter_jenis_klinik'] ?? 9999);
      $jenisB = (int) ($b['sort_parameter_jenis_klinik'] ?? 9999);
      if ($jenisA !== $jenisB) {
        return $jenisA <=> $jenisB;
      }

      return strcmp(
        (string) ($a['id_parameter_jenis_klinik'] ?? ''),
        (string) ($b['id_parameter_jenis_klinik'] ?? '')
      );
    };

    usort($roots, $sortGroups);

    foreach ($childrenByParent as &$children) {
      usort($children, $sortGroups);
    }
    unset($children);

    $result = [];
    $placedIds = [];

    foreach ($roots as $root) {
      $result[] = $root;
      $rootId = $root['id_parameter_jenis_klinik'] ?? null;
      if ($rootId) {
        $placedIds[$rootId] = true;
      }

      if ($rootId && !empty($childrenByParent[$rootId])) {
        foreach ($childrenByParent[$rootId] as $child) {
          $result[] = $child;
          $childId = $child['id_parameter_jenis_klinik'] ?? null;
          if ($childId) {
            $placedIds[$childId] = true;
          }
        }
      }
    }

    foreach ($groups as $group) {
      $id = $group['id_parameter_jenis_klinik'] ?? null;
      if ($id && empty($placedIds[$id])) {
        $result[] = $group;
      }
    }

    $ordered = !empty($result) ? $result : $groups;

    foreach ($ordered as &$group) {
      if (empty($group['item_permohonan_parameter_satuan']) || !is_array($group['item_permohonan_parameter_satuan'])) {
        continue;
      }

      usort($group['item_permohonan_parameter_satuan'], function ($a, $b) use ($sortMapById, $sortMapByName) {
        return $this->comparePrintSatuanSortItems($a, $b, $sortMapById, $sortMapByName);
      });

      foreach ($group['item_permohonan_parameter_satuan'] as &$satuan) {
        $satuan['sort_parameter_satuan_klinik'] = $this->resolvePrintSatuanSortValue($satuan, $sortMapById, $sortMapByName);
      }
      unset($satuan);
    }
    unset($group);

    return $ordered;
  }

  /**
   * Ambil hasil alat TMS untuk diisi ke form analis klinik.
   * Match biolis_results.parameter_id ke parameter satuan pada permohonan.
   */
  public function fetchTmsResults(Request $request, $id_permohonan_uji_klinik)
  {
    try {
      $permohonan = PermohonanUjiKlinik2::with('pasien')->findOrFail($id_permohonan_uji_klinik);

      $sampleIdInput = trim((string) $request->get('sample_id', ''));
      $candidates = TmsKlinikHelper::sampleIdCandidates($permohonan);

      $orderBarcodes = OrderTms::query()
        ->where('id_permohonan_uji_klinik', $id_permohonan_uji_klinik)
        ->whereNull('deleted_at')
        ->whereNotNull('kode_barcode')
        ->pluck('kode_barcode')
        ->map(function ($v) {
          return trim((string) $v);
        })
        ->filter()
        ->unique()
        ->values()
        ->all();
      $candidates = array_values(array_unique(array_merge($orderBarcodes, $candidates)));

      if ($sampleIdInput !== '') {
        array_unshift($candidates, $sampleIdInput);
        $candidates = array_values(array_unique($candidates));
      }

      $tmsQuery = \App\TmsResult::query()->orderBy('result_date', 'desc')->orderBy('id', 'desc');

      $resolvedSampleId = null;
      $tmsRows = collect();

      if (!empty($candidates)) {
        foreach ($candidates as $candidate) {
          $rows = (clone $tmsQuery)->where('sample_id', $candidate)->get();
          if ($rows->isNotEmpty()) {
            $resolvedSampleId = $candidate;
            $tmsRows = $rows;
            break;
          }
        }
      }

      // Fallback: cocokkan nama pasien
      if ($tmsRows->isEmpty()) {
        $patientName = trim((string) ($permohonan->pasien->nama_pasien ?? ''));
        if ($patientName !== '') {
          $rows = (clone $tmsQuery)
            ->where('patient_name', 'like', '%' . $patientName . '%')
            ->limit(50)
            ->get();
          if ($rows->isNotEmpty()) {
            $resolvedSampleId = $rows->first()->sample_id;
            $tmsRows = $rows->where('sample_id', $resolvedSampleId)->values();
          }
        }
      }

      $suggestedSampleIds = \App\TmsResult::query()
        ->whereNotNull('sample_id')
        ->where('sample_id', '!=', '')
        ->orderBy('result_date', 'desc')
        ->orderBy('id', 'desc')
        ->limit(80)
        ->pluck('sample_id')
        ->unique()
        ->take(15)
        ->values();

      $parameters = PermohonanUjiParameterKlinik::query()
        ->where('permohonan_uji_klinik', $id_permohonan_uji_klinik)
        ->whereNull('deleted_at')
        ->with('parametersatuanklinik')
        ->get();

      $matched = [];
      $usedParamIds = [];
      $latestByParamId = [];
      $source = 'alat';

      if ($tmsRows->isNotEmpty()) {
        foreach ($tmsRows as $row) {
          $pid = (int) ($row->parameter_id ?? 0);
          if ($pid <= 0) {
            continue;
          }
          if (!isset($latestByParamId[$pid])) {
            $latestByParamId[$pid] = $row;
          }
        }

        foreach ($parameters as $param) {
          $tmsParamId = TmsKlinikHelper::resolveTmsIdFromParam($param);
          if ($tmsParamId <= 0 || !isset($latestByParamId[$tmsParamId])) {
            continue;
          }

          $tms = $latestByParamId[$tmsParamId];
          $usedParamIds[$tmsParamId] = true;
          $satuanName = (string) ($param->parametersatuanklinik->name_parameter_satuan_klinik ?? '');

          $matched[] = [
            'id_permohonan_uji_parameter_klinik' => $param->id_permohonan_uji_parameter_klinik,
            'nama_parameter_satuan_klinik' => $satuanName,
            'tms_parameter_id' => $tmsParamId,
            'tms_parameter_name' => $tms->parameter_name ?: ($satuanName ?: ('ID ' . $tmsParamId)),
            'result_value' => TmsKlinikHelper::formatResultValue($tms->result_value),
            'result_date' => $tms->result_date,
          ];
        }
      }

      // Jika hasil alat belum ketemu, pakai value yang sudah ada di order TMS
      if (empty($matched)) {
        $orderDetails = OrderDetailTms::query()
          ->whereNull('deleted_at')
          ->whereNotNull('value')
          ->where('value', '!=', '')
          ->whereHas('order', function ($q) use ($id_permohonan_uji_klinik) {
            $q->where('id_permohonan_uji_klinik', $id_permohonan_uji_klinik)->whereNull('deleted_at');
          })
          ->with(['parameterTms', 'order'])
          ->orderBy('updated_at', 'desc')
          ->get();

        if ($orderDetails->isNotEmpty()) {
          $source = 'order';
          $seenPuk = [];
          foreach ($orderDetails as $detail) {
            $pukId = $detail->id_permohonan_uji_parameter_klinik;
            if (empty($pukId)) {
              $tmsId = (int) $detail->id_parameter_tms;
              $puk = $parameters->first(function ($param) use ($tmsId) {
                return TmsKlinikHelper::resolveTmsIdFromParam($param) === $tmsId;
              });
              $pukId = $puk ? $puk->id_permohonan_uji_parameter_klinik : null;
            }
            if (empty($pukId) || isset($seenPuk[$pukId])) {
              continue;
            }
            $seenPuk[$pukId] = true;
            $param = $parameters->firstWhere('id_permohonan_uji_parameter_klinik', $pukId);
            $satuanName = (string) (optional(optional($param)->parametersatuanklinik)->name_parameter_satuan_klinik ?? '');
            $matched[] = [
              'id_permohonan_uji_parameter_klinik' => $pukId,
              'nama_parameter_satuan_klinik' => $satuanName,
              'tms_parameter_id' => (int) $detail->id_parameter_tms,
              'tms_parameter_name' => optional($detail->parameterTms)->name_parameter_tms ?: $satuanName,
              'result_value' => TmsKlinikHelper::formatResultValue($detail->value),
              'result_date' => optional($detail->order)->executed_at,
            ];
          }
        }
      }

      if ($tmsRows->isEmpty() && empty($matched)) {
        return response()->json([
          'status' => false,
          'pesan' => 'Data TMS tidak ditemukan. Periksa Sample ID alat, atau klik salah satu Sample ID terbaru di bawah.',
          'sample_candidates' => $candidates,
          'suggested_sample_ids' => $suggestedSampleIds,
        ], 404);
      }

      $unmatched = [];
      foreach ($latestByParamId as $pid => $tms) {
        if (isset($usedParamIds[$pid])) {
          continue;
        }
        $acuan = TmsKlinikHelper::acuanParameters()[$pid]['name'] ?? ($tms->parameter_name ?: ('ID ' . $pid));
        $unmatched[] = [
          'tms_parameter_id' => (int) $pid,
          'tms_parameter_name' => $tms->parameter_name ?: $acuan,
          'result_value' => TmsKlinikHelper::formatResultValue($tms->result_value),
        ];
      }

      $pesan = 'Data TMS ditemukan, tetapi tidak ada parameter yang cocok di permohonan ini.';
      if (count($matched)) {
        $pesan = $source === 'order'
          ? ('Berhasil memuat ' . count($matched) . ' parameter dari order TMS. Klik Isi ke Form.')
          : ('Berhasil memuat ' . count($matched) . ' parameter dari TMS. Klik Isi ke Form.');
      }

      $firstRow = $tmsRows->first();

      return response()->json([
        'status' => true,
        'pesan' => $pesan,
        'source' => $source,
        'sample_id' => $resolvedSampleId,
        'patient_name' => $firstRow ? $firstRow->patient_name : ($permohonan->pasien->nama_pasien ?? null),
        'result_date' => $firstRow ? $firstRow->result_date : null,
        'matched' => $matched,
        'unmatched' => $unmatched,
        'sample_candidates' => $candidates,
        'suggested_sample_ids' => $suggestedSampleIds,
      ]);
    } catch (\Throwable $th) {
      return response()->json([
        'status' => false,
        'pesan' => $th->getMessage(),
      ], 500);
    }
  }

  /**
   * Data form Make Order TMS: pasien, barcode suggestion, parameter master.
   */
  public function tmsOrderForm(Request $request, $id_permohonan_uji_klinik)
  {
    try {
      $permohonan = PermohonanUjiKlinik2::with('pasien')->findOrFail($id_permohonan_uji_klinik);
      $pasien = $permohonan->pasien;

      $pukParams = PermohonanUjiParameterKlinik::query()
        ->where('permohonan_uji_klinik', $id_permohonan_uji_klinik)
        ->whereNull('deleted_at')
        ->with(['parametersatuanklinik', 'parameterTms'])
        ->get();

      // Hanya parameter yang ada di permohonan DAN punya mapping ms_parameter_tms
      $isHaji = \Smt\Masterweb\Helpers\Smt::resolvePermohonanIsHaji($permohonan);
      $linked = [];
      foreach ($pukParams as $param) {
        $tmsId = TmsKlinikHelper::resolveTmsIdFromParam($param);
        if ($tmsId <= 0) {
          continue;
        }

        $pukId = (string) $param->id_permohonan_uji_parameter_klinik;
        if (isset($linked[$pukId])) {
          continue;
        }

        $linked[$pukId] = [
          'id_parameter_tms' => $tmsId,
          'id_permohonan_uji_parameter_klinik' => $param->id_permohonan_uji_parameter_klinik,
          'nama_parameter_klinik' => (string) ($param->parametersatuanklinik->name_parameter_satuan_klinik ?? ''),
          'param' => $param,
        ];
      }

      $tmsMasters = ParameterTms::query()
        ->whereIn('id_parameter_tms', array_values(array_unique(array_map(function ($meta) {
          return (int) $meta['id_parameter_tms'];
        }, $linked))))
        ->whereNull('deleted_at')
        ->whereNotNull('name_parameter_tms')
        ->where('name_parameter_tms', '!=', '')
        ->orderBy('id_parameter_tms')
        ->get(['id_parameter_tms', 'name_parameter_tms', 'jenis_sampel'])
        ->keyBy('id_parameter_tms');

      $parameters = [];
      foreach ($linked as $meta) {
        $tmsId = (int) $meta['id_parameter_tms'];
        $master = $tmsMasters->get($tmsId);
        if (!$master) {
          continue;
        }
        $jenis = TmsKlinikHelper::resolveJenisSpesimenForTmsOrder(
          $meta['param'],
          $master->jenis_sampel,
          $isHaji
        );
        $parameters[] = [
          'id_parameter_tms' => (int) $tmsId,
          'name_parameter_tms' => $master->name_parameter_tms,
          'nama_parameter_klinik' => $meta['nama_parameter_klinik'],
          'id_permohonan_uji_parameter_klinik' => $meta['id_permohonan_uji_parameter_klinik'],
          'jenis_spesimen' => $jenis,
          'selected_default' => false,
        ];
      }

      // Urutkan parameter per spesimen agar mudah dipilih
      $orderMap = array_flip(TmsKlinikHelper::specimenTypeOrder());
      usort($parameters, function ($a, $b) use ($orderMap) {
        $ia = $orderMap[$a['jenis_spesimen']] ?? 99;
        $ib = $orderMap[$b['jenis_spesimen']] ?? 99;
        if ($ia !== $ib) {
          return $ia <=> $ib;
        }
        return ((int) $a['id_parameter_tms']) <=> ((int) $b['id_parameter_tms']);
      });

      $candidates = TmsKlinikHelper::sampleIdCandidates($permohonan);
      $barcode = TmsKlinikHelper::labelRegisterCode($permohonan);
      if ($barcode === '' && !empty($candidates)) {
        $barcode = $candidates[0];
      }

      $gender = trim((string) ($pasien->gender_pasien ?? ''));
      if (strcasecmp($gender, 'L') === 0 || strcasecmp($gender, 'M') === 0) {
        $genderLabel = 'Laki-laki';
      } elseif (strcasecmp($gender, 'P') === 0 || strcasecmp($gender, 'F') === 0) {
        $genderLabel = 'Perempuan';
      } else {
        $genderLabel = $gender;
      }

      $dob = $pasien->tgllahir_pasien ?? null;
      if ($dob && !($dob instanceof \Carbon\Carbon)) {
        try {
          $dob = Carbon::parse($dob)->format('Y-m-d');
        } catch (\Throwable $e) {
          $dob = null;
        }
      } elseif ($dob instanceof \Carbon\Carbon) {
        $dob = $dob->format('Y-m-d');
      }

      $existingOrdersCount = OrderTms::query()
        ->where('id_permohonan_uji_klinik', $id_permohonan_uji_klinik)
        ->whereNull('deleted_at')
        ->count();

      return response()->json([
        'status' => true,
        'pasien' => [
          'nama_pasien' => $pasien->nama_pasien ?? '',
          'tanggal_lahir' => $dob,
          'jenis_kelamin' => $genderLabel,
        ],
        'kode_barcode' => $barcode,
        'sample_candidates' => $candidates,
        'parameters' => $parameters,
        'existing_orders_count' => $existingOrdersCount,
      ]);
    } catch (\Throwable $th) {
      return response()->json([
        'status' => false,
        'pesan' => $th->getMessage(),
      ], 500);
    }
  }

  /**
   * Daftar order TMS untuk permohonan (pending + selesai + value).
   * Sumber parameter/value riwayat: tb_orderdetail_tms (grup per header tb_order_tms).
   */
  public function listTmsOrders(Request $request, $id_permohonan_uji_klinik)
  {
    try {
      $permohonan = PermohonanUjiKlinik2::findOrFail($id_permohonan_uji_klinik);

      if (!Schema::hasTable('tb_orderdetail_tms') || !Schema::hasTable('tb_order_tms')) {
        return response()->json([
          'status' => true,
          'orders' => [],
        ]);
      }

      // Ambil detail dulu — value/parameter riwayat wajib dari tb_orderdetail_tms
      $details = OrderDetailTms::query()
        ->whereNull('deleted_at')
        ->whereHas('order', function ($q) use ($id_permohonan_uji_klinik) {
          $q->where('id_permohonan_uji_klinik', $id_permohonan_uji_klinik)
            ->whereNull('deleted_at');
        })
        ->with([
          'parameterTms',
          'permohonanUjiParameterKlinik.parametersatuanklinik',
          'order',
        ])
        ->orderBy('created_at', 'asc')
        ->get();

      $orders = $details
        ->groupBy('id_order_tms')
        ->map(function ($detailGroup) use ($permohonan) {
          /** @var \Smt\Masterweb\Models\OrderTms|null $order */
          $order = optional($detailGroup->first())->order;
          if (!$order) {
            return null;
          }

          $jenis = trim((string) ($order->jenis_sampel ?? ''));
          if ($jenis === '') {
            $jenis = TmsKlinikHelper::inferJenisSpesimenFromOrder($order, $permohonan);
          }

          $mappedDetails = $detailGroup->map(function ($d) {
            $pukId = $d->id_permohonan_uji_parameter_klinik;
            if (empty($pukId) && $d->permohonanUjiParameterKlinik) {
              $pukId = $d->permohonanUjiParameterKlinik->id_permohonan_uji_parameter_klinik;
            }

            $satuanName = optional(optional($d->permohonanUjiParameterKlinik)->parametersatuanklinik)->name_parameter_satuan_klinik;

            return [
              'id_orderdetail_tms' => $d->id_orderdetail_tms,
              'id_parameter_tms' => (int) $d->id_parameter_tms,
              'name_parameter_tms' => optional($d->parameterTms)->name_parameter_tms ?: $satuanName,
              'nama_parameter_satuan_klinik' => $satuanName,
              'id_permohonan_uji_parameter_klinik' => $pukId,
              // Value hanya dari kolom tb_orderdetail_tms.value
              'value' => TmsKlinikHelper::formatResultValue($d->value),
            ];
          })->values();

          return [
            'id_order_tms' => $order->id_order_tms,
            'nama_pasien' => $order->nama_pasien,
            'tanggal_lahir' => optional($order->tanggal_lahir)->format('Y-m-d'),
            'jenis_kelamin' => $order->jenis_kelamin,
            'jenis_sampel' => $jenis ?: 'Lainnya',
            'jenis_spesimen' => $jenis ?: 'Lainnya',
            'kode_barcode' => $order->kode_barcode,
            'tray' => $order->tray,
            'pos' => $order->pos,
            'posisi' => $order->pos,
            'is_executed' => (bool) $order->is_executed,
            'executed_at' => optional($order->executed_at)->format('Y-m-d H:i:s'),
            'created_at' => optional($order->created_at)->format('Y-m-d H:i:s'),
            'details' => $mappedDetails,
            'source' => 'tb_orderdetail_tms',
          ];
        })
        ->filter()
        ->sortByDesc(function ($order) {
          return $order['created_at'] ?? '';
        })
        ->values();

      return response()->json([
        'status' => true,
        'orders' => $orders,
        'source' => 'tb_orderdetail_tms',
      ]);
    } catch (\Throwable $th) {
      return response()->json([
        'status' => false,
        'pesan' => $th->getMessage(),
      ], 500);
    }
  }

  /**
   * Scope query permohonan yang sudah sampai tahap Input Hasil (step 3 belum selesai).
   */
  private function applyInputHasilScope($query)
  {
    return $query->whereExists(function ($subquery) {
      $subquery->select(DB::raw(1))
        ->from('tb_verification_activity_samples')
        ->whereColumn('tb_verification_activity_samples.is_klinik', 'tb_permohonan_uji_klinik_2.id_permohonan_uji_klinik')
        ->where('id_verification_activity', 1)
        ->where('is_done', 1);
    })->whereExists(function ($subquery) {
      $subquery->select(DB::raw(1))
        ->from('tb_verification_activity_samples')
        ->whereColumn('tb_verification_activity_samples.is_klinik', 'tb_permohonan_uji_klinik_2.id_permohonan_uji_klinik')
        ->where('id_verification_activity', 6)
        ->where('is_done', 1);
    })->whereExists(function ($subquery) {
      $subquery->select(DB::raw(1))
        ->from('tb_verification_activity_samples')
        ->whereColumn('tb_verification_activity_samples.is_klinik', 'tb_permohonan_uji_klinik_2.id_permohonan_uji_klinik')
        ->where('id_verification_activity', 7)
        ->where('is_done', 1);
    })->whereExists(function ($subquery) {
      $subquery->select(DB::raw(1))
        ->from('tb_verification_activity_samples')
        ->whereColumn('tb_verification_activity_samples.is_klinik', 'tb_permohonan_uji_klinik_2.id_permohonan_uji_klinik')
        ->where('id_verification_activity', 2)
        ->where('is_done', 1);
    })->where(function ($q) {
      $q->whereNotExists(function ($subquery) {
        $subquery->select(DB::raw(1))
          ->from('tb_verification_activity_samples')
          ->whereColumn('tb_verification_activity_samples.is_klinik', 'tb_permohonan_uji_klinik_2.id_permohonan_uji_klinik')
          ->where('id_verification_activity', 3);
      })->orWhereExists(function ($subquery) {
        $subquery->select(DB::raw(1))
          ->from('tb_verification_activity_samples')
          ->whereColumn('tb_verification_activity_samples.is_klinik', 'tb_permohonan_uji_klinik_2.id_permohonan_uji_klinik')
          ->where('id_verification_activity', 3)
          ->where('is_done', 0);
      });
    });
  }

  /**
   * Kumpulkan parameter TMS untuk satu permohonan (struktur sama dengan tmsOrderForm).
   */
  private function collectTmsOrderParametersForPermohonan(PermohonanUjiKlinik2 $permohonan): array
  {
    $isHaji = Smt::resolvePermohonanIsHaji($permohonan);
    $idPermohonan = $permohonan->id_permohonan_uji_klinik;

    $pukParams = PermohonanUjiParameterKlinik::query()
      ->where('permohonan_uji_klinik', $idPermohonan)
      ->whereNull('deleted_at')
      ->with(['parametersatuanklinik', 'parameterTms'])
      ->get();

    $linked = [];
    foreach ($pukParams as $param) {
      $tmsId = TmsKlinikHelper::resolveTmsIdFromParam($param);
      if ($tmsId <= 0) {
        continue;
      }
      $pukId = (string) $param->id_permohonan_uji_parameter_klinik;
      if (isset($linked[$pukId])) {
        continue;
      }
      $linked[$pukId] = [
        'id_parameter_tms' => $tmsId,
        'id_permohonan_uji_parameter_klinik' => $param->id_permohonan_uji_parameter_klinik,
        'nama_parameter_klinik' => (string) ($param->parametersatuanklinik->name_parameter_satuan_klinik ?? ''),
        'param' => $param,
      ];
    }

    if (empty($linked)) {
      return [];
    }

    $tmsMasters = ParameterTms::query()
      ->whereIn('id_parameter_tms', array_values(array_unique(array_map(function ($meta) {
        return (int) $meta['id_parameter_tms'];
      }, $linked))))
      ->whereNull('deleted_at')
      ->whereNotNull('name_parameter_tms')
      ->where('name_parameter_tms', '!=', '')
      ->orderBy('id_parameter_tms')
      ->get(['id_parameter_tms', 'name_parameter_tms', 'jenis_sampel'])
      ->keyBy('id_parameter_tms');

    $parameters = [];
    foreach ($linked as $meta) {
      $tmsId = (int) $meta['id_parameter_tms'];
      $master = $tmsMasters->get($tmsId);
      if (!$master) {
        continue;
      }
      $jenis = TmsKlinikHelper::resolveJenisSpesimenForTmsOrder(
        $meta['param'],
        $master->jenis_sampel,
        $isHaji
      );
      $parameters[] = [
        'id_parameter_tms' => $tmsId,
        'name_parameter_tms' => $master->name_parameter_tms,
        'nama_parameter_klinik' => $meta['nama_parameter_klinik'],
        'id_permohonan_uji_parameter_klinik' => $meta['id_permohonan_uji_parameter_klinik'],
        'jenis_spesimen' => $jenis,
      ];
    }

    $orderMap = array_flip(TmsKlinikHelper::specimenTypeOrder());
    usort($parameters, function ($a, $b) use ($orderMap) {
      $ia = $orderMap[$a['jenis_spesimen']] ?? 99;
      $ib = $orderMap[$b['jenis_spesimen']] ?? 99;
      if ($ia !== $ib) {
        return $ia <=> $ib;
      }
      return ((int) $a['id_parameter_tms']) <=> ((int) $b['id_parameter_tms']);
    });

    return $parameters;
  }

  /**
   * Buat order TMS dari item terpilih (satu order per jenis spesimen).
   *
   * @return array{createdOrders: array, summaryParts: array, mqttReports: array}
   */
  private function createTmsOrdersFromSelectedItems(PermohonanUjiKlinik2 $permohonan, array $selectedItems, array $options): array
  {
    $groups = [];
    foreach ($selectedItems as $item) {
      $jenis = trim((string) ($item['jenis'] ?? 'Lainnya'));
      if ($jenis === '') {
        $jenis = 'Lainnya';
      }
      if (!isset($groups[$jenis])) {
        $groups[$jenis] = [];
      }
      $groups[$jenis][] = $item;
    }

    if (empty($groups)) {
      throw new \InvalidArgumentException('Tidak ada parameter yang dapat dikelompokkan per spesimen.');
    }

    $pasien = $permohonan->pasien;
    $nama = trim((string) ($options['nama_pasien'] ?? ($pasien->nama_pasien ?? '')));
    $dobInput = $options['tanggal_lahir'] ?? ($pasien->tgllahir_pasien ?? null);
    $genderInput = trim((string) ($options['jenis_kelamin'] ?? ''));
    if ($genderInput === '') {
      $g = trim((string) ($pasien->gender_pasien ?? ''));
      if (strcasecmp($g, 'L') === 0 || strcasecmp($g, 'M') === 0) {
        $genderInput = 'Laki-laki';
      } elseif (strcasecmp($g, 'P') === 0 || strcasecmp($g, 'F') === 0) {
        $genderInput = 'Perempuan';
      } else {
        $genderInput = $g;
      }
    }

    $dob = null;
    if (!empty($dobInput)) {
      try {
        $dob = Carbon::parse($dobInput)->format('Y-m-d');
      } catch (\Throwable $e) {
        $dob = null;
      }
    }

    $baseBarcode = trim((string) ($options['kode_barcode'] ?? ''));
    if ($baseBarcode === '') {
      $baseBarcode = TmsKlinikHelper::labelRegisterCode($permohonan);
    }
    if ($baseBarcode === '') {
      $candidates = TmsKlinikHelper::sampleIdCandidates($permohonan);
      $baseBarcode = $candidates[0] ?? '';
    }

    $traysInput = $options['trays'] ?? [];
    $positionsInput = $options['positions'] ?? [];
    if (!is_array($traysInput)) {
      $traysInput = [];
    }
    if (!is_array($positionsInput)) {
      $positionsInput = [];
    }

    $traysByJenis = [];
    foreach ($traysInput as $k => $v) {
      $key = trim((string) $k);
      if ($key === '') {
        continue;
      }
      $traysByJenis[$key] = trim((string) $v);
    }
    $posByJenis = [];
    foreach ($positionsInput as $k => $v) {
      $key = trim((string) $k);
      if ($key === '') {
        continue;
      }
      $posByJenis[$key] = trim((string) $v);
    }

    $fallbackTray = trim((string) ($options['tray'] ?? ''));
    $fallbackPos = trim((string) ($options['pos'] ?? ($options['posisi'] ?? '')));
    $viaMqtt = filter_var($options['via_mqtt'] ?? false, FILTER_VALIDATE_BOOLEAN);

    foreach (array_keys($groups) as $jenis) {
      $tray = $traysByJenis[$jenis] ?? $fallbackTray;
      $pos = $posByJenis[$jenis] ?? $fallbackPos;
      if (!$viaMqtt && ($tray === '' || $pos === '')) {
        throw new \InvalidArgumentException(
          'Tray dan Posisi wajib diisi untuk jenis sampel "' . $jenis . '" (satu jenis sampel = satu order).'
        );
      }
      $traysByJenis[$jenis] = $tray !== '' ? $tray : null;
      $posByJenis[$jenis] = $pos !== '' ? $pos : null;
    }

    $createdOrders = [];
    $summaryParts = [];

    foreach ($groups as $jenis => $groupItems) {
      $tray = array_key_exists($jenis, $traysByJenis) ? $traysByJenis[$jenis] : $fallbackTray;
      $pos = array_key_exists($jenis, $posByJenis) ? $posByJenis[$jenis] : $fallbackPos;
      if ($tray === '') {
        $tray = null;
      }
      if ($pos === '') {
        $pos = null;
      }

      $order = new OrderTms();
      $order->id_permohonan_uji_klinik = $permohonan->id_permohonan_uji_klinik;
      $order->nama_pasien = $nama !== '' ? $nama : null;
      $order->tanggal_lahir = $dob;
      $order->jenis_kelamin = $genderInput !== '' ? $genderInput : null;
      $order->jenis_sampel = trim((string) $jenis) !== '' ? (string) $jenis : null;
      $orderBarcode = TmsKlinikHelper::barcodeForSpesimen($baseBarcode, (string) $jenis, true);
      $order->kode_barcode = $orderBarcode !== '' ? $orderBarcode : null;
      $order->tray = $tray;
      $order->pos = $pos;
      $order->is_executed = 0;
      $order->executed_at = null;
      $order->save();

      foreach ($groupItems as $item) {
        $tmsId = (int) ($item['tms_id'] ?? 0);
        if ($tmsId <= 0) {
          continue;
        }
        $detail = new OrderDetailTms();
        $detail->id_order_tms = $order->id_order_tms;
        $detail->id_parameter_tms = $tmsId;
        $detail->id_permohonan_uji_parameter_klinik = $item['puk_id'] ?? null;
        $detail->value = null;
        $detail->save();
      }

      $order->load(['details.parameterTms']);

      $createdOrders[] = [
        'id_order_tms' => $order->id_order_tms,
        'id_permohonan_uji_klinik' => $permohonan->id_permohonan_uji_klinik,
        'jenis_sampel' => (string) $jenis,
        'jenis_spesimen' => (string) $jenis,
        'kode_barcode' => $order->kode_barcode,
        'tray' => $order->tray,
        'pos' => $order->pos,
        'posisi' => $order->pos,
        'is_executed' => false,
        'details_count' => $order->details->count(),
        'details' => $order->details->map(function ($d) {
          return [
            'id_parameter_tms' => (int) $d->id_parameter_tms,
            'name_parameter_tms' => optional($d->parameterTms)->name_parameter_tms,
          ];
        })->values(),
      ];

      $summaryParts[] = $jenis . ': ' . count($groupItems) . ' param (Tray ' . ($tray ?? '-') . '/Pos ' . ($pos ?? '-') . ')';
    }

    $mqttReports = [];
    if (!empty($options['publish_mqtt'])) {
      try {
        foreach ($createdOrders as $createdSummary) {
          $mqttReports[] = app(TmsOrderPublisher::class)->publishById($createdSummary['id_order_tms']);
        }
      } catch (\Throwable $mqttException) {
        Log::error('MQTT TMS order publish failed setelah store', [
          'message' => $mqttException->getMessage(),
        ]);
      }
    }

    return [
      'createdOrders' => $createdOrders,
      'summaryParts' => $summaryParts,
      'mqttReports' => $mqttReports,
    ];
  }

  /**
   * Resolve item terpilih untuk order TMS dari permohonan + daftar PUK id.
   */
  private function resolveTmsSelectedItemsForPermohonan(PermohonanUjiKlinik2 $permohonan, array $parameterPukIds): array
  {
    $isHaji = Smt::resolvePermohonanIsHaji($permohonan);
    $parameterPukIds = array_values(array_unique(array_filter(array_map('strval', $parameterPukIds))));

    if (empty($parameterPukIds)) {
      throw new \InvalidArgumentException('Pilih minimal satu parameter TMS.');
    }

    $pukParams = PermohonanUjiParameterKlinik::query()
      ->where('permohonan_uji_klinik', $permohonan->id_permohonan_uji_klinik)
      ->whereNull('deleted_at')
      ->with('parametersatuanklinik')
      ->get();

    $tmsIdsForMap = [];
    foreach ($pukParams as $param) {
      $tid = TmsKlinikHelper::resolveTmsIdFromParam($param);
      if ($tid > 0) {
        $tmsIdsForMap[] = $tid;
      }
    }
    $tmsJenisById = ParameterTms::query()
      ->whereIn('id_parameter_tms', array_values(array_unique($tmsIdsForMap)))
      ->pluck('jenis_sampel', 'id_parameter_tms');

    $selectionItems = [];
    foreach ($pukParams as $param) {
      $tmsId = TmsKlinikHelper::resolveTmsIdFromParam($param);
      if ($tmsId <= 0) {
        continue;
      }
      $pukId = (string) $param->id_permohonan_uji_parameter_klinik;
      $jenis = TmsKlinikHelper::resolveJenisSpesimenForTmsOrder(
        $param,
        $tmsJenisById->get($tmsId),
        $isHaji
      );
      $selectionItems[$pukId] = [
        'tms_id' => $tmsId,
        'puk_id' => $param->id_permohonan_uji_parameter_klinik,
        'jenis' => $jenis,
      ];
    }

    $selectedItems = [];
    foreach ($parameterPukIds as $pukId) {
      if (!isset($selectionItems[$pukId])) {
        continue;
      }
      $selectedItems[] = $selectionItems[$pukId];
    }

    if (empty($selectedItems)) {
      throw new \InvalidArgumentException('Parameter tidak valid / tidak termasuk permohonan ini.');
    }

    return $selectedItems;
  }

  /**
   * Daftar pasien di tahap Input Hasil yang punya parameter TMS (untuk order massal).
   */
  public function listTmsMassOrderCandidates(Request $request, $id_permohonan_uji_klinik)
  {
    try {
      $anchor = PermohonanUjiKlinik2::with('pasien')->findOrFail($id_permohonan_uji_klinik);
      $isHaji = Smt::resolvePermohonanIsHaji($anchor);

      $query = PermohonanUjiKlinik2::query()
        ->whereNull('deleted_at')
        ->with('pasien');

      if ($isHaji && !empty($anchor->id_permohonan_uji_klinik_haji)) {
        $query->where('id_permohonan_uji_klinik_haji', $anchor->id_permohonan_uji_klinik_haji);
      } else {
        $anchorDate = null;
        $requestJam = trim((string) $request->query('jam', ''));
        if ($requestJam !== '') {
          try {
            $anchorDate = Carbon::parse($requestJam)->format('Y-m-d');
          } catch (\Throwable $e) {
            $anchorDate = null;
          }
        }
        if ($anchorDate === null && !empty($anchor->tglpengujian_permohonan_uji_klinik)) {
          try {
            $anchorDate = Carbon::parse($anchor->tglpengujian_permohonan_uji_klinik)->format('Y-m-d');
          } catch (\Throwable $e) {
            $anchorDate = null;
          }
        }
        if ($anchorDate !== null) {
          $query->whereDate('tglpengujian_permohonan_uji_klinik', $anchorDate);
        }
      }

      $this->applyInputHasilScope($query);

      $permohonans = $query
        ->orderBy('noregister_permohonan_uji_klinik')
        ->get();

      $patients = [];
      $paramCatalog = [];

      foreach ($permohonans as $permohonan) {
        $parameters = $this->collectTmsOrderParametersForPermohonan($permohonan);
        if (empty($parameters)) {
          continue;
        }

        $pasien = $permohonan->pasien;
        $existingOrdersCount = OrderTms::query()
          ->where('id_permohonan_uji_klinik', $permohonan->id_permohonan_uji_klinik)
          ->whereNull('deleted_at')
          ->count();

        $barcode = TmsKlinikHelper::labelRegisterCode($permohonan);
        if ($barcode === '') {
          $candidates = TmsKlinikHelper::sampleIdCandidates($permohonan);
          $barcode = $candidates[0] ?? '';
        }

        $patients[] = [
          'id_permohonan_uji_klinik' => $permohonan->id_permohonan_uji_klinik,
          'noregister' => $permohonan->noregister_permohonan_uji_klinik ?? '',
          'nama_pasien' => $pasien->nama_pasien ?? '',
          'kode_barcode' => $barcode,
          'is_current' => $permohonan->id_permohonan_uji_klinik === $anchor->id_permohonan_uji_klinik,
          'existing_orders_count' => $existingOrdersCount,
          'parameters' => $parameters,
        ];

        foreach ($parameters as $param) {
          $catalogKey = (int) $param['id_parameter_tms'] . '|' . ($param['jenis_spesimen'] ?? 'Lainnya');
          if (!isset($paramCatalog[$catalogKey])) {
            $paramCatalog[$catalogKey] = [
              'catalog_key' => $catalogKey,
              'id_parameter_tms' => (int) $param['id_parameter_tms'],
              'name_parameter_tms' => $param['name_parameter_tms'],
              'jenis_spesimen' => $param['jenis_spesimen'] ?? 'Lainnya',
              'nama_parameter_klinik_samples' => [],
            ];
          }
          $klinikName = trim((string) ($param['nama_parameter_klinik'] ?? ''));
          if ($klinikName !== '' && !in_array($klinikName, $paramCatalog[$catalogKey]['nama_parameter_klinik_samples'], true)) {
            $paramCatalog[$catalogKey]['nama_parameter_klinik_samples'][] = $klinikName;
          }
        }
      }

      $catalogList = array_values($paramCatalog);
      usort($catalogList, function ($a, $b) {
        $orderMap = array_flip(TmsKlinikHelper::specimenTypeOrder());
        $ia = $orderMap[$a['jenis_spesimen']] ?? 99;
        $ib = $orderMap[$b['jenis_spesimen']] ?? 99;
        if ($ia !== $ib) {
          return $ia <=> $ib;
        }
        return ((int) $a['id_parameter_tms']) <=> ((int) $b['id_parameter_tms']);
      });

      return response()->json([
        'status' => true,
        'scope' => [
          'is_haji' => $isHaji,
          'id_permohonan_uji_klinik_haji' => $anchor->id_permohonan_uji_klinik_haji ?? null,
        ],
        'patients' => $patients,
        'parameter_catalog' => $catalogList,
        'total' => count($patients),
      ]);
    } catch (\Throwable $th) {
      return response()->json([
        'status' => false,
        'pesan' => $th->getMessage(),
      ], 500);
    }
  }

  /**
   * Buat order TMS massal untuk beberapa pasien dengan tipe order berbeda-beda.
   *
   * Payload:
   * - assignments: [{ id_permohonan_uji_klinik, parameter_puk_ids: [] }]
   * - via_mqtt: 1 (opsional, tray/pos opsional)
   */
  public function storeTmsMassOrder(Request $request, $id_permohonan_uji_klinik)
  {
    try {
      PermohonanUjiKlinik2::findOrFail($id_permohonan_uji_klinik);

      $assignments = $request->input('assignments', []);
      if (!is_array($assignments) || empty($assignments)) {
        return response()->json([
          'status' => false,
          'pesan' => 'Tidak ada pasien yang dipilih untuk order massal.',
        ], 422);
      }

      $viaMqtt = filter_var($request->input('via_mqtt', true), FILTER_VALIDATE_BOOLEAN);
      $allCreated = [];
      $allMqtt = [];
      $patientSummaries = [];
      $errors = [];

      DB::beginTransaction();

      foreach ($assignments as $idx => $assignment) {
        if (!is_array($assignment)) {
          continue;
        }
        $targetId = trim((string) ($assignment['id_permohonan_uji_klinik'] ?? ''));
        $pukIds = $assignment['parameter_puk_ids'] ?? [];
        if (!is_array($pukIds)) {
          $pukIds = [];
        }

        if ($targetId === '' || empty($pukIds)) {
          continue;
        }

        try {
          $permohonan = PermohonanUjiKlinik2::with('pasien')->findOrFail($targetId);
          $selectedItems = $this->resolveTmsSelectedItemsForPermohonan($permohonan, $pukIds);

          $options = [
            'via_mqtt' => $viaMqtt,
            'publish_mqtt' => false,
            'trays' => $assignment['trays'] ?? [],
            'positions' => $assignment['positions'] ?? [],
            'tray' => $assignment['tray'] ?? '',
            'pos' => $assignment['pos'] ?? ($assignment['posisi'] ?? ''),
            'kode_barcode' => $assignment['kode_barcode'] ?? '',
          ];

          $result = $this->createTmsOrdersFromSelectedItems($permohonan, $selectedItems, $options);
          $allCreated = array_merge($allCreated, $result['createdOrders']);

          $patientSummaries[] = [
            'id_permohonan_uji_klinik' => $targetId,
            'nama_pasien' => optional($permohonan->pasien)->nama_pasien ?? '',
            'orders_count' => count($result['createdOrders']),
            'summary' => implode('; ', $result['summaryParts']),
          ];
        } catch (\Throwable $e) {
          $errors[] = 'Baris ' . ($idx + 1) . ': ' . $e->getMessage();
        }
      }

      if (empty($allCreated)) {
        DB::rollBack();
        return response()->json([
          'status' => false,
          'pesan' => !empty($errors)
            ? implode(' ', $errors)
            : 'Tidak ada order yang berhasil dibuat.',
          'errors' => $errors,
        ], 422);
      }

      DB::commit();

      if ($viaMqtt) {
        try {
          foreach ($allCreated as $createdSummary) {
            $allMqtt[] = app(TmsOrderPublisher::class)->publishById($createdSummary['id_order_tms']);
          }
        } catch (\Throwable $mqttException) {
          Log::error('MQTT TMS mass order publish failed', [
            'message' => $mqttException->getMessage(),
          ]);
        }
      }

      $pesan = count($patientSummaries) . ' pasien, ' . count($allCreated) . ' order TMS berhasil dibuat.';
      if (!empty($errors)) {
        $pesan .= ' Beberapa gagal: ' . implode('; ', $errors);
      }

      return response()->json([
        'status' => true,
        'pesan' => $pesan,
        'patients' => $patientSummaries,
        'orders' => $allCreated,
        'orders_count' => count($allCreated),
        'mqtt' => $allMqtt,
        'errors' => $errors,
      ]);
    } catch (\Throwable $th) {
      DB::rollBack();
      return response()->json([
        'status' => false,
        'pesan' => $th->getMessage(),
      ], 500);
    }
  }

  /**
   * Buat order TMS + detail parameter terpilih.
   * Parameter beda jenis spesimen → dipecah jadi beberapa order (satu order per spesimen).
   */
  public function storeTmsOrder(Request $request, $id_permohonan_uji_klinik)
  {
    try {
      $permohonan = PermohonanUjiKlinik2::with('pasien')->findOrFail($id_permohonan_uji_klinik);
      $isHaji = Smt::resolvePermohonanIsHaji($permohonan);

      $parameterIds = $request->input('parameter_ids', []);
      if (!is_array($parameterIds)) {
        $parameterIds = [];
      }
      $parameterIds = array_values(array_unique(array_filter(array_map('intval', $parameterIds))));

      $parameterPukIds = $request->input('parameter_puk_ids', []);
      if (!is_array($parameterPukIds)) {
        $parameterPukIds = [];
      }
      $parameterPukIds = array_values(array_unique(array_filter(array_map('strval', $parameterPukIds))));

      if (empty($parameterIds) && empty($parameterPukIds)) {
        return response()->json([
          'status' => false,
          'pesan' => 'Pilih minimal satu parameter TMS.',
        ], 422);
      }

      if (!empty($parameterPukIds)) {
        $selectedItems = $this->resolveTmsSelectedItemsForPermohonan($permohonan, $parameterPukIds);
      } else {
        $pukParams = PermohonanUjiParameterKlinik::query()
          ->where('permohonan_uji_klinik', $id_permohonan_uji_klinik)
          ->whereNull('deleted_at')
          ->with('parametersatuanklinik')
          ->get();

        $tmsIdsForMap = [];
        foreach ($pukParams as $param) {
          $tid = TmsKlinikHelper::resolveTmsIdFromParam($param);
          if ($tid > 0) {
            $tmsIdsForMap[] = $tid;
          }
        }
        $tmsJenisById = ParameterTms::query()
          ->whereIn('id_parameter_tms', array_values(array_unique($tmsIdsForMap)))
          ->pluck('jenis_sampel', 'id_parameter_tms');

        $pukByTmsId = [];
        $metaByTmsId = [];
        foreach ($pukParams as $param) {
          $tmsId = TmsKlinikHelper::resolveTmsIdFromParam($param);
          if ($tmsId <= 0) {
            continue;
          }
          $jenis = TmsKlinikHelper::resolveJenisSpesimenForTmsOrder(
            $param,
            $tmsJenisById->get($tmsId),
            $isHaji
          );
          if (!isset($pukByTmsId[$tmsId])) {
            $pukByTmsId[$tmsId] = $param->id_permohonan_uji_parameter_klinik;
            $metaByTmsId[$tmsId] = ['jenis' => $jenis];
          }
        }

        $allowedIds = array_values(array_intersect($parameterIds, array_map('intval', array_keys($pukByTmsId))));
        $validIds = ParameterTms::query()
          ->whereIn('id_parameter_tms', $allowedIds)
          ->whereNull('deleted_at')
          ->whereNotNull('name_parameter_tms')
          ->where('name_parameter_tms', '!=', '')
          ->pluck('id_parameter_tms')
          ->map(function ($id) {
            return (int) $id;
          })
          ->all();

        if (empty($validIds)) {
          return response()->json([
            'status' => false,
            'pesan' => 'Parameter tidak valid / tidak termasuk permohonan ini.',
          ], 422);
        }

        $selectedItems = [];
        foreach ($validIds as $tmsId) {
          $selectedItems[] = [
            'tms_id' => (int) $tmsId,
            'puk_id' => $pukByTmsId[$tmsId] ?? null,
            'jenis' => $metaByTmsId[$tmsId]['jenis'] ?? 'Lainnya',
          ];
        }
      }

      $viaMqtt = filter_var($request->input('via_mqtt', false), FILTER_VALIDATE_BOOLEAN);
      $options = [
        'nama_pasien' => $request->input('nama_pasien', optional($permohonan->pasien)->nama_pasien ?? ''),
        'tanggal_lahir' => $request->input('tanggal_lahir', optional($permohonan->pasien)->tgllahir_pasien ?? null),
        'jenis_kelamin' => $request->input('jenis_kelamin', ''),
        'kode_barcode' => $request->input('kode_barcode', ''),
        'trays' => $request->input('trays', []),
        'positions' => $request->input('positions', $request->input('posisi_map', [])),
        'tray' => $request->input('tray', ''),
        'pos' => $request->input('pos', $request->input('posisi', '')),
        'via_mqtt' => $viaMqtt,
        'publish_mqtt' => true,
      ];

      DB::beginTransaction();
      try {
        $result = $this->createTmsOrdersFromSelectedItems($permohonan, $selectedItems, $options);
      } catch (\InvalidArgumentException $e) {
        DB::rollBack();
        return response()->json([
          'status' => false,
          'pesan' => $e->getMessage(),
        ], 422);
      }
      DB::commit();

      $createdOrders = $result['createdOrders'];
      $summaryParts = $result['summaryParts'];
      $mqttReports = $result['mqttReports'];

      $pesan = count($createdOrders) === 1
        ? ('Order TMS berhasil dibuat (' . $summaryParts[0] . ').')
        : ('Order TMS dipecah per spesimen: ' . count($createdOrders) . ' order (' . implode('; ', $summaryParts) . ').');

      return response()->json([
        'status' => true,
        'pesan' => $pesan,
        'orders' => $createdOrders,
        'order' => $createdOrders[0] ?? null,
        'mqtt' => $mqttReports,
      ]);
    } catch (\Throwable $th) {
      DB::rollBack();
      return response()->json([
        'status' => false,
        'pesan' => $th->getMessage(),
      ], 500);
    }
  }

  /**
   * Tarik hasil dari biolis_results ke order detail + tandai executed bila ada value.
   */
  public function syncTmsOrder(Request $request, $id_order_tms)
  {
    try {
      $order = OrderTms::query()
        ->where('id_order_tms', $id_order_tms)
        ->whereNull('deleted_at')
        ->with('details')
        ->firstOrFail();

      $sampleId = trim((string) $request->input('sample_id', $order->kode_barcode));
      $candidates = [];
      if ($sampleId !== '') {
        $candidates[] = $sampleId;
      }
      if (!empty($order->kode_barcode)) {
        $candidates[] = trim((string) $order->kode_barcode);
      }
      $permohonan = PermohonanUjiKlinik2::with('pasien')->find($order->id_permohonan_uji_klinik);
      if ($permohonan) {
        $candidates = array_merge($candidates, TmsKlinikHelper::sampleIdCandidates($permohonan));
      }
      $candidates = array_values(array_unique(array_filter(array_map('trim', $candidates))));

      $tmsQuery = \App\TmsResult::query()->orderBy('result_date', 'desc')->orderBy('id', 'desc');
      $tmsRows = collect();
      $resolvedSampleId = $sampleId;

      foreach ($candidates as $candidate) {
        $rows = (clone $tmsQuery)->where('sample_id', $candidate)->get();
        if ($rows->isNotEmpty()) {
          $resolvedSampleId = $candidate;
          $tmsRows = $rows;
          break;
        }
      }

      if ($tmsRows->isEmpty() && $permohonan) {
        $patientName = trim((string) ($permohonan->pasien->nama_pasien ?? ''));
        if ($patientName !== '') {
          $rows = (clone $tmsQuery)
            ->where('patient_name', 'like', '%' . $patientName . '%')
            ->limit(50)
            ->get();
          if ($rows->isNotEmpty()) {
            $resolvedSampleId = $rows->first()->sample_id;
            $tmsRows = $rows->where('sample_id', $resolvedSampleId)->values();
          }
        }
      }

      if ($tmsRows->isEmpty()) {
        return response()->json([
          'status' => false,
          'pesan' => 'Hasil alat belum tersedia untuk Sample ID: ' . ($sampleId !== '' ? $sampleId : '(kosong)'),
        ], 404);
      }

      $latestByParamId = [];
      foreach ($tmsRows as $row) {
        $pid = (int) ($row->parameter_id ?? 0);
        if ($pid <= 0) {
          continue;
        }
        if (!isset($latestByParamId[$pid])) {
          $latestByParamId[$pid] = $row;
        }
      }

      $filled = 0;

      foreach ($order->details as $detail) {
        $pid = (int) $detail->id_parameter_tms;
        if ($pid <= 0 || !isset($latestByParamId[$pid])) {
          continue;
        }
        $val = TmsKlinikHelper::formatResultValue($latestByParamId[$pid]->result_value);
        $detail->value = $val !== '' ? $val : $detail->value;
        $detail->save();
        $filled++;
      }

      if ($filled > 0) {
        $order->is_executed = 1;
        $order->executed_at = $order->executed_at ?: now();
        $order->save();
      }

      // Response details selalu dari tb_orderdetail_tms (bukan cache relasi lama)
      $freshDetails = OrderDetailTms::query()
        ->where('id_order_tms', $order->id_order_tms)
        ->whereNull('deleted_at')
        ->with(['parameterTms', 'permohonanUjiParameterKlinik'])
        ->orderBy('created_at', 'asc')
        ->get();

      $matchedForForm = [];
      foreach ($freshDetails as $detail) {
        $val = TmsKlinikHelper::formatResultValue($detail->value);
        if ($val === '' || empty($detail->id_permohonan_uji_parameter_klinik)) {
          continue;
        }
        $matchedForForm[] = [
          'id_permohonan_uji_parameter_klinik' => $detail->id_permohonan_uji_parameter_klinik,
          'nama_parameter_satuan_klinik' => optional($detail->parameterTms)->name_parameter_tms,
          'tms_parameter_id' => (int) $detail->id_parameter_tms,
          'tms_parameter_name' => optional($detail->parameterTms)->name_parameter_tms,
          'result_value' => $val,
        ];
      }

      return response()->json([
        'status' => true,
        'pesan' => $filled > 0
          ? ('Berhasil sinkron ' . $filled . ' parameter. Order ditandai sudah tereksekusi.')
          : 'Hasil alat ditemukan, tetapi tidak ada parameter order yang cocok.',
        'is_executed' => (bool) $order->is_executed,
        'matched' => $matchedForForm,
        'source' => 'tb_orderdetail_tms',
        'details' => $freshDetails->map(function ($d) {
          return [
            'id_orderdetail_tms' => $d->id_orderdetail_tms,
            'id_parameter_tms' => (int) $d->id_parameter_tms,
            'name_parameter_tms' => optional($d->parameterTms)->name_parameter_tms,
            'id_permohonan_uji_parameter_klinik' => $d->id_permohonan_uji_parameter_klinik,
            'value' => TmsKlinikHelper::formatResultValue($d->value),
          ];
        })->values(),
      ]);
    } catch (\Throwable $th) {
      return response()->json([
        'status' => false,
        'pesan' => $th->getMessage(),
      ], 500);
    }
  }

  /**
   * Update satu order TMS (header + daftar parameter).
   * Saat edit, parameter harus satu jenis sampel (order tidak dipecah ulang).
   */
  public function updateTmsOrder(Request $request, $id_order_tms)
  {
    try {
      $order = OrderTms::query()
        ->where('id_order_tms', $id_order_tms)
        ->whereNull('deleted_at')
        ->with(['details' => function ($q) {
          $q->whereNull('deleted_at');
        }])
        ->firstOrFail();

      $id_permohonan_uji_klinik = $order->id_permohonan_uji_klinik;
      $permohonan = PermohonanUjiKlinik2::with('pasien')->findOrFail($id_permohonan_uji_klinik);
      $isHaji = \Smt\Masterweb\Helpers\Smt::resolvePermohonanIsHaji($permohonan);

      $parameterIds = $request->input('parameter_ids', []);
      if (!is_array($parameterIds)) {
        $parameterIds = [];
      }
      $parameterIds = array_values(array_unique(array_filter(array_map('intval', $parameterIds))));

      $parameterPukIds = $request->input('parameter_puk_ids', []);
      if (!is_array($parameterPukIds)) {
        $parameterPukIds = [];
      }
      $parameterPukIds = array_values(array_unique(array_filter(array_map('strval', $parameterPukIds))));

      if (empty($parameterIds) && empty($parameterPukIds)) {
        return response()->json([
          'status' => false,
          'pesan' => 'Pilih minimal satu parameter TMS.',
        ], 422);
      }

      $pukParams = PermohonanUjiParameterKlinik::query()
        ->where('permohonan_uji_klinik', $id_permohonan_uji_klinik)
        ->whereNull('deleted_at')
        ->with('parametersatuanklinik')
        ->get();

      $tmsIdsForMap = [];
      foreach ($pukParams as $param) {
        $tid = TmsKlinikHelper::resolveTmsIdFromParam($param);
        if ($tid > 0) {
          $tmsIdsForMap[] = $tid;
        }
      }
      $tmsJenisById = ParameterTms::query()
        ->whereIn('id_parameter_tms', array_values(array_unique($tmsIdsForMap)))
        ->pluck('jenis_sampel', 'id_parameter_tms');

      $pukByTmsId = [];
      $metaByTmsId = [];
      $selectionItems = [];

      foreach ($pukParams as $param) {
        $tmsId = TmsKlinikHelper::resolveTmsIdFromParam($param);
        if ($tmsId <= 0) {
          continue;
        }

        $pukId = (string) $param->id_permohonan_uji_parameter_klinik;
        $jenis = TmsKlinikHelper::resolveJenisSpesimenForTmsOrder(
          $param,
          $tmsJenisById->get($tmsId),
          $isHaji
        );

        if (!isset($pukByTmsId[$tmsId])) {
          $pukByTmsId[$tmsId] = $param->id_permohonan_uji_parameter_klinik;
          $metaByTmsId[$tmsId] = ['jenis' => $jenis];
        }

        $selectionItems[$pukId] = [
          'tms_id' => $tmsId,
          'puk_id' => $param->id_permohonan_uji_parameter_klinik,
          'jenis' => $jenis,
        ];
      }

      if (!empty($parameterPukIds)) {
        $selectedItems = [];
        foreach ($parameterPukIds as $pukId) {
          if (!isset($selectionItems[$pukId])) {
            continue;
          }
          $selectedItems[] = $selectionItems[$pukId];
        }
        if (empty($selectedItems)) {
          return response()->json([
            'status' => false,
            'pesan' => 'Parameter tidak valid / tidak termasuk permohonan ini.',
          ], 422);
        }
      } else {
        $allowedIds = array_values(array_intersect($parameterIds, array_map('intval', array_keys($pukByTmsId))));
        $validIds = ParameterTms::query()
          ->whereIn('id_parameter_tms', $allowedIds)
          ->whereNull('deleted_at')
          ->whereNotNull('name_parameter_tms')
          ->where('name_parameter_tms', '!=', '')
          ->pluck('id_parameter_tms')
          ->map(function ($id) {
            return (int) $id;
          })
          ->all();

        if (empty($validIds)) {
          return response()->json([
            'status' => false,
            'pesan' => 'Parameter tidak valid / tidak termasuk permohonan ini.',
          ], 422);
        }

        $selectedItems = [];
        foreach ($validIds as $tmsId) {
          $selectedItems[] = [
            'tms_id' => (int) $tmsId,
            'puk_id' => $pukByTmsId[$tmsId] ?? null,
            'jenis' => $metaByTmsId[$tmsId]['jenis'] ?? 'Lainnya',
          ];
        }
      }

      $jenisSet = [];
      foreach ($selectedItems as $item) {
        $jenis = trim((string) ($item['jenis'] ?? 'Lainnya'));
        if ($jenis === '') {
          $jenis = 'Lainnya';
        }
        $jenisSet[$jenis] = true;
      }
      $jenisList = array_keys($jenisSet);
      if (count($jenisList) !== 1) {
        return response()->json([
          'status' => false,
          'pesan' => 'Saat mengedit order, pilih parameter dari satu jenis sampel saja.',
        ], 422);
      }
      $jenis = $jenisList[0];

      $traysInput = $request->input('trays', []);
      $positionsInput = $request->input('positions', $request->input('posisi_map', []));
      if (!is_array($traysInput)) {
        $traysInput = [];
      }
      if (!is_array($positionsInput)) {
        $positionsInput = [];
      }

      $viaMqtt = filter_var($request->input('via_mqtt', false), FILTER_VALIDATE_BOOLEAN);
      $tray = trim((string) ($traysInput[$jenis] ?? $request->input('tray', $order->tray)));
      $pos = trim((string) ($positionsInput[$jenis] ?? $request->input('pos', $request->input('posisi', $order->pos))));
      if (!$viaMqtt && ($tray === '' || $pos === '')) {
        return response()->json([
          'status' => false,
          'pesan' => 'Tray dan Posisi wajib diisi untuk jenis sampel "' . $jenis . '".',
        ], 422);
      }
      $tray = $tray !== '' ? $tray : null;
      $pos = $pos !== '' ? $pos : null;

      $pasien = $permohonan->pasien;
      $nama = trim((string) $request->input('nama_pasien', $order->nama_pasien ?: ($pasien->nama_pasien ?? '')));
      $dobInput = $request->input('tanggal_lahir', optional($order->tanggal_lahir)->format('Y-m-d') ?: ($pasien->tgllahir_pasien ?? null));
      $genderInput = trim((string) $request->input('jenis_kelamin', $order->jenis_kelamin ?: ''));
      if ($genderInput === '') {
        $g = trim((string) ($pasien->gender_pasien ?? ''));
        if (strcasecmp($g, 'L') === 0 || strcasecmp($g, 'M') === 0) {
          $genderInput = 'Laki-laki';
        } elseif (strcasecmp($g, 'P') === 0 || strcasecmp($g, 'F') === 0) {
          $genderInput = 'Perempuan';
        } else {
          $genderInput = $g;
        }
      }

      $dob = null;
      if (!empty($dobInput)) {
        try {
          $dob = Carbon::parse($dobInput)->format('Y-m-d');
        } catch (\Throwable $e) {
          $dob = null;
        }
      }

      $barcode = trim((string) $request->input('kode_barcode', $order->kode_barcode ?? ''));
      if ($barcode === '') {
        $barcode = TmsKlinikHelper::labelRegisterCode($permohonan);
      }
      $barcode = TmsKlinikHelper::barcodeForSpesimen($barcode, (string) $jenis, true);

      DB::beginTransaction();

      $order->nama_pasien = $nama !== '' ? $nama : null;
      $order->tanggal_lahir = $dob;
      $order->jenis_kelamin = $genderInput !== '' ? $genderInput : null;
      $order->jenis_sampel = $jenis;
      $order->kode_barcode = $barcode !== '' ? $barcode : null;
      $order->tray = $tray;
      $order->pos = $pos;
      $order->save();

      $existing = $order->details->keyBy(function ($d) {
        $puk = (string) ($d->id_permohonan_uji_parameter_klinik ?? '');
        if ($puk !== '') {
          return 'puk:' . $puk;
        }
        return 'tms:' . (int) $d->id_parameter_tms;
      });

      $keepKeys = [];
      foreach ($selectedItems as $item) {
        $tmsId = (int) ($item['tms_id'] ?? 0);
        if ($tmsId <= 0) {
          continue;
        }
        $pukId = $item['puk_id'] ?? null;
        $key = $pukId ? ('puk:' . (string) $pukId) : ('tms:' . $tmsId);
        $keepKeys[$key] = true;

        if ($existing->has($key)) {
          continue;
        }

        $detail = new OrderDetailTms();
        $detail->id_order_tms = $order->id_order_tms;
        $detail->id_parameter_tms = $tmsId;
        $detail->id_permohonan_uji_parameter_klinik = $pukId;
        $detail->value = null;
        $detail->save();
      }

      foreach ($existing as $key => $detail) {
        if (!isset($keepKeys[$key])) {
          $detail->delete();
        }
      }

      DB::commit();

      $order->load(['details' => function ($q) {
        $q->whereNull('deleted_at')->with('parameterTms');
      }]);

      $mqttReport = null;
      try {
        $mqttReport = app(TmsOrderPublisher::class)->publishById($order->id_order_tms);
      } catch (\Throwable $mqttException) {
        Log::error('MQTT TMS order publish failed setelah update', [
          'id_order_tms' => $order->id_order_tms,
          'message' => $mqttException->getMessage(),
        ]);
      }

      return response()->json([
        'status' => true,
        'pesan' => 'Order TMS berhasil diperbarui (' . $jenis . ', ' . $order->details->count() . ' parameter).',
        'order' => [
          'id_order_tms' => $order->id_order_tms,
          'jenis_sampel' => $order->jenis_sampel,
          'kode_barcode' => $order->kode_barcode,
          'tray' => $order->tray,
          'pos' => $order->pos,
          'details_count' => $order->details->count(),
        ],
        'mqtt' => $mqttReport ? [$mqttReport] : [],
      ]);
    } catch (\Throwable $th) {
      DB::rollBack();
      return response()->json([
        'status' => false,
        'pesan' => $th->getMessage(),
      ], 500);
    }
  }

  /**
   * Hapus (soft-delete) satu order TMS beserta detailnya.
   */
  public function deleteTmsOrder(Request $request, $id_order_tms)
  {
    try {
      $order = OrderTms::query()
        ->where('id_order_tms', $id_order_tms)
        ->whereNull('deleted_at')
        ->firstOrFail();

      DB::beginTransaction();

      OrderDetailTms::query()
        ->where('id_order_tms', $order->id_order_tms)
        ->whereNull('deleted_at')
        ->get()
        ->each(function ($detail) {
          $detail->delete();
        });

      $order->delete();

      DB::commit();

      return response()->json([
        'status' => true,
        'pesan' => 'Order TMS berhasil dihapus.',
        'id_order_tms' => $id_order_tms,
      ]);
    } catch (\Throwable $th) {
      DB::rollBack();
      return response()->json([
        'status' => false,
        'pesan' => $th->getMessage(),
      ], 500);
    }
  }

  /**
   * Listen singkat topic MQTT result/status (pola mqtt:tms-subscribe).
   * Hasil yang cocok dengan permohonan ini ditulis ke order existing.
   */
  public function listenTmsMqtt(Request $request, $id_permohonan_uji_klinik)
  {
    try {
      PermohonanUjiKlinik2::findOrFail($id_permohonan_uji_klinik);
      @set_time_limit(35);

      $timeout = (int) $request->input('timeout', config('mqtt.listen_timeout', 6));
      $topics = array_values(array_filter([
        config('mqtt.topics.tms.result'),
        config('mqtt.topics.tms.status'),
      ]));

      $messages = app(\App\Services\Mqtt\MqttService::class)->subscribeCollect(
        $topics,
        $timeout,
        (int) config('mqtt.qos', 1)
      );

      $handler = app(TmsMqttResultHandler::class);
      $applied = [];
      foreach ($messages as $i => $message) {
        $topic = (string) ($message['topic'] ?? '');
        $resultTopic = (string) config('mqtt.topics.tms.result');
        if ($topic === $resultTopic && !empty($message['payload'])) {
          $report = $handler->applyToPermohonan($id_permohonan_uji_klinik, $message);
          $messages[$i]['apply'] = $report;
          if (!empty($report['applied'])) {
            $applied[] = $report;
          }
        }
      }

      return response()->json([
        'status' => true,
        'pesan' => empty($messages)
          ? ('Tidak ada pesan MQTT selama ' . max(2, min(15, $timeout)) . ' detik.')
          : ('Diterima ' . count($messages) . ' pesan MQTT.'),
        'topics' => $topics,
        'timeout' => max(2, min(15, $timeout)),
        'count' => count($messages),
        'applied_count' => count($applied),
        'messages' => $messages,
      ]);
    } catch (\Throwable $th) {
      return response()->json([
        'status' => false,
        'pesan' => $th->getMessage(),
      ], 500);
    }
  }

  /**
   * Kirim ulang satu order ke topic MQTT order (pola mqtt:test-tms-order).
   */
  public function republishTmsMqttOrder(Request $request, $id_order_tms)
  {
    try {
      $order = OrderTms::query()
        ->where('id_order_tms', $id_order_tms)
        ->whereNull('deleted_at')
        ->firstOrFail();

      $report = app(TmsOrderPublisher::class)->publishById($order->id_order_tms);

      return response()->json([
        'status' => !empty($report['published']),
        'pesan' => !empty($report['published'])
          ? ('Order dikirim ke MQTT ' . $report['topic'] . '.')
          : ('Gagal publish MQTT: ' . ($report['error'] ?: 'unknown')),
        'mqtt' => $report,
      ], !empty($report['published']) ? 200 : 502);
    } catch (\Throwable $th) {
      return response()->json([
        'status' => false,
        'pesan' => $th->getMessage(),
      ], 500);
    }
  }

  /**
   * Minta alat TMS mengirim ulang hasil (message_type: tms.result.resend).
   */
  public function resendTmsMqttResult(Request $request, $id_order_tms)
  {
    try {
      OrderTms::query()
        ->where('id_order_tms', $id_order_tms)
        ->whereNull('deleted_at')
        ->firstOrFail();

      $sampleId = trim((string) $request->input('sample_id', ''));
      if ($sampleId !== '') {
        $report = app(TmsResultResendPublisher::class)->publishBySampleId($sampleId, $id_order_tms);
      } else {
        $report = app(TmsResultResendPublisher::class)->publishByOrderId($id_order_tms);
      }

      return response()->json([
        'status' => !empty($report['published']),
        'pesan' => !empty($report['published'])
          ? ('Permintaan resend hasil dikirim ke MQTT ' . $report['topic'] . ' (sample ' . ($report['sample_id'] ?? '-') . ').')
          : ('Gagal publish resend hasil: ' . ($report['error'] ?: 'unknown')),
        'mqtt' => $report,
      ], !empty($report['published']) ? 200 : 502);
    } catch (\Throwable $th) {
      return response()->json([
        'status' => false,
        'pesan' => $th->getMessage(),
      ], 500);
    }
  }

}